questions.push(...[{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 2/9 + 1/10.","கூட்டிச் சுருக்குக: 2/9 + 1/10."],"options":[["119/90","119/90"],["29/90","29/90"],["-61/90","-61/90"],["209/90","209/90"]],"answer":1,"explanation":["[2×10 + 9]/[9×10] = 29/90.","[2×10 + 9]/[9×10] = 29/90."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20000,"question_number":20001,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 2/9 − 1/10.","கழித்துச் சுருக்குக: 2/9 − 1/10."],"options":[["-79/90","-79/90"],["101/90","101/90"],["191/90","191/90"],["11/90","11/90"]],"answer":3,"explanation":["[2×10 − 9]/[9×10] = 11/90.","[2×10 − 9]/[9×10] = 11/90."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20001,"question_number":20002,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−2/9) × (10/3).","(−2/9) × (10/3) பெருக்கற்பலனைச் சுருக்குக."],"options":[["34/27","34/27"],["-47/27","-47/27"],["7/27","7/27"],["-20/27","-20/27"]],"answer":3,"explanation":["−20/27 = -20/27.","−20/27 = -20/27."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20002,"question_number":20003,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (2/9) ÷ (3/10) in simplest form.","(2/9) ÷ (3/10) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["20/27","20/27"],["-7/27","-7/27"],["47/27","47/27"],["74/27","74/27"]],"answer":0,"explanation":["(2/9) × (10/3) = 20/27.","(2/9) × (10/3) = 20/27."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20003,"question_number":20004,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 2.9 and 0.09.","2.9 மற்றும் 0.09 தசம எண்களைக் கூட்டுக."],"options":[["2.99","2.99"],["3.00","3.00"],["2.98","2.98"],["3.09","3.09"]],"answer":0,"explanation":["2.9 + 0.09 = 2.99.","2.9 + 0.09 = 2.99."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20004,"question_number":20005,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 9x + 2 = 101.","9x + 2 = 101 சமன்பாட்டைத் தீர்க்க."],"options":[["13","13"],["11","11"],["12","12"],["10","10"]],"answer":1,"explanation":["x = (101 − 2)/9 = 11.","x = (101 − 2)/9 = 11."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20005,"question_number":20006,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 2 and y = 9, find (x+y)² − x² − y², then divide by 2.","x = 2, y = 9 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["19","19"],["18","18"],["17","17"],["20","20"]],"answer":1,"explanation":["[(x+y)²−x²−y²]/2 = xy = 2×9 = 18.","[(x+y)²−x²−y²]/2 = xy = 2×9 = 18."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20006,"question_number":20007,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 2, y = 9.","x = 2, y = 9 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["122","122"],["123","123"],["120","120"],["121","121"]],"answer":3,"explanation":["(x+y)² = (2+9)² = 121.","(x+y)² = (2+9)² = 121."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20007,"question_number":20008,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^2 × 7^9 = 7^m, what is m?","7^2 × 7^9 = 7^m எனில் m என்ன?"],"options":[["11","11"],["13","13"],["10","10"],["12","12"]],"answer":0,"explanation":["m = 2 + 9 = 11.","m = 2 + 9 = 11."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20008,"question_number":20009,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^2)^9 = 2^m, find m.","(2^2)^9 = 2^m எனில் m காண்க."],"options":[["17","17"],["18","18"],["20","20"],["19","19"]],"answer":1,"explanation":["m = 2 × 9 = 18.","m = 2 × 9 = 18."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20009,"question_number":20010,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 841.","841 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["30","30"],["31","31"],["29","29"],["28","28"]],"answer":2,"explanation":["29 × 29 = 841; √841 = 29.","29 × 29 = 841; √841 = 29."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20010,"question_number":20011,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 24389.","24389 இன் கனமூலத்தைக் காண்க."],"options":[["30","30"],["28","28"],["31","31"],["29","29"]],"answer":3,"explanation":["29 × 29 × 29 = 24389; cube root = 29.","29 × 29 × 29 = 24389; கனமூலம் = 29."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20011,"question_number":20012,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 45% of ₹40.","₹40 இன் 45% காண்க."],"options":[["19","19"],["20","20"],["17","17"],["18","18"]],"answer":3,"explanation":["40×45/100 = 18.","40×45/100 = 18."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20012,"question_number":20013,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹200 has a 45% discount. What is the sale price in rupees?","₹200 குறித்த விலையுள்ள பைக்கு 45% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["109","109"],["112","112"],["111","111"],["110","110"]],"answer":3,"explanation":["200 × (100−45)/100 = 110.","200 × (100−45)/100 = 110."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20013,"question_number":20014,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹200 sells for ₹290. Find the profit percentage.","₹200 க்கு வாங்கிய பொருள் ₹290 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["44","44"],["46","46"],["45","45"],["47","47"]],"answer":2,"explanation":["(290−200)/200×100 = 45%.","(290−200)/200×100 = 45%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20014,"question_number":20015,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹2000 at 9% per year for 3 years.","₹2000 க்கு ஆண்டுக்கு 9% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["541","541"],["539","539"],["540","540"],["542","542"]],"answer":2,"explanation":["2000×9×3/100 = 540.","2000×9×3/100 = 540."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20015,"question_number":20016,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹20000 at 9% a year for 2 years, compounded annually.","₹20000 க்கு ஆண்டுக்கு 9% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["3761","3761"],["3762","3762"],["3763","3763"],["3764","3764"]],"answer":1,"explanation":["20000×[(1+9/100)²−1] = 3762.","20000×[(1+9/100)²−1] = 3762."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20016,"question_number":20017,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["9 metres of cloth cost ₹20. At the same rate, what is the cost of 12 metres in rupees?","9 மீ துணியின் விலை ₹20. அதே வீதத்தில் 12 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["80/3","80/3"],["77/3","77/3"],["83/3","83/3"],["86/3","86/3"]],"answer":0,"explanation":["20/9×12 = 80/3.","20/9×12 = 80/3."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20017,"question_number":20018,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["9 equally efficient machines complete a job in 2 hours. How many hours do 11 such machines require at the same rate?","சமத் திறனுடைய 9 இயந்திரங்கள் வேலையை 2 மணியில் முடிக்கின்றன. அதே வீதத்தில் 11 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["40/11","40/11"],["18/11","18/11"],["7/11","7/11"],["29/11","29/11"]],"answer":1,"explanation":["9×2/(9+2) = 18/11 hours.","9×2/(9+2) = 18/11 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20018,"question_number":20019,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 4 cm and perpendicular height 9 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 4 செமீ; செங்குத்து உயரம் 9 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["38","38"],["37","37"],["36","36"],["35","35"]],"answer":2,"explanation":["4×9 = 36.","4×9 = 36."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20019,"question_number":20020,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 4 cm and 18 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 4 செமீ, 18 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["38","38"],["35","35"],["37","37"],["36","36"]],"answer":3,"explanation":["½×4×18 = 36 cm².","½×4×18 = 36 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20020,"question_number":20021,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 4 m and 22 m, and height 9 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 4 மீ, 22 மீ; உயரம் 9 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["118","118"],["116","116"],["119","119"],["117","117"]],"answer":3,"explanation":["½×(4+22)×9 = 117.","½×(4+22)×9 = 117."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20021,"question_number":20022,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 14 cm makes 9 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","14 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 9 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["792","792"],["793","793"],["794","794"],["791","791"]],"answer":0,"explanation":["9×2×22/7×14 = 792.","9×2×22/7×14 = 792."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20022,"question_number":20023,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 9 circular mats, each of radius 14 cm. Find their total area in cm², using π=22/7.","தலா 14 செமீ ஆரமுள்ள 9 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["5546","5546"],["5545","5545"],["5543","5543"],["5544","5544"]],"answer":3,"explanation":["9×22/7×14² = 5544.","9×22/7×14² = 5544."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20023,"question_number":20024,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 24° and 48°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 24°, 48°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["107","107"],["110","110"],["109","109"],["108","108"]],"answer":3,"explanation":["180−24−48 = 108°.","180−24−48 = 108°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20024,"question_number":20025,"practice_set":801},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 52°. One remote interior angle is 29°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 52°. அதற்கான ஓர் எதிர் உட்கோணம் 29°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["25","25"],["22","22"],["24","24"],["23","23"]],"answer":3,"explanation":["52 − 29 = 23°.","52 − 29 = 23°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20025,"question_number":20026,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 2, 11, 20, 29, 38.","2, 11, 20, 29, 38 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["22","22"],["19","19"],["20","20"],["21","21"]],"answer":2,"explanation":["Sum/5 = 100/5 = 20.","கூடுதல்/5 = 100/5 = 20."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20026,"question_number":20027,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 47, 2, 20, 65, 11.","வரிசைப்படுத்தி இடைநிலை காண்க: 47, 2, 20, 65, 11."],"options":[["22","22"],["21","21"],["20","20"],["19","19"]],"answer":2,"explanation":["Sorted: 2, 11, 20, 47, 65; middle value = 20.","வரிசை: 2, 11, 20, 47, 65; நடு மதிப்பு = 20."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20027,"question_number":20028,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 2, 11, 2, 20, 29, 2?","2, 11, 2, 20, 29, 2 தரவுகளின் முகடு எது?"],"options":[["4","4"],["2","2"],["1","1"],["3","3"]],"answer":1,"explanation":["2 occurs 3 times; each other value occurs once.","2 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20028,"question_number":20029,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 2 hours and another in 9 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 2 மணியிலும் மற்றொன்று 9 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["18/11","18/11"],["7/11","7/11"],["29/11","29/11"],["40/11","40/11"]],"answer":0,"explanation":["Combined hourly rate = 1/2+1/9; time = 18/11 = 18/11 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/2+1/9; காலம் = 18/11 = 18/11 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20029,"question_number":20030,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −2/9. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −2/9. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["20/9","20/9"],["2/9","2/9"],["11/9","11/9"],["-7/9","-7/9"]],"answer":1,"explanation":["−2/9 + 2/9 = 0. Simplified additive inverse: 2/9.","−2/9 + 2/9 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 2/9."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20030,"question_number":20031,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 2 and 9?","2 மற்றும் 9 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["13/2","13/2"],["15/2","15/2"],["9/2","9/2"],["11/2","11/2"]],"answer":3,"explanation":["(2+9)/2 = 11/2.","(2+9)/2 = 11/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20031,"question_number":20032,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 3/9 + 1/10.","கூட்டிச் சுருக்குக: 3/9 + 1/10."],"options":[["-17/30","-17/30"],["13/30","13/30"],["73/30","73/30"],["43/30","43/30"]],"answer":1,"explanation":["[3×10 + 9]/[9×10] = 13/30.","[3×10 + 9]/[9×10] = 13/30."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20032,"question_number":20033,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 3/9 − 1/10.","கழித்துச் சுருக்குக: 3/9 − 1/10."],"options":[["7/30","7/30"],["-23/30","-23/30"],["37/30","37/30"],["67/30","67/30"]],"answer":0,"explanation":["[3×10 − 9]/[9×10] = 7/30.","[3×10 − 9]/[9×10] = 7/30."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20033,"question_number":20034,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−3/9) × (10/4).","(−3/9) × (10/4) பெருக்கற்பலனைச் சுருக்குக."],"options":[["7/6","7/6"],["-11/6","-11/6"],["1/6","1/6"],["-5/6","-5/6"]],"answer":3,"explanation":["−30/36 = -5/6.","−30/36 = -5/6."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20034,"question_number":20035,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (3/9) ÷ (4/10) in simplest form.","(3/9) ÷ (4/10) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["11/6","11/6"],["5/6","5/6"],["-1/6","-1/6"],["17/6","17/6"]],"answer":1,"explanation":["(3/9) × (10/4) = 5/6.","(3/9) × (10/4) = 5/6."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20035,"question_number":20036,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 3.9 and 0.09.","3.9 மற்றும் 0.09 தசம எண்களைக் கூட்டுக."],"options":[["3.98","3.98"],["4.09","4.09"],["4.00","4.00"],["3.99","3.99"]],"answer":3,"explanation":["3.9 + 0.09 = 3.99.","3.9 + 0.09 = 3.99."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20036,"question_number":20037,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 9x + 3 = 111.","9x + 3 = 111 சமன்பாட்டைத் தீர்க்க."],"options":[["13","13"],["12","12"],["14","14"],["11","11"]],"answer":1,"explanation":["x = (111 − 3)/9 = 12.","x = (111 − 3)/9 = 12."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20037,"question_number":20038,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 3 and y = 9, find (x+y)² − x² − y², then divide by 2.","x = 3, y = 9 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["26","26"],["28","28"],["29","29"],["27","27"]],"answer":3,"explanation":["[(x+y)²−x²−y²]/2 = xy = 3×9 = 27.","[(x+y)²−x²−y²]/2 = xy = 3×9 = 27."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20038,"question_number":20039,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 3, y = 9.","x = 3, y = 9 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["144","144"],["143","143"],["146","146"],["145","145"]],"answer":0,"explanation":["(x+y)² = (3+9)² = 144.","(x+y)² = (3+9)² = 144."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20039,"question_number":20040,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^3 × 7^9 = 7^m, what is m?","7^3 × 7^9 = 7^m எனில் m என்ன?"],"options":[["12","12"],["14","14"],["11","11"],["13","13"]],"answer":0,"explanation":["m = 3 + 9 = 12.","m = 3 + 9 = 12."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20040,"question_number":20041,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^3)^9 = 2^m, find m.","(2^3)^9 = 2^m எனில் m காண்க."],"options":[["29","29"],["28","28"],["27","27"],["26","26"]],"answer":2,"explanation":["m = 3 × 9 = 27.","m = 3 × 9 = 27."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20041,"question_number":20042,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 1521.","1521 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["41","41"],["39","39"],["38","38"],["40","40"]],"answer":1,"explanation":["39 × 39 = 1521; √1521 = 39.","39 × 39 = 1521; √1521 = 39."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20042,"question_number":20043,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 59319.","59319 இன் கனமூலத்தைக் காண்க."],"options":[["41","41"],["39","39"],["38","38"],["40","40"]],"answer":1,"explanation":["39 × 39 × 39 = 59319; cube root = 39.","39 × 39 × 39 = 59319; கனமூலம் = 39."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20043,"question_number":20044,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 45% of ₹60.","₹60 இன் 45% காண்க."],"options":[["29","29"],["28","28"],["27","27"],["26","26"]],"answer":2,"explanation":["60×45/100 = 27.","60×45/100 = 27."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20044,"question_number":20045,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹300 has a 45% discount. What is the sale price in rupees?","₹300 குறித்த விலையுள்ள பைக்கு 45% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["165","165"],["167","167"],["166","166"],["164","164"]],"answer":0,"explanation":["300 × (100−45)/100 = 165.","300 × (100−45)/100 = 165."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20045,"question_number":20046,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹300 sells for ₹435. Find the profit percentage.","₹300 க்கு வாங்கிய பொருள் ₹435 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["47","47"],["46","46"],["45","45"],["44","44"]],"answer":2,"explanation":["(435−300)/300×100 = 45%.","(435−300)/300×100 = 45%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20046,"question_number":20047,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹3000 at 9% per year for 3 years.","₹3000 க்கு ஆண்டுக்கு 9% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["811","811"],["810","810"],["812","812"],["809","809"]],"answer":1,"explanation":["3000×9×3/100 = 810.","3000×9×3/100 = 810."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20047,"question_number":20048,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹30000 at 9% a year for 2 years, compounded annually.","₹30000 க்கு ஆண்டுக்கு 9% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["5643","5643"],["5644","5644"],["5642","5642"],["5645","5645"]],"answer":0,"explanation":["30000×[(1+9/100)²−1] = 5643.","30000×[(1+9/100)²−1] = 5643."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20048,"question_number":20049,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["9 metres of cloth cost ₹30. At the same rate, what is the cost of 12 metres in rupees?","9 மீ துணியின் விலை ₹30. அதே வீதத்தில் 12 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["40","40"],["42","42"],["39","39"],["41","41"]],"answer":0,"explanation":["30/9×12 = 40.","30/9×12 = 40."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20049,"question_number":20050,"practice_set":802},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["9 equally efficient machines complete a job in 3 hours. How many hours do 11 such machines require at the same rate?","சமத் திறனுடைய 9 இயந்திரங்கள் வேலையை 3 மணியில் முடிக்கின்றன. அதே வீதத்தில் 11 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["16/11","16/11"],["49/11","49/11"],["38/11","38/11"],["27/11","27/11"]],"answer":3,"explanation":["9×3/(9+2) = 27/11 hours.","9×3/(9+2) = 27/11 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20050,"question_number":20051,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 6 cm and perpendicular height 9 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 6 செமீ; செங்குத்து உயரம் 9 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["53","53"],["55","55"],["54","54"],["56","56"]],"answer":2,"explanation":["6×9 = 54.","6×9 = 54."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20051,"question_number":20052,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 6 cm and 18 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 6 செமீ, 18 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["56","56"],["54","54"],["55","55"],["53","53"]],"answer":1,"explanation":["½×6×18 = 54 cm².","½×6×18 = 54 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20052,"question_number":20053,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 6 m and 24 m, and height 9 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 6 மீ, 24 மீ; உயரம் 9 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["134","134"],["137","137"],["135","135"],["136","136"]],"answer":2,"explanation":["½×(6+24)×9 = 135.","½×(6+24)×9 = 135."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20053,"question_number":20054,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 21 cm makes 9 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","21 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 9 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["1190","1190"],["1187","1187"],["1188","1188"],["1189","1189"]],"answer":2,"explanation":["9×2×22/7×21 = 1188.","9×2×22/7×21 = 1188."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20054,"question_number":20055,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 9 circular mats, each of radius 21 cm. Find their total area in cm², using π=22/7.","தலா 21 செமீ ஆரமுள்ள 9 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["12473","12473"],["12474","12474"],["12476","12476"],["12475","12475"]],"answer":1,"explanation":["9×22/7×21² = 12474.","9×22/7×21² = 12474."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20055,"question_number":20056,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 26° and 48°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 26°, 48°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["105","105"],["108","108"],["107","107"],["106","106"]],"answer":3,"explanation":["180−26−48 = 106°.","180−26−48 = 106°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20056,"question_number":20057,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 53°. One remote interior angle is 29°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 53°. அதற்கான ஓர் எதிர் உட்கோணம் 29°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["24","24"],["25","25"],["23","23"],["26","26"]],"answer":0,"explanation":["53 − 29 = 24°.","53 − 29 = 24°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20057,"question_number":20058,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 3, 12, 21, 30, 39.","3, 12, 21, 30, 39 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["23","23"],["20","20"],["21","21"],["22","22"]],"answer":2,"explanation":["Sum/5 = 105/5 = 21.","கூடுதல்/5 = 105/5 = 21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20058,"question_number":20059,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 48, 3, 21, 66, 12.","வரிசைப்படுத்தி இடைநிலை காண்க: 48, 3, 21, 66, 12."],"options":[["23","23"],["22","22"],["20","20"],["21","21"]],"answer":3,"explanation":["Sorted: 3, 12, 21, 48, 66; middle value = 21.","வரிசை: 3, 12, 21, 48, 66; நடு மதிப்பு = 21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20059,"question_number":20060,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 3, 12, 3, 21, 30, 3?","3, 12, 3, 21, 30, 3 தரவுகளின் முகடு எது?"],"options":[["4","4"],["3","3"],["5","5"],["2","2"]],"answer":1,"explanation":["3 occurs 3 times; each other value occurs once.","3 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20060,"question_number":20061,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 3 hours and another in 9 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 3 மணியிலும் மற்றொன்று 9 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["9/4","9/4"],["17/4","17/4"],["5/4","5/4"],["13/4","13/4"]],"answer":0,"explanation":["Combined hourly rate = 1/3+1/9; time = 27/12 = 9/4 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/3+1/9; காலம் = 27/12 = 9/4 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20061,"question_number":20062,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −3/9. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −3/9. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["1/3","1/3"],["4/3","4/3"],["-2/3","-2/3"],["7/3","7/3"]],"answer":0,"explanation":["−3/9 + 3/9 = 0. Simplified additive inverse: 1/3.","−3/9 + 3/9 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 1/3."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20062,"question_number":20063,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 3 and 9?","3 மற்றும் 9 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["7","7"],["6","6"],["5","5"],["8","8"]],"answer":1,"explanation":["(3+9)/2 = 6.","(3+9)/2 = 6."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20063,"question_number":20064,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 4/9 + 1/10.","கூட்டிச் சுருக்குக: 4/9 + 1/10."],"options":[["-41/90","-41/90"],["139/90","139/90"],["229/90","229/90"],["49/90","49/90"]],"answer":3,"explanation":["[4×10 + 9]/[9×10] = 49/90.","[4×10 + 9]/[9×10] = 49/90."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20064,"question_number":20065,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 4/9 − 1/10.","கழித்துச் சுருக்குக: 4/9 − 1/10."],"options":[["-59/90","-59/90"],["121/90","121/90"],["211/90","211/90"],["31/90","31/90"]],"answer":3,"explanation":["[4×10 − 9]/[9×10] = 31/90.","[4×10 − 9]/[9×10] = 31/90."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20065,"question_number":20066,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−4/9) × (10/5).","(−4/9) × (10/5) பெருக்கற்பலனைச் சுருக்குக."],"options":[["1/9","1/9"],["10/9","10/9"],["-17/9","-17/9"],["-8/9","-8/9"]],"answer":3,"explanation":["−40/45 = -8/9.","−40/45 = -8/9."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20066,"question_number":20067,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (4/9) ÷ (5/10) in simplest form.","(4/9) ÷ (5/10) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["8/9","8/9"],["17/9","17/9"],["26/9","26/9"],["-1/9","-1/9"]],"answer":0,"explanation":["(4/9) × (10/5) = 8/9.","(4/9) × (10/5) = 8/9."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20067,"question_number":20068,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 4.9 and 0.09.","4.9 மற்றும் 0.09 தசம எண்களைக் கூட்டுக."],"options":[["4.98","4.98"],["5.00","5.00"],["4.99","4.99"],["5.09","5.09"]],"answer":2,"explanation":["4.9 + 0.09 = 4.99.","4.9 + 0.09 = 4.99."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20068,"question_number":20069,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 9x + 4 = 121.","9x + 4 = 121 சமன்பாட்டைத் தீர்க்க."],"options":[["12","12"],["14","14"],["15","15"],["13","13"]],"answer":3,"explanation":["x = (121 − 4)/9 = 13.","x = (121 − 4)/9 = 13."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20069,"question_number":20070,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 4 and y = 9, find (x+y)² − x² − y², then divide by 2.","x = 4, y = 9 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["36","36"],["38","38"],["37","37"],["35","35"]],"answer":0,"explanation":["[(x+y)²−x²−y²]/2 = xy = 4×9 = 36.","[(x+y)²−x²−y²]/2 = xy = 4×9 = 36."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20070,"question_number":20071,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 4, y = 9.","x = 4, y = 9 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["169","169"],["171","171"],["168","168"],["170","170"]],"answer":0,"explanation":["(x+y)² = (4+9)² = 169.","(x+y)² = (4+9)² = 169."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20071,"question_number":20072,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^4 × 7^9 = 7^m, what is m?","7^4 × 7^9 = 7^m எனில் m என்ன?"],"options":[["13","13"],["12","12"],["14","14"],["15","15"]],"answer":0,"explanation":["m = 4 + 9 = 13.","m = 4 + 9 = 13."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20072,"question_number":20073,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^4)^9 = 2^m, find m.","(2^4)^9 = 2^m எனில் m காண்க."],"options":[["38","38"],["36","36"],["37","37"],["35","35"]],"answer":1,"explanation":["m = 4 × 9 = 36.","m = 4 × 9 = 36."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20073,"question_number":20074,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 2401.","2401 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["50","50"],["48","48"],["51","51"],["49","49"]],"answer":3,"explanation":["49 × 49 = 2401; √2401 = 49.","49 × 49 = 2401; √2401 = 49."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20074,"question_number":20075,"practice_set":803},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 117649.","117649 இன் கனமூலத்தைக் காண்க."],"options":[["49","49"],["50","50"],["48","48"],["51","51"]],"answer":0,"explanation":["49 × 49 × 49 = 117649; cube root = 49.","49 × 49 × 49 = 117649; கனமூலம் = 49."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20075,"question_number":20076,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 45% of ₹80.","₹80 இன் 45% காண்க."],"options":[["35","35"],["36","36"],["38","38"],["37","37"]],"answer":1,"explanation":["80×45/100 = 36.","80×45/100 = 36."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20076,"question_number":20077,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹400 has a 45% discount. What is the sale price in rupees?","₹400 குறித்த விலையுள்ள பைக்கு 45% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["220","220"],["219","219"],["221","221"],["222","222"]],"answer":0,"explanation":["400 × (100−45)/100 = 220.","400 × (100−45)/100 = 220."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20077,"question_number":20078,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹400 sells for ₹580. Find the profit percentage.","₹400 க்கு வாங்கிய பொருள் ₹580 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["46","46"],["45","45"],["44","44"],["47","47"]],"answer":1,"explanation":["(580−400)/400×100 = 45%.","(580−400)/400×100 = 45%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20078,"question_number":20079,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹4000 at 9% per year for 3 years.","₹4000 க்கு ஆண்டுக்கு 9% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1080","1080"],["1079","1079"],["1082","1082"],["1081","1081"]],"answer":0,"explanation":["4000×9×3/100 = 1080.","4000×9×3/100 = 1080."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20079,"question_number":20080,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹40000 at 9% a year for 2 years, compounded annually.","₹40000 க்கு ஆண்டுக்கு 9% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["7524","7524"],["7525","7525"],["7526","7526"],["7523","7523"]],"answer":0,"explanation":["40000×[(1+9/100)²−1] = 7524.","40000×[(1+9/100)²−1] = 7524."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20080,"question_number":20081,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["9 metres of cloth cost ₹40. At the same rate, what is the cost of 12 metres in rupees?","9 மீ துணியின் விலை ₹40. அதே வீதத்தில் 12 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["163/3","163/3"],["157/3","157/3"],["166/3","166/3"],["160/3","160/3"]],"answer":3,"explanation":["40/9×12 = 160/3.","40/9×12 = 160/3."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20081,"question_number":20082,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["9 equally efficient machines complete a job in 4 hours. How many hours do 11 such machines require at the same rate?","சமத் திறனுடைய 9 இயந்திரங்கள் வேலையை 4 மணியில் முடிக்கின்றன. அதே வீதத்தில் 11 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["36/11","36/11"],["47/11","47/11"],["25/11","25/11"],["58/11","58/11"]],"answer":0,"explanation":["9×4/(9+2) = 36/11 hours.","9×4/(9+2) = 36/11 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20082,"question_number":20083,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 8 cm and perpendicular height 9 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 8 செமீ; செங்குத்து உயரம் 9 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["71","71"],["74","74"],["72","72"],["73","73"]],"answer":2,"explanation":["8×9 = 72.","8×9 = 72."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20083,"question_number":20084,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 8 cm and 18 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 8 செமீ, 18 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["72","72"],["71","71"],["74","74"],["73","73"]],"answer":0,"explanation":["½×8×18 = 72 cm².","½×8×18 = 72 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20084,"question_number":20085,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 8 m and 26 m, and height 9 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 8 மீ, 26 மீ; உயரம் 9 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["154","154"],["153","153"],["155","155"],["152","152"]],"answer":1,"explanation":["½×(8+26)×9 = 153.","½×(8+26)×9 = 153."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20085,"question_number":20086,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 28 cm makes 9 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","28 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 9 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["1586","1586"],["1583","1583"],["1585","1585"],["1584","1584"]],"answer":3,"explanation":["9×2×22/7×28 = 1584.","9×2×22/7×28 = 1584."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20086,"question_number":20087,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 9 circular mats, each of radius 28 cm. Find their total area in cm², using π=22/7.","தலா 28 செமீ ஆரமுள்ள 9 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["22175","22175"],["22178","22178"],["22177","22177"],["22176","22176"]],"answer":3,"explanation":["9×22/7×28² = 22176.","9×22/7×28² = 22176."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20087,"question_number":20088,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 28° and 48°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 28°, 48°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["105","105"],["103","103"],["106","106"],["104","104"]],"answer":3,"explanation":["180−28−48 = 104°.","180−28−48 = 104°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20088,"question_number":20089,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 54°. One remote interior angle is 29°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 54°. அதற்கான ஓர் எதிர் உட்கோணம் 29°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["27","27"],["26","26"],["25","25"],["24","24"]],"answer":2,"explanation":["54 − 29 = 25°.","54 − 29 = 25°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20089,"question_number":20090,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 4, 13, 22, 31, 40.","4, 13, 22, 31, 40 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["24","24"],["23","23"],["21","21"],["22","22"]],"answer":3,"explanation":["Sum/5 = 110/5 = 22.","கூடுதல்/5 = 110/5 = 22."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20090,"question_number":20091,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 49, 4, 22, 67, 13.","வரிசைப்படுத்தி இடைநிலை காண்க: 49, 4, 22, 67, 13."],"options":[["22","22"],["21","21"],["23","23"],["24","24"]],"answer":0,"explanation":["Sorted: 4, 13, 22, 49, 67; middle value = 22.","வரிசை: 4, 13, 22, 49, 67; நடு மதிப்பு = 22."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20091,"question_number":20092,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 4, 13, 4, 22, 31, 4?","4, 13, 4, 22, 31, 4 தரவுகளின் முகடு எது?"],"options":[["5","5"],["3","3"],["6","6"],["4","4"]],"answer":3,"explanation":["4 occurs 3 times; each other value occurs once.","4 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20092,"question_number":20093,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 4 hours and another in 9 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 4 மணியிலும் மற்றொன்று 9 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["23/13","23/13"],["49/13","49/13"],["36/13","36/13"],["62/13","62/13"]],"answer":2,"explanation":["Combined hourly rate = 1/4+1/9; time = 36/13 = 36/13 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/4+1/9; காலம் = 36/13 = 36/13 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20093,"question_number":20094,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −4/9. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −4/9. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["22/9","22/9"],["-5/9","-5/9"],["4/9","4/9"],["13/9","13/9"]],"answer":2,"explanation":["−4/9 + 4/9 = 0. Simplified additive inverse: 4/9.","−4/9 + 4/9 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 4/9."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20094,"question_number":20095,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 4 and 9?","4 மற்றும் 9 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["17/2","17/2"],["11/2","11/2"],["13/2","13/2"],["15/2","15/2"]],"answer":2,"explanation":["(4+9)/2 = 13/2.","(4+9)/2 = 13/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20095,"question_number":20096,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 5/9 + 1/10.","கூட்டிச் சுருக்குக: 5/9 + 1/10."],"options":[["-31/90","-31/90"],["59/90","59/90"],["239/90","239/90"],["149/90","149/90"]],"answer":1,"explanation":["[5×10 + 9]/[9×10] = 59/90.","[5×10 + 9]/[9×10] = 59/90."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20096,"question_number":20097,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 5/9 − 1/10.","கழித்துச் சுருக்குக: 5/9 − 1/10."],"options":[["221/90","221/90"],["131/90","131/90"],["41/90","41/90"],["-49/90","-49/90"]],"answer":2,"explanation":["[5×10 − 9]/[9×10] = 41/90.","[5×10 − 9]/[9×10] = 41/90."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20097,"question_number":20098,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−5/9) × (10/6).","(−5/9) × (10/6) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-52/27","-52/27"],["2/27","2/27"],["-25/27","-25/27"],["29/27","29/27"]],"answer":2,"explanation":["−50/54 = -25/27.","−50/54 = -25/27."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20098,"question_number":20099,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (5/9) ÷ (6/10) in simplest form.","(5/9) ÷ (6/10) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["79/27","79/27"],["-2/27","-2/27"],["25/27","25/27"],["52/27","52/27"]],"answer":2,"explanation":["(5/9) × (10/6) = 25/27.","(5/9) × (10/6) = 25/27."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20099,"question_number":20100,"practice_set":804},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 5.9 and 0.09.","5.9 மற்றும் 0.09 தசம எண்களைக் கூட்டுக."],"options":[["6.00","6.00"],["5.98","5.98"],["6.09","6.09"],["5.99","5.99"]],"answer":3,"explanation":["5.9 + 0.09 = 5.99.","5.9 + 0.09 = 5.99."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20100,"question_number":20101,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 9x + 5 = 131.","9x + 5 = 131 சமன்பாட்டைத் தீர்க்க."],"options":[["16","16"],["15","15"],["14","14"],["13","13"]],"answer":2,"explanation":["x = (131 − 5)/9 = 14.","x = (131 − 5)/9 = 14."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20101,"question_number":20102,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 5 and y = 9, find (x+y)² − x² − y², then divide by 2.","x = 5, y = 9 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["44","44"],["47","47"],["45","45"],["46","46"]],"answer":2,"explanation":["[(x+y)²−x²−y²]/2 = xy = 5×9 = 45.","[(x+y)²−x²−y²]/2 = xy = 5×9 = 45."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20102,"question_number":20103,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 5, y = 9.","x = 5, y = 9 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["195","195"],["196","196"],["198","198"],["197","197"]],"answer":1,"explanation":["(x+y)² = (5+9)² = 196.","(x+y)² = (5+9)² = 196."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20103,"question_number":20104,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^5 × 7^9 = 7^m, what is m?","7^5 × 7^9 = 7^m எனில் m என்ன?"],"options":[["13","13"],["14","14"],["15","15"],["16","16"]],"answer":1,"explanation":["m = 5 + 9 = 14.","m = 5 + 9 = 14."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20104,"question_number":20105,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^5)^9 = 2^m, find m.","(2^5)^9 = 2^m எனில் m காண்க."],"options":[["45","45"],["44","44"],["47","47"],["46","46"]],"answer":0,"explanation":["m = 5 × 9 = 45.","m = 5 × 9 = 45."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20105,"question_number":20106,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 3481.","3481 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["61","61"],["60","60"],["59","59"],["58","58"]],"answer":2,"explanation":["59 × 59 = 3481; √3481 = 59.","59 × 59 = 3481; √3481 = 59."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20106,"question_number":20107,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 205379.","205379 இன் கனமூலத்தைக் காண்க."],"options":[["60","60"],["61","61"],["59","59"],["58","58"]],"answer":2,"explanation":["59 × 59 × 59 = 205379; cube root = 59.","59 × 59 × 59 = 205379; கனமூலம் = 59."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20107,"question_number":20108,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 45% of ₹100.","₹100 இன் 45% காண்க."],"options":[["46","46"],["47","47"],["45","45"],["44","44"]],"answer":2,"explanation":["100×45/100 = 45.","100×45/100 = 45."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20108,"question_number":20109,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹500 has a 45% discount. What is the sale price in rupees?","₹500 குறித்த விலையுள்ள பைக்கு 45% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["277","277"],["274","274"],["276","276"],["275","275"]],"answer":3,"explanation":["500 × (100−45)/100 = 275.","500 × (100−45)/100 = 275."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20109,"question_number":20110,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹500 sells for ₹725. Find the profit percentage.","₹500 க்கு வாங்கிய பொருள் ₹725 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["47","47"],["45","45"],["46","46"],["44","44"]],"answer":1,"explanation":["(725−500)/500×100 = 45%.","(725−500)/500×100 = 45%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20110,"question_number":20111,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹5000 at 9% per year for 3 years.","₹5000 க்கு ஆண்டுக்கு 9% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1351","1351"],["1350","1350"],["1349","1349"],["1352","1352"]],"answer":1,"explanation":["5000×9×3/100 = 1350.","5000×9×3/100 = 1350."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20111,"question_number":20112,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹50000 at 9% a year for 2 years, compounded annually.","₹50000 க்கு ஆண்டுக்கு 9% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["9406","9406"],["9407","9407"],["9404","9404"],["9405","9405"]],"answer":3,"explanation":["50000×[(1+9/100)²−1] = 9405.","50000×[(1+9/100)²−1] = 9405."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20112,"question_number":20113,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["9 metres of cloth cost ₹50. At the same rate, what is the cost of 12 metres in rupees?","9 மீ துணியின் விலை ₹50. அதே வீதத்தில் 12 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["197/3","197/3"],["206/3","206/3"],["200/3","200/3"],["203/3","203/3"]],"answer":2,"explanation":["50/9×12 = 200/3.","50/9×12 = 200/3."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20113,"question_number":20114,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["9 equally efficient machines complete a job in 5 hours. How many hours do 11 such machines require at the same rate?","சமத் திறனுடைய 9 இயந்திரங்கள் வேலையை 5 மணியில் முடிக்கின்றன. அதே வீதத்தில் 11 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["34/11","34/11"],["56/11","56/11"],["67/11","67/11"],["45/11","45/11"]],"answer":3,"explanation":["9×5/(9+2) = 45/11 hours.","9×5/(9+2) = 45/11 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20114,"question_number":20115,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 10 cm and perpendicular height 9 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 10 செமீ; செங்குத்து உயரம் 9 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["90","90"],["89","89"],["92","92"],["91","91"]],"answer":0,"explanation":["10×9 = 90.","10×9 = 90."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20115,"question_number":20116,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 10 cm and 18 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 10 செமீ, 18 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["92","92"],["91","91"],["90","90"],["89","89"]],"answer":2,"explanation":["½×10×18 = 90 cm².","½×10×18 = 90 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20116,"question_number":20117,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 10 m and 28 m, and height 9 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 10 மீ, 28 மீ; உயரம் 9 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["172","172"],["173","173"],["171","171"],["170","170"]],"answer":2,"explanation":["½×(10+28)×9 = 171.","½×(10+28)×9 = 171."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20117,"question_number":20118,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 35 cm makes 9 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","35 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 9 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["1981","1981"],["1982","1982"],["1980","1980"],["1979","1979"]],"answer":2,"explanation":["9×2×22/7×35 = 1980.","9×2×22/7×35 = 1980."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20118,"question_number":20119,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 9 circular mats, each of radius 35 cm. Find their total area in cm², using π=22/7.","தலா 35 செமீ ஆரமுள்ள 9 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["34649","34649"],["34651","34651"],["34652","34652"],["34650","34650"]],"answer":3,"explanation":["9×22/7×35² = 34650.","9×22/7×35² = 34650."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20119,"question_number":20120,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 30° and 48°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 30°, 48°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["104","104"],["101","101"],["103","103"],["102","102"]],"answer":3,"explanation":["180−30−48 = 102°.","180−30−48 = 102°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20120,"question_number":20121,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 55°. One remote interior angle is 29°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 55°. அதற்கான ஓர் எதிர் உட்கோணம் 29°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["27","27"],["28","28"],["26","26"],["25","25"]],"answer":2,"explanation":["55 − 29 = 26°.","55 − 29 = 26°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20121,"question_number":20122,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 5, 14, 23, 32, 41.","5, 14, 23, 32, 41 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["25","25"],["22","22"],["24","24"],["23","23"]],"answer":3,"explanation":["Sum/5 = 115/5 = 23.","கூடுதல்/5 = 115/5 = 23."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20122,"question_number":20123,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 50, 5, 23, 68, 14.","வரிசைப்படுத்தி இடைநிலை காண்க: 50, 5, 23, 68, 14."],"options":[["24","24"],["22","22"],["23","23"],["25","25"]],"answer":2,"explanation":["Sorted: 5, 14, 23, 50, 68; middle value = 23.","வரிசை: 5, 14, 23, 50, 68; நடு மதிப்பு = 23."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20123,"question_number":20124,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 5, 14, 5, 23, 32, 5?","5, 14, 5, 23, 32, 5 தரவுகளின் முகடு எது?"],"options":[["6","6"],["7","7"],["4","4"],["5","5"]],"answer":3,"explanation":["5 occurs 3 times; each other value occurs once.","5 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20124,"question_number":20125,"practice_set":805},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 5 hours and another in 9 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 5 மணியிலும் மற்றொன்று 9 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["31/14","31/14"],["45/14","45/14"],["73/14","73/14"],["59/14","59/14"]],"answer":1,"explanation":["Combined hourly rate = 1/5+1/9; time = 45/14 = 45/14 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/5+1/9; காலம் = 45/14 = 45/14 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20125,"question_number":20126,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −5/9. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −5/9. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["14/9","14/9"],["5/9","5/9"],["23/9","23/9"],["-4/9","-4/9"]],"answer":1,"explanation":["−5/9 + 5/9 = 0. Simplified additive inverse: 5/9.","−5/9 + 5/9 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 5/9."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20126,"question_number":20127,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 5 and 9?","5 மற்றும் 9 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["8","8"],["9","9"],["7","7"],["6","6"]],"answer":2,"explanation":["(5+9)/2 = 7.","(5+9)/2 = 7."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20127,"question_number":20128,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 6/9 + 1/10.","கூட்டிச் சுருக்குக: 6/9 + 1/10."],"options":[["83/30","83/30"],["-7/30","-7/30"],["53/30","53/30"],["23/30","23/30"]],"answer":3,"explanation":["[6×10 + 9]/[9×10] = 23/30.","[6×10 + 9]/[9×10] = 23/30."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20128,"question_number":20129,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 6/9 − 1/10.","கழித்துச் சுருக்குக: 6/9 − 1/10."],"options":[["-13/30","-13/30"],["47/30","47/30"],["77/30","77/30"],["17/30","17/30"]],"answer":3,"explanation":["[6×10 − 9]/[9×10] = 17/30.","[6×10 − 9]/[9×10] = 17/30."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20129,"question_number":20130,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−6/9) × (10/7).","(−6/9) × (10/7) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-41/21","-41/21"],["1/21","1/21"],["22/21","22/21"],["-20/21","-20/21"]],"answer":3,"explanation":["−60/63 = -20/21.","−60/63 = -20/21."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20130,"question_number":20131,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (6/9) ÷ (7/10) in simplest form.","(6/9) ÷ (7/10) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["20/21","20/21"],["-1/21","-1/21"],["41/21","41/21"],["62/21","62/21"]],"answer":0,"explanation":["(6/9) × (10/7) = 20/21.","(6/9) × (10/7) = 20/21."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20131,"question_number":20132,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 6.9 and 0.09.","6.9 மற்றும் 0.09 தசம எண்களைக் கூட்டுக."],"options":[["6.98","6.98"],["7.00","7.00"],["6.99","6.99"],["7.09","7.09"]],"answer":2,"explanation":["6.9 + 0.09 = 6.99.","6.9 + 0.09 = 6.99."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20132,"question_number":20133,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 9x + 6 = 141.","9x + 6 = 141 சமன்பாட்டைத் தீர்க்க."],"options":[["17","17"],["14","14"],["16","16"],["15","15"]],"answer":3,"explanation":["x = (141 − 6)/9 = 15.","x = (141 − 6)/9 = 15."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20133,"question_number":20134,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 6 and y = 9, find (x+y)² − x² − y², then divide by 2.","x = 6, y = 9 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["53","53"],["56","56"],["55","55"],["54","54"]],"answer":3,"explanation":["[(x+y)²−x²−y²]/2 = xy = 6×9 = 54.","[(x+y)²−x²−y²]/2 = xy = 6×9 = 54."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20134,"question_number":20135,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 6, y = 9.","x = 6, y = 9 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["224","224"],["226","226"],["225","225"],["227","227"]],"answer":2,"explanation":["(x+y)² = (6+9)² = 225.","(x+y)² = (6+9)² = 225."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20135,"question_number":20136,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^6 × 7^9 = 7^m, what is m?","7^6 × 7^9 = 7^m எனில் m என்ன?"],"options":[["14","14"],["16","16"],["17","17"],["15","15"]],"answer":3,"explanation":["m = 6 + 9 = 15.","m = 6 + 9 = 15."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20136,"question_number":20137,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^6)^9 = 2^m, find m.","(2^6)^9 = 2^m எனில் m காண்க."],"options":[["53","53"],["56","56"],["54","54"],["55","55"]],"answer":2,"explanation":["m = 6 × 9 = 54.","m = 6 × 9 = 54."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20137,"question_number":20138,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 4761.","4761 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["69","69"],["68","68"],["70","70"],["71","71"]],"answer":0,"explanation":["69 × 69 = 4761; √4761 = 69.","69 × 69 = 4761; √4761 = 69."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20138,"question_number":20139,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 328509.","328509 இன் கனமூலத்தைக் காண்க."],"options":[["69","69"],["68","68"],["70","70"],["71","71"]],"answer":0,"explanation":["69 × 69 × 69 = 328509; cube root = 69.","69 × 69 × 69 = 328509; கனமூலம் = 69."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20139,"question_number":20140,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 45% of ₹120.","₹120 இன் 45% காண்க."],"options":[["56","56"],["53","53"],["54","54"],["55","55"]],"answer":2,"explanation":["120×45/100 = 54.","120×45/100 = 54."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20140,"question_number":20141,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹600 has a 45% discount. What is the sale price in rupees?","₹600 குறித்த விலையுள்ள பைக்கு 45% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["332","332"],["331","331"],["330","330"],["329","329"]],"answer":2,"explanation":["600 × (100−45)/100 = 330.","600 × (100−45)/100 = 330."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20141,"question_number":20142,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹600 sells for ₹870. Find the profit percentage.","₹600 க்கு வாங்கிய பொருள் ₹870 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["46","46"],["44","44"],["47","47"],["45","45"]],"answer":3,"explanation":["(870−600)/600×100 = 45%.","(870−600)/600×100 = 45%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20142,"question_number":20143,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹6000 at 9% per year for 3 years.","₹6000 க்கு ஆண்டுக்கு 9% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1619","1619"],["1621","1621"],["1622","1622"],["1620","1620"]],"answer":3,"explanation":["6000×9×3/100 = 1620.","6000×9×3/100 = 1620."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20143,"question_number":20144,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹60000 at 9% a year for 2 years, compounded annually.","₹60000 க்கு ஆண்டுக்கு 9% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["11285","11285"],["11287","11287"],["11286","11286"],["11288","11288"]],"answer":2,"explanation":["60000×[(1+9/100)²−1] = 11286.","60000×[(1+9/100)²−1] = 11286."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20144,"question_number":20145,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["9 metres of cloth cost ₹60. At the same rate, what is the cost of 12 metres in rupees?","9 மீ துணியின் விலை ₹60. அதே வீதத்தில் 12 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["79","79"],["81","81"],["82","82"],["80","80"]],"answer":3,"explanation":["60/9×12 = 80.","60/9×12 = 80."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20145,"question_number":20146,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["9 equally efficient machines complete a job in 6 hours. How many hours do 11 such machines require at the same rate?","சமத் திறனுடைய 9 இயந்திரங்கள் வேலையை 6 மணியில் முடிக்கின்றன. அதே வீதத்தில் 11 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["43/11","43/11"],["54/11","54/11"],["65/11","65/11"],["76/11","76/11"]],"answer":1,"explanation":["9×6/(9+2) = 54/11 hours.","9×6/(9+2) = 54/11 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20146,"question_number":20147,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 12 cm and perpendicular height 9 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 12 செமீ; செங்குத்து உயரம் 9 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["110","110"],["108","108"],["109","109"],["107","107"]],"answer":1,"explanation":["12×9 = 108.","12×9 = 108."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20147,"question_number":20148,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 12 cm and 18 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 12 செமீ, 18 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["108","108"],["107","107"],["110","110"],["109","109"]],"answer":0,"explanation":["½×12×18 = 108 cm².","½×12×18 = 108 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20148,"question_number":20149,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 12 m and 30 m, and height 9 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 12 மீ, 30 மீ; உயரம் 9 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["188","188"],["191","191"],["189","189"],["190","190"]],"answer":2,"explanation":["½×(12+30)×9 = 189.","½×(12+30)×9 = 189."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20149,"question_number":20150,"practice_set":806},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 42 cm makes 9 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","42 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 9 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["2377","2377"],["2376","2376"],["2378","2378"],["2375","2375"]],"answer":1,"explanation":["9×2×22/7×42 = 2376.","9×2×22/7×42 = 2376."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20150,"question_number":20151,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 9 circular mats, each of radius 42 cm. Find their total area in cm², using π=22/7.","தலா 42 செமீ ஆரமுள்ள 9 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["49895","49895"],["49897","49897"],["49896","49896"],["49898","49898"]],"answer":2,"explanation":["9×22/7×42² = 49896.","9×22/7×42² = 49896."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20151,"question_number":20152,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 32° and 48°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 32°, 48°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["102","102"],["99","99"],["101","101"],["100","100"]],"answer":3,"explanation":["180−32−48 = 100°.","180−32−48 = 100°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20152,"question_number":20153,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 56°. One remote interior angle is 29°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 56°. அதற்கான ஓர் எதிர் உட்கோணம் 29°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["27","27"],["29","29"],["26","26"],["28","28"]],"answer":0,"explanation":["56 − 29 = 27°.","56 − 29 = 27°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20153,"question_number":20154,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 6, 15, 24, 33, 42.","6, 15, 24, 33, 42 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["26","26"],["24","24"],["23","23"],["25","25"]],"answer":1,"explanation":["Sum/5 = 120/5 = 24.","கூடுதல்/5 = 120/5 = 24."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20154,"question_number":20155,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 51, 6, 24, 69, 15.","வரிசைப்படுத்தி இடைநிலை காண்க: 51, 6, 24, 69, 15."],"options":[["26","26"],["25","25"],["23","23"],["24","24"]],"answer":3,"explanation":["Sorted: 6, 15, 24, 51, 69; middle value = 24.","வரிசை: 6, 15, 24, 51, 69; நடு மதிப்பு = 24."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20155,"question_number":20156,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 6, 15, 6, 24, 33, 6?","6, 15, 6, 24, 33, 6 தரவுகளின் முகடு எது?"],"options":[["8","8"],["6","6"],["7","7"],["5","5"]],"answer":1,"explanation":["6 occurs 3 times; each other value occurs once.","6 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20156,"question_number":20157,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 6 hours and another in 9 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 6 மணியிலும் மற்றொன்று 9 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["18/5","18/5"],["13/5","13/5"],["23/5","23/5"],["28/5","28/5"]],"answer":0,"explanation":["Combined hourly rate = 1/6+1/9; time = 54/15 = 18/5 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/6+1/9; காலம் = 54/15 = 18/5 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20157,"question_number":20158,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −6/9. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −6/9. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["-1/3","-1/3"],["2/3","2/3"],["8/3","8/3"],["5/3","5/3"]],"answer":1,"explanation":["−6/9 + 6/9 = 0. Simplified additive inverse: 2/3.","−6/9 + 6/9 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 2/3."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20158,"question_number":20159,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 6 and 9?","6 மற்றும் 9 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["15/2","15/2"],["17/2","17/2"],["13/2","13/2"],["19/2","19/2"]],"answer":0,"explanation":["(6+9)/2 = 15/2.","(6+9)/2 = 15/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20159,"question_number":20160,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 7/9 + 1/10.","கூட்டிச் சுருக்குக: 7/9 + 1/10."],"options":[["79/90","79/90"],["259/90","259/90"],["169/90","169/90"],["-11/90","-11/90"]],"answer":0,"explanation":["[7×10 + 9]/[9×10] = 79/90.","[7×10 + 9]/[9×10] = 79/90."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20160,"question_number":20161,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 7/9 − 1/10.","கழித்துச் சுருக்குக: 7/9 − 1/10."],"options":[["151/90","151/90"],["-29/90","-29/90"],["241/90","241/90"],["61/90","61/90"]],"answer":3,"explanation":["[7×10 − 9]/[9×10] = 61/90.","[7×10 − 9]/[9×10] = 61/90."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20161,"question_number":20162,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−7/9) × (10/8).","(−7/9) × (10/8) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-35/36","-35/36"],["-71/36","-71/36"],["37/36","37/36"],["1/36","1/36"]],"answer":0,"explanation":["−70/72 = -35/36.","−70/72 = -35/36."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20162,"question_number":20163,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (7/9) ÷ (8/10) in simplest form.","(7/9) ÷ (8/10) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["35/36","35/36"],["-1/36","-1/36"],["107/36","107/36"],["71/36","71/36"]],"answer":0,"explanation":["(7/9) × (10/8) = 35/36.","(7/9) × (10/8) = 35/36."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20163,"question_number":20164,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 7.9 and 0.09.","7.9 மற்றும் 0.09 தசம எண்களைக் கூட்டுக."],"options":[["8.00","8.00"],["7.99","7.99"],["8.09","8.09"],["7.98","7.98"]],"answer":1,"explanation":["7.9 + 0.09 = 7.99.","7.9 + 0.09 = 7.99."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20164,"question_number":20165,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 9x + 7 = 151.","9x + 7 = 151 சமன்பாட்டைத் தீர்க்க."],"options":[["16","16"],["18","18"],["17","17"],["15","15"]],"answer":0,"explanation":["x = (151 − 7)/9 = 16.","x = (151 − 7)/9 = 16."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20165,"question_number":20166,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 7 and y = 9, find (x+y)² − x² − y², then divide by 2.","x = 7, y = 9 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["65","65"],["63","63"],["64","64"],["62","62"]],"answer":1,"explanation":["[(x+y)²−x²−y²]/2 = xy = 7×9 = 63.","[(x+y)²−x²−y²]/2 = xy = 7×9 = 63."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20166,"question_number":20167,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 7, y = 9.","x = 7, y = 9 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["256","256"],["255","255"],["257","257"],["258","258"]],"answer":0,"explanation":["(x+y)² = (7+9)² = 256.","(x+y)² = (7+9)² = 256."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20167,"question_number":20168,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^7 × 7^9 = 7^m, what is m?","7^7 × 7^9 = 7^m எனில் m என்ன?"],"options":[["17","17"],["16","16"],["18","18"],["15","15"]],"answer":1,"explanation":["m = 7 + 9 = 16.","m = 7 + 9 = 16."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20168,"question_number":20169,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^7)^9 = 2^m, find m.","(2^7)^9 = 2^m எனில் m காண்க."],"options":[["64","64"],["63","63"],["65","65"],["62","62"]],"answer":1,"explanation":["m = 7 × 9 = 63.","m = 7 × 9 = 63."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20169,"question_number":20170,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 6241.","6241 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["81","81"],["79","79"],["78","78"],["80","80"]],"answer":1,"explanation":["79 × 79 = 6241; √6241 = 79.","79 × 79 = 6241; √6241 = 79."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20170,"question_number":20171,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 493039.","493039 இன் கனமூலத்தைக் காண்க."],"options":[["78","78"],["79","79"],["80","80"],["81","81"]],"answer":1,"explanation":["79 × 79 × 79 = 493039; cube root = 79.","79 × 79 × 79 = 493039; கனமூலம் = 79."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20171,"question_number":20172,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 45% of ₹140.","₹140 இன் 45% காண்க."],"options":[["63","63"],["64","64"],["65","65"],["62","62"]],"answer":0,"explanation":["140×45/100 = 63.","140×45/100 = 63."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20172,"question_number":20173,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹700 has a 45% discount. What is the sale price in rupees?","₹700 குறித்த விலையுள்ள பைக்கு 45% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["384","384"],["385","385"],["386","386"],["387","387"]],"answer":1,"explanation":["700 × (100−45)/100 = 385.","700 × (100−45)/100 = 385."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20173,"question_number":20174,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹700 sells for ₹1015. Find the profit percentage.","₹700 க்கு வாங்கிய பொருள் ₹1015 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["47","47"],["45","45"],["46","46"],["44","44"]],"answer":1,"explanation":["(1015−700)/700×100 = 45%.","(1015−700)/700×100 = 45%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20174,"question_number":20175,"practice_set":807},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹7000 at 9% per year for 3 years.","₹7000 க்கு ஆண்டுக்கு 9% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1890","1890"],["1892","1892"],["1889","1889"],["1891","1891"]],"answer":0,"explanation":["7000×9×3/100 = 1890.","7000×9×3/100 = 1890."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20175,"question_number":20176,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹70000 at 9% a year for 2 years, compounded annually.","₹70000 க்கு ஆண்டுக்கு 9% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["13169","13169"],["13166","13166"],["13168","13168"],["13167","13167"]],"answer":3,"explanation":["70000×[(1+9/100)²−1] = 13167.","70000×[(1+9/100)²−1] = 13167."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20176,"question_number":20177,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["9 metres of cloth cost ₹70. At the same rate, what is the cost of 12 metres in rupees?","9 மீ துணியின் விலை ₹70. அதே வீதத்தில் 12 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["283/3","283/3"],["277/3","277/3"],["286/3","286/3"],["280/3","280/3"]],"answer":3,"explanation":["70/9×12 = 280/3.","70/9×12 = 280/3."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20177,"question_number":20178,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["9 equally efficient machines complete a job in 7 hours. How many hours do 11 such machines require at the same rate?","சமத் திறனுடைய 9 இயந்திரங்கள் வேலையை 7 மணியில் முடிக்கின்றன. அதே வீதத்தில் 11 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["63/11","63/11"],["85/11","85/11"],["74/11","74/11"],["52/11","52/11"]],"answer":0,"explanation":["9×7/(9+2) = 63/11 hours.","9×7/(9+2) = 63/11 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20178,"question_number":20179,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 14 cm and perpendicular height 9 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 14 செமீ; செங்குத்து உயரம் 9 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["126","126"],["127","127"],["128","128"],["125","125"]],"answer":0,"explanation":["14×9 = 126.","14×9 = 126."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20179,"question_number":20180,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 14 cm and 18 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 14 செமீ, 18 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["125","125"],["127","127"],["126","126"],["128","128"]],"answer":2,"explanation":["½×14×18 = 126 cm².","½×14×18 = 126 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20180,"question_number":20181,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 14 m and 32 m, and height 9 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 14 மீ, 32 மீ; உயரம் 9 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["207","207"],["206","206"],["208","208"],["209","209"]],"answer":0,"explanation":["½×(14+32)×9 = 207.","½×(14+32)×9 = 207."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20181,"question_number":20182,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 49 cm makes 9 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","49 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 9 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["2773","2773"],["2772","2772"],["2771","2771"],["2774","2774"]],"answer":1,"explanation":["9×2×22/7×49 = 2772.","9×2×22/7×49 = 2772."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20182,"question_number":20183,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 9 circular mats, each of radius 49 cm. Find their total area in cm², using π=22/7.","தலா 49 செமீ ஆரமுள்ள 9 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["67916","67916"],["67914","67914"],["67913","67913"],["67915","67915"]],"answer":1,"explanation":["9×22/7×49² = 67914.","9×22/7×49² = 67914."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20183,"question_number":20184,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 34° and 48°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 34°, 48°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["99","99"],["100","100"],["98","98"],["97","97"]],"answer":2,"explanation":["180−34−48 = 98°.","180−34−48 = 98°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20184,"question_number":20185,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 57°. One remote interior angle is 29°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 57°. அதற்கான ஓர் எதிர் உட்கோணம் 29°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["29","29"],["28","28"],["27","27"],["30","30"]],"answer":1,"explanation":["57 − 29 = 28°.","57 − 29 = 28°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20185,"question_number":20186,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 7, 16, 25, 34, 43.","7, 16, 25, 34, 43 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["26","26"],["27","27"],["25","25"],["24","24"]],"answer":2,"explanation":["Sum/5 = 125/5 = 25.","கூடுதல்/5 = 125/5 = 25."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20186,"question_number":20187,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 52, 7, 25, 70, 16.","வரிசைப்படுத்தி இடைநிலை காண்க: 52, 7, 25, 70, 16."],"options":[["27","27"],["24","24"],["26","26"],["25","25"]],"answer":3,"explanation":["Sorted: 7, 16, 25, 52, 70; middle value = 25.","வரிசை: 7, 16, 25, 52, 70; நடு மதிப்பு = 25."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20187,"question_number":20188,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 7, 16, 7, 25, 34, 7?","7, 16, 7, 25, 34, 7 தரவுகளின் முகடு எது?"],"options":[["8","8"],["9","9"],["6","6"],["7","7"]],"answer":3,"explanation":["7 occurs 3 times; each other value occurs once.","7 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20188,"question_number":20189,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 7 hours and another in 9 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 7 மணியிலும் மற்றொன்று 9 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["95/16","95/16"],["63/16","63/16"],["79/16","79/16"],["47/16","47/16"]],"answer":1,"explanation":["Combined hourly rate = 1/7+1/9; time = 63/16 = 63/16 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/7+1/9; காலம் = 63/16 = 63/16 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20189,"question_number":20190,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −7/9. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −7/9. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["7/9","7/9"],["16/9","16/9"],["25/9","25/9"],["-2/9","-2/9"]],"answer":0,"explanation":["−7/9 + 7/9 = 0. Simplified additive inverse: 7/9.","−7/9 + 7/9 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 7/9."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20190,"question_number":20191,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 7 and 9?","7 மற்றும் 9 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["8","8"],["9","9"],["7","7"],["10","10"]],"answer":0,"explanation":["(7+9)/2 = 8.","(7+9)/2 = 8."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20191,"question_number":20192,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 8/9 + 1/10.","கூட்டிச் சுருக்குக: 8/9 + 1/10."],"options":[["269/90","269/90"],["89/90","89/90"],["-1/90","-1/90"],["179/90","179/90"]],"answer":1,"explanation":["[8×10 + 9]/[9×10] = 89/90.","[8×10 + 9]/[9×10] = 89/90."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20192,"question_number":20193,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 8/9 − 1/10.","கழித்துச் சுருக்குக: 8/9 − 1/10."],"options":[["161/90","161/90"],["251/90","251/90"],["71/90","71/90"],["-19/90","-19/90"]],"answer":2,"explanation":["[8×10 − 9]/[9×10] = 71/90.","[8×10 − 9]/[9×10] = 71/90."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20193,"question_number":20194,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−8/9) × (10/9).","(−8/9) × (10/9) பெருக்கற்பலனைச் சுருக்குக."],"options":[["1/81","1/81"],["82/81","82/81"],["-161/81","-161/81"],["-80/81","-80/81"]],"answer":3,"explanation":["−80/81 = -80/81.","−80/81 = -80/81."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20194,"question_number":20195,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (8/9) ÷ (9/10) in simplest form.","(8/9) ÷ (9/10) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["80/81","80/81"],["161/81","161/81"],["242/81","242/81"],["-1/81","-1/81"]],"answer":0,"explanation":["(8/9) × (10/9) = 80/81.","(8/9) × (10/9) = 80/81."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20195,"question_number":20196,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 8.9 and 0.09.","8.9 மற்றும் 0.09 தசம எண்களைக் கூட்டுக."],"options":[["9.09","9.09"],["8.98","8.98"],["9.00","9.00"],["8.99","8.99"]],"answer":3,"explanation":["8.9 + 0.09 = 8.99.","8.9 + 0.09 = 8.99."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20196,"question_number":20197,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 9x + 8 = 161.","9x + 8 = 161 சமன்பாட்டைத் தீர்க்க."],"options":[["18","18"],["17","17"],["16","16"],["19","19"]],"answer":1,"explanation":["x = (161 − 8)/9 = 17.","x = (161 − 8)/9 = 17."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20197,"question_number":20198,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 8 and y = 9, find (x+y)² − x² − y², then divide by 2.","x = 8, y = 9 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["72","72"],["73","73"],["71","71"],["74","74"]],"answer":0,"explanation":["[(x+y)²−x²−y²]/2 = xy = 8×9 = 72.","[(x+y)²−x²−y²]/2 = xy = 8×9 = 72."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20198,"question_number":20199,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 8, y = 9.","x = 8, y = 9 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["289","289"],["291","291"],["290","290"],["288","288"]],"answer":0,"explanation":["(x+y)² = (8+9)² = 289.","(x+y)² = (8+9)² = 289."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20199,"question_number":20200,"practice_set":808},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^8 × 7^9 = 7^m, what is m?","7^8 × 7^9 = 7^m எனில் m என்ன?"],"options":[["16","16"],["17","17"],["19","19"],["18","18"]],"answer":1,"explanation":["m = 8 + 9 = 17.","m = 8 + 9 = 17."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20200,"question_number":20201,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^8)^9 = 2^m, find m.","(2^8)^9 = 2^m எனில் m காண்க."],"options":[["73","73"],["72","72"],["74","74"],["71","71"]],"answer":1,"explanation":["m = 8 × 9 = 72.","m = 8 × 9 = 72."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20201,"question_number":20202,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 7921.","7921 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["88","88"],["90","90"],["89","89"],["91","91"]],"answer":2,"explanation":["89 × 89 = 7921; √7921 = 89.","89 × 89 = 7921; √7921 = 89."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20202,"question_number":20203,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 704969.","704969 இன் கனமூலத்தைக் காண்க."],"options":[["91","91"],["88","88"],["89","89"],["90","90"]],"answer":2,"explanation":["89 × 89 × 89 = 704969; cube root = 89.","89 × 89 × 89 = 704969; கனமூலம் = 89."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20203,"question_number":20204,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 45% of ₹160.","₹160 இன் 45% காண்க."],"options":[["73","73"],["74","74"],["72","72"],["71","71"]],"answer":2,"explanation":["160×45/100 = 72.","160×45/100 = 72."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20204,"question_number":20205,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹800 has a 45% discount. What is the sale price in rupees?","₹800 குறித்த விலையுள்ள பைக்கு 45% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["439","439"],["441","441"],["440","440"],["442","442"]],"answer":2,"explanation":["800 × (100−45)/100 = 440.","800 × (100−45)/100 = 440."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20205,"question_number":20206,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹800 sells for ₹1160. Find the profit percentage.","₹800 க்கு வாங்கிய பொருள் ₹1160 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["47","47"],["44","44"],["46","46"],["45","45"]],"answer":3,"explanation":["(1160−800)/800×100 = 45%.","(1160−800)/800×100 = 45%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20206,"question_number":20207,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹8000 at 9% per year for 3 years.","₹8000 க்கு ஆண்டுக்கு 9% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2160","2160"],["2161","2161"],["2162","2162"],["2159","2159"]],"answer":0,"explanation":["8000×9×3/100 = 2160.","8000×9×3/100 = 2160."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20207,"question_number":20208,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹80000 at 9% a year for 2 years, compounded annually.","₹80000 க்கு ஆண்டுக்கு 9% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["15050","15050"],["15047","15047"],["15048","15048"],["15049","15049"]],"answer":2,"explanation":["80000×[(1+9/100)²−1] = 15048.","80000×[(1+9/100)²−1] = 15048."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20208,"question_number":20209,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["9 metres of cloth cost ₹80. At the same rate, what is the cost of 12 metres in rupees?","9 மீ துணியின் விலை ₹80. அதே வீதத்தில் 12 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["323/3","323/3"],["326/3","326/3"],["317/3","317/3"],["320/3","320/3"]],"answer":3,"explanation":["80/9×12 = 320/3.","80/9×12 = 320/3."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20209,"question_number":20210,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["9 equally efficient machines complete a job in 8 hours. How many hours do 11 such machines require at the same rate?","சமத் திறனுடைய 9 இயந்திரங்கள் வேலையை 8 மணியில் முடிக்கின்றன. அதே வீதத்தில் 11 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["94/11","94/11"],["83/11","83/11"],["72/11","72/11"],["61/11","61/11"]],"answer":2,"explanation":["9×8/(9+2) = 72/11 hours.","9×8/(9+2) = 72/11 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20210,"question_number":20211,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 16 cm and perpendicular height 9 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 16 செமீ; செங்குத்து உயரம் 9 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["144","144"],["145","145"],["143","143"],["146","146"]],"answer":0,"explanation":["16×9 = 144.","16×9 = 144."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20211,"question_number":20212,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 16 cm and 18 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 16 செமீ, 18 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["143","143"],["144","144"],["145","145"],["146","146"]],"answer":1,"explanation":["½×16×18 = 144 cm².","½×16×18 = 144 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20212,"question_number":20213,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 16 m and 34 m, and height 9 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 16 மீ, 34 மீ; உயரம் 9 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["226","226"],["225","225"],["227","227"],["224","224"]],"answer":1,"explanation":["½×(16+34)×9 = 225.","½×(16+34)×9 = 225."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20213,"question_number":20214,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 56 cm makes 9 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","56 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 9 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["3170","3170"],["3167","3167"],["3169","3169"],["3168","3168"]],"answer":3,"explanation":["9×2×22/7×56 = 3168.","9×2×22/7×56 = 3168."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20214,"question_number":20215,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 9 circular mats, each of radius 56 cm. Find their total area in cm², using π=22/7.","தலா 56 செமீ ஆரமுள்ள 9 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["88704","88704"],["88703","88703"],["88705","88705"],["88706","88706"]],"answer":0,"explanation":["9×22/7×56² = 88704.","9×22/7×56² = 88704."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20215,"question_number":20216,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 36° and 48°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 36°, 48°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["98","98"],["97","97"],["96","96"],["95","95"]],"answer":2,"explanation":["180−36−48 = 96°.","180−36−48 = 96°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20216,"question_number":20217,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 58°. One remote interior angle is 29°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 58°. அதற்கான ஓர் எதிர் உட்கோணம் 29°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["30","30"],["28","28"],["31","31"],["29","29"]],"answer":3,"explanation":["58 − 29 = 29°.","58 − 29 = 29°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20217,"question_number":20218,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 8, 17, 26, 35, 44.","8, 17, 26, 35, 44 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["28","28"],["25","25"],["27","27"],["26","26"]],"answer":3,"explanation":["Sum/5 = 130/5 = 26.","கூடுதல்/5 = 130/5 = 26."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20218,"question_number":20219,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 53, 8, 26, 71, 17.","வரிசைப்படுத்தி இடைநிலை காண்க: 53, 8, 26, 71, 17."],"options":[["25","25"],["28","28"],["27","27"],["26","26"]],"answer":3,"explanation":["Sorted: 8, 17, 26, 53, 71; middle value = 26.","வரிசை: 8, 17, 26, 53, 71; நடு மதிப்பு = 26."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20219,"question_number":20220,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 8, 17, 8, 26, 35, 8?","8, 17, 8, 26, 35, 8 தரவுகளின் முகடு எது?"],"options":[["7","7"],["8","8"],["9","9"],["10","10"]],"answer":1,"explanation":["8 occurs 3 times; each other value occurs once.","8 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20220,"question_number":20221,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 8 hours and another in 9 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 8 மணியிலும் மற்றொன்று 9 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["106/17","106/17"],["55/17","55/17"],["89/17","89/17"],["72/17","72/17"]],"answer":3,"explanation":["Combined hourly rate = 1/8+1/9; time = 72/17 = 72/17 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/8+1/9; காலம் = 72/17 = 72/17 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20221,"question_number":20222,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −8/9. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −8/9. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["17/9","17/9"],["26/9","26/9"],["8/9","8/9"],["-1/9","-1/9"]],"answer":2,"explanation":["−8/9 + 8/9 = 0. Simplified additive inverse: 8/9.","−8/9 + 8/9 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 8/9."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20222,"question_number":20223,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 8 and 9?","8 மற்றும் 9 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["19/2","19/2"],["15/2","15/2"],["21/2","21/2"],["17/2","17/2"]],"answer":3,"explanation":["(8+9)/2 = 17/2.","(8+9)/2 = 17/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20223,"question_number":20224,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 9/9 + 1/10.","கூட்டிச் சுருக்குக: 9/9 + 1/10."],"options":[["1/10","1/10"],["21/10","21/10"],["11/10","11/10"],["31/10","31/10"]],"answer":2,"explanation":["[9×10 + 9]/[9×10] = 11/10.","[9×10 + 9]/[9×10] = 11/10."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20224,"question_number":20225,"practice_set":809},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 9/9 − 1/10.","கழித்துச் சுருக்குக: 9/9 − 1/10."],"options":[["-1/10","-1/10"],["19/10","19/10"],["29/10","29/10"],["9/10","9/10"]],"answer":3,"explanation":["[9×10 − 9]/[9×10] = 9/10.","[9×10 − 9]/[9×10] = 9/10."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20225,"question_number":20226,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−9/9) × (10/10).","(−9/9) × (10/10) பெருக்கற்பலனைச் சுருக்குக."],"options":[["1","1"],["-1","-1"],["0","0"],["-2","-2"]],"answer":1,"explanation":["−90/90 = -1.","−90/90 = -1."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20226,"question_number":20227,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (9/9) ÷ (10/10) in simplest form.","(9/9) ÷ (10/10) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["0","0"],["2","2"],["1","1"],["3","3"]],"answer":2,"explanation":["(9/9) × (10/10) = 1.","(9/9) × (10/10) = 1."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20227,"question_number":20228,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 9.9 and 0.09.","9.9 மற்றும் 0.09 தசம எண்களைக் கூட்டுக."],"options":[["9.98","9.98"],["10.00","10.00"],["9.99","9.99"],["10.09","10.09"]],"answer":2,"explanation":["9.9 + 0.09 = 9.99.","9.9 + 0.09 = 9.99."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20228,"question_number":20229,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 9x + 9 = 171.","9x + 9 = 171 சமன்பாட்டைத் தீர்க்க."],"options":[["19","19"],["17","17"],["20","20"],["18","18"]],"answer":3,"explanation":["x = (171 − 9)/9 = 18.","x = (171 − 9)/9 = 18."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20229,"question_number":20230,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 9 and y = 9, find (x+y)² − x² − y², then divide by 2.","x = 9, y = 9 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["82","82"],["80","80"],["83","83"],["81","81"]],"answer":3,"explanation":["[(x+y)²−x²−y²]/2 = xy = 9×9 = 81.","[(x+y)²−x²−y²]/2 = xy = 9×9 = 81."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20230,"question_number":20231,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 9, y = 9.","x = 9, y = 9 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["326","326"],["325","325"],["323","323"],["324","324"]],"answer":3,"explanation":["(x+y)² = (9+9)² = 324.","(x+y)² = (9+9)² = 324."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20231,"question_number":20232,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^9 × 7^9 = 7^m, what is m?","7^9 × 7^9 = 7^m எனில் m என்ன?"],"options":[["18","18"],["17","17"],["19","19"],["20","20"]],"answer":0,"explanation":["m = 9 + 9 = 18.","m = 9 + 9 = 18."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20232,"question_number":20233,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^9)^9 = 2^m, find m.","(2^9)^9 = 2^m எனில் m காண்க."],"options":[["82","82"],["81","81"],["83","83"],["80","80"]],"answer":1,"explanation":["m = 9 × 9 = 81.","m = 9 × 9 = 81."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20233,"question_number":20234,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 9801.","9801 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["100","100"],["99","99"],["98","98"],["101","101"]],"answer":1,"explanation":["99 × 99 = 9801; √9801 = 99.","99 × 99 = 9801; √9801 = 99."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20234,"question_number":20235,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 970299.","970299 இன் கனமூலத்தைக் காண்க."],"options":[["98","98"],["100","100"],["101","101"],["99","99"]],"answer":3,"explanation":["99 × 99 × 99 = 970299; cube root = 99.","99 × 99 × 99 = 970299; கனமூலம் = 99."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20235,"question_number":20236,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 45% of ₹180.","₹180 இன் 45% காண்க."],"options":[["81","81"],["83","83"],["82","82"],["80","80"]],"answer":0,"explanation":["180×45/100 = 81.","180×45/100 = 81."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20236,"question_number":20237,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹900 has a 45% discount. What is the sale price in rupees?","₹900 குறித்த விலையுள்ள பைக்கு 45% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["496","496"],["497","497"],["495","495"],["494","494"]],"answer":2,"explanation":["900 × (100−45)/100 = 495.","900 × (100−45)/100 = 495."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20237,"question_number":20238,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹900 sells for ₹1305. Find the profit percentage.","₹900 க்கு வாங்கிய பொருள் ₹1305 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["44","44"],["45","45"],["47","47"],["46","46"]],"answer":1,"explanation":["(1305−900)/900×100 = 45%.","(1305−900)/900×100 = 45%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20238,"question_number":20239,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹9000 at 9% per year for 3 years.","₹9000 க்கு ஆண்டுக்கு 9% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2429","2429"],["2431","2431"],["2430","2430"],["2432","2432"]],"answer":2,"explanation":["9000×9×3/100 = 2430.","9000×9×3/100 = 2430."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20239,"question_number":20240,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹90000 at 9% a year for 2 years, compounded annually.","₹90000 க்கு ஆண்டுக்கு 9% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["16930","16930"],["16929","16929"],["16931","16931"],["16928","16928"]],"answer":1,"explanation":["90000×[(1+9/100)²−1] = 16929.","90000×[(1+9/100)²−1] = 16929."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20240,"question_number":20241,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["9 metres of cloth cost ₹90. At the same rate, what is the cost of 12 metres in rupees?","9 மீ துணியின் விலை ₹90. அதே வீதத்தில் 12 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["121","121"],["120","120"],["119","119"],["122","122"]],"answer":1,"explanation":["90/9×12 = 120.","90/9×12 = 120."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20241,"question_number":20242,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["9 equally efficient machines complete a job in 9 hours. How many hours do 11 such machines require at the same rate?","சமத் திறனுடைய 9 இயந்திரங்கள் வேலையை 9 மணியில் முடிக்கின்றன. அதே வீதத்தில் 11 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["103/11","103/11"],["70/11","70/11"],["92/11","92/11"],["81/11","81/11"]],"answer":3,"explanation":["9×9/(9+2) = 81/11 hours.","9×9/(9+2) = 81/11 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20242,"question_number":20243,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 18 cm and perpendicular height 9 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 18 செமீ; செங்குத்து உயரம் 9 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["163","163"],["161","161"],["162","162"],["164","164"]],"answer":2,"explanation":["18×9 = 162.","18×9 = 162."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20243,"question_number":20244,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 18 cm and 18 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 18 செமீ, 18 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["164","164"],["163","163"],["162","162"],["161","161"]],"answer":2,"explanation":["½×18×18 = 162 cm².","½×18×18 = 162 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20244,"question_number":20245,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 18 m and 36 m, and height 9 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 18 மீ, 36 மீ; உயரம் 9 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["245","245"],["244","244"],["243","243"],["242","242"]],"answer":2,"explanation":["½×(18+36)×9 = 243.","½×(18+36)×9 = 243."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20245,"question_number":20246,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 63 cm makes 9 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","63 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 9 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["3563","3563"],["3565","3565"],["3566","3566"],["3564","3564"]],"answer":3,"explanation":["9×2×22/7×63 = 3564.","9×2×22/7×63 = 3564."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20246,"question_number":20247,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 9 circular mats, each of radius 63 cm. Find their total area in cm², using π=22/7.","தலா 63 செமீ ஆரமுள்ள 9 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["112267","112267"],["112265","112265"],["112266","112266"],["112268","112268"]],"answer":2,"explanation":["9×22/7×63² = 112266.","9×22/7×63² = 112266."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20247,"question_number":20248,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 38° and 48°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 38°, 48°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["94","94"],["95","95"],["96","96"],["93","93"]],"answer":0,"explanation":["180−38−48 = 94°.","180−38−48 = 94°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20248,"question_number":20249,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 59°. One remote interior angle is 29°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 59°. அதற்கான ஓர் எதிர் உட்கோணம் 29°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["30","30"],["32","32"],["29","29"],["31","31"]],"answer":0,"explanation":["59 − 29 = 30°.","59 − 29 = 30°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20249,"question_number":20250,"practice_set":810},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 9, 18, 27, 36, 45.","9, 18, 27, 36, 45 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["27","27"],["28","28"],["26","26"],["29","29"]],"answer":0,"explanation":["Sum/5 = 135/5 = 27.","கூடுதல்/5 = 135/5 = 27."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20250,"question_number":20251,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 54, 9, 27, 72, 18.","வரிசைப்படுத்தி இடைநிலை காண்க: 54, 9, 27, 72, 18."],"options":[["27","27"],["29","29"],["26","26"],["28","28"]],"answer":0,"explanation":["Sorted: 9, 18, 27, 54, 72; middle value = 27.","வரிசை: 9, 18, 27, 54, 72; நடு மதிப்பு = 27."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20251,"question_number":20252,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 9, 18, 9, 27, 36, 9?","9, 18, 9, 27, 36, 9 தரவுகளின் முகடு எது?"],"options":[["11","11"],["9","9"],["10","10"],["8","8"]],"answer":1,"explanation":["9 occurs 3 times; each other value occurs once.","9 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20252,"question_number":20253,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 9 hours and another in 9 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 9 மணியிலும் மற்றொன்று 9 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["7/2","7/2"],["9/2","9/2"],["13/2","13/2"],["11/2","11/2"]],"answer":1,"explanation":["Combined hourly rate = 1/9+1/9; time = 81/18 = 9/2 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/9+1/9; காலம் = 81/18 = 9/2 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20253,"question_number":20254,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −9/9. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −9/9. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["1","1"],["0","0"],["2","2"],["3","3"]],"answer":0,"explanation":["−9/9 + 9/9 = 0. Simplified additive inverse: 1.","−9/9 + 9/9 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 1."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20254,"question_number":20255,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 9 and 9?","9 மற்றும் 9 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["8","8"],["10","10"],["9","9"],["11","11"]],"answer":2,"explanation":["(9+9)/2 = 9.","(9+9)/2 = 9."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20255,"question_number":20256,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 10/9 + 1/10.","கூட்டிச் சுருக்குக: 10/9 + 1/10."],"options":[["19/90","19/90"],["289/90","289/90"],["199/90","199/90"],["109/90","109/90"]],"answer":3,"explanation":["[10×10 + 9]/[9×10] = 109/90.","[10×10 + 9]/[9×10] = 109/90."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20256,"question_number":20257,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 10/9 − 1/10.","கழித்துச் சுருக்குக: 10/9 − 1/10."],"options":[["271/90","271/90"],["181/90","181/90"],["91/90","91/90"],["1/90","1/90"]],"answer":2,"explanation":["[10×10 − 9]/[9×10] = 91/90.","[10×10 − 9]/[9×10] = 91/90."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20257,"question_number":20258,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−10/9) × (10/11).","(−10/9) × (10/11) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-1/99","-1/99"],["98/99","98/99"],["-199/99","-199/99"],["-100/99","-100/99"]],"answer":3,"explanation":["−100/99 = -100/99.","−100/99 = -100/99."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20258,"question_number":20259,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (10/9) ÷ (11/10) in simplest form.","(10/9) ÷ (11/10) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["1/99","1/99"],["298/99","298/99"],["199/99","199/99"],["100/99","100/99"]],"answer":3,"explanation":["(10/9) × (10/11) = 100/99.","(10/9) × (10/11) = 100/99."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20259,"question_number":20260,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 10.9 and 0.09.","10.9 மற்றும் 0.09 தசம எண்களைக் கூட்டுக."],"options":[["10.99","10.99"],["11.09","11.09"],["10.98","10.98"],["11.00","11.00"]],"answer":0,"explanation":["10.9 + 0.09 = 10.99.","10.9 + 0.09 = 10.99."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20260,"question_number":20261,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 9x + 10 = 181.","9x + 10 = 181 சமன்பாட்டைத் தீர்க்க."],"options":[["19","19"],["18","18"],["20","20"],["21","21"]],"answer":0,"explanation":["x = (181 − 10)/9 = 19.","x = (181 − 10)/9 = 19."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20261,"question_number":20262,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 10 and y = 9, find (x+y)² − x² − y², then divide by 2.","x = 10, y = 9 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["89","89"],["92","92"],["90","90"],["91","91"]],"answer":2,"explanation":["[(x+y)²−x²−y²]/2 = xy = 10×9 = 90.","[(x+y)²−x²−y²]/2 = xy = 10×9 = 90."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20262,"question_number":20263,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 10, y = 9.","x = 10, y = 9 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["361","361"],["360","360"],["363","363"],["362","362"]],"answer":0,"explanation":["(x+y)² = (10+9)² = 361.","(x+y)² = (10+9)² = 361."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20263,"question_number":20264,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^10 × 7^9 = 7^m, what is m?","7^10 × 7^9 = 7^m எனில் m என்ன?"],"options":[["18","18"],["21","21"],["19","19"],["20","20"]],"answer":2,"explanation":["m = 10 + 9 = 19.","m = 10 + 9 = 19."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20264,"question_number":20265,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^10)^9 = 2^m, find m.","(2^10)^9 = 2^m எனில் m காண்க."],"options":[["91","91"],["92","92"],["90","90"],["89","89"]],"answer":2,"explanation":["m = 10 × 9 = 90.","m = 10 × 9 = 90."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20265,"question_number":20266,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 11881.","11881 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["109","109"],["110","110"],["111","111"],["108","108"]],"answer":0,"explanation":["109 × 109 = 11881; √11881 = 109.","109 × 109 = 11881; √11881 = 109."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20266,"question_number":20267,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 1295029.","1295029 இன் கனமூலத்தைக் காண்க."],"options":[["110","110"],["111","111"],["109","109"],["108","108"]],"answer":2,"explanation":["109 × 109 × 109 = 1295029; cube root = 109.","109 × 109 × 109 = 1295029; கனமூலம் = 109."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20267,"question_number":20268,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 45% of ₹200.","₹200 இன் 45% காண்க."],"options":[["92","92"],["90","90"],["91","91"],["89","89"]],"answer":1,"explanation":["200×45/100 = 90.","200×45/100 = 90."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20268,"question_number":20269,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹1000 has a 45% discount. What is the sale price in rupees?","₹1000 குறித்த விலையுள்ள பைக்கு 45% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["550","550"],["551","551"],["549","549"],["552","552"]],"answer":0,"explanation":["1000 × (100−45)/100 = 550.","1000 × (100−45)/100 = 550."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20269,"question_number":20270,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹1000 sells for ₹1450. Find the profit percentage.","₹1000 க்கு வாங்கிய பொருள் ₹1450 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["45","45"],["47","47"],["46","46"],["44","44"]],"answer":0,"explanation":["(1450−1000)/1000×100 = 45%.","(1450−1000)/1000×100 = 45%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20270,"question_number":20271,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹10000 at 9% per year for 3 years.","₹10000 க்கு ஆண்டுக்கு 9% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2699","2699"],["2701","2701"],["2700","2700"],["2702","2702"]],"answer":2,"explanation":["10000×9×3/100 = 2700.","10000×9×3/100 = 2700."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20271,"question_number":20272,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹100000 at 9% a year for 2 years, compounded annually.","₹100000 க்கு ஆண்டுக்கு 9% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["18809","18809"],["18810","18810"],["18811","18811"],["18812","18812"]],"answer":1,"explanation":["100000×[(1+9/100)²−1] = 18810.","100000×[(1+9/100)²−1] = 18810."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20272,"question_number":20273,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["9 metres of cloth cost ₹100. At the same rate, what is the cost of 12 metres in rupees?","9 மீ துணியின் விலை ₹100. அதே வீதத்தில் 12 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["400/3","400/3"],["406/3","406/3"],["403/3","403/3"],["397/3","397/3"]],"answer":0,"explanation":["100/9×12 = 400/3.","100/9×12 = 400/3."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20273,"question_number":20274,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["9 equally efficient machines complete a job in 10 hours. How many hours do 11 such machines require at the same rate?","சமத் திறனுடைய 9 இயந்திரங்கள் வேலையை 10 மணியில் முடிக்கின்றன. அதே வீதத்தில் 11 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["112/11","112/11"],["90/11","90/11"],["79/11","79/11"],["101/11","101/11"]],"answer":1,"explanation":["9×10/(9+2) = 90/11 hours.","9×10/(9+2) = 90/11 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20274,"question_number":20275,"practice_set":811},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 20 cm and perpendicular height 9 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 20 செமீ; செங்குத்து உயரம் 9 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["181","181"],["182","182"],["179","179"],["180","180"]],"answer":3,"explanation":["20×9 = 180.","20×9 = 180."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20275,"question_number":20276,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 20 cm and 18 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 20 செமீ, 18 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["181","181"],["179","179"],["180","180"],["182","182"]],"answer":2,"explanation":["½×20×18 = 180 cm².","½×20×18 = 180 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20276,"question_number":20277,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 20 m and 38 m, and height 9 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 20 மீ, 38 மீ; உயரம் 9 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["262","262"],["263","263"],["261","261"],["260","260"]],"answer":2,"explanation":["½×(20+38)×9 = 261.","½×(20+38)×9 = 261."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20277,"question_number":20278,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 70 cm makes 9 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","70 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 9 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["3962","3962"],["3959","3959"],["3960","3960"],["3961","3961"]],"answer":2,"explanation":["9×2×22/7×70 = 3960.","9×2×22/7×70 = 3960."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20278,"question_number":20279,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 9 circular mats, each of radius 70 cm. Find their total area in cm², using π=22/7.","தலா 70 செமீ ஆரமுள்ள 9 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["138601","138601"],["138599","138599"],["138600","138600"],["138602","138602"]],"answer":2,"explanation":["9×22/7×70² = 138600.","9×22/7×70² = 138600."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20279,"question_number":20280,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 40° and 48°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 40°, 48°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["92","92"],["93","93"],["91","91"],["94","94"]],"answer":0,"explanation":["180−40−48 = 92°.","180−40−48 = 92°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20280,"question_number":20281,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 60°. One remote interior angle is 29°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 60°. அதற்கான ஓர் எதிர் உட்கோணம் 29°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["31","31"],["30","30"],["32","32"],["33","33"]],"answer":0,"explanation":["60 − 29 = 31°.","60 − 29 = 31°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20281,"question_number":20282,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 10, 19, 28, 37, 46.","10, 19, 28, 37, 46 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["28","28"],["30","30"],["27","27"],["29","29"]],"answer":0,"explanation":["Sum/5 = 140/5 = 28.","கூடுதல்/5 = 140/5 = 28."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20282,"question_number":20283,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 55, 10, 28, 73, 19.","வரிசைப்படுத்தி இடைநிலை காண்க: 55, 10, 28, 73, 19."],"options":[["30","30"],["27","27"],["29","29"],["28","28"]],"answer":3,"explanation":["Sorted: 10, 19, 28, 55, 73; middle value = 28.","வரிசை: 10, 19, 28, 55, 73; நடு மதிப்பு = 28."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20283,"question_number":20284,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 10, 19, 10, 28, 37, 10?","10, 19, 10, 28, 37, 10 தரவுகளின் முகடு எது?"],"options":[["9","9"],["10","10"],["11","11"],["12","12"]],"answer":1,"explanation":["10 occurs 3 times; each other value occurs once.","10 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20284,"question_number":20285,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 10 hours and another in 9 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 10 மணியிலும் மற்றொன்று 9 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["71/19","71/19"],["128/19","128/19"],["109/19","109/19"],["90/19","90/19"]],"answer":3,"explanation":["Combined hourly rate = 1/10+1/9; time = 90/19 = 90/19 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/10+1/9; காலம் = 90/19 = 90/19 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20285,"question_number":20286,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −10/9. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −10/9. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["1/9","1/9"],["28/9","28/9"],["19/9","19/9"],["10/9","10/9"]],"answer":3,"explanation":["−10/9 + 10/9 = 0. Simplified additive inverse: 10/9.","−10/9 + 10/9 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 10/9."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20286,"question_number":20287,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 10 and 9?","10 மற்றும் 9 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["23/2","23/2"],["17/2","17/2"],["21/2","21/2"],["19/2","19/2"]],"answer":3,"explanation":["(10+9)/2 = 19/2.","(10+9)/2 = 19/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20287,"question_number":20288,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 11/9 + 1/10.","கூட்டிச் சுருக்குக: 11/9 + 1/10."],"options":[["29/90","29/90"],["209/90","209/90"],["299/90","299/90"],["119/90","119/90"]],"answer":3,"explanation":["[11×10 + 9]/[9×10] = 119/90.","[11×10 + 9]/[9×10] = 119/90."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20288,"question_number":20289,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 11/9 − 1/10.","கழித்துச் சுருக்குக: 11/9 − 1/10."],"options":[["191/90","191/90"],["11/90","11/90"],["281/90","281/90"],["101/90","101/90"]],"answer":3,"explanation":["[11×10 − 9]/[9×10] = 101/90.","[11×10 − 9]/[9×10] = 101/90."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20289,"question_number":20290,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−11/9) × (10/12).","(−11/9) × (10/12) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-1/54","-1/54"],["53/54","53/54"],["-55/54","-55/54"],["-109/54","-109/54"]],"answer":2,"explanation":["−110/108 = -55/54.","−110/108 = -55/54."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20290,"question_number":20291,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (11/9) ÷ (12/10) in simplest form.","(11/9) ÷ (12/10) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["55/54","55/54"],["1/54","1/54"],["109/54","109/54"],["163/54","163/54"]],"answer":0,"explanation":["(11/9) × (10/12) = 55/54.","(11/9) × (10/12) = 55/54."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20291,"question_number":20292,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 11.9 and 0.09.","11.9 மற்றும் 0.09 தசம எண்களைக் கூட்டுக."],"options":[["12.00","12.00"],["11.99","11.99"],["11.98","11.98"],["12.09","12.09"]],"answer":1,"explanation":["11.9 + 0.09 = 11.99.","11.9 + 0.09 = 11.99."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20292,"question_number":20293,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 9x + 11 = 191.","9x + 11 = 191 சமன்பாட்டைத் தீர்க்க."],"options":[["22","22"],["20","20"],["21","21"],["19","19"]],"answer":1,"explanation":["x = (191 − 11)/9 = 20.","x = (191 − 11)/9 = 20."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20293,"question_number":20294,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 11 and y = 9, find (x+y)² − x² − y², then divide by 2.","x = 11, y = 9 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["99","99"],["101","101"],["100","100"],["98","98"]],"answer":0,"explanation":["[(x+y)²−x²−y²]/2 = xy = 11×9 = 99.","[(x+y)²−x²−y²]/2 = xy = 11×9 = 99."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20294,"question_number":20295,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 11, y = 9.","x = 11, y = 9 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["399","399"],["402","402"],["401","401"],["400","400"]],"answer":3,"explanation":["(x+y)² = (11+9)² = 400.","(x+y)² = (11+9)² = 400."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20295,"question_number":20296,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^11 × 7^9 = 7^m, what is m?","7^11 × 7^9 = 7^m எனில் m என்ன?"],"options":[["20","20"],["22","22"],["21","21"],["19","19"]],"answer":0,"explanation":["m = 11 + 9 = 20.","m = 11 + 9 = 20."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20296,"question_number":20297,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^11)^9 = 2^m, find m.","(2^11)^9 = 2^m எனில் m காண்க."],"options":[["101","101"],["98","98"],["99","99"],["100","100"]],"answer":2,"explanation":["m = 11 × 9 = 99.","m = 11 × 9 = 99."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20297,"question_number":20298,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 14161.","14161 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["119","119"],["118","118"],["121","121"],["120","120"]],"answer":0,"explanation":["119 × 119 = 14161; √14161 = 119.","119 × 119 = 14161; √14161 = 119."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20298,"question_number":20299,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 1685159.","1685159 இன் கனமூலத்தைக் காண்க."],"options":[["120","120"],["118","118"],["119","119"],["121","121"]],"answer":2,"explanation":["119 × 119 × 119 = 1685159; cube root = 119.","119 × 119 × 119 = 1685159; கனமூலம் = 119."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20299,"question_number":20300,"practice_set":812},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 45% of ₹220.","₹220 இன் 45% காண்க."],"options":[["101","101"],["99","99"],["100","100"],["98","98"]],"answer":1,"explanation":["220×45/100 = 99.","220×45/100 = 99."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20300,"question_number":20301,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹1100 has a 45% discount. What is the sale price in rupees?","₹1100 குறித்த விலையுள்ள பைக்கு 45% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["606","606"],["605","605"],["604","604"],["607","607"]],"answer":1,"explanation":["1100 × (100−45)/100 = 605.","1100 × (100−45)/100 = 605."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20301,"question_number":20302,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹1100 sells for ₹1595. Find the profit percentage.","₹1100 க்கு வாங்கிய பொருள் ₹1595 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["47","47"],["45","45"],["44","44"],["46","46"]],"answer":1,"explanation":["(1595−1100)/1100×100 = 45%.","(1595−1100)/1100×100 = 45%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20302,"question_number":20303,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹11000 at 9% per year for 3 years.","₹11000 க்கு ஆண்டுக்கு 9% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2969","2969"],["2971","2971"],["2970","2970"],["2972","2972"]],"answer":2,"explanation":["11000×9×3/100 = 2970.","11000×9×3/100 = 2970."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20303,"question_number":20304,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹110000 at 9% a year for 2 years, compounded annually.","₹110000 க்கு ஆண்டுக்கு 9% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["20692","20692"],["20691","20691"],["20693","20693"],["20690","20690"]],"answer":1,"explanation":["110000×[(1+9/100)²−1] = 20691.","110000×[(1+9/100)²−1] = 20691."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20304,"question_number":20305,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["9 metres of cloth cost ₹110. At the same rate, what is the cost of 12 metres in rupees?","9 மீ துணியின் விலை ₹110. அதே வீதத்தில் 12 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["443/3","443/3"],["437/3","437/3"],["446/3","446/3"],["440/3","440/3"]],"answer":3,"explanation":["110/9×12 = 440/3.","110/9×12 = 440/3."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20305,"question_number":20306,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["9 equally efficient machines complete a job in 11 hours. How many hours do 11 such machines require at the same rate?","சமத் திறனுடைய 9 இயந்திரங்கள் வேலையை 11 மணியில் முடிக்கின்றன. அதே வீதத்தில் 11 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["11","11"],["10","10"],["8","8"],["9","9"]],"answer":3,"explanation":["9×11/(9+2) = 9 hours.","9×11/(9+2) = 9 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20306,"question_number":20307,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 22 cm and perpendicular height 9 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 22 செமீ; செங்குத்து உயரம் 9 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["200","200"],["199","199"],["197","197"],["198","198"]],"answer":3,"explanation":["22×9 = 198.","22×9 = 198."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20307,"question_number":20308,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 22 cm and 18 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 22 செமீ, 18 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["197","197"],["200","200"],["198","198"],["199","199"]],"answer":2,"explanation":["½×22×18 = 198 cm².","½×22×18 = 198 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20308,"question_number":20309,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 22 m and 40 m, and height 9 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 22 மீ, 40 மீ; உயரம் 9 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["278","278"],["280","280"],["281","281"],["279","279"]],"answer":3,"explanation":["½×(22+40)×9 = 279.","½×(22+40)×9 = 279."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20309,"question_number":20310,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 77 cm makes 9 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","77 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 9 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["4357","4357"],["4356","4356"],["4358","4358"],["4355","4355"]],"answer":1,"explanation":["9×2×22/7×77 = 4356.","9×2×22/7×77 = 4356."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20310,"question_number":20311,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 9 circular mats, each of radius 77 cm. Find their total area in cm², using π=22/7.","தலா 77 செமீ ஆரமுள்ள 9 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["167705","167705"],["167706","167706"],["167708","167708"],["167707","167707"]],"answer":1,"explanation":["9×22/7×77² = 167706.","9×22/7×77² = 167706."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20311,"question_number":20312,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 42° and 48°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 42°, 48°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["91","91"],["92","92"],["90","90"],["89","89"]],"answer":2,"explanation":["180−42−48 = 90°.","180−42−48 = 90°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20312,"question_number":20313,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 61°. One remote interior angle is 29°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 61°. அதற்கான ஓர் எதிர் உட்கோணம் 29°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["34","34"],["33","33"],["31","31"],["32","32"]],"answer":3,"explanation":["61 − 29 = 32°.","61 − 29 = 32°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20313,"question_number":20314,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 11, 20, 29, 38, 47.","11, 20, 29, 38, 47 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["31","31"],["29","29"],["28","28"],["30","30"]],"answer":1,"explanation":["Sum/5 = 145/5 = 29.","கூடுதல்/5 = 145/5 = 29."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20314,"question_number":20315,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 56, 11, 29, 74, 20.","வரிசைப்படுத்தி இடைநிலை காண்க: 56, 11, 29, 74, 20."],"options":[["30","30"],["28","28"],["31","31"],["29","29"]],"answer":3,"explanation":["Sorted: 11, 20, 29, 56, 74; middle value = 29.","வரிசை: 11, 20, 29, 56, 74; நடு மதிப்பு = 29."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20315,"question_number":20316,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 11, 20, 11, 29, 38, 11?","11, 20, 11, 29, 38, 11 தரவுகளின் முகடு எது?"],"options":[["13","13"],["11","11"],["12","12"],["10","10"]],"answer":1,"explanation":["11 occurs 3 times; each other value occurs once.","11 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20316,"question_number":20317,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 11 hours and another in 9 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 11 மணியிலும் மற்றொன்று 9 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["139/20","139/20"],["99/20","99/20"],["119/20","119/20"],["79/20","79/20"]],"answer":1,"explanation":["Combined hourly rate = 1/11+1/9; time = 99/20 = 99/20 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/11+1/9; காலம் = 99/20 = 99/20 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20317,"question_number":20318,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −11/9. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −11/9. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["11/9","11/9"],["29/9","29/9"],["2/9","2/9"],["20/9","20/9"]],"answer":0,"explanation":["−11/9 + 11/9 = 0. Simplified additive inverse: 11/9.","−11/9 + 11/9 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 11/9."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20318,"question_number":20319,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 11 and 9?","11 மற்றும் 9 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["9","9"],["12","12"],["10","10"],["11","11"]],"answer":2,"explanation":["(11+9)/2 = 10.","(11+9)/2 = 10."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20319,"question_number":20320,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 2/10 + 1/11.","கூட்டிச் சுருக்குக: 2/10 + 1/11."],"options":[["71/55","71/55"],["16/55","16/55"],["-39/55","-39/55"],["126/55","126/55"]],"answer":1,"explanation":["[2×11 + 10]/[10×11] = 16/55.","[2×11 + 10]/[10×11] = 16/55."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20320,"question_number":20321,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 2/10 − 1/11.","கழித்துச் சுருக்குக: 2/10 − 1/11."],"options":[["61/55","61/55"],["-49/55","-49/55"],["116/55","116/55"],["6/55","6/55"]],"answer":3,"explanation":["[2×11 − 10]/[10×11] = 6/55.","[2×11 − 10]/[10×11] = 6/55."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20321,"question_number":20322,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−2/10) × (11/3).","(−2/10) × (11/3) பெருக்கற்பலனைச் சுருக்குக."],"options":[["4/15","4/15"],["19/15","19/15"],["-11/15","-11/15"],["-26/15","-26/15"]],"answer":2,"explanation":["−22/30 = -11/15.","−22/30 = -11/15."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20322,"question_number":20323,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (2/10) ÷ (3/11) in simplest form.","(2/10) ÷ (3/11) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["-4/15","-4/15"],["41/15","41/15"],["26/15","26/15"],["11/15","11/15"]],"answer":3,"explanation":["(2/10) × (11/3) = 11/15.","(2/10) × (11/3) = 11/15."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20323,"question_number":20324,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 3.0 and 0.10.","3.0 மற்றும் 0.10 தசம எண்களைக் கூட்டுக."],"options":[["3.10","3.10"],["3.20","3.20"],["3.11","3.11"],["3.09","3.09"]],"answer":0,"explanation":["3.0 + 0.10 = 3.10.","3.0 + 0.10 = 3.10."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20324,"question_number":20325,"practice_set":813},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 10x + 2 = 122.","10x + 2 = 122 சமன்பாட்டைத் தீர்க்க."],"options":[["11","11"],["12","12"],["13","13"],["14","14"]],"answer":1,"explanation":["x = (122 − 2)/10 = 12.","x = (122 − 2)/10 = 12."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20325,"question_number":20326,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 2 and y = 10, find (x+y)² − x² − y², then divide by 2.","x = 2, y = 10 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["21","21"],["20","20"],["19","19"],["22","22"]],"answer":1,"explanation":["[(x+y)²−x²−y²]/2 = xy = 2×10 = 20.","[(x+y)²−x²−y²]/2 = xy = 2×10 = 20."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20326,"question_number":20327,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 2, y = 10.","x = 2, y = 10 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["144","144"],["145","145"],["146","146"],["143","143"]],"answer":0,"explanation":["(x+y)² = (2+10)² = 144.","(x+y)² = (2+10)² = 144."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20327,"question_number":20328,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^2 × 7^10 = 7^m, what is m?","7^2 × 7^10 = 7^m எனில் m என்ன?"],"options":[["11","11"],["12","12"],["14","14"],["13","13"]],"answer":1,"explanation":["m = 2 + 10 = 12.","m = 2 + 10 = 12."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20328,"question_number":20329,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^2)^10 = 2^m, find m.","(2^2)^10 = 2^m எனில் m காண்க."],"options":[["21","21"],["19","19"],["20","20"],["22","22"]],"answer":2,"explanation":["m = 2 × 10 = 20.","m = 2 × 10 = 20."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20329,"question_number":20330,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 900.","900 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["30","30"],["31","31"],["32","32"],["29","29"]],"answer":0,"explanation":["30 × 30 = 900; √900 = 30.","30 × 30 = 900; √900 = 30."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20330,"question_number":20331,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 27000.","27000 இன் கனமூலத்தைக் காண்க."],"options":[["29","29"],["30","30"],["32","32"],["31","31"]],"answer":1,"explanation":["30 × 30 × 30 = 27000; cube root = 30.","30 × 30 × 30 = 27000; கனமூலம் = 30."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20331,"question_number":20332,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 50% of ₹40.","₹40 இன் 50% காண்க."],"options":[["22","22"],["20","20"],["19","19"],["21","21"]],"answer":1,"explanation":["40×50/100 = 20.","40×50/100 = 20."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20332,"question_number":20333,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹200 has a 50% discount. What is the sale price in rupees?","₹200 குறித்த விலையுள்ள பைக்கு 50% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["101","101"],["102","102"],["99","99"],["100","100"]],"answer":3,"explanation":["200 × (100−50)/100 = 100.","200 × (100−50)/100 = 100."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20333,"question_number":20334,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹200 sells for ₹300. Find the profit percentage.","₹200 க்கு வாங்கிய பொருள் ₹300 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["49","49"],["52","52"],["50","50"],["51","51"]],"answer":2,"explanation":["(300−200)/200×100 = 50%.","(300−200)/200×100 = 50%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20334,"question_number":20335,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹2000 at 10% per year for 3 years.","₹2000 க்கு ஆண்டுக்கு 10% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["600","600"],["601","601"],["599","599"],["602","602"]],"answer":0,"explanation":["2000×10×3/100 = 600.","2000×10×3/100 = 600."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20335,"question_number":20336,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹20000 at 10% a year for 2 years, compounded annually.","₹20000 க்கு ஆண்டுக்கு 10% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["4200","4200"],["4202","4202"],["4201","4201"],["4199","4199"]],"answer":0,"explanation":["20000×[(1+10/100)²−1] = 4200.","20000×[(1+10/100)²−1] = 4200."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20336,"question_number":20337,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["10 metres of cloth cost ₹20. At the same rate, what is the cost of 13 metres in rupees?","10 மீ துணியின் விலை ₹20. அதே வீதத்தில் 13 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["25","25"],["26","26"],["28","28"],["27","27"]],"answer":1,"explanation":["20/10×13 = 26.","20/10×13 = 26."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20337,"question_number":20338,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["10 equally efficient machines complete a job in 2 hours. How many hours do 12 such machines require at the same rate?","சமத் திறனுடைய 10 இயந்திரங்கள் வேலையை 2 மணியில் முடிக்கின்றன. அதே வீதத்தில் 12 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["11/3","11/3"],["5/3","5/3"],["8/3","8/3"],["2/3","2/3"]],"answer":1,"explanation":["10×2/(10+2) = 5/3 hours.","10×2/(10+2) = 5/3 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20338,"question_number":20339,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 4 cm and perpendicular height 10 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 4 செமீ; செங்குத்து உயரம் 10 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["42","42"],["41","41"],["39","39"],["40","40"]],"answer":3,"explanation":["4×10 = 40.","4×10 = 40."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20339,"question_number":20340,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 4 cm and 20 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 4 செமீ, 20 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["42","42"],["39","39"],["41","41"],["40","40"]],"answer":3,"explanation":["½×4×20 = 40 cm².","½×4×20 = 40 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20340,"question_number":20341,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 4 m and 24 m, and height 10 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 4 மீ, 24 மீ; உயரம் 10 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["140","140"],["139","139"],["142","142"],["141","141"]],"answer":0,"explanation":["½×(4+24)×10 = 140.","½×(4+24)×10 = 140."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20341,"question_number":20342,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 14 cm makes 10 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","14 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 10 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["882","882"],["879","879"],["880","880"],["881","881"]],"answer":2,"explanation":["10×2×22/7×14 = 880.","10×2×22/7×14 = 880."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20342,"question_number":20343,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 10 circular mats, each of radius 14 cm. Find their total area in cm², using π=22/7.","தலா 14 செமீ ஆரமுள்ள 10 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["6159","6159"],["6162","6162"],["6161","6161"],["6160","6160"]],"answer":3,"explanation":["10×22/7×14² = 6160.","10×22/7×14² = 6160."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20343,"question_number":20344,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 24° and 50°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 24°, 50°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["106","106"],["105","105"],["108","108"],["107","107"]],"answer":0,"explanation":["180−24−50 = 106°.","180−24−50 = 106°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20344,"question_number":20345,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 52°. One remote interior angle is 30°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 52°. அதற்கான ஓர் எதிர் உட்கோணம் 30°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["24","24"],["23","23"],["22","22"],["21","21"]],"answer":2,"explanation":["52 − 30 = 22°.","52 − 30 = 22°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20345,"question_number":20346,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 2, 12, 22, 32, 42.","2, 12, 22, 32, 42 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["23","23"],["22","22"],["21","21"],["24","24"]],"answer":1,"explanation":["Sum/5 = 110/5 = 22.","கூடுதல்/5 = 110/5 = 22."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20346,"question_number":20347,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 52, 2, 22, 72, 12.","வரிசைப்படுத்தி இடைநிலை காண்க: 52, 2, 22, 72, 12."],"options":[["23","23"],["22","22"],["21","21"],["24","24"]],"answer":1,"explanation":["Sorted: 2, 12, 22, 52, 72; middle value = 22.","வரிசை: 2, 12, 22, 52, 72; நடு மதிப்பு = 22."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20347,"question_number":20348,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 2, 12, 2, 22, 32, 2?","2, 12, 2, 22, 32, 2 தரவுகளின் முகடு எது?"],"options":[["1","1"],["2","2"],["3","3"],["4","4"]],"answer":1,"explanation":["2 occurs 3 times; each other value occurs once.","2 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20348,"question_number":20349,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 2 hours and another in 10 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 2 மணியிலும் மற்றொன்று 10 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["5/3","5/3"],["8/3","8/3"],["2/3","2/3"],["11/3","11/3"]],"answer":0,"explanation":["Combined hourly rate = 1/2+1/10; time = 20/12 = 5/3 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/2+1/10; காலம் = 20/12 = 5/3 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20349,"question_number":20350,"practice_set":814},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −2/10. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −2/10. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["-4/5","-4/5"],["1/5","1/5"],["6/5","6/5"],["11/5","11/5"]],"answer":1,"explanation":["−2/10 + 2/10 = 0. Simplified additive inverse: 1/5.","−2/10 + 2/10 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 1/5."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20350,"question_number":20351,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 2 and 10?","2 மற்றும் 10 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["8","8"],["5","5"],["7","7"],["6","6"]],"answer":3,"explanation":["(2+10)/2 = 6.","(2+10)/2 = 6."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20351,"question_number":20352,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 3/10 + 1/11.","கூட்டிச் சுருக்குக: 3/10 + 1/11."],"options":[["263/110","263/110"],["43/110","43/110"],["-67/110","-67/110"],["153/110","153/110"]],"answer":1,"explanation":["[3×11 + 10]/[10×11] = 43/110.","[3×11 + 10]/[10×11] = 43/110."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20352,"question_number":20353,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 3/10 − 1/11.","கழித்துச் சுருக்குக: 3/10 − 1/11."],"options":[["243/110","243/110"],["-87/110","-87/110"],["133/110","133/110"],["23/110","23/110"]],"answer":3,"explanation":["[3×11 − 10]/[10×11] = 23/110.","[3×11 − 10]/[10×11] = 23/110."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20353,"question_number":20354,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−3/10) × (11/4).","(−3/10) × (11/4) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-33/40","-33/40"],["7/40","7/40"],["47/40","47/40"],["-73/40","-73/40"]],"answer":0,"explanation":["−33/40 = -33/40.","−33/40 = -33/40."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20354,"question_number":20355,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (3/10) ÷ (4/11) in simplest form.","(3/10) ÷ (4/11) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["73/40","73/40"],["113/40","113/40"],["33/40","33/40"],["-7/40","-7/40"]],"answer":2,"explanation":["(3/10) × (11/4) = 33/40.","(3/10) × (11/4) = 33/40."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20355,"question_number":20356,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 4.0 and 0.10.","4.0 மற்றும் 0.10 தசம எண்களைக் கூட்டுக."],"options":[["4.09","4.09"],["4.11","4.11"],["4.10","4.10"],["4.20","4.20"]],"answer":2,"explanation":["4.0 + 0.10 = 4.10.","4.0 + 0.10 = 4.10."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20356,"question_number":20357,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 10x + 3 = 133.","10x + 3 = 133 சமன்பாட்டைத் தீர்க்க."],"options":[["12","12"],["14","14"],["15","15"],["13","13"]],"answer":3,"explanation":["x = (133 − 3)/10 = 13.","x = (133 − 3)/10 = 13."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20357,"question_number":20358,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 3 and y = 10, find (x+y)² − x² − y², then divide by 2.","x = 3, y = 10 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["29","29"],["32","32"],["30","30"],["31","31"]],"answer":2,"explanation":["[(x+y)²−x²−y²]/2 = xy = 3×10 = 30.","[(x+y)²−x²−y²]/2 = xy = 3×10 = 30."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20358,"question_number":20359,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 3, y = 10.","x = 3, y = 10 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["169","169"],["170","170"],["168","168"],["171","171"]],"answer":0,"explanation":["(x+y)² = (3+10)² = 169.","(x+y)² = (3+10)² = 169."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20359,"question_number":20360,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^3 × 7^10 = 7^m, what is m?","7^3 × 7^10 = 7^m எனில் m என்ன?"],"options":[["13","13"],["15","15"],["14","14"],["12","12"]],"answer":0,"explanation":["m = 3 + 10 = 13.","m = 3 + 10 = 13."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20360,"question_number":20361,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^3)^10 = 2^m, find m.","(2^3)^10 = 2^m எனில் m காண்க."],"options":[["29","29"],["32","32"],["31","31"],["30","30"]],"answer":3,"explanation":["m = 3 × 10 = 30.","m = 3 × 10 = 30."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20361,"question_number":20362,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 1600.","1600 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["40","40"],["39","39"],["42","42"],["41","41"]],"answer":0,"explanation":["40 × 40 = 1600; √1600 = 40.","40 × 40 = 1600; √1600 = 40."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20362,"question_number":20363,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 64000.","64000 இன் கனமூலத்தைக் காண்க."],"options":[["40","40"],["41","41"],["39","39"],["42","42"]],"answer":0,"explanation":["40 × 40 × 40 = 64000; cube root = 40.","40 × 40 × 40 = 64000; கனமூலம் = 40."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20363,"question_number":20364,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 50% of ₹60.","₹60 இன் 50% காண்க."],"options":[["31","31"],["29","29"],["30","30"],["32","32"]],"answer":2,"explanation":["60×50/100 = 30.","60×50/100 = 30."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20364,"question_number":20365,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹300 has a 50% discount. What is the sale price in rupees?","₹300 குறித்த விலையுள்ள பைக்கு 50% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["150","150"],["152","152"],["151","151"],["149","149"]],"answer":0,"explanation":["300 × (100−50)/100 = 150.","300 × (100−50)/100 = 150."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20365,"question_number":20366,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹300 sells for ₹450. Find the profit percentage.","₹300 க்கு வாங்கிய பொருள் ₹450 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["51","51"],["49","49"],["52","52"],["50","50"]],"answer":3,"explanation":["(450−300)/300×100 = 50%.","(450−300)/300×100 = 50%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20366,"question_number":20367,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹3000 at 10% per year for 3 years.","₹3000 க்கு ஆண்டுக்கு 10% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["900","900"],["899","899"],["902","902"],["901","901"]],"answer":0,"explanation":["3000×10×3/100 = 900.","3000×10×3/100 = 900."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20367,"question_number":20368,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹30000 at 10% a year for 2 years, compounded annually.","₹30000 க்கு ஆண்டுக்கு 10% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["6300","6300"],["6302","6302"],["6301","6301"],["6299","6299"]],"answer":0,"explanation":["30000×[(1+10/100)²−1] = 6300.","30000×[(1+10/100)²−1] = 6300."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20368,"question_number":20369,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["10 metres of cloth cost ₹30. At the same rate, what is the cost of 13 metres in rupees?","10 மீ துணியின் விலை ₹30. அதே வீதத்தில் 13 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["39","39"],["40","40"],["38","38"],["41","41"]],"answer":0,"explanation":["30/10×13 = 39.","30/10×13 = 39."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20369,"question_number":20370,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["10 equally efficient machines complete a job in 3 hours. How many hours do 12 such machines require at the same rate?","சமத் திறனுடைய 10 இயந்திரங்கள் வேலையை 3 மணியில் முடிக்கின்றன. அதே வீதத்தில் 12 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["9/2","9/2"],["7/2","7/2"],["5/2","5/2"],["3/2","3/2"]],"answer":2,"explanation":["10×3/(10+2) = 5/2 hours.","10×3/(10+2) = 5/2 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20370,"question_number":20371,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 6 cm and perpendicular height 10 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 6 செமீ; செங்குத்து உயரம் 10 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["59","59"],["61","61"],["62","62"],["60","60"]],"answer":3,"explanation":["6×10 = 60.","6×10 = 60."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20371,"question_number":20372,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 6 cm and 20 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 6 செமீ, 20 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["60","60"],["59","59"],["62","62"],["61","61"]],"answer":0,"explanation":["½×6×20 = 60 cm².","½×6×20 = 60 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20372,"question_number":20373,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 6 m and 26 m, and height 10 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 6 மீ, 26 மீ; உயரம் 10 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["160","160"],["162","162"],["159","159"],["161","161"]],"answer":0,"explanation":["½×(6+26)×10 = 160.","½×(6+26)×10 = 160."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20373,"question_number":20374,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 21 cm makes 10 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","21 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 10 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["1322","1322"],["1320","1320"],["1319","1319"],["1321","1321"]],"answer":1,"explanation":["10×2×22/7×21 = 1320.","10×2×22/7×21 = 1320."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20374,"question_number":20375,"practice_set":815},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 10 circular mats, each of radius 21 cm. Find their total area in cm², using π=22/7.","தலா 21 செமீ ஆரமுள்ள 10 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["13862","13862"],["13860","13860"],["13861","13861"],["13859","13859"]],"answer":1,"explanation":["10×22/7×21² = 13860.","10×22/7×21² = 13860."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20375,"question_number":20376,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 26° and 50°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 26°, 50°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["104","104"],["106","106"],["105","105"],["103","103"]],"answer":0,"explanation":["180−26−50 = 104°.","180−26−50 = 104°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20376,"question_number":20377,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 53°. One remote interior angle is 30°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 53°. அதற்கான ஓர் எதிர் உட்கோணம் 30°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["24","24"],["23","23"],["25","25"],["22","22"]],"answer":1,"explanation":["53 − 30 = 23°.","53 − 30 = 23°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20377,"question_number":20378,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 3, 13, 23, 33, 43.","3, 13, 23, 33, 43 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["24","24"],["25","25"],["22","22"],["23","23"]],"answer":3,"explanation":["Sum/5 = 115/5 = 23.","கூடுதல்/5 = 115/5 = 23."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20378,"question_number":20379,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 53, 3, 23, 73, 13.","வரிசைப்படுத்தி இடைநிலை காண்க: 53, 3, 23, 73, 13."],"options":[["23","23"],["22","22"],["25","25"],["24","24"]],"answer":0,"explanation":["Sorted: 3, 13, 23, 53, 73; middle value = 23.","வரிசை: 3, 13, 23, 53, 73; நடு மதிப்பு = 23."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20379,"question_number":20380,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 3, 13, 3, 23, 33, 3?","3, 13, 3, 23, 33, 3 தரவுகளின் முகடு எது?"],"options":[["5","5"],["4","4"],["2","2"],["3","3"]],"answer":3,"explanation":["3 occurs 3 times; each other value occurs once.","3 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20380,"question_number":20381,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 3 hours and another in 10 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 3 மணியிலும் மற்றொன்று 10 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["17/13","17/13"],["30/13","30/13"],["56/13","56/13"],["43/13","43/13"]],"answer":1,"explanation":["Combined hourly rate = 1/3+1/10; time = 30/13 = 30/13 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/3+1/10; காலம் = 30/13 = 30/13 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20381,"question_number":20382,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −3/10. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −3/10. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["3/10","3/10"],["23/10","23/10"],["-7/10","-7/10"],["13/10","13/10"]],"answer":0,"explanation":["−3/10 + 3/10 = 0. Simplified additive inverse: 3/10.","−3/10 + 3/10 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 3/10."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20382,"question_number":20383,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 3 and 10?","3 மற்றும் 10 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["11/2","11/2"],["15/2","15/2"],["17/2","17/2"],["13/2","13/2"]],"answer":3,"explanation":["(3+10)/2 = 13/2.","(3+10)/2 = 13/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20383,"question_number":20384,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 4/10 + 1/11.","கூட்டிச் சுருக்குக: 4/10 + 1/11."],"options":[["-28/55","-28/55"],["137/55","137/55"],["27/55","27/55"],["82/55","82/55"]],"answer":2,"explanation":["[4×11 + 10]/[10×11] = 27/55.","[4×11 + 10]/[10×11] = 27/55."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20384,"question_number":20385,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 4/10 − 1/11.","கழித்துச் சுருக்குக: 4/10 − 1/11."],"options":[["-38/55","-38/55"],["72/55","72/55"],["127/55","127/55"],["17/55","17/55"]],"answer":3,"explanation":["[4×11 − 10]/[10×11] = 17/55.","[4×11 − 10]/[10×11] = 17/55."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20385,"question_number":20386,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−4/10) × (11/5).","(−4/10) × (11/5) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-22/25","-22/25"],["-47/25","-47/25"],["28/25","28/25"],["3/25","3/25"]],"answer":0,"explanation":["−44/50 = -22/25.","−44/50 = -22/25."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20386,"question_number":20387,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (4/10) ÷ (5/11) in simplest form.","(4/10) ÷ (5/11) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["72/25","72/25"],["-3/25","-3/25"],["47/25","47/25"],["22/25","22/25"]],"answer":3,"explanation":["(4/10) × (11/5) = 22/25.","(4/10) × (11/5) = 22/25."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20387,"question_number":20388,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 5.0 and 0.10.","5.0 மற்றும் 0.10 தசம எண்களைக் கூட்டுக."],"options":[["5.11","5.11"],["5.10","5.10"],["5.20","5.20"],["5.09","5.09"]],"answer":1,"explanation":["5.0 + 0.10 = 5.10.","5.0 + 0.10 = 5.10."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20388,"question_number":20389,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 10x + 4 = 144.","10x + 4 = 144 சமன்பாட்டைத் தீர்க்க."],"options":[["14","14"],["13","13"],["15","15"],["16","16"]],"answer":0,"explanation":["x = (144 − 4)/10 = 14.","x = (144 − 4)/10 = 14."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20389,"question_number":20390,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 4 and y = 10, find (x+y)² − x² − y², then divide by 2.","x = 4, y = 10 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["41","41"],["40","40"],["39","39"],["42","42"]],"answer":1,"explanation":["[(x+y)²−x²−y²]/2 = xy = 4×10 = 40.","[(x+y)²−x²−y²]/2 = xy = 4×10 = 40."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20390,"question_number":20391,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 4, y = 10.","x = 4, y = 10 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["196","196"],["198","198"],["197","197"],["195","195"]],"answer":0,"explanation":["(x+y)² = (4+10)² = 196.","(x+y)² = (4+10)² = 196."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20391,"question_number":20392,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^4 × 7^10 = 7^m, what is m?","7^4 × 7^10 = 7^m எனில் m என்ன?"],"options":[["14","14"],["13","13"],["15","15"],["16","16"]],"answer":0,"explanation":["m = 4 + 10 = 14.","m = 4 + 10 = 14."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20392,"question_number":20393,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^4)^10 = 2^m, find m.","(2^4)^10 = 2^m எனில் m காண்க."],"options":[["41","41"],["42","42"],["39","39"],["40","40"]],"answer":3,"explanation":["m = 4 × 10 = 40.","m = 4 × 10 = 40."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20393,"question_number":20394,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 2500.","2500 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["51","51"],["52","52"],["50","50"],["49","49"]],"answer":2,"explanation":["50 × 50 = 2500; √2500 = 50.","50 × 50 = 2500; √2500 = 50."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20394,"question_number":20395,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 125000.","125000 இன் கனமூலத்தைக் காண்க."],"options":[["52","52"],["50","50"],["49","49"],["51","51"]],"answer":1,"explanation":["50 × 50 × 50 = 125000; cube root = 50.","50 × 50 × 50 = 125000; கனமூலம் = 50."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20395,"question_number":20396,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 50% of ₹80.","₹80 இன் 50% காண்க."],"options":[["41","41"],["39","39"],["40","40"],["42","42"]],"answer":2,"explanation":["80×50/100 = 40.","80×50/100 = 40."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20396,"question_number":20397,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹400 has a 50% discount. What is the sale price in rupees?","₹400 குறித்த விலையுள்ள பைக்கு 50% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["201","201"],["199","199"],["200","200"],["202","202"]],"answer":2,"explanation":["400 × (100−50)/100 = 200.","400 × (100−50)/100 = 200."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20397,"question_number":20398,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹400 sells for ₹600. Find the profit percentage.","₹400 க்கு வாங்கிய பொருள் ₹600 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["51","51"],["49","49"],["50","50"],["52","52"]],"answer":2,"explanation":["(600−400)/400×100 = 50%.","(600−400)/400×100 = 50%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20398,"question_number":20399,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹4000 at 10% per year for 3 years.","₹4000 க்கு ஆண்டுக்கு 10% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1201","1201"],["1200","1200"],["1202","1202"],["1199","1199"]],"answer":1,"explanation":["4000×10×3/100 = 1200.","4000×10×3/100 = 1200."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20399,"question_number":20400,"practice_set":816},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹40000 at 10% a year for 2 years, compounded annually.","₹40000 க்கு ஆண்டுக்கு 10% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["8402","8402"],["8399","8399"],["8400","8400"],["8401","8401"]],"answer":2,"explanation":["40000×[(1+10/100)²−1] = 8400.","40000×[(1+10/100)²−1] = 8400."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20400,"question_number":20401,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["10 metres of cloth cost ₹40. At the same rate, what is the cost of 13 metres in rupees?","10 மீ துணியின் விலை ₹40. அதே வீதத்தில் 13 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["54","54"],["51","51"],["53","53"],["52","52"]],"answer":3,"explanation":["40/10×13 = 52.","40/10×13 = 52."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20401,"question_number":20402,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["10 equally efficient machines complete a job in 4 hours. How many hours do 12 such machines require at the same rate?","சமத் திறனுடைய 10 இயந்திரங்கள் வேலையை 4 மணியில் முடிக்கின்றன. அதே வீதத்தில் 12 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["7/3","7/3"],["16/3","16/3"],["13/3","13/3"],["10/3","10/3"]],"answer":3,"explanation":["10×4/(10+2) = 10/3 hours.","10×4/(10+2) = 10/3 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20402,"question_number":20403,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 8 cm and perpendicular height 10 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 8 செமீ; செங்குத்து உயரம் 10 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["80","80"],["81","81"],["82","82"],["79","79"]],"answer":0,"explanation":["8×10 = 80.","8×10 = 80."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20403,"question_number":20404,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 8 cm and 20 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 8 செமீ, 20 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["82","82"],["79","79"],["80","80"],["81","81"]],"answer":2,"explanation":["½×8×20 = 80 cm².","½×8×20 = 80 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20404,"question_number":20405,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 8 m and 28 m, and height 10 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 8 மீ, 28 மீ; உயரம் 10 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["181","181"],["180","180"],["182","182"],["179","179"]],"answer":1,"explanation":["½×(8+28)×10 = 180.","½×(8+28)×10 = 180."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20405,"question_number":20406,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 28 cm makes 10 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","28 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 10 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["1762","1762"],["1759","1759"],["1761","1761"],["1760","1760"]],"answer":3,"explanation":["10×2×22/7×28 = 1760.","10×2×22/7×28 = 1760."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20406,"question_number":20407,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 10 circular mats, each of radius 28 cm. Find their total area in cm², using π=22/7.","தலா 28 செமீ ஆரமுள்ள 10 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["24639","24639"],["24640","24640"],["24642","24642"],["24641","24641"]],"answer":1,"explanation":["10×22/7×28² = 24640.","10×22/7×28² = 24640."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20407,"question_number":20408,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 28° and 50°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 28°, 50°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["102","102"],["104","104"],["101","101"],["103","103"]],"answer":0,"explanation":["180−28−50 = 102°.","180−28−50 = 102°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20408,"question_number":20409,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 54°. One remote interior angle is 30°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 54°. அதற்கான ஓர் எதிர் உட்கோணம் 30°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["23","23"],["24","24"],["26","26"],["25","25"]],"answer":1,"explanation":["54 − 30 = 24°.","54 − 30 = 24°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20409,"question_number":20410,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 4, 14, 24, 34, 44.","4, 14, 24, 34, 44 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["25","25"],["23","23"],["26","26"],["24","24"]],"answer":3,"explanation":["Sum/5 = 120/5 = 24.","கூடுதல்/5 = 120/5 = 24."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20410,"question_number":20411,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 54, 4, 24, 74, 14.","வரிசைப்படுத்தி இடைநிலை காண்க: 54, 4, 24, 74, 14."],"options":[["25","25"],["24","24"],["26","26"],["23","23"]],"answer":1,"explanation":["Sorted: 4, 14, 24, 54, 74; middle value = 24.","வரிசை: 4, 14, 24, 54, 74; நடு மதிப்பு = 24."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20411,"question_number":20412,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 4, 14, 4, 24, 34, 4?","4, 14, 4, 24, 34, 4 தரவுகளின் முகடு எது?"],"options":[["5","5"],["4","4"],["6","6"],["3","3"]],"answer":1,"explanation":["4 occurs 3 times; each other value occurs once.","4 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20412,"question_number":20413,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 4 hours and another in 10 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 4 மணியிலும் மற்றொன்று 10 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["27/7","27/7"],["13/7","13/7"],["34/7","34/7"],["20/7","20/7"]],"answer":3,"explanation":["Combined hourly rate = 1/4+1/10; time = 40/14 = 20/7 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/4+1/10; காலம் = 40/14 = 20/7 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20413,"question_number":20414,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −4/10. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −4/10. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["12/5","12/5"],["-3/5","-3/5"],["7/5","7/5"],["2/5","2/5"]],"answer":3,"explanation":["−4/10 + 4/10 = 0. Simplified additive inverse: 2/5.","−4/10 + 4/10 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 2/5."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20414,"question_number":20415,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 4 and 10?","4 மற்றும் 10 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["9","9"],["6","6"],["8","8"],["7","7"]],"answer":3,"explanation":["(4+10)/2 = 7.","(4+10)/2 = 7."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20415,"question_number":20416,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 5/10 + 1/11.","கூட்டிச் சுருக்குக: 5/10 + 1/11."],"options":[["57/22","57/22"],["35/22","35/22"],["-9/22","-9/22"],["13/22","13/22"]],"answer":3,"explanation":["[5×11 + 10]/[10×11] = 13/22.","[5×11 + 10]/[10×11] = 13/22."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20416,"question_number":20417,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 5/10 − 1/11.","கழித்துச் சுருக்குக: 5/10 − 1/11."],"options":[["31/22","31/22"],["9/22","9/22"],["-13/22","-13/22"],["53/22","53/22"]],"answer":1,"explanation":["[5×11 − 10]/[10×11] = 9/22.","[5×11 − 10]/[10×11] = 9/22."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20417,"question_number":20418,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−5/10) × (11/6).","(−5/10) × (11/6) பெருக்கற்பலனைச் சுருக்குக."],"options":[["13/12","13/12"],["-11/12","-11/12"],["1/12","1/12"],["-23/12","-23/12"]],"answer":1,"explanation":["−55/60 = -11/12.","−55/60 = -11/12."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20418,"question_number":20419,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (5/10) ÷ (6/11) in simplest form.","(5/10) ÷ (6/11) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["11/12","11/12"],["-1/12","-1/12"],["35/12","35/12"],["23/12","23/12"]],"answer":0,"explanation":["(5/10) × (11/6) = 11/12.","(5/10) × (11/6) = 11/12."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20419,"question_number":20420,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 6.0 and 0.10.","6.0 மற்றும் 0.10 தசம எண்களைக் கூட்டுக."],"options":[["6.20","6.20"],["6.10","6.10"],["6.11","6.11"],["6.09","6.09"]],"answer":1,"explanation":["6.0 + 0.10 = 6.10.","6.0 + 0.10 = 6.10."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20420,"question_number":20421,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 10x + 5 = 155.","10x + 5 = 155 சமன்பாட்டைத் தீர்க்க."],"options":[["16","16"],["14","14"],["17","17"],["15","15"]],"answer":3,"explanation":["x = (155 − 5)/10 = 15.","x = (155 − 5)/10 = 15."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20421,"question_number":20422,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 5 and y = 10, find (x+y)² − x² − y², then divide by 2.","x = 5, y = 10 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["52","52"],["49","49"],["51","51"],["50","50"]],"answer":3,"explanation":["[(x+y)²−x²−y²]/2 = xy = 5×10 = 50.","[(x+y)²−x²−y²]/2 = xy = 5×10 = 50."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20422,"question_number":20423,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 5, y = 10.","x = 5, y = 10 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["225","225"],["227","227"],["224","224"],["226","226"]],"answer":0,"explanation":["(x+y)² = (5+10)² = 225.","(x+y)² = (5+10)² = 225."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20423,"question_number":20424,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^5 × 7^10 = 7^m, what is m?","7^5 × 7^10 = 7^m எனில் m என்ன?"],"options":[["16","16"],["17","17"],["14","14"],["15","15"]],"answer":3,"explanation":["m = 5 + 10 = 15.","m = 5 + 10 = 15."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20424,"question_number":20425,"practice_set":817},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^5)^10 = 2^m, find m.","(2^5)^10 = 2^m எனில் m காண்க."],"options":[["49","49"],["51","51"],["50","50"],["52","52"]],"answer":2,"explanation":["m = 5 × 10 = 50.","m = 5 × 10 = 50."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20425,"question_number":20426,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 3600.","3600 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["59","59"],["61","61"],["62","62"],["60","60"]],"answer":3,"explanation":["60 × 60 = 3600; √3600 = 60.","60 × 60 = 3600; √3600 = 60."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20426,"question_number":20427,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 216000.","216000 இன் கனமூலத்தைக் காண்க."],"options":[["59","59"],["62","62"],["61","61"],["60","60"]],"answer":3,"explanation":["60 × 60 × 60 = 216000; cube root = 60.","60 × 60 × 60 = 216000; கனமூலம் = 60."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20427,"question_number":20428,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 50% of ₹100.","₹100 இன் 50% காண்க."],"options":[["52","52"],["51","51"],["49","49"],["50","50"]],"answer":3,"explanation":["100×50/100 = 50.","100×50/100 = 50."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20428,"question_number":20429,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹500 has a 50% discount. What is the sale price in rupees?","₹500 குறித்த விலையுள்ள பைக்கு 50% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["249","249"],["252","252"],["250","250"],["251","251"]],"answer":2,"explanation":["500 × (100−50)/100 = 250.","500 × (100−50)/100 = 250."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20429,"question_number":20430,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹500 sells for ₹750. Find the profit percentage.","₹500 க்கு வாங்கிய பொருள் ₹750 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["51","51"],["52","52"],["49","49"],["50","50"]],"answer":3,"explanation":["(750−500)/500×100 = 50%.","(750−500)/500×100 = 50%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20430,"question_number":20431,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹5000 at 10% per year for 3 years.","₹5000 க்கு ஆண்டுக்கு 10% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1500","1500"],["1501","1501"],["1502","1502"],["1499","1499"]],"answer":0,"explanation":["5000×10×3/100 = 1500.","5000×10×3/100 = 1500."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20431,"question_number":20432,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹50000 at 10% a year for 2 years, compounded annually.","₹50000 க்கு ஆண்டுக்கு 10% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["10499","10499"],["10501","10501"],["10502","10502"],["10500","10500"]],"answer":3,"explanation":["50000×[(1+10/100)²−1] = 10500.","50000×[(1+10/100)²−1] = 10500."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20432,"question_number":20433,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["10 metres of cloth cost ₹50. At the same rate, what is the cost of 13 metres in rupees?","10 மீ துணியின் விலை ₹50. அதே வீதத்தில் 13 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["64","64"],["67","67"],["65","65"],["66","66"]],"answer":2,"explanation":["50/10×13 = 65.","50/10×13 = 65."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20433,"question_number":20434,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["10 equally efficient machines complete a job in 5 hours. How many hours do 12 such machines require at the same rate?","சமத் திறனுடைய 10 இயந்திரங்கள் வேலையை 5 மணியில் முடிக்கின்றன. அதே வீதத்தில் 12 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["19/6","19/6"],["37/6","37/6"],["31/6","31/6"],["25/6","25/6"]],"answer":3,"explanation":["10×5/(10+2) = 25/6 hours.","10×5/(10+2) = 25/6 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20434,"question_number":20435,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 10 cm and perpendicular height 10 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 10 செமீ; செங்குத்து உயரம் 10 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["100","100"],["101","101"],["99","99"],["102","102"]],"answer":0,"explanation":["10×10 = 100.","10×10 = 100."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20435,"question_number":20436,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 10 cm and 20 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 10 செமீ, 20 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["101","101"],["100","100"],["99","99"],["102","102"]],"answer":1,"explanation":["½×10×20 = 100 cm².","½×10×20 = 100 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20436,"question_number":20437,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 10 m and 30 m, and height 10 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 10 மீ, 30 மீ; உயரம் 10 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["202","202"],["200","200"],["201","201"],["199","199"]],"answer":1,"explanation":["½×(10+30)×10 = 200.","½×(10+30)×10 = 200."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20437,"question_number":20438,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 35 cm makes 10 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","35 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 10 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["2201","2201"],["2202","2202"],["2199","2199"],["2200","2200"]],"answer":3,"explanation":["10×2×22/7×35 = 2200.","10×2×22/7×35 = 2200."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20438,"question_number":20439,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 10 circular mats, each of radius 35 cm. Find their total area in cm², using π=22/7.","தலா 35 செமீ ஆரமுள்ள 10 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["38501","38501"],["38499","38499"],["38502","38502"],["38500","38500"]],"answer":3,"explanation":["10×22/7×35² = 38500.","10×22/7×35² = 38500."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20439,"question_number":20440,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 30° and 50°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 30°, 50°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["101","101"],["100","100"],["102","102"],["99","99"]],"answer":1,"explanation":["180−30−50 = 100°.","180−30−50 = 100°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20440,"question_number":20441,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 55°. One remote interior angle is 30°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 55°. அதற்கான ஓர் எதிர் உட்கோணம் 30°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["26","26"],["25","25"],["24","24"],["27","27"]],"answer":1,"explanation":["55 − 30 = 25°.","55 − 30 = 25°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20441,"question_number":20442,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 5, 15, 25, 35, 45.","5, 15, 25, 35, 45 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["26","26"],["25","25"],["24","24"],["27","27"]],"answer":1,"explanation":["Sum/5 = 125/5 = 25.","கூடுதல்/5 = 125/5 = 25."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20442,"question_number":20443,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 55, 5, 25, 75, 15.","வரிசைப்படுத்தி இடைநிலை காண்க: 55, 5, 25, 75, 15."],"options":[["26","26"],["27","27"],["24","24"],["25","25"]],"answer":3,"explanation":["Sorted: 5, 15, 25, 55, 75; middle value = 25.","வரிசை: 5, 15, 25, 55, 75; நடு மதிப்பு = 25."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20443,"question_number":20444,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 5, 15, 5, 25, 35, 5?","5, 15, 5, 25, 35, 5 தரவுகளின் முகடு எது?"],"options":[["7","7"],["5","5"],["6","6"],["4","4"]],"answer":1,"explanation":["5 occurs 3 times; each other value occurs once.","5 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20444,"question_number":20445,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 5 hours and another in 10 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 5 மணியிலும் மற்றொன்று 10 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["13/3","13/3"],["16/3","16/3"],["10/3","10/3"],["7/3","7/3"]],"answer":2,"explanation":["Combined hourly rate = 1/5+1/10; time = 50/15 = 10/3 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/5+1/10; காலம் = 50/15 = 10/3 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20445,"question_number":20446,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −5/10. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −5/10. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["5/2","5/2"],["3/2","3/2"],["-1/2","-1/2"],["1/2","1/2"]],"answer":3,"explanation":["−5/10 + 5/10 = 0. Simplified additive inverse: 1/2.","−5/10 + 5/10 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 1/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20446,"question_number":20447,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 5 and 10?","5 மற்றும் 10 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["13/2","13/2"],["15/2","15/2"],["19/2","19/2"],["17/2","17/2"]],"answer":1,"explanation":["(5+10)/2 = 15/2.","(5+10)/2 = 15/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20447,"question_number":20448,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 6/10 + 1/11.","கூட்டிச் சுருக்குக: 6/10 + 1/11."],"options":[["148/55","148/55"],["-17/55","-17/55"],["38/55","38/55"],["93/55","93/55"]],"answer":2,"explanation":["[6×11 + 10]/[10×11] = 38/55.","[6×11 + 10]/[10×11] = 38/55."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20448,"question_number":20449,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 6/10 − 1/11.","கழித்துச் சுருக்குக: 6/10 − 1/11."],"options":[["28/55","28/55"],["-27/55","-27/55"],["83/55","83/55"],["138/55","138/55"]],"answer":0,"explanation":["[6×11 − 10]/[10×11] = 28/55.","[6×11 − 10]/[10×11] = 28/55."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20449,"question_number":20450,"practice_set":818},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−6/10) × (11/7).","(−6/10) × (11/7) பெருக்கற்பலனைச் சுருக்குக."],"options":[["2/35","2/35"],["37/35","37/35"],["-68/35","-68/35"],["-33/35","-33/35"]],"answer":3,"explanation":["−66/70 = -33/35.","−66/70 = -33/35."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20450,"question_number":20451,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (6/10) ÷ (7/11) in simplest form.","(6/10) ÷ (7/11) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["33/35","33/35"],["68/35","68/35"],["-2/35","-2/35"],["103/35","103/35"]],"answer":0,"explanation":["(6/10) × (11/7) = 33/35.","(6/10) × (11/7) = 33/35."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20451,"question_number":20452,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 7.0 and 0.10.","7.0 மற்றும் 0.10 தசம எண்களைக் கூட்டுக."],"options":[["7.10","7.10"],["7.20","7.20"],["7.09","7.09"],["7.11","7.11"]],"answer":0,"explanation":["7.0 + 0.10 = 7.10.","7.0 + 0.10 = 7.10."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20452,"question_number":20453,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 10x + 6 = 166.","10x + 6 = 166 சமன்பாட்டைத் தீர்க்க."],"options":[["18","18"],["16","16"],["17","17"],["15","15"]],"answer":1,"explanation":["x = (166 − 6)/10 = 16.","x = (166 − 6)/10 = 16."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20453,"question_number":20454,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 6 and y = 10, find (x+y)² − x² − y², then divide by 2.","x = 6, y = 10 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["60","60"],["62","62"],["59","59"],["61","61"]],"answer":0,"explanation":["[(x+y)²−x²−y²]/2 = xy = 6×10 = 60.","[(x+y)²−x²−y²]/2 = xy = 6×10 = 60."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20454,"question_number":20455,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 6, y = 10.","x = 6, y = 10 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["257","257"],["256","256"],["258","258"],["255","255"]],"answer":1,"explanation":["(x+y)² = (6+10)² = 256.","(x+y)² = (6+10)² = 256."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20455,"question_number":20456,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^6 × 7^10 = 7^m, what is m?","7^6 × 7^10 = 7^m எனில் m என்ன?"],"options":[["18","18"],["15","15"],["17","17"],["16","16"]],"answer":3,"explanation":["m = 6 + 10 = 16.","m = 6 + 10 = 16."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20456,"question_number":20457,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^6)^10 = 2^m, find m.","(2^6)^10 = 2^m எனில் m காண்க."],"options":[["61","61"],["62","62"],["59","59"],["60","60"]],"answer":3,"explanation":["m = 6 × 10 = 60.","m = 6 × 10 = 60."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20457,"question_number":20458,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 4900.","4900 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["70","70"],["72","72"],["71","71"],["69","69"]],"answer":0,"explanation":["70 × 70 = 4900; √4900 = 70.","70 × 70 = 4900; √4900 = 70."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20458,"question_number":20459,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 343000.","343000 இன் கனமூலத்தைக் காண்க."],"options":[["70","70"],["72","72"],["71","71"],["69","69"]],"answer":0,"explanation":["70 × 70 × 70 = 343000; cube root = 70.","70 × 70 × 70 = 343000; கனமூலம் = 70."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20459,"question_number":20460,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 50% of ₹120.","₹120 இன் 50% காண்க."],"options":[["60","60"],["59","59"],["61","61"],["62","62"]],"answer":0,"explanation":["120×50/100 = 60.","120×50/100 = 60."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20460,"question_number":20461,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹600 has a 50% discount. What is the sale price in rupees?","₹600 குறித்த விலையுள்ள பைக்கு 50% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["299","299"],["301","301"],["302","302"],["300","300"]],"answer":3,"explanation":["600 × (100−50)/100 = 300.","600 × (100−50)/100 = 300."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20461,"question_number":20462,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹600 sells for ₹900. Find the profit percentage.","₹600 க்கு வாங்கிய பொருள் ₹900 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["49","49"],["51","51"],["52","52"],["50","50"]],"answer":3,"explanation":["(900−600)/600×100 = 50%.","(900−600)/600×100 = 50%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20462,"question_number":20463,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹6000 at 10% per year for 3 years.","₹6000 க்கு ஆண்டுக்கு 10% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1800","1800"],["1802","1802"],["1799","1799"],["1801","1801"]],"answer":0,"explanation":["6000×10×3/100 = 1800.","6000×10×3/100 = 1800."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20463,"question_number":20464,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹60000 at 10% a year for 2 years, compounded annually.","₹60000 க்கு ஆண்டுக்கு 10% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["12599","12599"],["12601","12601"],["12602","12602"],["12600","12600"]],"answer":3,"explanation":["60000×[(1+10/100)²−1] = 12600.","60000×[(1+10/100)²−1] = 12600."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20464,"question_number":20465,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["10 metres of cloth cost ₹60. At the same rate, what is the cost of 13 metres in rupees?","10 மீ துணியின் விலை ₹60. அதே வீதத்தில் 13 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["79","79"],["80","80"],["77","77"],["78","78"]],"answer":3,"explanation":["60/10×13 = 78.","60/10×13 = 78."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20465,"question_number":20466,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["10 equally efficient machines complete a job in 6 hours. How many hours do 12 such machines require at the same rate?","சமத் திறனுடைய 10 இயந்திரங்கள் வேலையை 6 மணியில் முடிக்கின்றன. அதே வீதத்தில் 12 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["5","5"],["7","7"],["6","6"],["4","4"]],"answer":0,"explanation":["10×6/(10+2) = 5 hours.","10×6/(10+2) = 5 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20466,"question_number":20467,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 12 cm and perpendicular height 10 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 12 செமீ; செங்குத்து உயரம் 10 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["120","120"],["119","119"],["122","122"],["121","121"]],"answer":0,"explanation":["12×10 = 120.","12×10 = 120."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20467,"question_number":20468,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 12 cm and 20 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 12 செமீ, 20 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["121","121"],["120","120"],["122","122"],["119","119"]],"answer":1,"explanation":["½×12×20 = 120 cm².","½×12×20 = 120 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20468,"question_number":20469,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 12 m and 32 m, and height 10 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 12 மீ, 32 மீ; உயரம் 10 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["220","220"],["222","222"],["221","221"],["219","219"]],"answer":0,"explanation":["½×(12+32)×10 = 220.","½×(12+32)×10 = 220."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20469,"question_number":20470,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 42 cm makes 10 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","42 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 10 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["2640","2640"],["2641","2641"],["2639","2639"],["2642","2642"]],"answer":0,"explanation":["10×2×22/7×42 = 2640.","10×2×22/7×42 = 2640."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20470,"question_number":20471,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 10 circular mats, each of radius 42 cm. Find their total area in cm², using π=22/7.","தலா 42 செமீ ஆரமுள்ள 10 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["55441","55441"],["55440","55440"],["55442","55442"],["55439","55439"]],"answer":1,"explanation":["10×22/7×42² = 55440.","10×22/7×42² = 55440."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20471,"question_number":20472,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 32° and 50°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 32°, 50°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["99","99"],["100","100"],["97","97"],["98","98"]],"answer":3,"explanation":["180−32−50 = 98°.","180−32−50 = 98°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20472,"question_number":20473,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 56°. One remote interior angle is 30°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 56°. அதற்கான ஓர் எதிர் உட்கோணம் 30°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["27","27"],["25","25"],["26","26"],["28","28"]],"answer":2,"explanation":["56 − 30 = 26°.","56 − 30 = 26°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20473,"question_number":20474,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 6, 16, 26, 36, 46.","6, 16, 26, 36, 46 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["28","28"],["26","26"],["27","27"],["25","25"]],"answer":1,"explanation":["Sum/5 = 130/5 = 26.","கூடுதல்/5 = 130/5 = 26."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20474,"question_number":20475,"practice_set":819},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 56, 6, 26, 76, 16.","வரிசைப்படுத்தி இடைநிலை காண்க: 56, 6, 26, 76, 16."],"options":[["26","26"],["27","27"],["25","25"],["28","28"]],"answer":0,"explanation":["Sorted: 6, 16, 26, 56, 76; middle value = 26.","வரிசை: 6, 16, 26, 56, 76; நடு மதிப்பு = 26."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20475,"question_number":20476,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 6, 16, 6, 26, 36, 6?","6, 16, 6, 26, 36, 6 தரவுகளின் முகடு எது?"],"options":[["5","5"],["7","7"],["6","6"],["8","8"]],"answer":2,"explanation":["6 occurs 3 times; each other value occurs once.","6 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20476,"question_number":20477,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 6 hours and another in 10 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 6 மணியிலும் மற்றொன்று 10 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["23/4","23/4"],["11/4","11/4"],["19/4","19/4"],["15/4","15/4"]],"answer":3,"explanation":["Combined hourly rate = 1/6+1/10; time = 60/16 = 15/4 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/6+1/10; காலம் = 60/16 = 15/4 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20477,"question_number":20478,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −6/10. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −6/10. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["13/5","13/5"],["3/5","3/5"],["8/5","8/5"],["-2/5","-2/5"]],"answer":1,"explanation":["−6/10 + 6/10 = 0. Simplified additive inverse: 3/5.","−6/10 + 6/10 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 3/5."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20478,"question_number":20479,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 6 and 10?","6 மற்றும் 10 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["9","9"],["7","7"],["8","8"],["10","10"]],"answer":2,"explanation":["(6+10)/2 = 8.","(6+10)/2 = 8."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20479,"question_number":20480,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 7/10 + 1/11.","கூட்டிச் சுருக்குக: 7/10 + 1/11."],"options":[["-23/110","-23/110"],["307/110","307/110"],["197/110","197/110"],["87/110","87/110"]],"answer":3,"explanation":["[7×11 + 10]/[10×11] = 87/110.","[7×11 + 10]/[10×11] = 87/110."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20480,"question_number":20481,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 7/10 − 1/11.","கழித்துச் சுருக்குக: 7/10 − 1/11."],"options":[["177/110","177/110"],["287/110","287/110"],["67/110","67/110"],["-43/110","-43/110"]],"answer":2,"explanation":["[7×11 − 10]/[10×11] = 67/110.","[7×11 − 10]/[10×11] = 67/110."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20481,"question_number":20482,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−7/10) × (11/8).","(−7/10) × (11/8) பெருக்கற்பலனைச் சுருக்குக."],"options":[["83/80","83/80"],["-157/80","-157/80"],["-77/80","-77/80"],["3/80","3/80"]],"answer":2,"explanation":["−77/80 = -77/80.","−77/80 = -77/80."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20482,"question_number":20483,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (7/10) ÷ (8/11) in simplest form.","(7/10) ÷ (8/11) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["77/80","77/80"],["157/80","157/80"],["-3/80","-3/80"],["237/80","237/80"]],"answer":0,"explanation":["(7/10) × (11/8) = 77/80.","(7/10) × (11/8) = 77/80."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20483,"question_number":20484,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 8.0 and 0.10.","8.0 மற்றும் 0.10 தசம எண்களைக் கூட்டுக."],"options":[["8.11","8.11"],["8.10","8.10"],["8.09","8.09"],["8.20","8.20"]],"answer":1,"explanation":["8.0 + 0.10 = 8.10.","8.0 + 0.10 = 8.10."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20484,"question_number":20485,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 10x + 7 = 177.","10x + 7 = 177 சமன்பாட்டைத் தீர்க்க."],"options":[["18","18"],["19","19"],["16","16"],["17","17"]],"answer":3,"explanation":["x = (177 − 7)/10 = 17.","x = (177 − 7)/10 = 17."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20485,"question_number":20486,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 7 and y = 10, find (x+y)² − x² − y², then divide by 2.","x = 7, y = 10 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["71","71"],["70","70"],["72","72"],["69","69"]],"answer":1,"explanation":["[(x+y)²−x²−y²]/2 = xy = 7×10 = 70.","[(x+y)²−x²−y²]/2 = xy = 7×10 = 70."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20486,"question_number":20487,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 7, y = 10.","x = 7, y = 10 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["290","290"],["288","288"],["289","289"],["291","291"]],"answer":2,"explanation":["(x+y)² = (7+10)² = 289.","(x+y)² = (7+10)² = 289."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20487,"question_number":20488,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^7 × 7^10 = 7^m, what is m?","7^7 × 7^10 = 7^m எனில் m என்ன?"],"options":[["18","18"],["17","17"],["19","19"],["16","16"]],"answer":1,"explanation":["m = 7 + 10 = 17.","m = 7 + 10 = 17."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20488,"question_number":20489,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^7)^10 = 2^m, find m.","(2^7)^10 = 2^m எனில் m காண்க."],"options":[["69","69"],["72","72"],["71","71"],["70","70"]],"answer":3,"explanation":["m = 7 × 10 = 70.","m = 7 × 10 = 70."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20489,"question_number":20490,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 6400.","6400 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["80","80"],["79","79"],["81","81"],["82","82"]],"answer":0,"explanation":["80 × 80 = 6400; √6400 = 80.","80 × 80 = 6400; √6400 = 80."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20490,"question_number":20491,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 512000.","512000 இன் கனமூலத்தைக் காண்க."],"options":[["82","82"],["81","81"],["79","79"],["80","80"]],"answer":3,"explanation":["80 × 80 × 80 = 512000; cube root = 80.","80 × 80 × 80 = 512000; கனமூலம் = 80."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20491,"question_number":20492,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 50% of ₹140.","₹140 இன் 50% காண்க."],"options":[["72","72"],["69","69"],["71","71"],["70","70"]],"answer":3,"explanation":["140×50/100 = 70.","140×50/100 = 70."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20492,"question_number":20493,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹700 has a 50% discount. What is the sale price in rupees?","₹700 குறித்த விலையுள்ள பைக்கு 50% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["351","351"],["350","350"],["349","349"],["352","352"]],"answer":1,"explanation":["700 × (100−50)/100 = 350.","700 × (100−50)/100 = 350."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20493,"question_number":20494,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹700 sells for ₹1050. Find the profit percentage.","₹700 க்கு வாங்கிய பொருள் ₹1050 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["50","50"],["52","52"],["51","51"],["49","49"]],"answer":0,"explanation":["(1050−700)/700×100 = 50%.","(1050−700)/700×100 = 50%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20494,"question_number":20495,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹7000 at 10% per year for 3 years.","₹7000 க்கு ஆண்டுக்கு 10% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2100","2100"],["2102","2102"],["2101","2101"],["2099","2099"]],"answer":0,"explanation":["7000×10×3/100 = 2100.","7000×10×3/100 = 2100."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20495,"question_number":20496,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹70000 at 10% a year for 2 years, compounded annually.","₹70000 க்கு ஆண்டுக்கு 10% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["14699","14699"],["14701","14701"],["14702","14702"],["14700","14700"]],"answer":3,"explanation":["70000×[(1+10/100)²−1] = 14700.","70000×[(1+10/100)²−1] = 14700."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20496,"question_number":20497,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["10 metres of cloth cost ₹70. At the same rate, what is the cost of 13 metres in rupees?","10 மீ துணியின் விலை ₹70. அதே வீதத்தில் 13 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["93","93"],["92","92"],["90","90"],["91","91"]],"answer":3,"explanation":["70/10×13 = 91.","70/10×13 = 91."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20497,"question_number":20498,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["10 equally efficient machines complete a job in 7 hours. How many hours do 12 such machines require at the same rate?","சமத் திறனுடைய 10 இயந்திரங்கள் வேலையை 7 மணியில் முடிக்கின்றன. அதே வீதத்தில் 12 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["47/6","47/6"],["41/6","41/6"],["35/6","35/6"],["29/6","29/6"]],"answer":2,"explanation":["10×7/(10+2) = 35/6 hours.","10×7/(10+2) = 35/6 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20498,"question_number":20499,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 14 cm and perpendicular height 10 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 14 செமீ; செங்குத்து உயரம் 10 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["140","140"],["139","139"],["141","141"],["142","142"]],"answer":0,"explanation":["14×10 = 140.","14×10 = 140."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20499,"question_number":20500,"practice_set":820},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 14 cm and 20 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 14 செமீ, 20 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["140","140"],["141","141"],["142","142"],["139","139"]],"answer":0,"explanation":["½×14×20 = 140 cm².","½×14×20 = 140 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20500,"question_number":20501,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 14 m and 34 m, and height 10 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 14 மீ, 34 மீ; உயரம் 10 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["239","239"],["240","240"],["242","242"],["241","241"]],"answer":1,"explanation":["½×(14+34)×10 = 240.","½×(14+34)×10 = 240."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20501,"question_number":20502,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 49 cm makes 10 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","49 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 10 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["3082","3082"],["3081","3081"],["3079","3079"],["3080","3080"]],"answer":3,"explanation":["10×2×22/7×49 = 3080.","10×2×22/7×49 = 3080."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20502,"question_number":20503,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 10 circular mats, each of radius 49 cm. Find their total area in cm², using π=22/7.","தலா 49 செமீ ஆரமுள்ள 10 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["75460","75460"],["75462","75462"],["75461","75461"],["75459","75459"]],"answer":0,"explanation":["10×22/7×49² = 75460.","10×22/7×49² = 75460."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20503,"question_number":20504,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 34° and 50°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 34°, 50°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["98","98"],["97","97"],["96","96"],["95","95"]],"answer":2,"explanation":["180−34−50 = 96°.","180−34−50 = 96°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20504,"question_number":20505,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 57°. One remote interior angle is 30°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 57°. அதற்கான ஓர் எதிர் உட்கோணம் 30°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["29","29"],["27","27"],["28","28"],["26","26"]],"answer":1,"explanation":["57 − 30 = 27°.","57 − 30 = 27°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20505,"question_number":20506,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 7, 17, 27, 37, 47.","7, 17, 27, 37, 47 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["29","29"],["28","28"],["27","27"],["26","26"]],"answer":2,"explanation":["Sum/5 = 135/5 = 27.","கூடுதல்/5 = 135/5 = 27."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20506,"question_number":20507,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 57, 7, 27, 77, 17.","வரிசைப்படுத்தி இடைநிலை காண்க: 57, 7, 27, 77, 17."],"options":[["28","28"],["27","27"],["26","26"],["29","29"]],"answer":1,"explanation":["Sorted: 7, 17, 27, 57, 77; middle value = 27.","வரிசை: 7, 17, 27, 57, 77; நடு மதிப்பு = 27."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20507,"question_number":20508,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 7, 17, 7, 27, 37, 7?","7, 17, 7, 27, 37, 7 தரவுகளின் முகடு எது?"],"options":[["8","8"],["7","7"],["9","9"],["6","6"]],"answer":1,"explanation":["7 occurs 3 times; each other value occurs once.","7 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20508,"question_number":20509,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 7 hours and another in 10 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 7 மணியிலும் மற்றொன்று 10 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["104/17","104/17"],["53/17","53/17"],["87/17","87/17"],["70/17","70/17"]],"answer":3,"explanation":["Combined hourly rate = 1/7+1/10; time = 70/17 = 70/17 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/7+1/10; காலம் = 70/17 = 70/17 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20509,"question_number":20510,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −7/10. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −7/10. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["7/10","7/10"],["-3/10","-3/10"],["17/10","17/10"],["27/10","27/10"]],"answer":0,"explanation":["−7/10 + 7/10 = 0. Simplified additive inverse: 7/10.","−7/10 + 7/10 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 7/10."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20510,"question_number":20511,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 7 and 10?","7 மற்றும் 10 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["21/2","21/2"],["19/2","19/2"],["15/2","15/2"],["17/2","17/2"]],"answer":3,"explanation":["(7+10)/2 = 17/2.","(7+10)/2 = 17/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20511,"question_number":20512,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 8/10 + 1/11.","கூட்டிச் சுருக்குக: 8/10 + 1/11."],"options":[["159/55","159/55"],["-6/55","-6/55"],["49/55","49/55"],["104/55","104/55"]],"answer":2,"explanation":["[8×11 + 10]/[10×11] = 49/55.","[8×11 + 10]/[10×11] = 49/55."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20512,"question_number":20513,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 8/10 − 1/11.","கழித்துச் சுருக்குக: 8/10 − 1/11."],"options":[["-16/55","-16/55"],["39/55","39/55"],["94/55","94/55"],["149/55","149/55"]],"answer":1,"explanation":["[8×11 − 10]/[10×11] = 39/55.","[8×11 − 10]/[10×11] = 39/55."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20513,"question_number":20514,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−8/10) × (11/9).","(−8/10) × (11/9) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-44/45","-44/45"],["1/45","1/45"],["-89/45","-89/45"],["46/45","46/45"]],"answer":0,"explanation":["−88/90 = -44/45.","−88/90 = -44/45."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20514,"question_number":20515,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (8/10) ÷ (9/11) in simplest form.","(8/10) ÷ (9/11) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["-1/45","-1/45"],["44/45","44/45"],["89/45","89/45"],["134/45","134/45"]],"answer":1,"explanation":["(8/10) × (11/9) = 44/45.","(8/10) × (11/9) = 44/45."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20515,"question_number":20516,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 9.0 and 0.10.","9.0 மற்றும் 0.10 தசம எண்களைக் கூட்டுக."],"options":[["9.09","9.09"],["9.11","9.11"],["9.20","9.20"],["9.10","9.10"]],"answer":3,"explanation":["9.0 + 0.10 = 9.10.","9.0 + 0.10 = 9.10."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20516,"question_number":20517,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 10x + 8 = 188.","10x + 8 = 188 சமன்பாட்டைத் தீர்க்க."],"options":[["20","20"],["18","18"],["19","19"],["17","17"]],"answer":1,"explanation":["x = (188 − 8)/10 = 18.","x = (188 − 8)/10 = 18."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20517,"question_number":20518,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 8 and y = 10, find (x+y)² − x² − y², then divide by 2.","x = 8, y = 10 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["81","81"],["82","82"],["80","80"],["79","79"]],"answer":2,"explanation":["[(x+y)²−x²−y²]/2 = xy = 8×10 = 80.","[(x+y)²−x²−y²]/2 = xy = 8×10 = 80."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20518,"question_number":20519,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 8, y = 10.","x = 8, y = 10 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["326","326"],["323","323"],["324","324"],["325","325"]],"answer":2,"explanation":["(x+y)² = (8+10)² = 324.","(x+y)² = (8+10)² = 324."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20519,"question_number":20520,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^8 × 7^10 = 7^m, what is m?","7^8 × 7^10 = 7^m எனில் m என்ன?"],"options":[["20","20"],["17","17"],["18","18"],["19","19"]],"answer":2,"explanation":["m = 8 + 10 = 18.","m = 8 + 10 = 18."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20520,"question_number":20521,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^8)^10 = 2^m, find m.","(2^8)^10 = 2^m எனில் m காண்க."],"options":[["82","82"],["81","81"],["79","79"],["80","80"]],"answer":3,"explanation":["m = 8 × 10 = 80.","m = 8 × 10 = 80."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20521,"question_number":20522,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 8100.","8100 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["90","90"],["92","92"],["89","89"],["91","91"]],"answer":0,"explanation":["90 × 90 = 8100; √8100 = 90.","90 × 90 = 8100; √8100 = 90."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20522,"question_number":20523,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 729000.","729000 இன் கனமூலத்தைக் காண்க."],"options":[["90","90"],["89","89"],["92","92"],["91","91"]],"answer":0,"explanation":["90 × 90 × 90 = 729000; cube root = 90.","90 × 90 × 90 = 729000; கனமூலம் = 90."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20523,"question_number":20524,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 50% of ₹160.","₹160 இன் 50% காண்க."],"options":[["81","81"],["79","79"],["80","80"],["82","82"]],"answer":2,"explanation":["160×50/100 = 80.","160×50/100 = 80."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20524,"question_number":20525,"practice_set":821},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹800 has a 50% discount. What is the sale price in rupees?","₹800 குறித்த விலையுள்ள பைக்கு 50% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["400","400"],["401","401"],["402","402"],["399","399"]],"answer":0,"explanation":["800 × (100−50)/100 = 400.","800 × (100−50)/100 = 400."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20525,"question_number":20526,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹800 sells for ₹1200. Find the profit percentage.","₹800 க்கு வாங்கிய பொருள் ₹1200 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["49","49"],["50","50"],["51","51"],["52","52"]],"answer":1,"explanation":["(1200−800)/800×100 = 50%.","(1200−800)/800×100 = 50%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20526,"question_number":20527,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹8000 at 10% per year for 3 years.","₹8000 க்கு ஆண்டுக்கு 10% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2400","2400"],["2401","2401"],["2399","2399"],["2402","2402"]],"answer":0,"explanation":["8000×10×3/100 = 2400.","8000×10×3/100 = 2400."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20527,"question_number":20528,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹80000 at 10% a year for 2 years, compounded annually.","₹80000 க்கு ஆண்டுக்கு 10% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["16800","16800"],["16799","16799"],["16802","16802"],["16801","16801"]],"answer":0,"explanation":["80000×[(1+10/100)²−1] = 16800.","80000×[(1+10/100)²−1] = 16800."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20528,"question_number":20529,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["10 metres of cloth cost ₹80. At the same rate, what is the cost of 13 metres in rupees?","10 மீ துணியின் விலை ₹80. அதே வீதத்தில் 13 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["106","106"],["104","104"],["105","105"],["103","103"]],"answer":1,"explanation":["80/10×13 = 104.","80/10×13 = 104."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20529,"question_number":20530,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["10 equally efficient machines complete a job in 8 hours. How many hours do 12 such machines require at the same rate?","சமத் திறனுடைய 10 இயந்திரங்கள் வேலையை 8 மணியில் முடிக்கின்றன. அதே வீதத்தில் 12 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["20/3","20/3"],["17/3","17/3"],["23/3","23/3"],["26/3","26/3"]],"answer":0,"explanation":["10×8/(10+2) = 20/3 hours.","10×8/(10+2) = 20/3 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20530,"question_number":20531,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 16 cm and perpendicular height 10 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 16 செமீ; செங்குத்து உயரம் 10 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["159","159"],["160","160"],["161","161"],["162","162"]],"answer":1,"explanation":["16×10 = 160.","16×10 = 160."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20531,"question_number":20532,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 16 cm and 20 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 16 செமீ, 20 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["161","161"],["160","160"],["162","162"],["159","159"]],"answer":1,"explanation":["½×16×20 = 160 cm².","½×16×20 = 160 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20532,"question_number":20533,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 16 m and 36 m, and height 10 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 16 மீ, 36 மீ; உயரம் 10 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["261","261"],["260","260"],["259","259"],["262","262"]],"answer":1,"explanation":["½×(16+36)×10 = 260.","½×(16+36)×10 = 260."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20533,"question_number":20534,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 56 cm makes 10 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","56 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 10 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["3520","3520"],["3519","3519"],["3521","3521"],["3522","3522"]],"answer":0,"explanation":["10×2×22/7×56 = 3520.","10×2×22/7×56 = 3520."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20534,"question_number":20535,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 10 circular mats, each of radius 56 cm. Find their total area in cm², using π=22/7.","தலா 56 செமீ ஆரமுள்ள 10 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["98562","98562"],["98560","98560"],["98561","98561"],["98559","98559"]],"answer":1,"explanation":["10×22/7×56² = 98560.","10×22/7×56² = 98560."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20535,"question_number":20536,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 36° and 50°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 36°, 50°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["93","93"],["95","95"],["94","94"],["96","96"]],"answer":2,"explanation":["180−36−50 = 94°.","180−36−50 = 94°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20536,"question_number":20537,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 58°. One remote interior angle is 30°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 58°. அதற்கான ஓர் எதிர் உட்கோணம் 30°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["28","28"],["27","27"],["30","30"],["29","29"]],"answer":0,"explanation":["58 − 30 = 28°.","58 − 30 = 28°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20537,"question_number":20538,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 8, 18, 28, 38, 48.","8, 18, 28, 38, 48 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["28","28"],["27","27"],["29","29"],["30","30"]],"answer":0,"explanation":["Sum/5 = 140/5 = 28.","கூடுதல்/5 = 140/5 = 28."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20538,"question_number":20539,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 58, 8, 28, 78, 18.","வரிசைப்படுத்தி இடைநிலை காண்க: 58, 8, 28, 78, 18."],"options":[["30","30"],["27","27"],["28","28"],["29","29"]],"answer":2,"explanation":["Sorted: 8, 18, 28, 58, 78; middle value = 28.","வரிசை: 8, 18, 28, 58, 78; நடு மதிப்பு = 28."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20539,"question_number":20540,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 8, 18, 8, 28, 38, 8?","8, 18, 8, 28, 38, 8 தரவுகளின் முகடு எது?"],"options":[["8","8"],["10","10"],["9","9"],["7","7"]],"answer":0,"explanation":["8 occurs 3 times; each other value occurs once.","8 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20540,"question_number":20541,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 8 hours and another in 10 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 8 மணியிலும் மற்றொன்று 10 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["40/9","40/9"],["49/9","49/9"],["58/9","58/9"],["31/9","31/9"]],"answer":0,"explanation":["Combined hourly rate = 1/8+1/10; time = 80/18 = 40/9 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/8+1/10; காலம் = 80/18 = 40/9 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20541,"question_number":20542,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −8/10. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −8/10. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["9/5","9/5"],["14/5","14/5"],["-1/5","-1/5"],["4/5","4/5"]],"answer":3,"explanation":["−8/10 + 8/10 = 0. Simplified additive inverse: 4/5.","−8/10 + 8/10 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 4/5."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20542,"question_number":20543,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 8 and 10?","8 மற்றும் 10 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["8","8"],["9","9"],["10","10"],["11","11"]],"answer":1,"explanation":["(8+10)/2 = 9.","(8+10)/2 = 9."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20543,"question_number":20544,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 9/10 + 1/11.","கூட்டிச் சுருக்குக: 9/10 + 1/11."],"options":[["329/110","329/110"],["219/110","219/110"],["-1/110","-1/110"],["109/110","109/110"]],"answer":3,"explanation":["[9×11 + 10]/[10×11] = 109/110.","[9×11 + 10]/[10×11] = 109/110."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20544,"question_number":20545,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 9/10 − 1/11.","கழித்துச் சுருக்குக: 9/10 − 1/11."],"options":[["-21/110","-21/110"],["199/110","199/110"],["309/110","309/110"],["89/110","89/110"]],"answer":3,"explanation":["[9×11 − 10]/[10×11] = 89/110.","[9×11 − 10]/[10×11] = 89/110."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20545,"question_number":20546,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−9/10) × (11/10).","(−9/10) × (11/10) பெருக்கற்பலனைச் சுருக்குக."],"options":[["101/100","101/100"],["-199/100","-199/100"],["-99/100","-99/100"],["1/100","1/100"]],"answer":2,"explanation":["−99/100 = -99/100.","−99/100 = -99/100."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20546,"question_number":20547,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (9/10) ÷ (10/11) in simplest form.","(9/10) ÷ (10/11) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["99/100","99/100"],["299/100","299/100"],["-1/100","-1/100"],["199/100","199/100"]],"answer":0,"explanation":["(9/10) × (11/10) = 99/100.","(9/10) × (11/10) = 99/100."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20547,"question_number":20548,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 10.0 and 0.10.","10.0 மற்றும் 0.10 தசம எண்களைக் கூட்டுக."],"options":[["10.20","10.20"],["10.11","10.11"],["10.10","10.10"],["10.09","10.09"]],"answer":2,"explanation":["10.0 + 0.10 = 10.10.","10.0 + 0.10 = 10.10."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20548,"question_number":20549,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 10x + 9 = 199.","10x + 9 = 199 சமன்பாட்டைத் தீர்க்க."],"options":[["18","18"],["21","21"],["20","20"],["19","19"]],"answer":3,"explanation":["x = (199 − 9)/10 = 19.","x = (199 − 9)/10 = 19."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20549,"question_number":20550,"practice_set":822},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 9 and y = 10, find (x+y)² − x² − y², then divide by 2.","x = 9, y = 10 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["89","89"],["91","91"],["90","90"],["92","92"]],"answer":2,"explanation":["[(x+y)²−x²−y²]/2 = xy = 9×10 = 90.","[(x+y)²−x²−y²]/2 = xy = 9×10 = 90."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20550,"question_number":20551,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 9, y = 10.","x = 9, y = 10 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["360","360"],["361","361"],["363","363"],["362","362"]],"answer":1,"explanation":["(x+y)² = (9+10)² = 361.","(x+y)² = (9+10)² = 361."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20551,"question_number":20552,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^9 × 7^10 = 7^m, what is m?","7^9 × 7^10 = 7^m எனில் m என்ன?"],"options":[["20","20"],["19","19"],["18","18"],["21","21"]],"answer":1,"explanation":["m = 9 + 10 = 19.","m = 9 + 10 = 19."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20552,"question_number":20553,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^9)^10 = 2^m, find m.","(2^9)^10 = 2^m எனில் m காண்க."],"options":[["90","90"],["92","92"],["89","89"],["91","91"]],"answer":0,"explanation":["m = 9 × 10 = 90.","m = 9 × 10 = 90."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20553,"question_number":20554,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 10000.","10000 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["102","102"],["99","99"],["101","101"],["100","100"]],"answer":3,"explanation":["100 × 100 = 10000; √10000 = 100.","100 × 100 = 10000; √10000 = 100."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20554,"question_number":20555,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 1000000.","1000000 இன் கனமூலத்தைக் காண்க."],"options":[["100","100"],["101","101"],["102","102"],["99","99"]],"answer":0,"explanation":["100 × 100 × 100 = 1000000; cube root = 100.","100 × 100 × 100 = 1000000; கனமூலம் = 100."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20555,"question_number":20556,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 50% of ₹180.","₹180 இன் 50% காண்க."],"options":[["90","90"],["89","89"],["92","92"],["91","91"]],"answer":0,"explanation":["180×50/100 = 90.","180×50/100 = 90."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20556,"question_number":20557,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹900 has a 50% discount. What is the sale price in rupees?","₹900 குறித்த விலையுள்ள பைக்கு 50% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["449","449"],["450","450"],["451","451"],["452","452"]],"answer":1,"explanation":["900 × (100−50)/100 = 450.","900 × (100−50)/100 = 450."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20557,"question_number":20558,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹900 sells for ₹1350. Find the profit percentage.","₹900 க்கு வாங்கிய பொருள் ₹1350 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["52","52"],["49","49"],["51","51"],["50","50"]],"answer":3,"explanation":["(1350−900)/900×100 = 50%.","(1350−900)/900×100 = 50%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20558,"question_number":20559,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹9000 at 10% per year for 3 years.","₹9000 க்கு ஆண்டுக்கு 10% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2702","2702"],["2700","2700"],["2701","2701"],["2699","2699"]],"answer":1,"explanation":["9000×10×3/100 = 2700.","9000×10×3/100 = 2700."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20559,"question_number":20560,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹90000 at 10% a year for 2 years, compounded annually.","₹90000 க்கு ஆண்டுக்கு 10% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["18900","18900"],["18901","18901"],["18899","18899"],["18902","18902"]],"answer":0,"explanation":["90000×[(1+10/100)²−1] = 18900.","90000×[(1+10/100)²−1] = 18900."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20560,"question_number":20561,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["10 metres of cloth cost ₹90. At the same rate, what is the cost of 13 metres in rupees?","10 மீ துணியின் விலை ₹90. அதே வீதத்தில் 13 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["118","118"],["116","116"],["119","119"],["117","117"]],"answer":3,"explanation":["90/10×13 = 117.","90/10×13 = 117."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20561,"question_number":20562,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["10 equally efficient machines complete a job in 9 hours. How many hours do 12 such machines require at the same rate?","சமத் திறனுடைய 10 இயந்திரங்கள் வேலையை 9 மணியில் முடிக்கின்றன. அதே வீதத்தில் 12 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["13/2","13/2"],["15/2","15/2"],["19/2","19/2"],["17/2","17/2"]],"answer":1,"explanation":["10×9/(10+2) = 15/2 hours.","10×9/(10+2) = 15/2 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20562,"question_number":20563,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 18 cm and perpendicular height 10 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 18 செமீ; செங்குத்து உயரம் 10 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["180","180"],["182","182"],["179","179"],["181","181"]],"answer":0,"explanation":["18×10 = 180.","18×10 = 180."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20563,"question_number":20564,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 18 cm and 20 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 18 செமீ, 20 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["181","181"],["179","179"],["180","180"],["182","182"]],"answer":2,"explanation":["½×18×20 = 180 cm².","½×18×20 = 180 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20564,"question_number":20565,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 18 m and 38 m, and height 10 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 18 மீ, 38 மீ; உயரம் 10 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["280","280"],["279","279"],["282","282"],["281","281"]],"answer":0,"explanation":["½×(18+38)×10 = 280.","½×(18+38)×10 = 280."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20565,"question_number":20566,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 63 cm makes 10 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","63 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 10 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["3962","3962"],["3959","3959"],["3960","3960"],["3961","3961"]],"answer":2,"explanation":["10×2×22/7×63 = 3960.","10×2×22/7×63 = 3960."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20566,"question_number":20567,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 10 circular mats, each of radius 63 cm. Find their total area in cm², using π=22/7.","தலா 63 செமீ ஆரமுள்ள 10 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["124741","124741"],["124740","124740"],["124739","124739"],["124742","124742"]],"answer":1,"explanation":["10×22/7×63² = 124740.","10×22/7×63² = 124740."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20567,"question_number":20568,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 38° and 50°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 38°, 50°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["94","94"],["92","92"],["93","93"],["91","91"]],"answer":1,"explanation":["180−38−50 = 92°.","180−38−50 = 92°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20568,"question_number":20569,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 59°. One remote interior angle is 30°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 59°. அதற்கான ஓர் எதிர் உட்கோணம் 30°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["31","31"],["30","30"],["28","28"],["29","29"]],"answer":3,"explanation":["59 − 30 = 29°.","59 − 30 = 29°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20569,"question_number":20570,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 9, 19, 29, 39, 49.","9, 19, 29, 39, 49 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["28","28"],["31","31"],["30","30"],["29","29"]],"answer":3,"explanation":["Sum/5 = 145/5 = 29.","கூடுதல்/5 = 145/5 = 29."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20570,"question_number":20571,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 59, 9, 29, 79, 19.","வரிசைப்படுத்தி இடைநிலை காண்க: 59, 9, 29, 79, 19."],"options":[["31","31"],["30","30"],["29","29"],["28","28"]],"answer":2,"explanation":["Sorted: 9, 19, 29, 59, 79; middle value = 29.","வரிசை: 9, 19, 29, 59, 79; நடு மதிப்பு = 29."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20571,"question_number":20572,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 9, 19, 9, 29, 39, 9?","9, 19, 9, 29, 39, 9 தரவுகளின் முகடு எது?"],"options":[["8","8"],["9","9"],["10","10"],["11","11"]],"answer":1,"explanation":["9 occurs 3 times; each other value occurs once.","9 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20572,"question_number":20573,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 9 hours and another in 10 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 9 மணியிலும் மற்றொன்று 10 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["90/19","90/19"],["128/19","128/19"],["71/19","71/19"],["109/19","109/19"]],"answer":0,"explanation":["Combined hourly rate = 1/9+1/10; time = 90/19 = 90/19 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/9+1/10; காலம் = 90/19 = 90/19 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20573,"question_number":20574,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −9/10. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −9/10. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["9/10","9/10"],["-1/10","-1/10"],["19/10","19/10"],["29/10","29/10"]],"answer":0,"explanation":["−9/10 + 9/10 = 0. Simplified additive inverse: 9/10.","−9/10 + 9/10 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 9/10."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20574,"question_number":20575,"practice_set":823},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 9 and 10?","9 மற்றும் 10 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["19/2","19/2"],["21/2","21/2"],["23/2","23/2"],["17/2","17/2"]],"answer":0,"explanation":["(9+10)/2 = 19/2.","(9+10)/2 = 19/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20575,"question_number":20576,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 10/10 + 1/11.","கூட்டிச் சுருக்குக: 10/10 + 1/11."],"options":[["1/11","1/11"],["23/11","23/11"],["34/11","34/11"],["12/11","12/11"]],"answer":3,"explanation":["[10×11 + 10]/[10×11] = 12/11.","[10×11 + 10]/[10×11] = 12/11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20576,"question_number":20577,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 10/10 − 1/11.","கழித்துச் சுருக்குக: 10/10 − 1/11."],"options":[["21/11","21/11"],["10/11","10/11"],["32/11","32/11"],["-1/11","-1/11"]],"answer":1,"explanation":["[10×11 − 10]/[10×11] = 10/11.","[10×11 − 10]/[10×11] = 10/11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20577,"question_number":20578,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−10/10) × (11/11).","(−10/10) × (11/11) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-2","-2"],["1","1"],["0","0"],["-1","-1"]],"answer":3,"explanation":["−110/110 = -1.","−110/110 = -1."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20578,"question_number":20579,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (10/10) ÷ (11/11) in simplest form.","(10/10) ÷ (11/11) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["2","2"],["0","0"],["1","1"],["3","3"]],"answer":2,"explanation":["(10/10) × (11/11) = 1.","(10/10) × (11/11) = 1."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20579,"question_number":20580,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 11.0 and 0.10.","11.0 மற்றும் 0.10 தசம எண்களைக் கூட்டுக."],"options":[["11.09","11.09"],["11.11","11.11"],["11.10","11.10"],["11.20","11.20"]],"answer":2,"explanation":["11.0 + 0.10 = 11.10.","11.0 + 0.10 = 11.10."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20580,"question_number":20581,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 10x + 10 = 210.","10x + 10 = 210 சமன்பாட்டைத் தீர்க்க."],"options":[["20","20"],["19","19"],["21","21"],["22","22"]],"answer":0,"explanation":["x = (210 − 10)/10 = 20.","x = (210 − 10)/10 = 20."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20581,"question_number":20582,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 10 and y = 10, find (x+y)² − x² − y², then divide by 2.","x = 10, y = 10 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["102","102"],["99","99"],["100","100"],["101","101"]],"answer":2,"explanation":["[(x+y)²−x²−y²]/2 = xy = 10×10 = 100.","[(x+y)²−x²−y²]/2 = xy = 10×10 = 100."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20582,"question_number":20583,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 10, y = 10.","x = 10, y = 10 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["400","400"],["399","399"],["401","401"],["402","402"]],"answer":0,"explanation":["(x+y)² = (10+10)² = 400.","(x+y)² = (10+10)² = 400."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20583,"question_number":20584,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^10 × 7^10 = 7^m, what is m?","7^10 × 7^10 = 7^m எனில் m என்ன?"],"options":[["20","20"],["22","22"],["19","19"],["21","21"]],"answer":0,"explanation":["m = 10 + 10 = 20.","m = 10 + 10 = 20."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20584,"question_number":20585,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^10)^10 = 2^m, find m.","(2^10)^10 = 2^m எனில் m காண்க."],"options":[["101","101"],["100","100"],["99","99"],["102","102"]],"answer":1,"explanation":["m = 10 × 10 = 100.","m = 10 × 10 = 100."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20585,"question_number":20586,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 12100.","12100 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["109","109"],["110","110"],["112","112"],["111","111"]],"answer":1,"explanation":["110 × 110 = 12100; √12100 = 110.","110 × 110 = 12100; √12100 = 110."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20586,"question_number":20587,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 1331000.","1331000 இன் கனமூலத்தைக் காண்க."],"options":[["109","109"],["112","112"],["111","111"],["110","110"]],"answer":3,"explanation":["110 × 110 × 110 = 1331000; cube root = 110.","110 × 110 × 110 = 1331000; கனமூலம் = 110."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20587,"question_number":20588,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 50% of ₹200.","₹200 இன் 50% காண்க."],"options":[["102","102"],["100","100"],["101","101"],["99","99"]],"answer":1,"explanation":["200×50/100 = 100.","200×50/100 = 100."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20588,"question_number":20589,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹1000 has a 50% discount. What is the sale price in rupees?","₹1000 குறித்த விலையுள்ள பைக்கு 50% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["502","502"],["501","501"],["499","499"],["500","500"]],"answer":3,"explanation":["1000 × (100−50)/100 = 500.","1000 × (100−50)/100 = 500."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20589,"question_number":20590,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹1000 sells for ₹1500. Find the profit percentage.","₹1000 க்கு வாங்கிய பொருள் ₹1500 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["51","51"],["52","52"],["49","49"],["50","50"]],"answer":3,"explanation":["(1500−1000)/1000×100 = 50%.","(1500−1000)/1000×100 = 50%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20590,"question_number":20591,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹10000 at 10% per year for 3 years.","₹10000 க்கு ஆண்டுக்கு 10% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2999","2999"],["3002","3002"],["3001","3001"],["3000","3000"]],"answer":3,"explanation":["10000×10×3/100 = 3000.","10000×10×3/100 = 3000."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20591,"question_number":20592,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹100000 at 10% a year for 2 years, compounded annually.","₹100000 க்கு ஆண்டுக்கு 10% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["21000","21000"],["21001","21001"],["20999","20999"],["21002","21002"]],"answer":0,"explanation":["100000×[(1+10/100)²−1] = 21000.","100000×[(1+10/100)²−1] = 21000."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20592,"question_number":20593,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["10 metres of cloth cost ₹100. At the same rate, what is the cost of 13 metres in rupees?","10 மீ துணியின் விலை ₹100. அதே வீதத்தில் 13 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["131","131"],["132","132"],["129","129"],["130","130"]],"answer":3,"explanation":["100/10×13 = 130.","100/10×13 = 130."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20593,"question_number":20594,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["10 equally efficient machines complete a job in 10 hours. How many hours do 12 such machines require at the same rate?","சமத் திறனுடைய 10 இயந்திரங்கள் வேலையை 10 மணியில் முடிக்கின்றன. அதே வீதத்தில் 12 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["22/3","22/3"],["31/3","31/3"],["25/3","25/3"],["28/3","28/3"]],"answer":2,"explanation":["10×10/(10+2) = 25/3 hours.","10×10/(10+2) = 25/3 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20594,"question_number":20595,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 20 cm and perpendicular height 10 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 20 செமீ; செங்குத்து உயரம் 10 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["202","202"],["201","201"],["200","200"],["199","199"]],"answer":2,"explanation":["20×10 = 200.","20×10 = 200."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20595,"question_number":20596,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 20 cm and 20 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 20 செமீ, 20 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["199","199"],["202","202"],["201","201"],["200","200"]],"answer":3,"explanation":["½×20×20 = 200 cm².","½×20×20 = 200 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20596,"question_number":20597,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 20 m and 40 m, and height 10 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 20 மீ, 40 மீ; உயரம் 10 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["301","301"],["300","300"],["299","299"],["302","302"]],"answer":1,"explanation":["½×(20+40)×10 = 300.","½×(20+40)×10 = 300."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20597,"question_number":20598,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 70 cm makes 10 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","70 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 10 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["4400","4400"],["4402","4402"],["4401","4401"],["4399","4399"]],"answer":0,"explanation":["10×2×22/7×70 = 4400.","10×2×22/7×70 = 4400."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20598,"question_number":20599,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 10 circular mats, each of radius 70 cm. Find their total area in cm², using π=22/7.","தலா 70 செமீ ஆரமுள்ள 10 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["154000","154000"],["154002","154002"],["154001","154001"],["153999","153999"]],"answer":0,"explanation":["10×22/7×70² = 154000.","10×22/7×70² = 154000."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20599,"question_number":20600,"practice_set":824},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 40° and 50°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 40°, 50°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["91","91"],["89","89"],["90","90"],["92","92"]],"answer":2,"explanation":["180−40−50 = 90°.","180−40−50 = 90°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20600,"question_number":20601,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 60°. One remote interior angle is 30°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 60°. அதற்கான ஓர் எதிர் உட்கோணம் 30°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["30","30"],["29","29"],["31","31"],["32","32"]],"answer":0,"explanation":["60 − 30 = 30°.","60 − 30 = 30°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20601,"question_number":20602,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 10, 20, 30, 40, 50.","10, 20, 30, 40, 50 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["31","31"],["32","32"],["29","29"],["30","30"]],"answer":3,"explanation":["Sum/5 = 150/5 = 30.","கூடுதல்/5 = 150/5 = 30."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20602,"question_number":20603,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 60, 10, 30, 80, 20.","வரிசைப்படுத்தி இடைநிலை காண்க: 60, 10, 30, 80, 20."],"options":[["32","32"],["29","29"],["30","30"],["31","31"]],"answer":2,"explanation":["Sorted: 10, 20, 30, 60, 80; middle value = 30.","வரிசை: 10, 20, 30, 60, 80; நடு மதிப்பு = 30."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20603,"question_number":20604,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 10, 20, 10, 30, 40, 10?","10, 20, 10, 30, 40, 10 தரவுகளின் முகடு எது?"],"options":[["9","9"],["11","11"],["12","12"],["10","10"]],"answer":3,"explanation":["10 occurs 3 times; each other value occurs once.","10 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20604,"question_number":20605,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 10 hours and another in 10 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 10 மணியிலும் மற்றொன்று 10 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["4","4"],["7","7"],["5","5"],["6","6"]],"answer":2,"explanation":["Combined hourly rate = 1/10+1/10; time = 100/20 = 5 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/10+1/10; காலம் = 100/20 = 5 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20605,"question_number":20606,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −10/10. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −10/10. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["0","0"],["2","2"],["1","1"],["3","3"]],"answer":2,"explanation":["−10/10 + 10/10 = 0. Simplified additive inverse: 1.","−10/10 + 10/10 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 1."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20606,"question_number":20607,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 10 and 10?","10 மற்றும் 10 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["9","9"],["11","11"],["12","12"],["10","10"]],"answer":3,"explanation":["(10+10)/2 = 10.","(10+10)/2 = 10."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20607,"question_number":20608,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 11/10 + 1/11.","கூட்டிச் சுருக்குக: 11/10 + 1/11."],"options":[["21/110","21/110"],["351/110","351/110"],["131/110","131/110"],["241/110","241/110"]],"answer":2,"explanation":["[11×11 + 10]/[10×11] = 131/110.","[11×11 + 10]/[10×11] = 131/110."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20608,"question_number":20609,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 11/10 − 1/11.","கழித்துச் சுருக்குக: 11/10 − 1/11."],"options":[["1/110","1/110"],["331/110","331/110"],["111/110","111/110"],["221/110","221/110"]],"answer":2,"explanation":["[11×11 − 10]/[10×11] = 111/110.","[11×11 − 10]/[10×11] = 111/110."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20609,"question_number":20610,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−11/10) × (11/12).","(−11/10) × (11/12) பெருக்கற்பலனைச் சுருக்குக."],"options":[["119/120","119/120"],["-121/120","-121/120"],["-1/120","-1/120"],["-241/120","-241/120"]],"answer":1,"explanation":["−121/120 = -121/120.","−121/120 = -121/120."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20610,"question_number":20611,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (11/10) ÷ (12/11) in simplest form.","(11/10) ÷ (12/11) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["121/120","121/120"],["241/120","241/120"],["1/120","1/120"],["361/120","361/120"]],"answer":0,"explanation":["(11/10) × (11/12) = 121/120.","(11/10) × (11/12) = 121/120."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20611,"question_number":20612,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 12.0 and 0.10.","12.0 மற்றும் 0.10 தசம எண்களைக் கூட்டுக."],"options":[["12.11","12.11"],["12.10","12.10"],["12.20","12.20"],["12.09","12.09"]],"answer":1,"explanation":["12.0 + 0.10 = 12.10.","12.0 + 0.10 = 12.10."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20612,"question_number":20613,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 10x + 11 = 221.","10x + 11 = 221 சமன்பாட்டைத் தீர்க்க."],"options":[["22","22"],["23","23"],["20","20"],["21","21"]],"answer":3,"explanation":["x = (221 − 11)/10 = 21.","x = (221 − 11)/10 = 21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20613,"question_number":20614,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 11 and y = 10, find (x+y)² − x² − y², then divide by 2.","x = 11, y = 10 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["110","110"],["111","111"],["109","109"],["112","112"]],"answer":0,"explanation":["[(x+y)²−x²−y²]/2 = xy = 11×10 = 110.","[(x+y)²−x²−y²]/2 = xy = 11×10 = 110."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20614,"question_number":20615,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 11, y = 10.","x = 11, y = 10 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["443","443"],["441","441"],["440","440"],["442","442"]],"answer":1,"explanation":["(x+y)² = (11+10)² = 441.","(x+y)² = (11+10)² = 441."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20615,"question_number":20616,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^11 × 7^10 = 7^m, what is m?","7^11 × 7^10 = 7^m எனில் m என்ன?"],"options":[["22","22"],["21","21"],["20","20"],["23","23"]],"answer":1,"explanation":["m = 11 + 10 = 21.","m = 11 + 10 = 21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20616,"question_number":20617,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^11)^10 = 2^m, find m.","(2^11)^10 = 2^m எனில் m காண்க."],"options":[["112","112"],["109","109"],["110","110"],["111","111"]],"answer":2,"explanation":["m = 11 × 10 = 110.","m = 11 × 10 = 110."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20617,"question_number":20618,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 14400.","14400 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["121","121"],["120","120"],["122","122"],["119","119"]],"answer":1,"explanation":["120 × 120 = 14400; √14400 = 120.","120 × 120 = 14400; √14400 = 120."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20618,"question_number":20619,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 1728000.","1728000 இன் கனமூலத்தைக் காண்க."],"options":[["119","119"],["120","120"],["122","122"],["121","121"]],"answer":1,"explanation":["120 × 120 × 120 = 1728000; cube root = 120.","120 × 120 × 120 = 1728000; கனமூலம் = 120."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20619,"question_number":20620,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 50% of ₹220.","₹220 இன் 50% காண்க."],"options":[["109","109"],["111","111"],["110","110"],["112","112"]],"answer":2,"explanation":["220×50/100 = 110.","220×50/100 = 110."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20620,"question_number":20621,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹1100 has a 50% discount. What is the sale price in rupees?","₹1100 குறித்த விலையுள்ள பைக்கு 50% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["551","551"],["549","549"],["550","550"],["552","552"]],"answer":2,"explanation":["1100 × (100−50)/100 = 550.","1100 × (100−50)/100 = 550."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20621,"question_number":20622,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹1100 sells for ₹1650. Find the profit percentage.","₹1100 க்கு வாங்கிய பொருள் ₹1650 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["51","51"],["50","50"],["52","52"],["49","49"]],"answer":1,"explanation":["(1650−1100)/1100×100 = 50%.","(1650−1100)/1100×100 = 50%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20622,"question_number":20623,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹11000 at 10% per year for 3 years.","₹11000 க்கு ஆண்டுக்கு 10% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["3300","3300"],["3299","3299"],["3301","3301"],["3302","3302"]],"answer":0,"explanation":["11000×10×3/100 = 3300.","11000×10×3/100 = 3300."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20623,"question_number":20624,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹110000 at 10% a year for 2 years, compounded annually.","₹110000 க்கு ஆண்டுக்கு 10% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["23102","23102"],["23100","23100"],["23101","23101"],["23099","23099"]],"answer":1,"explanation":["110000×[(1+10/100)²−1] = 23100.","110000×[(1+10/100)²−1] = 23100."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20624,"question_number":20625,"practice_set":825},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["10 metres of cloth cost ₹110. At the same rate, what is the cost of 13 metres in rupees?","10 மீ துணியின் விலை ₹110. அதே வீதத்தில் 13 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["143","143"],["145","145"],["142","142"],["144","144"]],"answer":0,"explanation":["110/10×13 = 143.","110/10×13 = 143."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20625,"question_number":20626,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["10 equally efficient machines complete a job in 11 hours. How many hours do 12 such machines require at the same rate?","சமத் திறனுடைய 10 இயந்திரங்கள் வேலையை 11 மணியில் முடிக்கின்றன. அதே வீதத்தில் 12 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["49/6","49/6"],["67/6","67/6"],["61/6","61/6"],["55/6","55/6"]],"answer":3,"explanation":["10×11/(10+2) = 55/6 hours.","10×11/(10+2) = 55/6 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20626,"question_number":20627,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 22 cm and perpendicular height 10 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 22 செமீ; செங்குத்து உயரம் 10 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["221","221"],["222","222"],["220","220"],["219","219"]],"answer":2,"explanation":["22×10 = 220.","22×10 = 220."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20627,"question_number":20628,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 22 cm and 20 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 22 செமீ, 20 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["222","222"],["219","219"],["221","221"],["220","220"]],"answer":3,"explanation":["½×22×20 = 220 cm².","½×22×20 = 220 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20628,"question_number":20629,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 22 m and 42 m, and height 10 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 22 மீ, 42 மீ; உயரம் 10 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["322","322"],["319","319"],["320","320"],["321","321"]],"answer":2,"explanation":["½×(22+42)×10 = 320.","½×(22+42)×10 = 320."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20629,"question_number":20630,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 77 cm makes 10 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","77 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 10 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["4839","4839"],["4840","4840"],["4842","4842"],["4841","4841"]],"answer":1,"explanation":["10×2×22/7×77 = 4840.","10×2×22/7×77 = 4840."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20630,"question_number":20631,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 10 circular mats, each of radius 77 cm. Find their total area in cm², using π=22/7.","தலா 77 செமீ ஆரமுள்ள 10 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["186342","186342"],["186339","186339"],["186340","186340"],["186341","186341"]],"answer":2,"explanation":["10×22/7×77² = 186340.","10×22/7×77² = 186340."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20631,"question_number":20632,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 42° and 50°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 42°, 50°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["90","90"],["87","87"],["88","88"],["89","89"]],"answer":2,"explanation":["180−42−50 = 88°.","180−42−50 = 88°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20632,"question_number":20633,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 61°. One remote interior angle is 30°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 61°. அதற்கான ஓர் எதிர் உட்கோணம் 30°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["30","30"],["31","31"],["32","32"],["33","33"]],"answer":1,"explanation":["61 − 30 = 31°.","61 − 30 = 31°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20633,"question_number":20634,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 11, 21, 31, 41, 51.","11, 21, 31, 41, 51 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["30","30"],["32","32"],["31","31"],["33","33"]],"answer":2,"explanation":["Sum/5 = 155/5 = 31.","கூடுதல்/5 = 155/5 = 31."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20634,"question_number":20635,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 61, 11, 31, 81, 21.","வரிசைப்படுத்தி இடைநிலை காண்க: 61, 11, 31, 81, 21."],"options":[["31","31"],["32","32"],["33","33"],["30","30"]],"answer":0,"explanation":["Sorted: 11, 21, 31, 61, 81; middle value = 31.","வரிசை: 11, 21, 31, 61, 81; நடு மதிப்பு = 31."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20635,"question_number":20636,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 11, 21, 11, 31, 41, 11?","11, 21, 11, 31, 41, 11 தரவுகளின் முகடு எது?"],"options":[["12","12"],["13","13"],["10","10"],["11","11"]],"answer":3,"explanation":["11 occurs 3 times; each other value occurs once.","11 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20636,"question_number":20637,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 11 hours and another in 10 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 11 மணியிலும் மற்றொன்று 10 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["131/21","131/21"],["110/21","110/21"],["152/21","152/21"],["89/21","89/21"]],"answer":1,"explanation":["Combined hourly rate = 1/11+1/10; time = 110/21 = 110/21 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/11+1/10; காலம் = 110/21 = 110/21 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20637,"question_number":20638,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −11/10. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −11/10. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["1/10","1/10"],["31/10","31/10"],["11/10","11/10"],["21/10","21/10"]],"answer":2,"explanation":["−11/10 + 11/10 = 0. Simplified additive inverse: 11/10.","−11/10 + 11/10 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 11/10."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20638,"question_number":20639,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 11 and 10?","11 மற்றும் 10 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["23/2","23/2"],["25/2","25/2"],["19/2","19/2"],["21/2","21/2"]],"answer":3,"explanation":["(11+10)/2 = 21/2.","(11+10)/2 = 21/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20639,"question_number":20640,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 2/11 + 1/12.","கூட்டிச் சுருக்குக: 2/11 + 1/12."],"options":[["-97/132","-97/132"],["167/132","167/132"],["35/132","35/132"],["299/132","299/132"]],"answer":2,"explanation":["[2×12 + 11]/[11×12] = 35/132.","[2×12 + 11]/[11×12] = 35/132."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20640,"question_number":20641,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 2/11 − 1/12.","கழித்துச் சுருக்குக: 2/11 − 1/12."],"options":[["277/132","277/132"],["-119/132","-119/132"],["145/132","145/132"],["13/132","13/132"]],"answer":3,"explanation":["[2×12 − 11]/[11×12] = 13/132.","[2×12 − 11]/[11×12] = 13/132."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20641,"question_number":20642,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−2/11) × (12/3).","(−2/11) × (12/3) பெருக்கற்பலனைச் சுருக்குக."],"options":[["3/11","3/11"],["14/11","14/11"],["-19/11","-19/11"],["-8/11","-8/11"]],"answer":3,"explanation":["−24/33 = -8/11.","−24/33 = -8/11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20642,"question_number":20643,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (2/11) ÷ (3/12) in simplest form.","(2/11) ÷ (3/12) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["-3/11","-3/11"],["8/11","8/11"],["30/11","30/11"],["19/11","19/11"]],"answer":1,"explanation":["(2/11) × (12/3) = 8/11.","(2/11) × (12/3) = 8/11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20643,"question_number":20644,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 3.1 and 0.11.","3.1 மற்றும் 0.11 தசம எண்களைக் கூட்டுக."],"options":[["3.31","3.31"],["3.21","3.21"],["3.20","3.20"],["3.22","3.22"]],"answer":1,"explanation":["3.1 + 0.11 = 3.21.","3.1 + 0.11 = 3.21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20644,"question_number":20645,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 11x + 2 = 145.","11x + 2 = 145 சமன்பாட்டைத் தீர்க்க."],"options":[["14","14"],["13","13"],["12","12"],["15","15"]],"answer":1,"explanation":["x = (145 − 2)/11 = 13.","x = (145 − 2)/11 = 13."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20645,"question_number":20646,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 2 and y = 11, find (x+y)² − x² − y², then divide by 2.","x = 2, y = 11 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["21","21"],["22","22"],["24","24"],["23","23"]],"answer":1,"explanation":["[(x+y)²−x²−y²]/2 = xy = 2×11 = 22.","[(x+y)²−x²−y²]/2 = xy = 2×11 = 22."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20646,"question_number":20647,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 2, y = 11.","x = 2, y = 11 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["168","168"],["170","170"],["171","171"],["169","169"]],"answer":3,"explanation":["(x+y)² = (2+11)² = 169.","(x+y)² = (2+11)² = 169."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20647,"question_number":20648,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^2 × 7^11 = 7^m, what is m?","7^2 × 7^11 = 7^m எனில் m என்ன?"],"options":[["14","14"],["12","12"],["13","13"],["15","15"]],"answer":2,"explanation":["m = 2 + 11 = 13.","m = 2 + 11 = 13."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20648,"question_number":20649,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^2)^11 = 2^m, find m.","(2^2)^11 = 2^m எனில் m காண்க."],"options":[["23","23"],["24","24"],["21","21"],["22","22"]],"answer":3,"explanation":["m = 2 × 11 = 22.","m = 2 × 11 = 22."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20649,"question_number":20650,"practice_set":826},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 961.","961 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["30","30"],["33","33"],["31","31"],["32","32"]],"answer":2,"explanation":["31 × 31 = 961; √961 = 31.","31 × 31 = 961; √961 = 31."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20650,"question_number":20651,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 29791.","29791 இன் கனமூலத்தைக் காண்க."],"options":[["33","33"],["32","32"],["31","31"],["30","30"]],"answer":2,"explanation":["31 × 31 × 31 = 29791; cube root = 31.","31 × 31 × 31 = 29791; கனமூலம் = 31."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20651,"question_number":20652,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 55% of ₹40.","₹40 இன் 55% காண்க."],"options":[["21","21"],["23","23"],["22","22"],["24","24"]],"answer":2,"explanation":["40×55/100 = 22.","40×55/100 = 22."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20652,"question_number":20653,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹200 has a 55% discount. What is the sale price in rupees?","₹200 குறித்த விலையுள்ள பைக்கு 55% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["92","92"],["90","90"],["89","89"],["91","91"]],"answer":1,"explanation":["200 × (100−55)/100 = 90.","200 × (100−55)/100 = 90."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20653,"question_number":20654,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹200 sells for ₹310. Find the profit percentage.","₹200 க்கு வாங்கிய பொருள் ₹310 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["57","57"],["56","56"],["54","54"],["55","55"]],"answer":3,"explanation":["(310−200)/200×100 = 55%.","(310−200)/200×100 = 55%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20654,"question_number":20655,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹2000 at 11% per year for 3 years.","₹2000 க்கு ஆண்டுக்கு 11% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["660","660"],["659","659"],["662","662"],["661","661"]],"answer":0,"explanation":["2000×11×3/100 = 660.","2000×11×3/100 = 660."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20655,"question_number":20656,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹20000 at 11% a year for 2 years, compounded annually.","₹20000 க்கு ஆண்டுக்கு 11% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["4641","4641"],["4644","4644"],["4642","4642"],["4643","4643"]],"answer":2,"explanation":["20000×[(1+11/100)²−1] = 4642.","20000×[(1+11/100)²−1] = 4642."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20656,"question_number":20657,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["11 metres of cloth cost ₹20. At the same rate, what is the cost of 14 metres in rupees?","11 மீ துணியின் விலை ₹20. அதே வீதத்தில் 14 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["302/11","302/11"],["269/11","269/11"],["280/11","280/11"],["291/11","291/11"]],"answer":2,"explanation":["20/11×14 = 280/11.","20/11×14 = 280/11."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20657,"question_number":20658,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["11 equally efficient machines complete a job in 2 hours. How many hours do 13 such machines require at the same rate?","சமத் திறனுடைய 11 இயந்திரங்கள் வேலையை 2 மணியில் முடிக்கின்றன. அதே வீதத்தில் 13 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["22/13","22/13"],["48/13","48/13"],["35/13","35/13"],["9/13","9/13"]],"answer":0,"explanation":["11×2/(11+2) = 22/13 hours.","11×2/(11+2) = 22/13 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20658,"question_number":20659,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 4 cm and perpendicular height 11 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 4 செமீ; செங்குத்து உயரம் 11 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["45","45"],["46","46"],["44","44"],["43","43"]],"answer":2,"explanation":["4×11 = 44.","4×11 = 44."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20659,"question_number":20660,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 4 cm and 22 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 4 செமீ, 22 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["46","46"],["44","44"],["43","43"],["45","45"]],"answer":1,"explanation":["½×4×22 = 44 cm².","½×4×22 = 44 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20660,"question_number":20661,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 4 m and 26 m, and height 11 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 4 மீ, 26 மீ; உயரம் 11 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["165","165"],["166","166"],["167","167"],["164","164"]],"answer":0,"explanation":["½×(4+26)×11 = 165.","½×(4+26)×11 = 165."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20661,"question_number":20662,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 14 cm makes 11 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","14 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 11 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["968","968"],["967","967"],["969","969"],["970","970"]],"answer":0,"explanation":["11×2×22/7×14 = 968.","11×2×22/7×14 = 968."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20662,"question_number":20663,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 11 circular mats, each of radius 14 cm. Find their total area in cm², using π=22/7.","தலா 14 செமீ ஆரமுள்ள 11 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["6775","6775"],["6778","6778"],["6776","6776"],["6777","6777"]],"answer":2,"explanation":["11×22/7×14² = 6776.","11×22/7×14² = 6776."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20663,"question_number":20664,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 24° and 52°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 24°, 52°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["103","103"],["104","104"],["106","106"],["105","105"]],"answer":1,"explanation":["180−24−52 = 104°.","180−24−52 = 104°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20664,"question_number":20665,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 52°. One remote interior angle is 31°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 52°. அதற்கான ஓர் எதிர் உட்கோணம் 31°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["21","21"],["23","23"],["20","20"],["22","22"]],"answer":0,"explanation":["52 − 31 = 21°.","52 − 31 = 21°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20665,"question_number":20666,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 2, 13, 24, 35, 46.","2, 13, 24, 35, 46 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["24","24"],["25","25"],["26","26"],["23","23"]],"answer":0,"explanation":["Sum/5 = 120/5 = 24.","கூடுதல்/5 = 120/5 = 24."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20666,"question_number":20667,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 57, 2, 24, 79, 13.","வரிசைப்படுத்தி இடைநிலை காண்க: 57, 2, 24, 79, 13."],"options":[["26","26"],["24","24"],["25","25"],["23","23"]],"answer":1,"explanation":["Sorted: 2, 13, 24, 57, 79; middle value = 24.","வரிசை: 2, 13, 24, 57, 79; நடு மதிப்பு = 24."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20667,"question_number":20668,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 2, 13, 2, 24, 35, 2?","2, 13, 2, 24, 35, 2 தரவுகளின் முகடு எது?"],"options":[["3","3"],["2","2"],["4","4"],["1","1"]],"answer":1,"explanation":["2 occurs 3 times; each other value occurs once.","2 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20668,"question_number":20669,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 2 hours and another in 11 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 2 மணியிலும் மற்றொன்று 11 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["35/13","35/13"],["22/13","22/13"],["48/13","48/13"],["9/13","9/13"]],"answer":1,"explanation":["Combined hourly rate = 1/2+1/11; time = 22/13 = 22/13 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/2+1/11; காலம் = 22/13 = 22/13 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20669,"question_number":20670,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −2/11. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −2/11. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["2/11","2/11"],["13/11","13/11"],["24/11","24/11"],["-9/11","-9/11"]],"answer":0,"explanation":["−2/11 + 2/11 = 0. Simplified additive inverse: 2/11.","−2/11 + 2/11 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 2/11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20670,"question_number":20671,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 2 and 11?","2 மற்றும் 11 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["11/2","11/2"],["17/2","17/2"],["13/2","13/2"],["15/2","15/2"]],"answer":2,"explanation":["(2+11)/2 = 13/2.","(2+11)/2 = 13/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20671,"question_number":20672,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 3/11 + 1/12.","கூட்டிச் சுருக்குக: 3/11 + 1/12."],"options":[["311/132","311/132"],["-85/132","-85/132"],["179/132","179/132"],["47/132","47/132"]],"answer":3,"explanation":["[3×12 + 11]/[11×12] = 47/132.","[3×12 + 11]/[11×12] = 47/132."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20672,"question_number":20673,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 3/11 − 1/12.","கழித்துச் சுருக்குக: 3/11 − 1/12."],"options":[["289/132","289/132"],["25/132","25/132"],["157/132","157/132"],["-107/132","-107/132"]],"answer":1,"explanation":["[3×12 − 11]/[11×12] = 25/132.","[3×12 − 11]/[11×12] = 25/132."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20673,"question_number":20674,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−3/11) × (12/4).","(−3/11) × (12/4) பெருக்கற்பலனைச் சுருக்குக."],"options":[["13/11","13/11"],["2/11","2/11"],["-9/11","-9/11"],["-20/11","-20/11"]],"answer":2,"explanation":["−36/44 = -9/11.","−36/44 = -9/11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20674,"question_number":20675,"practice_set":827},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (3/11) ÷ (4/12) in simplest form.","(3/11) ÷ (4/12) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["-2/11","-2/11"],["31/11","31/11"],["20/11","20/11"],["9/11","9/11"]],"answer":3,"explanation":["(3/11) × (12/4) = 9/11.","(3/11) × (12/4) = 9/11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20675,"question_number":20676,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 4.1 and 0.11.","4.1 மற்றும் 0.11 தசம எண்களைக் கூட்டுக."],"options":[["4.21","4.21"],["4.31","4.31"],["4.22","4.22"],["4.20","4.20"]],"answer":0,"explanation":["4.1 + 0.11 = 4.21.","4.1 + 0.11 = 4.21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20676,"question_number":20677,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 11x + 3 = 157.","11x + 3 = 157 சமன்பாட்டைத் தீர்க்க."],"options":[["14","14"],["13","13"],["16","16"],["15","15"]],"answer":0,"explanation":["x = (157 − 3)/11 = 14.","x = (157 − 3)/11 = 14."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20677,"question_number":20678,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 3 and y = 11, find (x+y)² − x² − y², then divide by 2.","x = 3, y = 11 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["35","35"],["34","34"],["32","32"],["33","33"]],"answer":3,"explanation":["[(x+y)²−x²−y²]/2 = xy = 3×11 = 33.","[(x+y)²−x²−y²]/2 = xy = 3×11 = 33."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20678,"question_number":20679,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 3, y = 11.","x = 3, y = 11 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["198","198"],["195","195"],["196","196"],["197","197"]],"answer":2,"explanation":["(x+y)² = (3+11)² = 196.","(x+y)² = (3+11)² = 196."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20679,"question_number":20680,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^3 × 7^11 = 7^m, what is m?","7^3 × 7^11 = 7^m எனில் m என்ன?"],"options":[["16","16"],["14","14"],["15","15"],["13","13"]],"answer":1,"explanation":["m = 3 + 11 = 14.","m = 3 + 11 = 14."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20680,"question_number":20681,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^3)^11 = 2^m, find m.","(2^3)^11 = 2^m எனில் m காண்க."],"options":[["34","34"],["32","32"],["33","33"],["35","35"]],"answer":2,"explanation":["m = 3 × 11 = 33.","m = 3 × 11 = 33."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20681,"question_number":20682,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 1681.","1681 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["40","40"],["43","43"],["41","41"],["42","42"]],"answer":2,"explanation":["41 × 41 = 1681; √1681 = 41.","41 × 41 = 1681; √1681 = 41."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20682,"question_number":20683,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 68921.","68921 இன் கனமூலத்தைக் காண்க."],"options":[["41","41"],["43","43"],["40","40"],["42","42"]],"answer":0,"explanation":["41 × 41 × 41 = 68921; cube root = 41.","41 × 41 × 41 = 68921; கனமூலம் = 41."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20683,"question_number":20684,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 55% of ₹60.","₹60 இன் 55% காண்க."],"options":[["35","35"],["34","34"],["33","33"],["32","32"]],"answer":2,"explanation":["60×55/100 = 33.","60×55/100 = 33."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20684,"question_number":20685,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹300 has a 55% discount. What is the sale price in rupees?","₹300 குறித்த விலையுள்ள பைக்கு 55% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["135","135"],["137","137"],["134","134"],["136","136"]],"answer":0,"explanation":["300 × (100−55)/100 = 135.","300 × (100−55)/100 = 135."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20685,"question_number":20686,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹300 sells for ₹465. Find the profit percentage.","₹300 க்கு வாங்கிய பொருள் ₹465 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["57","57"],["54","54"],["55","55"],["56","56"]],"answer":2,"explanation":["(465−300)/300×100 = 55%.","(465−300)/300×100 = 55%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20686,"question_number":20687,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹3000 at 11% per year for 3 years.","₹3000 க்கு ஆண்டுக்கு 11% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["989","989"],["990","990"],["991","991"],["992","992"]],"answer":1,"explanation":["3000×11×3/100 = 990.","3000×11×3/100 = 990."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20687,"question_number":20688,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹30000 at 11% a year for 2 years, compounded annually.","₹30000 க்கு ஆண்டுக்கு 11% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["6964","6964"],["6962","6962"],["6965","6965"],["6963","6963"]],"answer":3,"explanation":["30000×[(1+11/100)²−1] = 6963.","30000×[(1+11/100)²−1] = 6963."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20688,"question_number":20689,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["11 metres of cloth cost ₹30. At the same rate, what is the cost of 14 metres in rupees?","11 மீ துணியின் விலை ₹30. அதே வீதத்தில் 14 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["409/11","409/11"],["442/11","442/11"],["420/11","420/11"],["431/11","431/11"]],"answer":2,"explanation":["30/11×14 = 420/11.","30/11×14 = 420/11."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20689,"question_number":20690,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["11 equally efficient machines complete a job in 3 hours. How many hours do 13 such machines require at the same rate?","சமத் திறனுடைய 11 இயந்திரங்கள் வேலையை 3 மணியில் முடிக்கின்றன. அதே வீதத்தில் 13 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["33/13","33/13"],["46/13","46/13"],["59/13","59/13"],["20/13","20/13"]],"answer":0,"explanation":["11×3/(11+2) = 33/13 hours.","11×3/(11+2) = 33/13 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20690,"question_number":20691,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 6 cm and perpendicular height 11 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 6 செமீ; செங்குத்து உயரம் 11 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["67","67"],["68","68"],["65","65"],["66","66"]],"answer":3,"explanation":["6×11 = 66.","6×11 = 66."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20691,"question_number":20692,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 6 cm and 22 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 6 செமீ, 22 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["65","65"],["68","68"],["66","66"],["67","67"]],"answer":2,"explanation":["½×6×22 = 66 cm².","½×6×22 = 66 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20692,"question_number":20693,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 6 m and 28 m, and height 11 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 6 மீ, 28 மீ; உயரம் 11 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["188","188"],["186","186"],["189","189"],["187","187"]],"answer":3,"explanation":["½×(6+28)×11 = 187.","½×(6+28)×11 = 187."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20693,"question_number":20694,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 21 cm makes 11 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","21 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 11 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["1454","1454"],["1452","1452"],["1453","1453"],["1451","1451"]],"answer":1,"explanation":["11×2×22/7×21 = 1452.","11×2×22/7×21 = 1452."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20694,"question_number":20695,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 11 circular mats, each of radius 21 cm. Find their total area in cm², using π=22/7.","தலா 21 செமீ ஆரமுள்ள 11 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["15245","15245"],["15248","15248"],["15246","15246"],["15247","15247"]],"answer":2,"explanation":["11×22/7×21² = 15246.","11×22/7×21² = 15246."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20695,"question_number":20696,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 26° and 52°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 26°, 52°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["104","104"],["103","103"],["101","101"],["102","102"]],"answer":3,"explanation":["180−26−52 = 102°.","180−26−52 = 102°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20696,"question_number":20697,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 53°. One remote interior angle is 31°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 53°. அதற்கான ஓர் எதிர் உட்கோணம் 31°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["24","24"],["21","21"],["23","23"],["22","22"]],"answer":3,"explanation":["53 − 31 = 22°.","53 − 31 = 22°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20697,"question_number":20698,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 3, 14, 25, 36, 47.","3, 14, 25, 36, 47 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["27","27"],["26","26"],["25","25"],["24","24"]],"answer":2,"explanation":["Sum/5 = 125/5 = 25.","கூடுதல்/5 = 125/5 = 25."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20698,"question_number":20699,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 58, 3, 25, 80, 14.","வரிசைப்படுத்தி இடைநிலை காண்க: 58, 3, 25, 80, 14."],"options":[["25","25"],["27","27"],["24","24"],["26","26"]],"answer":0,"explanation":["Sorted: 3, 14, 25, 58, 80; middle value = 25.","வரிசை: 3, 14, 25, 58, 80; நடு மதிப்பு = 25."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20699,"question_number":20700,"practice_set":828},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 3, 14, 3, 25, 36, 3?","3, 14, 3, 25, 36, 3 தரவுகளின் முகடு எது?"],"options":[["3","3"],["5","5"],["4","4"],["2","2"]],"answer":0,"explanation":["3 occurs 3 times; each other value occurs once.","3 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20700,"question_number":20701,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 3 hours and another in 11 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 3 மணியிலும் மற்றொன்று 11 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["47/14","47/14"],["61/14","61/14"],["33/14","33/14"],["19/14","19/14"]],"answer":2,"explanation":["Combined hourly rate = 1/3+1/11; time = 33/14 = 33/14 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/3+1/11; காலம் = 33/14 = 33/14 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20701,"question_number":20702,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −3/11. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −3/11. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["3/11","3/11"],["25/11","25/11"],["-8/11","-8/11"],["14/11","14/11"]],"answer":0,"explanation":["−3/11 + 3/11 = 0. Simplified additive inverse: 3/11.","−3/11 + 3/11 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 3/11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20702,"question_number":20703,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 3 and 11?","3 மற்றும் 11 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["8","8"],["7","7"],["9","9"],["6","6"]],"answer":1,"explanation":["(3+11)/2 = 7.","(3+11)/2 = 7."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20703,"question_number":20704,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 4/11 + 1/12.","கூட்டிச் சுருக்குக: 4/11 + 1/12."],"options":[["59/132","59/132"],["-73/132","-73/132"],["323/132","323/132"],["191/132","191/132"]],"answer":0,"explanation":["[4×12 + 11]/[11×12] = 59/132.","[4×12 + 11]/[11×12] = 59/132."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20704,"question_number":20705,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 4/11 − 1/12.","கழித்துச் சுருக்குக: 4/11 − 1/12."],"options":[["37/132","37/132"],["-95/132","-95/132"],["169/132","169/132"],["301/132","301/132"]],"answer":0,"explanation":["[4×12 − 11]/[11×12] = 37/132.","[4×12 − 11]/[11×12] = 37/132."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20705,"question_number":20706,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−4/11) × (12/5).","(−4/11) × (12/5) பெருக்கற்பலனைச் சுருக்குக."],"options":[["62/55","62/55"],["-103/55","-103/55"],["7/55","7/55"],["-48/55","-48/55"]],"answer":3,"explanation":["−48/55 = -48/55.","−48/55 = -48/55."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20706,"question_number":20707,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (4/11) ÷ (5/12) in simplest form.","(4/11) ÷ (5/12) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["158/55","158/55"],["103/55","103/55"],["-7/55","-7/55"],["48/55","48/55"]],"answer":3,"explanation":["(4/11) × (12/5) = 48/55.","(4/11) × (12/5) = 48/55."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20707,"question_number":20708,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 5.1 and 0.11.","5.1 மற்றும் 0.11 தசம எண்களைக் கூட்டுக."],"options":[["5.21","5.21"],["5.22","5.22"],["5.31","5.31"],["5.20","5.20"]],"answer":0,"explanation":["5.1 + 0.11 = 5.21.","5.1 + 0.11 = 5.21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20708,"question_number":20709,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 11x + 4 = 169.","11x + 4 = 169 சமன்பாட்டைத் தீர்க்க."],"options":[["14","14"],["17","17"],["16","16"],["15","15"]],"answer":3,"explanation":["x = (169 − 4)/11 = 15.","x = (169 − 4)/11 = 15."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20709,"question_number":20710,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 4 and y = 11, find (x+y)² − x² − y², then divide by 2.","x = 4, y = 11 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["44","44"],["45","45"],["46","46"],["43","43"]],"answer":0,"explanation":["[(x+y)²−x²−y²]/2 = xy = 4×11 = 44.","[(x+y)²−x²−y²]/2 = xy = 4×11 = 44."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20710,"question_number":20711,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 4, y = 11.","x = 4, y = 11 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["224","224"],["225","225"],["227","227"],["226","226"]],"answer":1,"explanation":["(x+y)² = (4+11)² = 225.","(x+y)² = (4+11)² = 225."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20711,"question_number":20712,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^4 × 7^11 = 7^m, what is m?","7^4 × 7^11 = 7^m எனில் m என்ன?"],"options":[["14","14"],["15","15"],["17","17"],["16","16"]],"answer":1,"explanation":["m = 4 + 11 = 15.","m = 4 + 11 = 15."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20712,"question_number":20713,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^4)^11 = 2^m, find m.","(2^4)^11 = 2^m எனில் m காண்க."],"options":[["43","43"],["46","46"],["45","45"],["44","44"]],"answer":3,"explanation":["m = 4 × 11 = 44.","m = 4 × 11 = 44."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20713,"question_number":20714,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 2601.","2601 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["51","51"],["50","50"],["52","52"],["53","53"]],"answer":0,"explanation":["51 × 51 = 2601; √2601 = 51.","51 × 51 = 2601; √2601 = 51."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20714,"question_number":20715,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 132651.","132651 இன் கனமூலத்தைக் காண்க."],"options":[["53","53"],["51","51"],["52","52"],["50","50"]],"answer":1,"explanation":["51 × 51 × 51 = 132651; cube root = 51.","51 × 51 × 51 = 132651; கனமூலம் = 51."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20715,"question_number":20716,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 55% of ₹80.","₹80 இன் 55% காண்க."],"options":[["46","46"],["45","45"],["43","43"],["44","44"]],"answer":3,"explanation":["80×55/100 = 44.","80×55/100 = 44."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20716,"question_number":20717,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹400 has a 55% discount. What is the sale price in rupees?","₹400 குறித்த விலையுள்ள பைக்கு 55% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["182","182"],["179","179"],["181","181"],["180","180"]],"answer":3,"explanation":["400 × (100−55)/100 = 180.","400 × (100−55)/100 = 180."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20717,"question_number":20718,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹400 sells for ₹620. Find the profit percentage.","₹400 க்கு வாங்கிய பொருள் ₹620 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["57","57"],["54","54"],["55","55"],["56","56"]],"answer":2,"explanation":["(620−400)/400×100 = 55%.","(620−400)/400×100 = 55%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20718,"question_number":20719,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹4000 at 11% per year for 3 years.","₹4000 க்கு ஆண்டுக்கு 11% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1319","1319"],["1320","1320"],["1321","1321"],["1322","1322"]],"answer":1,"explanation":["4000×11×3/100 = 1320.","4000×11×3/100 = 1320."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20719,"question_number":20720,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹40000 at 11% a year for 2 years, compounded annually.","₹40000 க்கு ஆண்டுக்கு 11% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["9286","9286"],["9285","9285"],["9284","9284"],["9283","9283"]],"answer":2,"explanation":["40000×[(1+11/100)²−1] = 9284.","40000×[(1+11/100)²−1] = 9284."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20720,"question_number":20721,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["11 metres of cloth cost ₹40. At the same rate, what is the cost of 14 metres in rupees?","11 மீ துணியின் விலை ₹40. அதே வீதத்தில் 14 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["549/11","549/11"],["560/11","560/11"],["582/11","582/11"],["571/11","571/11"]],"answer":1,"explanation":["40/11×14 = 560/11.","40/11×14 = 560/11."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20721,"question_number":20722,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["11 equally efficient machines complete a job in 4 hours. How many hours do 13 such machines require at the same rate?","சமத் திறனுடைய 11 இயந்திரங்கள் வேலையை 4 மணியில் முடிக்கின்றன. அதே வீதத்தில் 13 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["44/13","44/13"],["31/13","31/13"],["57/13","57/13"],["70/13","70/13"]],"answer":0,"explanation":["11×4/(11+2) = 44/13 hours.","11×4/(11+2) = 44/13 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20722,"question_number":20723,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 8 cm and perpendicular height 11 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 8 செமீ; செங்குத்து உயரம் 11 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["89","89"],["87","87"],["88","88"],["90","90"]],"answer":2,"explanation":["8×11 = 88.","8×11 = 88."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20723,"question_number":20724,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 8 cm and 22 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 8 செமீ, 22 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["89","89"],["87","87"],["90","90"],["88","88"]],"answer":3,"explanation":["½×8×22 = 88 cm².","½×8×22 = 88 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20724,"question_number":20725,"practice_set":829},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 8 m and 30 m, and height 11 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 8 மீ, 30 மீ; உயரம் 11 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["208","208"],["209","209"],["211","211"],["210","210"]],"answer":1,"explanation":["½×(8+30)×11 = 209.","½×(8+30)×11 = 209."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20725,"question_number":20726,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 28 cm makes 11 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","28 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 11 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["1936","1936"],["1937","1937"],["1938","1938"],["1935","1935"]],"answer":0,"explanation":["11×2×22/7×28 = 1936.","11×2×22/7×28 = 1936."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20726,"question_number":20727,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 11 circular mats, each of radius 28 cm. Find their total area in cm², using π=22/7.","தலா 28 செமீ ஆரமுள்ள 11 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["27104","27104"],["27103","27103"],["27106","27106"],["27105","27105"]],"answer":0,"explanation":["11×22/7×28² = 27104.","11×22/7×28² = 27104."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20727,"question_number":20728,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 28° and 52°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 28°, 52°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["99","99"],["100","100"],["101","101"],["102","102"]],"answer":1,"explanation":["180−28−52 = 100°.","180−28−52 = 100°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20728,"question_number":20729,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 54°. One remote interior angle is 31°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 54°. அதற்கான ஓர் எதிர் உட்கோணம் 31°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["25","25"],["23","23"],["22","22"],["24","24"]],"answer":1,"explanation":["54 − 31 = 23°.","54 − 31 = 23°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20729,"question_number":20730,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 4, 15, 26, 37, 48.","4, 15, 26, 37, 48 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["25","25"],["28","28"],["27","27"],["26","26"]],"answer":3,"explanation":["Sum/5 = 130/5 = 26.","கூடுதல்/5 = 130/5 = 26."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20730,"question_number":20731,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 59, 4, 26, 81, 15.","வரிசைப்படுத்தி இடைநிலை காண்க: 59, 4, 26, 81, 15."],"options":[["25","25"],["27","27"],["28","28"],["26","26"]],"answer":3,"explanation":["Sorted: 4, 15, 26, 59, 81; middle value = 26.","வரிசை: 4, 15, 26, 59, 81; நடு மதிப்பு = 26."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20731,"question_number":20732,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 4, 15, 4, 26, 37, 4?","4, 15, 4, 26, 37, 4 தரவுகளின் முகடு எது?"],"options":[["6","6"],["3","3"],["5","5"],["4","4"]],"answer":3,"explanation":["4 occurs 3 times; each other value occurs once.","4 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20732,"question_number":20733,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 4 hours and another in 11 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 4 மணியிலும் மற்றொன்று 11 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["29/15","29/15"],["74/15","74/15"],["44/15","44/15"],["59/15","59/15"]],"answer":2,"explanation":["Combined hourly rate = 1/4+1/11; time = 44/15 = 44/15 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/4+1/11; காலம் = 44/15 = 44/15 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20733,"question_number":20734,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −4/11. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −4/11. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["15/11","15/11"],["-7/11","-7/11"],["26/11","26/11"],["4/11","4/11"]],"answer":3,"explanation":["−4/11 + 4/11 = 0. Simplified additive inverse: 4/11.","−4/11 + 4/11 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 4/11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20734,"question_number":20735,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 4 and 11?","4 மற்றும் 11 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["13/2","13/2"],["19/2","19/2"],["15/2","15/2"],["17/2","17/2"]],"answer":2,"explanation":["(4+11)/2 = 15/2.","(4+11)/2 = 15/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20735,"question_number":20736,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 5/11 + 1/12.","கூட்டிச் சுருக்குக: 5/11 + 1/12."],"options":[["-61/132","-61/132"],["203/132","203/132"],["71/132","71/132"],["335/132","335/132"]],"answer":2,"explanation":["[5×12 + 11]/[11×12] = 71/132.","[5×12 + 11]/[11×12] = 71/132."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20736,"question_number":20737,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 5/11 − 1/12.","கழித்துச் சுருக்குக: 5/11 − 1/12."],"options":[["181/132","181/132"],["49/132","49/132"],["313/132","313/132"],["-83/132","-83/132"]],"answer":1,"explanation":["[5×12 − 11]/[11×12] = 49/132.","[5×12 − 11]/[11×12] = 49/132."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20737,"question_number":20738,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−5/11) × (12/6).","(−5/11) × (12/6) பெருக்கற்பலனைச் சுருக்குக."],"options":[["12/11","12/11"],["-10/11","-10/11"],["-21/11","-21/11"],["1/11","1/11"]],"answer":1,"explanation":["−60/66 = -10/11.","−60/66 = -10/11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20738,"question_number":20739,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (5/11) ÷ (6/12) in simplest form.","(5/11) ÷ (6/12) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["10/11","10/11"],["21/11","21/11"],["-1/11","-1/11"],["32/11","32/11"]],"answer":0,"explanation":["(5/11) × (12/6) = 10/11.","(5/11) × (12/6) = 10/11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20739,"question_number":20740,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 6.1 and 0.11.","6.1 மற்றும் 0.11 தசம எண்களைக் கூட்டுக."],"options":[["6.21","6.21"],["6.31","6.31"],["6.22","6.22"],["6.20","6.20"]],"answer":0,"explanation":["6.1 + 0.11 = 6.21.","6.1 + 0.11 = 6.21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20740,"question_number":20741,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 11x + 5 = 181.","11x + 5 = 181 சமன்பாட்டைத் தீர்க்க."],"options":[["17","17"],["18","18"],["15","15"],["16","16"]],"answer":3,"explanation":["x = (181 − 5)/11 = 16.","x = (181 − 5)/11 = 16."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20741,"question_number":20742,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 5 and y = 11, find (x+y)² − x² − y², then divide by 2.","x = 5, y = 11 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["56","56"],["57","57"],["54","54"],["55","55"]],"answer":3,"explanation":["[(x+y)²−x²−y²]/2 = xy = 5×11 = 55.","[(x+y)²−x²−y²]/2 = xy = 5×11 = 55."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20742,"question_number":20743,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 5, y = 11.","x = 5, y = 11 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["258","258"],["257","257"],["256","256"],["255","255"]],"answer":2,"explanation":["(x+y)² = (5+11)² = 256.","(x+y)² = (5+11)² = 256."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20743,"question_number":20744,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^5 × 7^11 = 7^m, what is m?","7^5 × 7^11 = 7^m எனில் m என்ன?"],"options":[["17","17"],["15","15"],["18","18"],["16","16"]],"answer":3,"explanation":["m = 5 + 11 = 16.","m = 5 + 11 = 16."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20744,"question_number":20745,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^5)^11 = 2^m, find m.","(2^5)^11 = 2^m எனில் m காண்க."],"options":[["56","56"],["57","57"],["55","55"],["54","54"]],"answer":2,"explanation":["m = 5 × 11 = 55.","m = 5 × 11 = 55."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20745,"question_number":20746,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 3721.","3721 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["63","63"],["62","62"],["61","61"],["60","60"]],"answer":2,"explanation":["61 × 61 = 3721; √3721 = 61.","61 × 61 = 3721; √3721 = 61."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20746,"question_number":20747,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 226981.","226981 இன் கனமூலத்தைக் காண்க."],"options":[["62","62"],["63","63"],["61","61"],["60","60"]],"answer":2,"explanation":["61 × 61 × 61 = 226981; cube root = 61.","61 × 61 × 61 = 226981; கனமூலம் = 61."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20747,"question_number":20748,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 55% of ₹100.","₹100 இன் 55% காண்க."],"options":[["54","54"],["56","56"],["57","57"],["55","55"]],"answer":3,"explanation":["100×55/100 = 55.","100×55/100 = 55."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20748,"question_number":20749,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹500 has a 55% discount. What is the sale price in rupees?","₹500 குறித்த விலையுள்ள பைக்கு 55% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["227","227"],["224","224"],["226","226"],["225","225"]],"answer":3,"explanation":["500 × (100−55)/100 = 225.","500 × (100−55)/100 = 225."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20749,"question_number":20750,"practice_set":830},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹500 sells for ₹775. Find the profit percentage.","₹500 க்கு வாங்கிய பொருள் ₹775 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["57","57"],["56","56"],["55","55"],["54","54"]],"answer":2,"explanation":["(775−500)/500×100 = 55%.","(775−500)/500×100 = 55%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20750,"question_number":20751,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹5000 at 11% per year for 3 years.","₹5000 க்கு ஆண்டுக்கு 11% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1652","1652"],["1649","1649"],["1651","1651"],["1650","1650"]],"answer":3,"explanation":["5000×11×3/100 = 1650.","5000×11×3/100 = 1650."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20751,"question_number":20752,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹50000 at 11% a year for 2 years, compounded annually.","₹50000 க்கு ஆண்டுக்கு 11% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["11606","11606"],["11604","11604"],["11607","11607"],["11605","11605"]],"answer":3,"explanation":["50000×[(1+11/100)²−1] = 11605.","50000×[(1+11/100)²−1] = 11605."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20752,"question_number":20753,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["11 metres of cloth cost ₹50. At the same rate, what is the cost of 14 metres in rupees?","11 மீ துணியின் விலை ₹50. அதே வீதத்தில் 14 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["722/11","722/11"],["689/11","689/11"],["700/11","700/11"],["711/11","711/11"]],"answer":2,"explanation":["50/11×14 = 700/11.","50/11×14 = 700/11."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20753,"question_number":20754,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["11 equally efficient machines complete a job in 5 hours. How many hours do 13 such machines require at the same rate?","சமத் திறனுடைய 11 இயந்திரங்கள் வேலையை 5 மணியில் முடிக்கின்றன. அதே வீதத்தில் 13 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["42/13","42/13"],["55/13","55/13"],["81/13","81/13"],["68/13","68/13"]],"answer":1,"explanation":["11×5/(11+2) = 55/13 hours.","11×5/(11+2) = 55/13 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20754,"question_number":20755,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 10 cm and perpendicular height 11 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 10 செமீ; செங்குத்து உயரம் 11 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["110","110"],["111","111"],["109","109"],["112","112"]],"answer":0,"explanation":["10×11 = 110.","10×11 = 110."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20755,"question_number":20756,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 10 cm and 22 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 10 செமீ, 22 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["111","111"],["110","110"],["112","112"],["109","109"]],"answer":1,"explanation":["½×10×22 = 110 cm².","½×10×22 = 110 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20756,"question_number":20757,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 10 m and 32 m, and height 11 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 10 மீ, 32 மீ; உயரம் 11 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["231","231"],["233","233"],["232","232"],["230","230"]],"answer":0,"explanation":["½×(10+32)×11 = 231.","½×(10+32)×11 = 231."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20757,"question_number":20758,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 35 cm makes 11 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","35 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 11 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["2422","2422"],["2420","2420"],["2421","2421"],["2419","2419"]],"answer":1,"explanation":["11×2×22/7×35 = 2420.","11×2×22/7×35 = 2420."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20758,"question_number":20759,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 11 circular mats, each of radius 35 cm. Find their total area in cm², using π=22/7.","தலா 35 செமீ ஆரமுள்ள 11 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["42349","42349"],["42352","42352"],["42351","42351"],["42350","42350"]],"answer":3,"explanation":["11×22/7×35² = 42350.","11×22/7×35² = 42350."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20759,"question_number":20760,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 30° and 52°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 30°, 52°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["97","97"],["98","98"],["100","100"],["99","99"]],"answer":1,"explanation":["180−30−52 = 98°.","180−30−52 = 98°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20760,"question_number":20761,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 55°. One remote interior angle is 31°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 55°. அதற்கான ஓர் எதிர் உட்கோணம் 31°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["25","25"],["24","24"],["23","23"],["26","26"]],"answer":1,"explanation":["55 − 31 = 24°.","55 − 31 = 24°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20761,"question_number":20762,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 5, 16, 27, 38, 49.","5, 16, 27, 38, 49 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["26","26"],["29","29"],["27","27"],["28","28"]],"answer":2,"explanation":["Sum/5 = 135/5 = 27.","கூடுதல்/5 = 135/5 = 27."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20762,"question_number":20763,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 60, 5, 27, 82, 16.","வரிசைப்படுத்தி இடைநிலை காண்க: 60, 5, 27, 82, 16."],"options":[["29","29"],["28","28"],["27","27"],["26","26"]],"answer":2,"explanation":["Sorted: 5, 16, 27, 60, 82; middle value = 27.","வரிசை: 5, 16, 27, 60, 82; நடு மதிப்பு = 27."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20763,"question_number":20764,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 5, 16, 5, 27, 38, 5?","5, 16, 5, 27, 38, 5 தரவுகளின் முகடு எது?"],"options":[["5","5"],["4","4"],["7","7"],["6","6"]],"answer":0,"explanation":["5 occurs 3 times; each other value occurs once.","5 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20764,"question_number":20765,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 5 hours and another in 11 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 5 மணியிலும் மற்றொன்று 11 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["87/16","87/16"],["55/16","55/16"],["39/16","39/16"],["71/16","71/16"]],"answer":1,"explanation":["Combined hourly rate = 1/5+1/11; time = 55/16 = 55/16 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/5+1/11; காலம் = 55/16 = 55/16 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20765,"question_number":20766,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −5/11. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −5/11. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["27/11","27/11"],["-6/11","-6/11"],["16/11","16/11"],["5/11","5/11"]],"answer":3,"explanation":["−5/11 + 5/11 = 0. Simplified additive inverse: 5/11.","−5/11 + 5/11 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 5/11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20766,"question_number":20767,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 5 and 11?","5 மற்றும் 11 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["9","9"],["7","7"],["8","8"],["10","10"]],"answer":2,"explanation":["(5+11)/2 = 8.","(5+11)/2 = 8."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20767,"question_number":20768,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 6/11 + 1/12.","கூட்டிச் சுருக்குக: 6/11 + 1/12."],"options":[["83/132","83/132"],["347/132","347/132"],["215/132","215/132"],["-49/132","-49/132"]],"answer":0,"explanation":["[6×12 + 11]/[11×12] = 83/132.","[6×12 + 11]/[11×12] = 83/132."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20768,"question_number":20769,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 6/11 − 1/12.","கழித்துச் சுருக்குக: 6/11 − 1/12."],"options":[["325/132","325/132"],["-71/132","-71/132"],["61/132","61/132"],["193/132","193/132"]],"answer":2,"explanation":["[6×12 − 11]/[11×12] = 61/132.","[6×12 − 11]/[11×12] = 61/132."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20769,"question_number":20770,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−6/11) × (12/7).","(−6/11) × (12/7) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-72/77","-72/77"],["82/77","82/77"],["5/77","5/77"],["-149/77","-149/77"]],"answer":0,"explanation":["−72/77 = -72/77.","−72/77 = -72/77."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20770,"question_number":20771,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (6/11) ÷ (7/12) in simplest form.","(6/11) ÷ (7/12) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["226/77","226/77"],["149/77","149/77"],["-5/77","-5/77"],["72/77","72/77"]],"answer":3,"explanation":["(6/11) × (12/7) = 72/77.","(6/11) × (12/7) = 72/77."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20771,"question_number":20772,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 7.1 and 0.11.","7.1 மற்றும் 0.11 தசம எண்களைக் கூட்டுக."],"options":[["7.20","7.20"],["7.31","7.31"],["7.21","7.21"],["7.22","7.22"]],"answer":2,"explanation":["7.1 + 0.11 = 7.21.","7.1 + 0.11 = 7.21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20772,"question_number":20773,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 11x + 6 = 193.","11x + 6 = 193 சமன்பாட்டைத் தீர்க்க."],"options":[["17","17"],["18","18"],["16","16"],["19","19"]],"answer":0,"explanation":["x = (193 − 6)/11 = 17.","x = (193 − 6)/11 = 17."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20773,"question_number":20774,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 6 and y = 11, find (x+y)² − x² − y², then divide by 2.","x = 6, y = 11 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["67","67"],["66","66"],["68","68"],["65","65"]],"answer":1,"explanation":["[(x+y)²−x²−y²]/2 = xy = 6×11 = 66.","[(x+y)²−x²−y²]/2 = xy = 6×11 = 66."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20774,"question_number":20775,"practice_set":831},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 6, y = 11.","x = 6, y = 11 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["289","289"],["290","290"],["291","291"],["288","288"]],"answer":0,"explanation":["(x+y)² = (6+11)² = 289.","(x+y)² = (6+11)² = 289."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20775,"question_number":20776,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^6 × 7^11 = 7^m, what is m?","7^6 × 7^11 = 7^m எனில் m என்ன?"],"options":[["18","18"],["16","16"],["19","19"],["17","17"]],"answer":3,"explanation":["m = 6 + 11 = 17.","m = 6 + 11 = 17."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20776,"question_number":20777,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^6)^11 = 2^m, find m.","(2^6)^11 = 2^m எனில் m காண்க."],"options":[["67","67"],["66","66"],["68","68"],["65","65"]],"answer":1,"explanation":["m = 6 × 11 = 66.","m = 6 × 11 = 66."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20777,"question_number":20778,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 5041.","5041 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["71","71"],["72","72"],["70","70"],["73","73"]],"answer":0,"explanation":["71 × 71 = 5041; √5041 = 71.","71 × 71 = 5041; √5041 = 71."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20778,"question_number":20779,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 357911.","357911 இன் கனமூலத்தைக் காண்க."],"options":[["73","73"],["72","72"],["70","70"],["71","71"]],"answer":3,"explanation":["71 × 71 × 71 = 357911; cube root = 71.","71 × 71 × 71 = 357911; கனமூலம் = 71."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20779,"question_number":20780,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 55% of ₹120.","₹120 இன் 55% காண்க."],"options":[["67","67"],["68","68"],["65","65"],["66","66"]],"answer":3,"explanation":["120×55/100 = 66.","120×55/100 = 66."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20780,"question_number":20781,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹600 has a 55% discount. What is the sale price in rupees?","₹600 குறித்த விலையுள்ள பைக்கு 55% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["272","272"],["270","270"],["269","269"],["271","271"]],"answer":1,"explanation":["600 × (100−55)/100 = 270.","600 × (100−55)/100 = 270."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20781,"question_number":20782,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹600 sells for ₹930. Find the profit percentage.","₹600 க்கு வாங்கிய பொருள் ₹930 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["57","57"],["56","56"],["54","54"],["55","55"]],"answer":3,"explanation":["(930−600)/600×100 = 55%.","(930−600)/600×100 = 55%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20782,"question_number":20783,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹6000 at 11% per year for 3 years.","₹6000 க்கு ஆண்டுக்கு 11% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1979","1979"],["1980","1980"],["1982","1982"],["1981","1981"]],"answer":1,"explanation":["6000×11×3/100 = 1980.","6000×11×3/100 = 1980."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20783,"question_number":20784,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹60000 at 11% a year for 2 years, compounded annually.","₹60000 க்கு ஆண்டுக்கு 11% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["13927","13927"],["13926","13926"],["13928","13928"],["13925","13925"]],"answer":1,"explanation":["60000×[(1+11/100)²−1] = 13926.","60000×[(1+11/100)²−1] = 13926."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20784,"question_number":20785,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["11 metres of cloth cost ₹60. At the same rate, what is the cost of 14 metres in rupees?","11 மீ துணியின் விலை ₹60. அதே வீதத்தில் 14 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["851/11","851/11"],["862/11","862/11"],["829/11","829/11"],["840/11","840/11"]],"answer":3,"explanation":["60/11×14 = 840/11.","60/11×14 = 840/11."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20785,"question_number":20786,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["11 equally efficient machines complete a job in 6 hours. How many hours do 13 such machines require at the same rate?","சமத் திறனுடைய 11 இயந்திரங்கள் வேலையை 6 மணியில் முடிக்கின்றன. அதே வீதத்தில் 13 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["79/13","79/13"],["53/13","53/13"],["92/13","92/13"],["66/13","66/13"]],"answer":3,"explanation":["11×6/(11+2) = 66/13 hours.","11×6/(11+2) = 66/13 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20786,"question_number":20787,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 12 cm and perpendicular height 11 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 12 செமீ; செங்குத்து உயரம் 11 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["133","133"],["134","134"],["132","132"],["131","131"]],"answer":2,"explanation":["12×11 = 132.","12×11 = 132."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20787,"question_number":20788,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 12 cm and 22 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 12 செமீ, 22 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["133","133"],["131","131"],["134","134"],["132","132"]],"answer":3,"explanation":["½×12×22 = 132 cm².","½×12×22 = 132 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20788,"question_number":20789,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 12 m and 34 m, and height 11 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 12 மீ, 34 மீ; உயரம் 11 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["253","253"],["255","255"],["254","254"],["252","252"]],"answer":0,"explanation":["½×(12+34)×11 = 253.","½×(12+34)×11 = 253."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20789,"question_number":20790,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 42 cm makes 11 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","42 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 11 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["2906","2906"],["2905","2905"],["2904","2904"],["2903","2903"]],"answer":2,"explanation":["11×2×22/7×42 = 2904.","11×2×22/7×42 = 2904."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20790,"question_number":20791,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 11 circular mats, each of radius 42 cm. Find their total area in cm², using π=22/7.","தலா 42 செமீ ஆரமுள்ள 11 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["60985","60985"],["60986","60986"],["60984","60984"],["60983","60983"]],"answer":2,"explanation":["11×22/7×42² = 60984.","11×22/7×42² = 60984."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20791,"question_number":20792,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 32° and 52°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 32°, 52°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["97","97"],["95","95"],["98","98"],["96","96"]],"answer":3,"explanation":["180−32−52 = 96°.","180−32−52 = 96°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20792,"question_number":20793,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 56°. One remote interior angle is 31°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 56°. அதற்கான ஓர் எதிர் உட்கோணம் 31°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["24","24"],["27","27"],["25","25"],["26","26"]],"answer":2,"explanation":["56 − 31 = 25°.","56 − 31 = 25°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20793,"question_number":20794,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 6, 17, 28, 39, 50.","6, 17, 28, 39, 50 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["30","30"],["28","28"],["27","27"],["29","29"]],"answer":1,"explanation":["Sum/5 = 140/5 = 28.","கூடுதல்/5 = 140/5 = 28."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20794,"question_number":20795,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 61, 6, 28, 83, 17.","வரிசைப்படுத்தி இடைநிலை காண்க: 61, 6, 28, 83, 17."],"options":[["27","27"],["29","29"],["30","30"],["28","28"]],"answer":3,"explanation":["Sorted: 6, 17, 28, 61, 83; middle value = 28.","வரிசை: 6, 17, 28, 61, 83; நடு மதிப்பு = 28."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20795,"question_number":20796,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 6, 17, 6, 28, 39, 6?","6, 17, 6, 28, 39, 6 தரவுகளின் முகடு எது?"],"options":[["5","5"],["8","8"],["6","6"],["7","7"]],"answer":2,"explanation":["6 occurs 3 times; each other value occurs once.","6 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20796,"question_number":20797,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 6 hours and another in 11 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 6 மணியிலும் மற்றொன்று 11 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["66/17","66/17"],["100/17","100/17"],["49/17","49/17"],["83/17","83/17"]],"answer":0,"explanation":["Combined hourly rate = 1/6+1/11; time = 66/17 = 66/17 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/6+1/11; காலம் = 66/17 = 66/17 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20797,"question_number":20798,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −6/11. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −6/11. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["17/11","17/11"],["-5/11","-5/11"],["28/11","28/11"],["6/11","6/11"]],"answer":3,"explanation":["−6/11 + 6/11 = 0. Simplified additive inverse: 6/11.","−6/11 + 6/11 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 6/11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20798,"question_number":20799,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 6 and 11?","6 மற்றும் 11 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["15/2","15/2"],["21/2","21/2"],["17/2","17/2"],["19/2","19/2"]],"answer":2,"explanation":["(6+11)/2 = 17/2.","(6+11)/2 = 17/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20799,"question_number":20800,"practice_set":832},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 7/11 + 1/12.","கூட்டிச் சுருக்குக: 7/11 + 1/12."],"options":[["359/132","359/132"],["-37/132","-37/132"],["227/132","227/132"],["95/132","95/132"]],"answer":3,"explanation":["[7×12 + 11]/[11×12] = 95/132.","[7×12 + 11]/[11×12] = 95/132."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20800,"question_number":20801,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 7/11 − 1/12.","கழித்துச் சுருக்குக: 7/11 − 1/12."],"options":[["205/132","205/132"],["337/132","337/132"],["-59/132","-59/132"],["73/132","73/132"]],"answer":3,"explanation":["[7×12 − 11]/[11×12] = 73/132.","[7×12 − 11]/[11×12] = 73/132."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20801,"question_number":20802,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−7/11) × (12/8).","(−7/11) × (12/8) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-43/22","-43/22"],["-21/22","-21/22"],["1/22","1/22"],["23/22","23/22"]],"answer":1,"explanation":["−84/88 = -21/22.","−84/88 = -21/22."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20802,"question_number":20803,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (7/11) ÷ (8/12) in simplest form.","(7/11) ÷ (8/12) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["65/22","65/22"],["21/22","21/22"],["43/22","43/22"],["-1/22","-1/22"]],"answer":1,"explanation":["(7/11) × (12/8) = 21/22.","(7/11) × (12/8) = 21/22."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20803,"question_number":20804,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 8.1 and 0.11.","8.1 மற்றும் 0.11 தசம எண்களைக் கூட்டுக."],"options":[["8.20","8.20"],["8.21","8.21"],["8.31","8.31"],["8.22","8.22"]],"answer":1,"explanation":["8.1 + 0.11 = 8.21.","8.1 + 0.11 = 8.21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20804,"question_number":20805,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 11x + 7 = 205.","11x + 7 = 205 சமன்பாட்டைத் தீர்க்க."],"options":[["18","18"],["17","17"],["19","19"],["20","20"]],"answer":0,"explanation":["x = (205 − 7)/11 = 18.","x = (205 − 7)/11 = 18."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20805,"question_number":20806,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 7 and y = 11, find (x+y)² − x² − y², then divide by 2.","x = 7, y = 11 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["76","76"],["78","78"],["77","77"],["79","79"]],"answer":2,"explanation":["[(x+y)²−x²−y²]/2 = xy = 7×11 = 77.","[(x+y)²−x²−y²]/2 = xy = 7×11 = 77."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20806,"question_number":20807,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 7, y = 11.","x = 7, y = 11 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["326","326"],["324","324"],["323","323"],["325","325"]],"answer":1,"explanation":["(x+y)² = (7+11)² = 324.","(x+y)² = (7+11)² = 324."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20807,"question_number":20808,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^7 × 7^11 = 7^m, what is m?","7^7 × 7^11 = 7^m எனில் m என்ன?"],"options":[["17","17"],["18","18"],["19","19"],["20","20"]],"answer":1,"explanation":["m = 7 + 11 = 18.","m = 7 + 11 = 18."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20808,"question_number":20809,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^7)^11 = 2^m, find m.","(2^7)^11 = 2^m எனில் m காண்க."],"options":[["77","77"],["78","78"],["79","79"],["76","76"]],"answer":0,"explanation":["m = 7 × 11 = 77.","m = 7 × 11 = 77."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20809,"question_number":20810,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 6561.","6561 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["83","83"],["80","80"],["82","82"],["81","81"]],"answer":3,"explanation":["81 × 81 = 6561; √6561 = 81.","81 × 81 = 6561; √6561 = 81."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20810,"question_number":20811,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 531441.","531441 இன் கனமூலத்தைக் காண்க."],"options":[["83","83"],["82","82"],["80","80"],["81","81"]],"answer":3,"explanation":["81 × 81 × 81 = 531441; cube root = 81.","81 × 81 × 81 = 531441; கனமூலம் = 81."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20811,"question_number":20812,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 55% of ₹140.","₹140 இன் 55% காண்க."],"options":[["76","76"],["77","77"],["79","79"],["78","78"]],"answer":1,"explanation":["140×55/100 = 77.","140×55/100 = 77."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20812,"question_number":20813,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹700 has a 55% discount. What is the sale price in rupees?","₹700 குறித்த விலையுள்ள பைக்கு 55% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["316","316"],["315","315"],["317","317"],["314","314"]],"answer":1,"explanation":["700 × (100−55)/100 = 315.","700 × (100−55)/100 = 315."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20813,"question_number":20814,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹700 sells for ₹1085. Find the profit percentage.","₹700 க்கு வாங்கிய பொருள் ₹1085 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["56","56"],["54","54"],["55","55"],["57","57"]],"answer":2,"explanation":["(1085−700)/700×100 = 55%.","(1085−700)/700×100 = 55%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20814,"question_number":20815,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹7000 at 11% per year for 3 years.","₹7000 க்கு ஆண்டுக்கு 11% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2310","2310"],["2311","2311"],["2312","2312"],["2309","2309"]],"answer":0,"explanation":["7000×11×3/100 = 2310.","7000×11×3/100 = 2310."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20815,"question_number":20816,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹70000 at 11% a year for 2 years, compounded annually.","₹70000 க்கு ஆண்டுக்கு 11% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["16249","16249"],["16246","16246"],["16248","16248"],["16247","16247"]],"answer":3,"explanation":["70000×[(1+11/100)²−1] = 16247.","70000×[(1+11/100)²−1] = 16247."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20816,"question_number":20817,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["11 metres of cloth cost ₹70. At the same rate, what is the cost of 14 metres in rupees?","11 மீ துணியின் விலை ₹70. அதே வீதத்தில் 14 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["1002/11","1002/11"],["980/11","980/11"],["991/11","991/11"],["969/11","969/11"]],"answer":1,"explanation":["70/11×14 = 980/11.","70/11×14 = 980/11."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20817,"question_number":20818,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["11 equally efficient machines complete a job in 7 hours. How many hours do 13 such machines require at the same rate?","சமத் திறனுடைய 11 இயந்திரங்கள் வேலையை 7 மணியில் முடிக்கின்றன. அதே வீதத்தில் 13 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["77/13","77/13"],["103/13","103/13"],["64/13","64/13"],["90/13","90/13"]],"answer":0,"explanation":["11×7/(11+2) = 77/13 hours.","11×7/(11+2) = 77/13 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20818,"question_number":20819,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 14 cm and perpendicular height 11 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 14 செமீ; செங்குத்து உயரம் 11 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["153","153"],["156","156"],["154","154"],["155","155"]],"answer":2,"explanation":["14×11 = 154.","14×11 = 154."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20819,"question_number":20820,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 14 cm and 22 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 14 செமீ, 22 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["156","156"],["155","155"],["154","154"],["153","153"]],"answer":2,"explanation":["½×14×22 = 154 cm².","½×14×22 = 154 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20820,"question_number":20821,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 14 m and 36 m, and height 11 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 14 மீ, 36 மீ; உயரம் 11 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["275","275"],["274","274"],["277","277"],["276","276"]],"answer":0,"explanation":["½×(14+36)×11 = 275.","½×(14+36)×11 = 275."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20821,"question_number":20822,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 49 cm makes 11 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","49 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 11 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["3387","3387"],["3388","3388"],["3390","3390"],["3389","3389"]],"answer":1,"explanation":["11×2×22/7×49 = 3388.","11×2×22/7×49 = 3388."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20822,"question_number":20823,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 11 circular mats, each of radius 49 cm. Find their total area in cm², using π=22/7.","தலா 49 செமீ ஆரமுள்ள 11 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["83006","83006"],["83005","83005"],["83007","83007"],["83008","83008"]],"answer":0,"explanation":["11×22/7×49² = 83006.","11×22/7×49² = 83006."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20823,"question_number":20824,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 34° and 52°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 34°, 52°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["94","94"],["96","96"],["93","93"],["95","95"]],"answer":0,"explanation":["180−34−52 = 94°.","180−34−52 = 94°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20824,"question_number":20825,"practice_set":833},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 57°. One remote interior angle is 31°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 57°. அதற்கான ஓர் எதிர் உட்கோணம் 31°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["28","28"],["26","26"],["27","27"],["25","25"]],"answer":1,"explanation":["57 − 31 = 26°.","57 − 31 = 26°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20825,"question_number":20826,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 7, 18, 29, 40, 51.","7, 18, 29, 40, 51 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["30","30"],["29","29"],["31","31"],["28","28"]],"answer":1,"explanation":["Sum/5 = 145/5 = 29.","கூடுதல்/5 = 145/5 = 29."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20826,"question_number":20827,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 62, 7, 29, 84, 18.","வரிசைப்படுத்தி இடைநிலை காண்க: 62, 7, 29, 84, 18."],"options":[["31","31"],["30","30"],["28","28"],["29","29"]],"answer":3,"explanation":["Sorted: 7, 18, 29, 62, 84; middle value = 29.","வரிசை: 7, 18, 29, 62, 84; நடு மதிப்பு = 29."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20827,"question_number":20828,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 7, 18, 7, 29, 40, 7?","7, 18, 7, 29, 40, 7 தரவுகளின் முகடு எது?"],"options":[["7","7"],["6","6"],["8","8"],["9","9"]],"answer":0,"explanation":["7 occurs 3 times; each other value occurs once.","7 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20828,"question_number":20829,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 7 hours and another in 11 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 7 மணியிலும் மற்றொன்று 11 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["95/18","95/18"],["59/18","59/18"],["77/18","77/18"],["113/18","113/18"]],"answer":2,"explanation":["Combined hourly rate = 1/7+1/11; time = 77/18 = 77/18 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/7+1/11; காலம் = 77/18 = 77/18 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20829,"question_number":20830,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −7/11. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −7/11. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["7/11","7/11"],["29/11","29/11"],["18/11","18/11"],["-4/11","-4/11"]],"answer":0,"explanation":["−7/11 + 7/11 = 0. Simplified additive inverse: 7/11.","−7/11 + 7/11 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 7/11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20830,"question_number":20831,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 7 and 11?","7 மற்றும் 11 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["9","9"],["8","8"],["11","11"],["10","10"]],"answer":0,"explanation":["(7+11)/2 = 9.","(7+11)/2 = 9."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20831,"question_number":20832,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 8/11 + 1/12.","கூட்டிச் சுருக்குக: 8/11 + 1/12."],"options":[["-25/132","-25/132"],["371/132","371/132"],["107/132","107/132"],["239/132","239/132"]],"answer":2,"explanation":["[8×12 + 11]/[11×12] = 107/132.","[8×12 + 11]/[11×12] = 107/132."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20832,"question_number":20833,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 8/11 − 1/12.","கழித்துச் சுருக்குக: 8/11 − 1/12."],"options":[["85/132","85/132"],["-47/132","-47/132"],["349/132","349/132"],["217/132","217/132"]],"answer":0,"explanation":["[8×12 − 11]/[11×12] = 85/132.","[8×12 − 11]/[11×12] = 85/132."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20833,"question_number":20834,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−8/11) × (12/9).","(−8/11) × (12/9) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-32/33","-32/33"],["34/33","34/33"],["1/33","1/33"],["-65/33","-65/33"]],"answer":0,"explanation":["−96/99 = -32/33.","−96/99 = -32/33."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20834,"question_number":20835,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (8/11) ÷ (9/12) in simplest form.","(8/11) ÷ (9/12) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["65/33","65/33"],["32/33","32/33"],["-1/33","-1/33"],["98/33","98/33"]],"answer":1,"explanation":["(8/11) × (12/9) = 32/33.","(8/11) × (12/9) = 32/33."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20835,"question_number":20836,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 9.1 and 0.11.","9.1 மற்றும் 0.11 தசம எண்களைக் கூட்டுக."],"options":[["9.22","9.22"],["9.20","9.20"],["9.21","9.21"],["9.31","9.31"]],"answer":2,"explanation":["9.1 + 0.11 = 9.21.","9.1 + 0.11 = 9.21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20836,"question_number":20837,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 11x + 8 = 217.","11x + 8 = 217 சமன்பாட்டைத் தீர்க்க."],"options":[["18","18"],["20","20"],["21","21"],["19","19"]],"answer":3,"explanation":["x = (217 − 8)/11 = 19.","x = (217 − 8)/11 = 19."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20837,"question_number":20838,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 8 and y = 11, find (x+y)² − x² − y², then divide by 2.","x = 8, y = 11 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["89","89"],["88","88"],["87","87"],["90","90"]],"answer":1,"explanation":["[(x+y)²−x²−y²]/2 = xy = 8×11 = 88.","[(x+y)²−x²−y²]/2 = xy = 8×11 = 88."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20838,"question_number":20839,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 8, y = 11.","x = 8, y = 11 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["360","360"],["362","362"],["363","363"],["361","361"]],"answer":3,"explanation":["(x+y)² = (8+11)² = 361.","(x+y)² = (8+11)² = 361."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20839,"question_number":20840,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^8 × 7^11 = 7^m, what is m?","7^8 × 7^11 = 7^m எனில் m என்ன?"],"options":[["18","18"],["21","21"],["19","19"],["20","20"]],"answer":2,"explanation":["m = 8 + 11 = 19.","m = 8 + 11 = 19."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20840,"question_number":20841,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^8)^11 = 2^m, find m.","(2^8)^11 = 2^m எனில் m காண்க."],"options":[["88","88"],["90","90"],["87","87"],["89","89"]],"answer":0,"explanation":["m = 8 × 11 = 88.","m = 8 × 11 = 88."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20841,"question_number":20842,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 8281.","8281 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["90","90"],["92","92"],["91","91"],["93","93"]],"answer":2,"explanation":["91 × 91 = 8281; √8281 = 91.","91 × 91 = 8281; √8281 = 91."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20842,"question_number":20843,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 753571.","753571 இன் கனமூலத்தைக் காண்க."],"options":[["91","91"],["92","92"],["93","93"],["90","90"]],"answer":0,"explanation":["91 × 91 × 91 = 753571; cube root = 91.","91 × 91 × 91 = 753571; கனமூலம் = 91."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20843,"question_number":20844,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 55% of ₹160.","₹160 இன் 55% காண்க."],"options":[["90","90"],["89","89"],["88","88"],["87","87"]],"answer":2,"explanation":["160×55/100 = 88.","160×55/100 = 88."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20844,"question_number":20845,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹800 has a 55% discount. What is the sale price in rupees?","₹800 குறித்த விலையுள்ள பைக்கு 55% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["361","361"],["362","362"],["360","360"],["359","359"]],"answer":2,"explanation":["800 × (100−55)/100 = 360.","800 × (100−55)/100 = 360."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20845,"question_number":20846,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹800 sells for ₹1240. Find the profit percentage.","₹800 க்கு வாங்கிய பொருள் ₹1240 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["54","54"],["55","55"],["57","57"],["56","56"]],"answer":1,"explanation":["(1240−800)/800×100 = 55%.","(1240−800)/800×100 = 55%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20846,"question_number":20847,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹8000 at 11% per year for 3 years.","₹8000 க்கு ஆண்டுக்கு 11% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2641","2641"],["2640","2640"],["2639","2639"],["2642","2642"]],"answer":1,"explanation":["8000×11×3/100 = 2640.","8000×11×3/100 = 2640."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20847,"question_number":20848,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹80000 at 11% a year for 2 years, compounded annually.","₹80000 க்கு ஆண்டுக்கு 11% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["18568","18568"],["18570","18570"],["18567","18567"],["18569","18569"]],"answer":0,"explanation":["80000×[(1+11/100)²−1] = 18568.","80000×[(1+11/100)²−1] = 18568."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20848,"question_number":20849,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["11 metres of cloth cost ₹80. At the same rate, what is the cost of 14 metres in rupees?","11 மீ துணியின் விலை ₹80. அதே வீதத்தில் 14 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["1131/11","1131/11"],["1109/11","1109/11"],["1142/11","1142/11"],["1120/11","1120/11"]],"answer":3,"explanation":["80/11×14 = 1120/11.","80/11×14 = 1120/11."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20849,"question_number":20850,"practice_set":834},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["11 equally efficient machines complete a job in 8 hours. How many hours do 13 such machines require at the same rate?","சமத் திறனுடைய 11 இயந்திரங்கள் வேலையை 8 மணியில் முடிக்கின்றன. அதே வீதத்தில் 13 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["75/13","75/13"],["114/13","114/13"],["101/13","101/13"],["88/13","88/13"]],"answer":3,"explanation":["11×8/(11+2) = 88/13 hours.","11×8/(11+2) = 88/13 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20850,"question_number":20851,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 16 cm and perpendicular height 11 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 16 செமீ; செங்குத்து உயரம் 11 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["175","175"],["176","176"],["178","178"],["177","177"]],"answer":1,"explanation":["16×11 = 176.","16×11 = 176."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20851,"question_number":20852,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 16 cm and 22 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 16 செமீ, 22 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["177","177"],["175","175"],["178","178"],["176","176"]],"answer":3,"explanation":["½×16×22 = 176 cm².","½×16×22 = 176 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20852,"question_number":20853,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 16 m and 38 m, and height 11 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 16 மீ, 38 மீ; உயரம் 11 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["297","297"],["298","298"],["296","296"],["299","299"]],"answer":0,"explanation":["½×(16+38)×11 = 297.","½×(16+38)×11 = 297."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20853,"question_number":20854,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 56 cm makes 11 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","56 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 11 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["3873","3873"],["3872","3872"],["3871","3871"],["3874","3874"]],"answer":1,"explanation":["11×2×22/7×56 = 3872.","11×2×22/7×56 = 3872."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20854,"question_number":20855,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 11 circular mats, each of radius 56 cm. Find their total area in cm², using π=22/7.","தலா 56 செமீ ஆரமுள்ள 11 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["108418","108418"],["108417","108417"],["108415","108415"],["108416","108416"]],"answer":3,"explanation":["11×22/7×56² = 108416.","11×22/7×56² = 108416."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20855,"question_number":20856,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 36° and 52°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 36°, 52°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["94","94"],["93","93"],["92","92"],["91","91"]],"answer":2,"explanation":["180−36−52 = 92°.","180−36−52 = 92°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20856,"question_number":20857,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 58°. One remote interior angle is 31°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 58°. அதற்கான ஓர் எதிர் உட்கோணம் 31°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["26","26"],["29","29"],["27","27"],["28","28"]],"answer":2,"explanation":["58 − 31 = 27°.","58 − 31 = 27°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20857,"question_number":20858,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 8, 19, 30, 41, 52.","8, 19, 30, 41, 52 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["32","32"],["30","30"],["29","29"],["31","31"]],"answer":1,"explanation":["Sum/5 = 150/5 = 30.","கூடுதல்/5 = 150/5 = 30."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20858,"question_number":20859,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 63, 8, 30, 85, 19.","வரிசைப்படுத்தி இடைநிலை காண்க: 63, 8, 30, 85, 19."],"options":[["31","31"],["32","32"],["30","30"],["29","29"]],"answer":2,"explanation":["Sorted: 8, 19, 30, 63, 85; middle value = 30.","வரிசை: 8, 19, 30, 63, 85; நடு மதிப்பு = 30."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20859,"question_number":20860,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 8, 19, 8, 30, 41, 8?","8, 19, 8, 30, 41, 8 தரவுகளின் முகடு எது?"],"options":[["7","7"],["8","8"],["9","9"],["10","10"]],"answer":1,"explanation":["8 occurs 3 times; each other value occurs once.","8 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20860,"question_number":20861,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 8 hours and another in 11 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 8 மணியிலும் மற்றொன்று 11 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["107/19","107/19"],["126/19","126/19"],["69/19","69/19"],["88/19","88/19"]],"answer":3,"explanation":["Combined hourly rate = 1/8+1/11; time = 88/19 = 88/19 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/8+1/11; காலம் = 88/19 = 88/19 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20861,"question_number":20862,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −8/11. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −8/11. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["30/11","30/11"],["-3/11","-3/11"],["8/11","8/11"],["19/11","19/11"]],"answer":2,"explanation":["−8/11 + 8/11 = 0. Simplified additive inverse: 8/11.","−8/11 + 8/11 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 8/11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20862,"question_number":20863,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 8 and 11?","8 மற்றும் 11 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["17/2","17/2"],["21/2","21/2"],["23/2","23/2"],["19/2","19/2"]],"answer":3,"explanation":["(8+11)/2 = 19/2.","(8+11)/2 = 19/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20863,"question_number":20864,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 9/11 + 1/12.","கூட்டிச் சுருக்குக: 9/11 + 1/12."],"options":[["-13/132","-13/132"],["119/132","119/132"],["383/132","383/132"],["251/132","251/132"]],"answer":1,"explanation":["[9×12 + 11]/[11×12] = 119/132.","[9×12 + 11]/[11×12] = 119/132."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20864,"question_number":20865,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 9/11 − 1/12.","கழித்துச் சுருக்குக: 9/11 − 1/12."],"options":[["-35/132","-35/132"],["97/132","97/132"],["229/132","229/132"],["361/132","361/132"]],"answer":1,"explanation":["[9×12 − 11]/[11×12] = 97/132.","[9×12 − 11]/[11×12] = 97/132."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20865,"question_number":20866,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−9/11) × (12/10).","(−9/11) × (12/10) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-109/55","-109/55"],["56/55","56/55"],["1/55","1/55"],["-54/55","-54/55"]],"answer":3,"explanation":["−108/110 = -54/55.","−108/110 = -54/55."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20866,"question_number":20867,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (9/11) ÷ (10/12) in simplest form.","(9/11) ÷ (10/12) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["54/55","54/55"],["109/55","109/55"],["164/55","164/55"],["-1/55","-1/55"]],"answer":0,"explanation":["(9/11) × (12/10) = 54/55.","(9/11) × (12/10) = 54/55."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20867,"question_number":20868,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 10.1 and 0.11.","10.1 மற்றும் 0.11 தசம எண்களைக் கூட்டுக."],"options":[["10.31","10.31"],["10.20","10.20"],["10.21","10.21"],["10.22","10.22"]],"answer":2,"explanation":["10.1 + 0.11 = 10.21.","10.1 + 0.11 = 10.21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20868,"question_number":20869,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 11x + 9 = 229.","11x + 9 = 229 சமன்பாட்டைத் தீர்க்க."],"options":[["19","19"],["22","22"],["20","20"],["21","21"]],"answer":2,"explanation":["x = (229 − 9)/11 = 20.","x = (229 − 9)/11 = 20."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20869,"question_number":20870,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 9 and y = 11, find (x+y)² − x² − y², then divide by 2.","x = 9, y = 11 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["98","98"],["101","101"],["100","100"],["99","99"]],"answer":3,"explanation":["[(x+y)²−x²−y²]/2 = xy = 9×11 = 99.","[(x+y)²−x²−y²]/2 = xy = 9×11 = 99."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20870,"question_number":20871,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 9, y = 11.","x = 9, y = 11 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["400","400"],["402","402"],["399","399"],["401","401"]],"answer":0,"explanation":["(x+y)² = (9+11)² = 400.","(x+y)² = (9+11)² = 400."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20871,"question_number":20872,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^9 × 7^11 = 7^m, what is m?","7^9 × 7^11 = 7^m எனில் m என்ன?"],"options":[["22","22"],["20","20"],["21","21"],["19","19"]],"answer":1,"explanation":["m = 9 + 11 = 20.","m = 9 + 11 = 20."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20872,"question_number":20873,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^9)^11 = 2^m, find m.","(2^9)^11 = 2^m எனில் m காண்க."],"options":[["98","98"],["99","99"],["100","100"],["101","101"]],"answer":1,"explanation":["m = 9 × 11 = 99.","m = 9 × 11 = 99."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20873,"question_number":20874,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 10201.","10201 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["101","101"],["102","102"],["103","103"],["100","100"]],"answer":0,"explanation":["101 × 101 = 10201; √10201 = 101.","101 × 101 = 10201; √10201 = 101."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20874,"question_number":20875,"practice_set":835},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 1030301.","1030301 இன் கனமூலத்தைக் காண்க."],"options":[["100","100"],["102","102"],["101","101"],["103","103"]],"answer":2,"explanation":["101 × 101 × 101 = 1030301; cube root = 101.","101 × 101 × 101 = 1030301; கனமூலம் = 101."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20875,"question_number":20876,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 55% of ₹180.","₹180 இன் 55% காண்க."],"options":[["98","98"],["99","99"],["101","101"],["100","100"]],"answer":1,"explanation":["180×55/100 = 99.","180×55/100 = 99."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20876,"question_number":20877,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹900 has a 55% discount. What is the sale price in rupees?","₹900 குறித்த விலையுள்ள பைக்கு 55% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["405","405"],["407","407"],["404","404"],["406","406"]],"answer":0,"explanation":["900 × (100−55)/100 = 405.","900 × (100−55)/100 = 405."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20877,"question_number":20878,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹900 sells for ₹1395. Find the profit percentage.","₹900 க்கு வாங்கிய பொருள் ₹1395 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["57","57"],["54","54"],["55","55"],["56","56"]],"answer":2,"explanation":["(1395−900)/900×100 = 55%.","(1395−900)/900×100 = 55%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20878,"question_number":20879,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹9000 at 11% per year for 3 years.","₹9000 க்கு ஆண்டுக்கு 11% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2971","2971"],["2970","2970"],["2972","2972"],["2969","2969"]],"answer":1,"explanation":["9000×11×3/100 = 2970.","9000×11×3/100 = 2970."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20879,"question_number":20880,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹90000 at 11% a year for 2 years, compounded annually.","₹90000 க்கு ஆண்டுக்கு 11% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["20889","20889"],["20888","20888"],["20890","20890"],["20891","20891"]],"answer":0,"explanation":["90000×[(1+11/100)²−1] = 20889.","90000×[(1+11/100)²−1] = 20889."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20880,"question_number":20881,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["11 metres of cloth cost ₹90. At the same rate, what is the cost of 14 metres in rupees?","11 மீ துணியின் விலை ₹90. அதே வீதத்தில் 14 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["1260/11","1260/11"],["1249/11","1249/11"],["1271/11","1271/11"],["1282/11","1282/11"]],"answer":0,"explanation":["90/11×14 = 1260/11.","90/11×14 = 1260/11."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20881,"question_number":20882,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["11 equally efficient machines complete a job in 9 hours. How many hours do 13 such machines require at the same rate?","சமத் திறனுடைய 11 இயந்திரங்கள் வேலையை 9 மணியில் முடிக்கின்றன. அதே வீதத்தில் 13 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["86/13","86/13"],["99/13","99/13"],["125/13","125/13"],["112/13","112/13"]],"answer":1,"explanation":["11×9/(11+2) = 99/13 hours.","11×9/(11+2) = 99/13 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20882,"question_number":20883,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 18 cm and perpendicular height 11 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 18 செமீ; செங்குத்து உயரம் 11 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["199","199"],["197","197"],["198","198"],["200","200"]],"answer":2,"explanation":["18×11 = 198.","18×11 = 198."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20883,"question_number":20884,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 18 cm and 22 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 18 செமீ, 22 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["198","198"],["199","199"],["200","200"],["197","197"]],"answer":0,"explanation":["½×18×22 = 198 cm².","½×18×22 = 198 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20884,"question_number":20885,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 18 m and 40 m, and height 11 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 18 மீ, 40 மீ; உயரம் 11 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["321","321"],["320","320"],["318","318"],["319","319"]],"answer":3,"explanation":["½×(18+40)×11 = 319.","½×(18+40)×11 = 319."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20885,"question_number":20886,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 63 cm makes 11 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","63 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 11 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["4358","4358"],["4356","4356"],["4357","4357"],["4355","4355"]],"answer":1,"explanation":["11×2×22/7×63 = 4356.","11×2×22/7×63 = 4356."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20886,"question_number":20887,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 11 circular mats, each of radius 63 cm. Find their total area in cm², using π=22/7.","தலா 63 செமீ ஆரமுள்ள 11 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["137214","137214"],["137213","137213"],["137216","137216"],["137215","137215"]],"answer":0,"explanation":["11×22/7×63² = 137214.","11×22/7×63² = 137214."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20887,"question_number":20888,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 38° and 52°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 38°, 52°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["91","91"],["92","92"],["90","90"],["89","89"]],"answer":2,"explanation":["180−38−52 = 90°.","180−38−52 = 90°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20888,"question_number":20889,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 59°. One remote interior angle is 31°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 59°. அதற்கான ஓர் எதிர் உட்கோணம் 31°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["30","30"],["29","29"],["27","27"],["28","28"]],"answer":3,"explanation":["59 − 31 = 28°.","59 − 31 = 28°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20889,"question_number":20890,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 9, 20, 31, 42, 53.","9, 20, 31, 42, 53 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["31","31"],["30","30"],["32","32"],["33","33"]],"answer":0,"explanation":["Sum/5 = 155/5 = 31.","கூடுதல்/5 = 155/5 = 31."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20890,"question_number":20891,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 64, 9, 31, 86, 20.","வரிசைப்படுத்தி இடைநிலை காண்க: 64, 9, 31, 86, 20."],"options":[["31","31"],["30","30"],["33","33"],["32","32"]],"answer":0,"explanation":["Sorted: 9, 20, 31, 64, 86; middle value = 31.","வரிசை: 9, 20, 31, 64, 86; நடு மதிப்பு = 31."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20891,"question_number":20892,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 9, 20, 9, 31, 42, 9?","9, 20, 9, 31, 42, 9 தரவுகளின் முகடு எது?"],"options":[["11","11"],["10","10"],["9","9"],["8","8"]],"answer":2,"explanation":["9 occurs 3 times; each other value occurs once.","9 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20892,"question_number":20893,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 9 hours and another in 11 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 9 மணியிலும் மற்றொன்று 11 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["139/20","139/20"],["99/20","99/20"],["79/20","79/20"],["119/20","119/20"]],"answer":1,"explanation":["Combined hourly rate = 1/9+1/11; time = 99/20 = 99/20 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/9+1/11; காலம் = 99/20 = 99/20 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20893,"question_number":20894,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −9/11. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −9/11. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["20/11","20/11"],["-2/11","-2/11"],["31/11","31/11"],["9/11","9/11"]],"answer":3,"explanation":["−9/11 + 9/11 = 0. Simplified additive inverse: 9/11.","−9/11 + 9/11 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 9/11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20894,"question_number":20895,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 9 and 11?","9 மற்றும் 11 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["11","11"],["12","12"],["10","10"],["9","9"]],"answer":2,"explanation":["(9+11)/2 = 10.","(9+11)/2 = 10."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20895,"question_number":20896,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 10/11 + 1/12.","கூட்டிச் சுருக்குக: 10/11 + 1/12."],"options":[["-1/132","-1/132"],["263/132","263/132"],["131/132","131/132"],["395/132","395/132"]],"answer":2,"explanation":["[10×12 + 11]/[11×12] = 131/132.","[10×12 + 11]/[11×12] = 131/132."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20896,"question_number":20897,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 10/11 − 1/12.","கழித்துச் சுருக்குக: 10/11 − 1/12."],"options":[["109/132","109/132"],["373/132","373/132"],["-23/132","-23/132"],["241/132","241/132"]],"answer":0,"explanation":["[10×12 − 11]/[11×12] = 109/132.","[10×12 − 11]/[11×12] = 109/132."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20897,"question_number":20898,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−10/11) × (12/11).","(−10/11) × (12/11) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-241/121","-241/121"],["-120/121","-120/121"],["1/121","1/121"],["122/121","122/121"]],"answer":1,"explanation":["−120/121 = -120/121.","−120/121 = -120/121."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20898,"question_number":20899,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (10/11) ÷ (11/12) in simplest form.","(10/11) ÷ (11/12) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["241/121","241/121"],["-1/121","-1/121"],["362/121","362/121"],["120/121","120/121"]],"answer":3,"explanation":["(10/11) × (12/11) = 120/121.","(10/11) × (12/11) = 120/121."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20899,"question_number":20900,"practice_set":836},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 11.1 and 0.11.","11.1 மற்றும் 0.11 தசம எண்களைக் கூட்டுக."],"options":[["11.31","11.31"],["11.22","11.22"],["11.20","11.20"],["11.21","11.21"]],"answer":3,"explanation":["11.1 + 0.11 = 11.21.","11.1 + 0.11 = 11.21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20900,"question_number":20901,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 11x + 10 = 241.","11x + 10 = 241 சமன்பாட்டைத் தீர்க்க."],"options":[["22","22"],["20","20"],["21","21"],["23","23"]],"answer":2,"explanation":["x = (241 − 10)/11 = 21.","x = (241 − 10)/11 = 21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20901,"question_number":20902,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 10 and y = 11, find (x+y)² − x² − y², then divide by 2.","x = 10, y = 11 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["111","111"],["112","112"],["109","109"],["110","110"]],"answer":3,"explanation":["[(x+y)²−x²−y²]/2 = xy = 10×11 = 110.","[(x+y)²−x²−y²]/2 = xy = 10×11 = 110."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20902,"question_number":20903,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 10, y = 11.","x = 10, y = 11 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["440","440"],["441","441"],["442","442"],["443","443"]],"answer":1,"explanation":["(x+y)² = (10+11)² = 441.","(x+y)² = (10+11)² = 441."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20903,"question_number":20904,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^10 × 7^11 = 7^m, what is m?","7^10 × 7^11 = 7^m எனில் m என்ன?"],"options":[["22","22"],["21","21"],["23","23"],["20","20"]],"answer":1,"explanation":["m = 10 + 11 = 21.","m = 10 + 11 = 21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20904,"question_number":20905,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^10)^11 = 2^m, find m.","(2^10)^11 = 2^m எனில் m காண்க."],"options":[["112","112"],["111","111"],["109","109"],["110","110"]],"answer":3,"explanation":["m = 10 × 11 = 110.","m = 10 × 11 = 110."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20905,"question_number":20906,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 12321.","12321 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["113","113"],["110","110"],["111","111"],["112","112"]],"answer":2,"explanation":["111 × 111 = 12321; √12321 = 111.","111 × 111 = 12321; √12321 = 111."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20906,"question_number":20907,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 1367631.","1367631 இன் கனமூலத்தைக் காண்க."],"options":[["111","111"],["113","113"],["110","110"],["112","112"]],"answer":0,"explanation":["111 × 111 × 111 = 1367631; cube root = 111.","111 × 111 × 111 = 1367631; கனமூலம் = 111."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20907,"question_number":20908,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 55% of ₹200.","₹200 இன் 55% காண்க."],"options":[["110","110"],["111","111"],["112","112"],["109","109"]],"answer":0,"explanation":["200×55/100 = 110.","200×55/100 = 110."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20908,"question_number":20909,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹1000 has a 55% discount. What is the sale price in rupees?","₹1000 குறித்த விலையுள்ள பைக்கு 55% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["450","450"],["449","449"],["452","452"],["451","451"]],"answer":0,"explanation":["1000 × (100−55)/100 = 450.","1000 × (100−55)/100 = 450."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20909,"question_number":20910,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹1000 sells for ₹1550. Find the profit percentage.","₹1000 க்கு வாங்கிய பொருள் ₹1550 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["55","55"],["56","56"],["57","57"],["54","54"]],"answer":0,"explanation":["(1550−1000)/1000×100 = 55%.","(1550−1000)/1000×100 = 55%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20910,"question_number":20911,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹10000 at 11% per year for 3 years.","₹10000 க்கு ஆண்டுக்கு 11% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["3299","3299"],["3302","3302"],["3301","3301"],["3300","3300"]],"answer":3,"explanation":["10000×11×3/100 = 3300.","10000×11×3/100 = 3300."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20911,"question_number":20912,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹100000 at 11% a year for 2 years, compounded annually.","₹100000 க்கு ஆண்டுக்கு 11% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["23211","23211"],["23209","23209"],["23212","23212"],["23210","23210"]],"answer":3,"explanation":["100000×[(1+11/100)²−1] = 23210.","100000×[(1+11/100)²−1] = 23210."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20912,"question_number":20913,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["11 metres of cloth cost ₹100. At the same rate, what is the cost of 14 metres in rupees?","11 மீ துணியின் விலை ₹100. அதே வீதத்தில் 14 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["1389/11","1389/11"],["1411/11","1411/11"],["1400/11","1400/11"],["1422/11","1422/11"]],"answer":2,"explanation":["100/11×14 = 1400/11.","100/11×14 = 1400/11."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20913,"question_number":20914,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["11 equally efficient machines complete a job in 10 hours. How many hours do 13 such machines require at the same rate?","சமத் திறனுடைய 11 இயந்திரங்கள் வேலையை 10 மணியில் முடிக்கின்றன. அதே வீதத்தில் 13 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["136/13","136/13"],["123/13","123/13"],["97/13","97/13"],["110/13","110/13"]],"answer":3,"explanation":["11×10/(11+2) = 110/13 hours.","11×10/(11+2) = 110/13 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20914,"question_number":20915,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 20 cm and perpendicular height 11 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 20 செமீ; செங்குத்து உயரம் 11 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["221","221"],["220","220"],["219","219"],["222","222"]],"answer":1,"explanation":["20×11 = 220.","20×11 = 220."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20915,"question_number":20916,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 20 cm and 22 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 20 செமீ, 22 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["219","219"],["220","220"],["221","221"],["222","222"]],"answer":1,"explanation":["½×20×22 = 220 cm².","½×20×22 = 220 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20916,"question_number":20917,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 20 m and 42 m, and height 11 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 20 மீ, 42 மீ; உயரம் 11 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["341","341"],["342","342"],["340","340"],["343","343"]],"answer":0,"explanation":["½×(20+42)×11 = 341.","½×(20+42)×11 = 341."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20917,"question_number":20918,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 70 cm makes 11 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","70 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 11 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["4842","4842"],["4840","4840"],["4841","4841"],["4839","4839"]],"answer":1,"explanation":["11×2×22/7×70 = 4840.","11×2×22/7×70 = 4840."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20918,"question_number":20919,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 11 circular mats, each of radius 70 cm. Find their total area in cm², using π=22/7.","தலா 70 செமீ ஆரமுள்ள 11 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["169402","169402"],["169399","169399"],["169401","169401"],["169400","169400"]],"answer":3,"explanation":["11×22/7×70² = 169400.","11×22/7×70² = 169400."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20919,"question_number":20920,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 40° and 52°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 40°, 52°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["88","88"],["90","90"],["89","89"],["87","87"]],"answer":0,"explanation":["180−40−52 = 88°.","180−40−52 = 88°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20920,"question_number":20921,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 60°. One remote interior angle is 31°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 60°. அதற்கான ஓர் எதிர் உட்கோணம் 31°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["28","28"],["31","31"],["29","29"],["30","30"]],"answer":2,"explanation":["60 − 31 = 29°.","60 − 31 = 29°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20921,"question_number":20922,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 10, 21, 32, 43, 54.","10, 21, 32, 43, 54 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["31","31"],["34","34"],["32","32"],["33","33"]],"answer":2,"explanation":["Sum/5 = 160/5 = 32.","கூடுதல்/5 = 160/5 = 32."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20922,"question_number":20923,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 65, 10, 32, 87, 21.","வரிசைப்படுத்தி இடைநிலை காண்க: 65, 10, 32, 87, 21."],"options":[["34","34"],["33","33"],["31","31"],["32","32"]],"answer":3,"explanation":["Sorted: 10, 21, 32, 65, 87; middle value = 32.","வரிசை: 10, 21, 32, 65, 87; நடு மதிப்பு = 32."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20923,"question_number":20924,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 10, 21, 10, 32, 43, 10?","10, 21, 10, 32, 43, 10 தரவுகளின் முகடு எது?"],"options":[["9","9"],["12","12"],["10","10"],["11","11"]],"answer":2,"explanation":["10 occurs 3 times; each other value occurs once.","10 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20924,"question_number":20925,"practice_set":837},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 10 hours and another in 11 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 10 மணியிலும் மற்றொன்று 11 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["110/21","110/21"],["131/21","131/21"],["152/21","152/21"],["89/21","89/21"]],"answer":0,"explanation":["Combined hourly rate = 1/10+1/11; time = 110/21 = 110/21 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/10+1/11; காலம் = 110/21 = 110/21 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20925,"question_number":20926,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −10/11. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −10/11. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["32/11","32/11"],["-1/11","-1/11"],["10/11","10/11"],["21/11","21/11"]],"answer":2,"explanation":["−10/11 + 10/11 = 0. Simplified additive inverse: 10/11.","−10/11 + 10/11 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 10/11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20926,"question_number":20927,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 10 and 11?","10 மற்றும் 11 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["23/2","23/2"],["25/2","25/2"],["19/2","19/2"],["21/2","21/2"]],"answer":3,"explanation":["(10+11)/2 = 21/2.","(10+11)/2 = 21/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20927,"question_number":20928,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 11/11 + 1/12.","கூட்டிச் சுருக்குக: 11/11 + 1/12."],"options":[["37/12","37/12"],["25/12","25/12"],["1/12","1/12"],["13/12","13/12"]],"answer":3,"explanation":["[11×12 + 11]/[11×12] = 13/12.","[11×12 + 11]/[11×12] = 13/12."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20928,"question_number":20929,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 11/11 − 1/12.","கழித்துச் சுருக்குக: 11/11 − 1/12."],"options":[["35/12","35/12"],["23/12","23/12"],["-1/12","-1/12"],["11/12","11/12"]],"answer":3,"explanation":["[11×12 − 11]/[11×12] = 11/12.","[11×12 − 11]/[11×12] = 11/12."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20929,"question_number":20930,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−11/11) × (12/12).","(−11/11) × (12/12) பெருக்கற்பலனைச் சுருக்குக."],"options":[["1","1"],["-2","-2"],["0","0"],["-1","-1"]],"answer":3,"explanation":["−132/132 = -1.","−132/132 = -1."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20930,"question_number":20931,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (11/11) ÷ (12/12) in simplest form.","(11/11) ÷ (12/12) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["1","1"],["0","0"],["3","3"],["2","2"]],"answer":0,"explanation":["(11/11) × (12/12) = 1.","(11/11) × (12/12) = 1."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20931,"question_number":20932,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 12.1 and 0.11.","12.1 மற்றும் 0.11 தசம எண்களைக் கூட்டுக."],"options":[["12.20","12.20"],["12.22","12.22"],["12.21","12.21"],["12.31","12.31"]],"answer":2,"explanation":["12.1 + 0.11 = 12.21.","12.1 + 0.11 = 12.21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20932,"question_number":20933,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 11x + 11 = 253.","11x + 11 = 253 சமன்பாட்டைத் தீர்க்க."],"options":[["21","21"],["24","24"],["22","22"],["23","23"]],"answer":2,"explanation":["x = (253 − 11)/11 = 22.","x = (253 − 11)/11 = 22."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20933,"question_number":20934,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 11 and y = 11, find (x+y)² − x² − y², then divide by 2.","x = 11, y = 11 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["122","122"],["121","121"],["120","120"],["123","123"]],"answer":1,"explanation":["[(x+y)²−x²−y²]/2 = xy = 11×11 = 121.","[(x+y)²−x²−y²]/2 = xy = 11×11 = 121."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20934,"question_number":20935,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 11, y = 11.","x = 11, y = 11 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["486","486"],["484","484"],["485","485"],["483","483"]],"answer":1,"explanation":["(x+y)² = (11+11)² = 484.","(x+y)² = (11+11)² = 484."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20935,"question_number":20936,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^11 × 7^11 = 7^m, what is m?","7^11 × 7^11 = 7^m எனில் m என்ன?"],"options":[["23","23"],["24","24"],["22","22"],["21","21"]],"answer":2,"explanation":["m = 11 + 11 = 22.","m = 11 + 11 = 22."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20936,"question_number":20937,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^11)^11 = 2^m, find m.","(2^11)^11 = 2^m எனில் m காண்க."],"options":[["122","122"],["120","120"],["123","123"],["121","121"]],"answer":3,"explanation":["m = 11 × 11 = 121.","m = 11 × 11 = 121."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20937,"question_number":20938,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 14641.","14641 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["123","123"],["120","120"],["121","121"],["122","122"]],"answer":2,"explanation":["121 × 121 = 14641; √14641 = 121.","121 × 121 = 14641; √14641 = 121."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":20938,"question_number":20939,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 1771561.","1771561 இன் கனமூலத்தைக் காண்க."],"options":[["121","121"],["120","120"],["122","122"],["123","123"]],"answer":0,"explanation":["121 × 121 × 121 = 1771561; cube root = 121.","121 × 121 × 121 = 1771561; கனமூலம் = 121."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":20939,"question_number":20940,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 55% of ₹220.","₹220 இன் 55% காண்க."],"options":[["122","122"],["121","121"],["123","123"],["120","120"]],"answer":1,"explanation":["220×55/100 = 121.","220×55/100 = 121."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20940,"question_number":20941,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹1100 has a 55% discount. What is the sale price in rupees?","₹1100 குறித்த விலையுள்ள பைக்கு 55% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["494","494"],["495","495"],["497","497"],["496","496"]],"answer":1,"explanation":["1100 × (100−55)/100 = 495.","1100 × (100−55)/100 = 495."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20941,"question_number":20942,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹1100 sells for ₹1705. Find the profit percentage.","₹1100 க்கு வாங்கிய பொருள் ₹1705 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["56","56"],["57","57"],["55","55"],["54","54"]],"answer":2,"explanation":["(1705−1100)/1100×100 = 55%.","(1705−1100)/1100×100 = 55%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20942,"question_number":20943,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹11000 at 11% per year for 3 years.","₹11000 க்கு ஆண்டுக்கு 11% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["3632","3632"],["3629","3629"],["3631","3631"],["3630","3630"]],"answer":3,"explanation":["11000×11×3/100 = 3630.","11000×11×3/100 = 3630."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20943,"question_number":20944,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹110000 at 11% a year for 2 years, compounded annually.","₹110000 க்கு ஆண்டுக்கு 11% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["25532","25532"],["25531","25531"],["25533","25533"],["25530","25530"]],"answer":1,"explanation":["110000×[(1+11/100)²−1] = 25531.","110000×[(1+11/100)²−1] = 25531."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20944,"question_number":20945,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["11 metres of cloth cost ₹110. At the same rate, what is the cost of 14 metres in rupees?","11 மீ துணியின் விலை ₹110. அதே வீதத்தில் 14 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["140","140"],["142","142"],["141","141"],["139","139"]],"answer":0,"explanation":["110/11×14 = 140.","110/11×14 = 140."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20945,"question_number":20946,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["11 equally efficient machines complete a job in 11 hours. How many hours do 13 such machines require at the same rate?","சமத் திறனுடைய 11 இயந்திரங்கள் வேலையை 11 மணியில் முடிக்கின்றன. அதே வீதத்தில் 13 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["121/13","121/13"],["134/13","134/13"],["108/13","108/13"],["147/13","147/13"]],"answer":0,"explanation":["11×11/(11+2) = 121/13 hours.","11×11/(11+2) = 121/13 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20946,"question_number":20947,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 22 cm and perpendicular height 11 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 22 செமீ; செங்குத்து உயரம் 11 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["244","244"],["243","243"],["242","242"],["241","241"]],"answer":2,"explanation":["22×11 = 242.","22×11 = 242."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20947,"question_number":20948,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 22 cm and 22 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 22 செமீ, 22 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["242","242"],["243","243"],["241","241"],["244","244"]],"answer":0,"explanation":["½×22×22 = 242 cm².","½×22×22 = 242 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20948,"question_number":20949,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 22 m and 44 m, and height 11 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 22 மீ, 44 மீ; உயரம் 11 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["364","364"],["365","365"],["362","362"],["363","363"]],"answer":3,"explanation":["½×(22+44)×11 = 363.","½×(22+44)×11 = 363."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20949,"question_number":20950,"practice_set":838},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 77 cm makes 11 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","77 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 11 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["5325","5325"],["5323","5323"],["5324","5324"],["5326","5326"]],"answer":2,"explanation":["11×2×22/7×77 = 5324.","11×2×22/7×77 = 5324."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20950,"question_number":20951,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 11 circular mats, each of radius 77 cm. Find their total area in cm², using π=22/7.","தலா 77 செமீ ஆரமுள்ள 11 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["204973","204973"],["204976","204976"],["204974","204974"],["204975","204975"]],"answer":2,"explanation":["11×22/7×77² = 204974.","11×22/7×77² = 204974."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20951,"question_number":20952,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 42° and 52°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 42°, 52°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["85","85"],["87","87"],["88","88"],["86","86"]],"answer":3,"explanation":["180−42−52 = 86°.","180−42−52 = 86°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20952,"question_number":20953,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 61°. One remote interior angle is 31°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 61°. அதற்கான ஓர் எதிர் உட்கோணம் 31°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["29","29"],["31","31"],["32","32"],["30","30"]],"answer":3,"explanation":["61 − 31 = 30°.","61 − 31 = 30°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20953,"question_number":20954,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 11, 22, 33, 44, 55.","11, 22, 33, 44, 55 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["32","32"],["35","35"],["33","33"],["34","34"]],"answer":2,"explanation":["Sum/5 = 165/5 = 33.","கூடுதல்/5 = 165/5 = 33."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20954,"question_number":20955,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 66, 11, 33, 88, 22.","வரிசைப்படுத்தி இடைநிலை காண்க: 66, 11, 33, 88, 22."],"options":[["33","33"],["32","32"],["35","35"],["34","34"]],"answer":0,"explanation":["Sorted: 11, 22, 33, 66, 88; middle value = 33.","வரிசை: 11, 22, 33, 66, 88; நடு மதிப்பு = 33."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20955,"question_number":20956,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 11, 22, 11, 33, 44, 11?","11, 22, 11, 33, 44, 11 தரவுகளின் முகடு எது?"],"options":[["11","11"],["12","12"],["13","13"],["10","10"]],"answer":0,"explanation":["11 occurs 3 times; each other value occurs once.","11 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20956,"question_number":20957,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 11 hours and another in 11 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 11 மணியிலும் மற்றொன்று 11 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["13/2","13/2"],["11/2","11/2"],["15/2","15/2"],["9/2","9/2"]],"answer":1,"explanation":["Combined hourly rate = 1/11+1/11; time = 121/22 = 11/2 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/11+1/11; காலம் = 121/22 = 11/2 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20957,"question_number":20958,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −11/11. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −11/11. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["1","1"],["3","3"],["0","0"],["2","2"]],"answer":0,"explanation":["−11/11 + 11/11 = 0. Simplified additive inverse: 1.","−11/11 + 11/11 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 1."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20958,"question_number":20959,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 11 and 11?","11 மற்றும் 11 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["10","10"],["13","13"],["12","12"],["11","11"]],"answer":3,"explanation":["(11+11)/2 = 11.","(11+11)/2 = 11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20959,"question_number":20960,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 2/12 + 1/13.","கூட்டிச் சுருக்குக: 2/12 + 1/13."],"options":[["175/78","175/78"],["-59/78","-59/78"],["19/78","19/78"],["97/78","97/78"]],"answer":2,"explanation":["[2×13 + 12]/[12×13] = 19/78.","[2×13 + 12]/[12×13] = 19/78."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20960,"question_number":20961,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 2/12 − 1/13.","கழித்துச் சுருக்குக: 2/12 − 1/13."],"options":[["7/78","7/78"],["85/78","85/78"],["-71/78","-71/78"],["163/78","163/78"]],"answer":0,"explanation":["[2×13 − 12]/[12×13] = 7/78.","[2×13 − 12]/[12×13] = 7/78."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20961,"question_number":20962,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−2/12) × (13/3).","(−2/12) × (13/3) பெருக்கற்பலனைச் சுருக்குக."],"options":[["5/18","5/18"],["23/18","23/18"],["-31/18","-31/18"],["-13/18","-13/18"]],"answer":3,"explanation":["−26/36 = -13/18.","−26/36 = -13/18."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20962,"question_number":20963,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (2/12) ÷ (3/13) in simplest form.","(2/12) ÷ (3/13) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["13/18","13/18"],["-5/18","-5/18"],["49/18","49/18"],["31/18","31/18"]],"answer":0,"explanation":["(2/12) × (13/3) = 13/18.","(2/12) × (13/3) = 13/18."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20963,"question_number":20964,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 3.2 and 0.12.","3.2 மற்றும் 0.12 தசம எண்களைக் கூட்டுக."],"options":[["3.32","3.32"],["3.42","3.42"],["3.33","3.33"],["3.31","3.31"]],"answer":0,"explanation":["3.2 + 0.12 = 3.32.","3.2 + 0.12 = 3.32."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20964,"question_number":20965,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 12x + 2 = 170.","12x + 2 = 170 சமன்பாட்டைத் தீர்க்க."],"options":[["14","14"],["15","15"],["13","13"],["16","16"]],"answer":0,"explanation":["x = (170 − 2)/12 = 14.","x = (170 − 2)/12 = 14."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20965,"question_number":20966,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 2 and y = 12, find (x+y)² − x² − y², then divide by 2.","x = 2, y = 12 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["24","24"],["23","23"],["26","26"],["25","25"]],"answer":0,"explanation":["[(x+y)²−x²−y²]/2 = xy = 2×12 = 24.","[(x+y)²−x²−y²]/2 = xy = 2×12 = 24."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20966,"question_number":20967,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 2, y = 12.","x = 2, y = 12 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["197","197"],["195","195"],["196","196"],["198","198"]],"answer":2,"explanation":["(x+y)² = (2+12)² = 196.","(x+y)² = (2+12)² = 196."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20967,"question_number":20968,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^2 × 7^12 = 7^m, what is m?","7^2 × 7^12 = 7^m எனில் m என்ன?"],"options":[["16","16"],["13","13"],["14","14"],["15","15"]],"answer":2,"explanation":["m = 2 + 12 = 14.","m = 2 + 12 = 14."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20968,"question_number":20969,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^2)^12 = 2^m, find m.","(2^2)^12 = 2^m எனில் m காண்க."],"options":[["24","24"],["26","26"],["23","23"],["25","25"]],"answer":0,"explanation":["m = 2 × 12 = 24.","m = 2 × 12 = 24."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20969,"question_number":20970,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 60% of ₹40.","₹40 இன் 60% காண்க."],"options":[["24","24"],["23","23"],["26","26"],["25","25"]],"answer":0,"explanation":["40×60/100 = 24.","40×60/100 = 24."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":20970,"question_number":20971,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹200 has a 60% discount. What is the sale price in rupees?","₹200 குறித்த விலையுள்ள பைக்கு 60% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["81","81"],["80","80"],["79","79"],["82","82"]],"answer":1,"explanation":["200 × (100−60)/100 = 80.","200 × (100−60)/100 = 80."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":20971,"question_number":20972,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹200 sells for ₹320. Find the profit percentage.","₹200 க்கு வாங்கிய பொருள் ₹320 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["61","61"],["60","60"],["59","59"],["62","62"]],"answer":1,"explanation":["(320−200)/200×100 = 60%.","(320−200)/200×100 = 60%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":20972,"question_number":20973,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹2000 at 12% per year for 3 years.","₹2000 க்கு ஆண்டுக்கு 12% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["722","722"],["719","719"],["720","720"],["721","721"]],"answer":2,"explanation":["2000×12×3/100 = 720.","2000×12×3/100 = 720."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":20973,"question_number":20974,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹20000 at 12% a year for 2 years, compounded annually.","₹20000 க்கு ஆண்டுக்கு 12% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["5087","5087"],["5088","5088"],["5089","5089"],["5090","5090"]],"answer":1,"explanation":["20000×[(1+12/100)²−1] = 5088.","20000×[(1+12/100)²−1] = 5088."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":20974,"question_number":20975,"practice_set":839},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["12 metres of cloth cost ₹20. At the same rate, what is the cost of 15 metres in rupees?","12 மீ துணியின் விலை ₹20. அதே வீதத்தில் 15 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["24","24"],["26","26"],["25","25"],["27","27"]],"answer":2,"explanation":["20/12×15 = 25.","20/12×15 = 25."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":20975,"question_number":20976,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["12 equally efficient machines complete a job in 2 hours. How many hours do 14 such machines require at the same rate?","சமத் திறனுடைய 12 இயந்திரங்கள் வேலையை 2 மணியில் முடிக்கின்றன. அதே வீதத்தில் 14 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["19/7","19/7"],["12/7","12/7"],["26/7","26/7"],["5/7","5/7"]],"answer":1,"explanation":["12×2/(12+2) = 12/7 hours.","12×2/(12+2) = 12/7 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":20976,"question_number":20977,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 4 cm and perpendicular height 12 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 4 செமீ; செங்குத்து உயரம் 12 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["49","49"],["47","47"],["48","48"],["50","50"]],"answer":2,"explanation":["4×12 = 48.","4×12 = 48."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":20977,"question_number":20978,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 4 cm and 24 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 4 செமீ, 24 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["49","49"],["50","50"],["47","47"],["48","48"]],"answer":3,"explanation":["½×4×24 = 48 cm².","½×4×24 = 48 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":20978,"question_number":20979,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 4 m and 28 m, and height 12 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 4 மீ, 28 மீ; உயரம் 12 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["191","191"],["194","194"],["193","193"],["192","192"]],"answer":3,"explanation":["½×(4+28)×12 = 192.","½×(4+28)×12 = 192."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":20979,"question_number":20980,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 14 cm makes 12 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","14 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 12 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["1057","1057"],["1056","1056"],["1058","1058"],["1055","1055"]],"answer":1,"explanation":["12×2×22/7×14 = 1056.","12×2×22/7×14 = 1056."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":20980,"question_number":20981,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 12 circular mats, each of radius 14 cm. Find their total area in cm², using π=22/7.","தலா 14 செமீ ஆரமுள்ள 12 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["7393","7393"],["7392","7392"],["7391","7391"],["7394","7394"]],"answer":1,"explanation":["12×22/7×14² = 7392.","12×22/7×14² = 7392."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":20981,"question_number":20982,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 24° and 54°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 24°, 54°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["104","104"],["103","103"],["102","102"],["101","101"]],"answer":2,"explanation":["180−24−54 = 102°.","180−24−54 = 102°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":20982,"question_number":20983,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 52°. One remote interior angle is 32°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 52°. அதற்கான ஓர் எதிர் உட்கோணம் 32°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["22","22"],["21","21"],["19","19"],["20","20"]],"answer":3,"explanation":["52 − 32 = 20°.","52 − 32 = 20°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":20983,"question_number":20984,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 2, 14, 26, 38, 50.","2, 14, 26, 38, 50 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["25","25"],["27","27"],["26","26"],["28","28"]],"answer":2,"explanation":["Sum/5 = 130/5 = 26.","கூடுதல்/5 = 130/5 = 26."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":20984,"question_number":20985,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 62, 2, 26, 86, 14.","வரிசைப்படுத்தி இடைநிலை காண்க: 62, 2, 26, 86, 14."],"options":[["27","27"],["28","28"],["25","25"],["26","26"]],"answer":3,"explanation":["Sorted: 2, 14, 26, 62, 86; middle value = 26.","வரிசை: 2, 14, 26, 62, 86; நடு மதிப்பு = 26."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":20985,"question_number":20986,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 2, 14, 2, 26, 38, 2?","2, 14, 2, 26, 38, 2 தரவுகளின் முகடு எது?"],"options":[["2","2"],["3","3"],["1","1"],["4","4"]],"answer":0,"explanation":["2 occurs 3 times; each other value occurs once.","2 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":20986,"question_number":20987,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 2 hours and another in 12 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 2 மணியிலும் மற்றொன்று 12 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["12/7","12/7"],["26/7","26/7"],["5/7","5/7"],["19/7","19/7"]],"answer":0,"explanation":["Combined hourly rate = 1/2+1/12; time = 24/14 = 12/7 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/2+1/12; காலம் = 24/14 = 12/7 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":20987,"question_number":20988,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −2/12. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −2/12. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["1/6","1/6"],["13/6","13/6"],["7/6","7/6"],["-5/6","-5/6"]],"answer":0,"explanation":["−2/12 + 2/12 = 0. Simplified additive inverse: 1/6.","−2/12 + 2/12 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 1/6."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":20988,"question_number":20989,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 2 and 12?","2 மற்றும் 12 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["9","9"],["8","8"],["6","6"],["7","7"]],"answer":3,"explanation":["(2+12)/2 = 7.","(2+12)/2 = 7."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":20989,"question_number":20990,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 3/12 + 1/13.","கூட்டிச் சுருக்குக: 3/12 + 1/13."],"options":[["69/52","69/52"],["-35/52","-35/52"],["17/52","17/52"],["121/52","121/52"]],"answer":2,"explanation":["[3×13 + 12]/[12×13] = 17/52.","[3×13 + 12]/[12×13] = 17/52."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":20990,"question_number":20991,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 3/12 − 1/13.","கழித்துச் சுருக்குக: 3/12 − 1/13."],"options":[["-43/52","-43/52"],["9/52","9/52"],["61/52","61/52"],["113/52","113/52"]],"answer":1,"explanation":["[3×13 − 12]/[12×13] = 9/52.","[3×13 − 12]/[12×13] = 9/52."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":20991,"question_number":20992,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−3/12) × (13/4).","(−3/12) × (13/4) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-29/16","-29/16"],["19/16","19/16"],["3/16","3/16"],["-13/16","-13/16"]],"answer":3,"explanation":["−39/48 = -13/16.","−39/48 = -13/16."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":20992,"question_number":20993,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (3/12) ÷ (4/13) in simplest form.","(3/12) ÷ (4/13) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["13/16","13/16"],["-3/16","-3/16"],["45/16","45/16"],["29/16","29/16"]],"answer":0,"explanation":["(3/12) × (13/4) = 13/16.","(3/12) × (13/4) = 13/16."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":20993,"question_number":20994,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 4.2 and 0.12.","4.2 மற்றும் 0.12 தசம எண்களைக் கூட்டுக."],"options":[["4.31","4.31"],["4.33","4.33"],["4.42","4.42"],["4.32","4.32"]],"answer":3,"explanation":["4.2 + 0.12 = 4.32.","4.2 + 0.12 = 4.32."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":20994,"question_number":20995,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 12x + 3 = 183.","12x + 3 = 183 சமன்பாட்டைத் தீர்க்க."],"options":[["16","16"],["14","14"],["15","15"],["17","17"]],"answer":2,"explanation":["x = (183 − 3)/12 = 15.","x = (183 − 3)/12 = 15."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":20995,"question_number":20996,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 3 and y = 12, find (x+y)² − x² − y², then divide by 2.","x = 3, y = 12 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["37","37"],["36","36"],["38","38"],["35","35"]],"answer":1,"explanation":["[(x+y)²−x²−y²]/2 = xy = 3×12 = 36.","[(x+y)²−x²−y²]/2 = xy = 3×12 = 36."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":20996,"question_number":20997,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 3, y = 12.","x = 3, y = 12 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["224","224"],["225","225"],["227","227"],["226","226"]],"answer":1,"explanation":["(x+y)² = (3+12)² = 225.","(x+y)² = (3+12)² = 225."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":20997,"question_number":20998,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^3 × 7^12 = 7^m, what is m?","7^3 × 7^12 = 7^m எனில் m என்ன?"],"options":[["16","16"],["17","17"],["15","15"],["14","14"]],"answer":2,"explanation":["m = 3 + 12 = 15.","m = 3 + 12 = 15."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":20998,"question_number":20999,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^3)^12 = 2^m, find m.","(2^3)^12 = 2^m எனில் m காண்க."],"options":[["35","35"],["37","37"],["38","38"],["36","36"]],"answer":3,"explanation":["m = 3 × 12 = 36.","m = 3 × 12 = 36."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":20999,"question_number":21000,"practice_set":840},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 60% of ₹60.","₹60 இன் 60% காண்க."],"options":[["37","37"],["38","38"],["36","36"],["35","35"]],"answer":2,"explanation":["60×60/100 = 36.","60×60/100 = 36."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21000,"question_number":21001,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹300 has a 60% discount. What is the sale price in rupees?","₹300 குறித்த விலையுள்ள பைக்கு 60% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["119","119"],["122","122"],["120","120"],["121","121"]],"answer":2,"explanation":["300 × (100−60)/100 = 120.","300 × (100−60)/100 = 120."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21001,"question_number":21002,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹300 sells for ₹480. Find the profit percentage.","₹300 க்கு வாங்கிய பொருள் ₹480 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["60","60"],["59","59"],["62","62"],["61","61"]],"answer":0,"explanation":["(480−300)/300×100 = 60%.","(480−300)/300×100 = 60%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21002,"question_number":21003,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹3000 at 12% per year for 3 years.","₹3000 க்கு ஆண்டுக்கு 12% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1082","1082"],["1080","1080"],["1079","1079"],["1081","1081"]],"answer":1,"explanation":["3000×12×3/100 = 1080.","3000×12×3/100 = 1080."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21003,"question_number":21004,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹30000 at 12% a year for 2 years, compounded annually.","₹30000 க்கு ஆண்டுக்கு 12% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["7634","7634"],["7631","7631"],["7632","7632"],["7633","7633"]],"answer":2,"explanation":["30000×[(1+12/100)²−1] = 7632.","30000×[(1+12/100)²−1] = 7632."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21004,"question_number":21005,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["12 metres of cloth cost ₹30. At the same rate, what is the cost of 15 metres in rupees?","12 மீ துணியின் விலை ₹30. அதே வீதத்தில் 15 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["77/2","77/2"],["73/2","73/2"],["79/2","79/2"],["75/2","75/2"]],"answer":3,"explanation":["30/12×15 = 75/2.","30/12×15 = 75/2."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21005,"question_number":21006,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["12 equally efficient machines complete a job in 3 hours. How many hours do 14 such machines require at the same rate?","சமத் திறனுடைய 12 இயந்திரங்கள் வேலையை 3 மணியில் முடிக்கின்றன. அதே வீதத்தில் 14 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["32/7","32/7"],["25/7","25/7"],["11/7","11/7"],["18/7","18/7"]],"answer":3,"explanation":["12×3/(12+2) = 18/7 hours.","12×3/(12+2) = 18/7 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21006,"question_number":21007,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 6 cm and perpendicular height 12 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 6 செமீ; செங்குத்து உயரம் 12 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["72","72"],["74","74"],["71","71"],["73","73"]],"answer":0,"explanation":["6×12 = 72.","6×12 = 72."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21007,"question_number":21008,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 6 cm and 24 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 6 செமீ, 24 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["73","73"],["74","74"],["71","71"],["72","72"]],"answer":3,"explanation":["½×6×24 = 72 cm².","½×6×24 = 72 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21008,"question_number":21009,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 6 m and 30 m, and height 12 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 6 மீ, 30 மீ; உயரம் 12 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["218","218"],["215","215"],["216","216"],["217","217"]],"answer":2,"explanation":["½×(6+30)×12 = 216.","½×(6+30)×12 = 216."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21009,"question_number":21010,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 21 cm makes 12 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","21 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 12 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["1584","1584"],["1586","1586"],["1583","1583"],["1585","1585"]],"answer":0,"explanation":["12×2×22/7×21 = 1584.","12×2×22/7×21 = 1584."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21010,"question_number":21011,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 12 circular mats, each of radius 21 cm. Find their total area in cm², using π=22/7.","தலா 21 செமீ ஆரமுள்ள 12 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["16632","16632"],["16631","16631"],["16634","16634"],["16633","16633"]],"answer":0,"explanation":["12×22/7×21² = 16632.","12×22/7×21² = 16632."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21011,"question_number":21012,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 26° and 54°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 26°, 54°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["101","101"],["100","100"],["102","102"],["99","99"]],"answer":1,"explanation":["180−26−54 = 100°.","180−26−54 = 100°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21012,"question_number":21013,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 53°. One remote interior angle is 32°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 53°. அதற்கான ஓர் எதிர் உட்கோணம் 32°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["23","23"],["21","21"],["20","20"],["22","22"]],"answer":1,"explanation":["53 − 32 = 21°.","53 − 32 = 21°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21013,"question_number":21014,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 3, 15, 27, 39, 51.","3, 15, 27, 39, 51 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["29","29"],["28","28"],["27","27"],["26","26"]],"answer":2,"explanation":["Sum/5 = 135/5 = 27.","கூடுதல்/5 = 135/5 = 27."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21014,"question_number":21015,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 63, 3, 27, 87, 15.","வரிசைப்படுத்தி இடைநிலை காண்க: 63, 3, 27, 87, 15."],"options":[["28","28"],["26","26"],["27","27"],["29","29"]],"answer":2,"explanation":["Sorted: 3, 15, 27, 63, 87; middle value = 27.","வரிசை: 3, 15, 27, 63, 87; நடு மதிப்பு = 27."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21015,"question_number":21016,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 3, 15, 3, 27, 39, 3?","3, 15, 3, 27, 39, 3 தரவுகளின் முகடு எது?"],"options":[["3","3"],["2","2"],["4","4"],["5","5"]],"answer":0,"explanation":["3 occurs 3 times; each other value occurs once.","3 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21016,"question_number":21017,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 3 hours and another in 12 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 3 மணியிலும் மற்றொன்று 12 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["17/5","17/5"],["22/5","22/5"],["7/5","7/5"],["12/5","12/5"]],"answer":3,"explanation":["Combined hourly rate = 1/3+1/12; time = 36/15 = 12/5 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/3+1/12; காலம் = 36/15 = 12/5 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21017,"question_number":21018,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −3/12. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −3/12. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["1/4","1/4"],["5/4","5/4"],["-3/4","-3/4"],["9/4","9/4"]],"answer":0,"explanation":["−3/12 + 3/12 = 0. Simplified additive inverse: 1/4.","−3/12 + 3/12 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 1/4."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21018,"question_number":21019,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 3 and 12?","3 மற்றும் 12 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["13/2","13/2"],["19/2","19/2"],["15/2","15/2"],["17/2","17/2"]],"answer":2,"explanation":["(3+12)/2 = 15/2.","(3+12)/2 = 15/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21019,"question_number":21020,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 4/12 + 1/13.","கூட்டிச் சுருக்குக: 4/12 + 1/13."],"options":[["16/39","16/39"],["-23/39","-23/39"],["94/39","94/39"],["55/39","55/39"]],"answer":0,"explanation":["[4×13 + 12]/[12×13] = 16/39.","[4×13 + 12]/[12×13] = 16/39."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21020,"question_number":21021,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 4/12 − 1/13.","கழித்துச் சுருக்குக: 4/12 − 1/13."],"options":[["88/39","88/39"],["49/39","49/39"],["-29/39","-29/39"],["10/39","10/39"]],"answer":3,"explanation":["[4×13 − 12]/[12×13] = 10/39.","[4×13 − 12]/[12×13] = 10/39."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21021,"question_number":21022,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−4/12) × (13/5).","(−4/12) × (13/5) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-13/15","-13/15"],["17/15","17/15"],["2/15","2/15"],["-28/15","-28/15"]],"answer":0,"explanation":["−52/60 = -13/15.","−52/60 = -13/15."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21022,"question_number":21023,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (4/12) ÷ (5/13) in simplest form.","(4/12) ÷ (5/13) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["43/15","43/15"],["-2/15","-2/15"],["13/15","13/15"],["28/15","28/15"]],"answer":2,"explanation":["(4/12) × (13/5) = 13/15.","(4/12) × (13/5) = 13/15."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21023,"question_number":21024,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 5.2 and 0.12.","5.2 மற்றும் 0.12 தசம எண்களைக் கூட்டுக."],"options":[["5.42","5.42"],["5.32","5.32"],["5.31","5.31"],["5.33","5.33"]],"answer":1,"explanation":["5.2 + 0.12 = 5.32.","5.2 + 0.12 = 5.32."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21024,"question_number":21025,"practice_set":841},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 12x + 4 = 196.","12x + 4 = 196 சமன்பாட்டைத் தீர்க்க."],"options":[["16","16"],["18","18"],["15","15"],["17","17"]],"answer":0,"explanation":["x = (196 − 4)/12 = 16.","x = (196 − 4)/12 = 16."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21025,"question_number":21026,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 4 and y = 12, find (x+y)² − x² − y², then divide by 2.","x = 4, y = 12 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["50","50"],["47","47"],["49","49"],["48","48"]],"answer":3,"explanation":["[(x+y)²−x²−y²]/2 = xy = 4×12 = 48.","[(x+y)²−x²−y²]/2 = xy = 4×12 = 48."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21026,"question_number":21027,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 4, y = 12.","x = 4, y = 12 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["256","256"],["257","257"],["258","258"],["255","255"]],"answer":0,"explanation":["(x+y)² = (4+12)² = 256.","(x+y)² = (4+12)² = 256."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21027,"question_number":21028,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^4 × 7^12 = 7^m, what is m?","7^4 × 7^12 = 7^m எனில் m என்ன?"],"options":[["16","16"],["17","17"],["18","18"],["15","15"]],"answer":0,"explanation":["m = 4 + 12 = 16.","m = 4 + 12 = 16."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21028,"question_number":21029,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^4)^12 = 2^m, find m.","(2^4)^12 = 2^m எனில் m காண்க."],"options":[["49","49"],["48","48"],["50","50"],["47","47"]],"answer":1,"explanation":["m = 4 × 12 = 48.","m = 4 × 12 = 48."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21029,"question_number":21030,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 60% of ₹80.","₹80 இன் 60% காண்க."],"options":[["49","49"],["50","50"],["47","47"],["48","48"]],"answer":3,"explanation":["80×60/100 = 48.","80×60/100 = 48."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21030,"question_number":21031,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹400 has a 60% discount. What is the sale price in rupees?","₹400 குறித்த விலையுள்ள பைக்கு 60% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["160","160"],["162","162"],["159","159"],["161","161"]],"answer":0,"explanation":["400 × (100−60)/100 = 160.","400 × (100−60)/100 = 160."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21031,"question_number":21032,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹400 sells for ₹640. Find the profit percentage.","₹400 க்கு வாங்கிய பொருள் ₹640 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["60","60"],["59","59"],["62","62"],["61","61"]],"answer":0,"explanation":["(640−400)/400×100 = 60%.","(640−400)/400×100 = 60%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21032,"question_number":21033,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹4000 at 12% per year for 3 years.","₹4000 க்கு ஆண்டுக்கு 12% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1440","1440"],["1439","1439"],["1441","1441"],["1442","1442"]],"answer":0,"explanation":["4000×12×3/100 = 1440.","4000×12×3/100 = 1440."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21033,"question_number":21034,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹40000 at 12% a year for 2 years, compounded annually.","₹40000 க்கு ஆண்டுக்கு 12% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["10178","10178"],["10176","10176"],["10175","10175"],["10177","10177"]],"answer":1,"explanation":["40000×[(1+12/100)²−1] = 10176.","40000×[(1+12/100)²−1] = 10176."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21034,"question_number":21035,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["12 metres of cloth cost ₹40. At the same rate, what is the cost of 15 metres in rupees?","12 மீ துணியின் விலை ₹40. அதே வீதத்தில் 15 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["51","51"],["52","52"],["49","49"],["50","50"]],"answer":3,"explanation":["40/12×15 = 50.","40/12×15 = 50."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21035,"question_number":21036,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["12 equally efficient machines complete a job in 4 hours. How many hours do 14 such machines require at the same rate?","சமத் திறனுடைய 12 இயந்திரங்கள் வேலையை 4 மணியில் முடிக்கின்றன. அதே வீதத்தில் 14 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["38/7","38/7"],["31/7","31/7"],["17/7","17/7"],["24/7","24/7"]],"answer":3,"explanation":["12×4/(12+2) = 24/7 hours.","12×4/(12+2) = 24/7 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21036,"question_number":21037,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 8 cm and perpendicular height 12 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 8 செமீ; செங்குத்து உயரம் 12 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["96","96"],["98","98"],["97","97"],["95","95"]],"answer":0,"explanation":["8×12 = 96.","8×12 = 96."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21037,"question_number":21038,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 8 cm and 24 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 8 செமீ, 24 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["97","97"],["98","98"],["96","96"],["95","95"]],"answer":2,"explanation":["½×8×24 = 96 cm².","½×8×24 = 96 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21038,"question_number":21039,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 8 m and 32 m, and height 12 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 8 மீ, 32 மீ; உயரம் 12 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["241","241"],["239","239"],["242","242"],["240","240"]],"answer":3,"explanation":["½×(8+32)×12 = 240.","½×(8+32)×12 = 240."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21039,"question_number":21040,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 28 cm makes 12 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","28 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 12 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["2111","2111"],["2112","2112"],["2114","2114"],["2113","2113"]],"answer":1,"explanation":["12×2×22/7×28 = 2112.","12×2×22/7×28 = 2112."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21040,"question_number":21041,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 12 circular mats, each of radius 28 cm. Find their total area in cm², using π=22/7.","தலா 28 செமீ ஆரமுள்ள 12 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["29570","29570"],["29567","29567"],["29568","29568"],["29569","29569"]],"answer":2,"explanation":["12×22/7×28² = 29568.","12×22/7×28² = 29568."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21041,"question_number":21042,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 28° and 54°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 28°, 54°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["99","99"],["97","97"],["100","100"],["98","98"]],"answer":3,"explanation":["180−28−54 = 98°.","180−28−54 = 98°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21042,"question_number":21043,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 54°. One remote interior angle is 32°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 54°. அதற்கான ஓர் எதிர் உட்கோணம் 32°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["21","21"],["24","24"],["22","22"],["23","23"]],"answer":2,"explanation":["54 − 32 = 22°.","54 − 32 = 22°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21043,"question_number":21044,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 4, 16, 28, 40, 52.","4, 16, 28, 40, 52 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["29","29"],["27","27"],["30","30"],["28","28"]],"answer":3,"explanation":["Sum/5 = 140/5 = 28.","கூடுதல்/5 = 140/5 = 28."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21044,"question_number":21045,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 64, 4, 28, 88, 16.","வரிசைப்படுத்தி இடைநிலை காண்க: 64, 4, 28, 88, 16."],"options":[["27","27"],["28","28"],["29","29"],["30","30"]],"answer":1,"explanation":["Sorted: 4, 16, 28, 64, 88; middle value = 28.","வரிசை: 4, 16, 28, 64, 88; நடு மதிப்பு = 28."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21045,"question_number":21046,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 4, 16, 4, 28, 40, 4?","4, 16, 4, 28, 40, 4 தரவுகளின் முகடு எது?"],"options":[["4","4"],["3","3"],["5","5"],["6","6"]],"answer":0,"explanation":["4 occurs 3 times; each other value occurs once.","4 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21046,"question_number":21047,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 4 hours and another in 12 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 4 மணியிலும் மற்றொன்று 12 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["5","5"],["4","4"],["3","3"],["2","2"]],"answer":2,"explanation":["Combined hourly rate = 1/4+1/12; time = 48/16 = 3 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/4+1/12; காலம் = 48/16 = 3 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21047,"question_number":21048,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −4/12. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −4/12. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["4/3","4/3"],["-2/3","-2/3"],["7/3","7/3"],["1/3","1/3"]],"answer":3,"explanation":["−4/12 + 4/12 = 0. Simplified additive inverse: 1/3.","−4/12 + 4/12 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 1/3."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21048,"question_number":21049,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 4 and 12?","4 மற்றும் 12 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["7","7"],["8","8"],["10","10"],["9","9"]],"answer":1,"explanation":["(4+12)/2 = 8.","(4+12)/2 = 8."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21049,"question_number":21050,"practice_set":842},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 5/12 + 1/13.","கூட்டிச் சுருக்குக: 5/12 + 1/13."],"options":[["389/156","389/156"],["-79/156","-79/156"],["77/156","77/156"],["233/156","233/156"]],"answer":2,"explanation":["[5×13 + 12]/[12×13] = 77/156.","[5×13 + 12]/[12×13] = 77/156."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21050,"question_number":21051,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 5/12 − 1/13.","கழித்துச் சுருக்குக: 5/12 − 1/13."],"options":[["209/156","209/156"],["53/156","53/156"],["-103/156","-103/156"],["365/156","365/156"]],"answer":1,"explanation":["[5×13 − 12]/[12×13] = 53/156.","[5×13 − 12]/[12×13] = 53/156."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21051,"question_number":21052,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−5/12) × (13/6).","(−5/12) × (13/6) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-137/72","-137/72"],["7/72","7/72"],["79/72","79/72"],["-65/72","-65/72"]],"answer":3,"explanation":["−65/72 = -65/72.","−65/72 = -65/72."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21052,"question_number":21053,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (5/12) ÷ (6/13) in simplest form.","(5/12) ÷ (6/13) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["65/72","65/72"],["-7/72","-7/72"],["137/72","137/72"],["209/72","209/72"]],"answer":0,"explanation":["(5/12) × (13/6) = 65/72.","(5/12) × (13/6) = 65/72."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21053,"question_number":21054,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 6.2 and 0.12.","6.2 மற்றும் 0.12 தசம எண்களைக் கூட்டுக."],"options":[["6.31","6.31"],["6.42","6.42"],["6.33","6.33"],["6.32","6.32"]],"answer":3,"explanation":["6.2 + 0.12 = 6.32.","6.2 + 0.12 = 6.32."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21054,"question_number":21055,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 12x + 5 = 209.","12x + 5 = 209 சமன்பாட்டைத் தீர்க்க."],"options":[["18","18"],["17","17"],["16","16"],["19","19"]],"answer":1,"explanation":["x = (209 − 5)/12 = 17.","x = (209 − 5)/12 = 17."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21055,"question_number":21056,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 5 and y = 12, find (x+y)² − x² − y², then divide by 2.","x = 5, y = 12 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["62","62"],["61","61"],["59","59"],["60","60"]],"answer":3,"explanation":["[(x+y)²−x²−y²]/2 = xy = 5×12 = 60.","[(x+y)²−x²−y²]/2 = xy = 5×12 = 60."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21056,"question_number":21057,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 5, y = 12.","x = 5, y = 12 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["290","290"],["288","288"],["291","291"],["289","289"]],"answer":3,"explanation":["(x+y)² = (5+12)² = 289.","(x+y)² = (5+12)² = 289."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21057,"question_number":21058,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^5 × 7^12 = 7^m, what is m?","7^5 × 7^12 = 7^m எனில் m என்ன?"],"options":[["17","17"],["19","19"],["16","16"],["18","18"]],"answer":0,"explanation":["m = 5 + 12 = 17.","m = 5 + 12 = 17."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21058,"question_number":21059,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^5)^12 = 2^m, find m.","(2^5)^12 = 2^m எனில் m காண்க."],"options":[["60","60"],["59","59"],["61","61"],["62","62"]],"answer":0,"explanation":["m = 5 × 12 = 60.","m = 5 × 12 = 60."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21059,"question_number":21060,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 60% of ₹100.","₹100 இன் 60% காண்க."],"options":[["59","59"],["61","61"],["60","60"],["62","62"]],"answer":2,"explanation":["100×60/100 = 60.","100×60/100 = 60."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21060,"question_number":21061,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹500 has a 60% discount. What is the sale price in rupees?","₹500 குறித்த விலையுள்ள பைக்கு 60% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["200","200"],["201","201"],["202","202"],["199","199"]],"answer":0,"explanation":["500 × (100−60)/100 = 200.","500 × (100−60)/100 = 200."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21061,"question_number":21062,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹500 sells for ₹800. Find the profit percentage.","₹500 க்கு வாங்கிய பொருள் ₹800 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["62","62"],["59","59"],["60","60"],["61","61"]],"answer":2,"explanation":["(800−500)/500×100 = 60%.","(800−500)/500×100 = 60%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21062,"question_number":21063,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹5000 at 12% per year for 3 years.","₹5000 க்கு ஆண்டுக்கு 12% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1800","1800"],["1799","1799"],["1801","1801"],["1802","1802"]],"answer":0,"explanation":["5000×12×3/100 = 1800.","5000×12×3/100 = 1800."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21063,"question_number":21064,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹50000 at 12% a year for 2 years, compounded annually.","₹50000 க்கு ஆண்டுக்கு 12% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["12719","12719"],["12720","12720"],["12722","12722"],["12721","12721"]],"answer":1,"explanation":["50000×[(1+12/100)²−1] = 12720.","50000×[(1+12/100)²−1] = 12720."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21064,"question_number":21065,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["12 metres of cloth cost ₹50. At the same rate, what is the cost of 15 metres in rupees?","12 மீ துணியின் விலை ₹50. அதே வீதத்தில் 15 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["123/2","123/2"],["129/2","129/2"],["127/2","127/2"],["125/2","125/2"]],"answer":3,"explanation":["50/12×15 = 125/2.","50/12×15 = 125/2."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21065,"question_number":21066,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["12 equally efficient machines complete a job in 5 hours. How many hours do 14 such machines require at the same rate?","சமத் திறனுடைய 12 இயந்திரங்கள் வேலையை 5 மணியில் முடிக்கின்றன. அதே வீதத்தில் 14 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["30/7","30/7"],["37/7","37/7"],["44/7","44/7"],["23/7","23/7"]],"answer":0,"explanation":["12×5/(12+2) = 30/7 hours.","12×5/(12+2) = 30/7 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21066,"question_number":21067,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 10 cm and perpendicular height 12 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 10 செமீ; செங்குத்து உயரம் 12 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["121","121"],["122","122"],["120","120"],["119","119"]],"answer":2,"explanation":["10×12 = 120.","10×12 = 120."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21067,"question_number":21068,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 10 cm and 24 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 10 செமீ, 24 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["120","120"],["122","122"],["119","119"],["121","121"]],"answer":0,"explanation":["½×10×24 = 120 cm².","½×10×24 = 120 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21068,"question_number":21069,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 10 m and 34 m, and height 12 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 10 மீ, 34 மீ; உயரம் 12 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["266","266"],["264","264"],["265","265"],["263","263"]],"answer":1,"explanation":["½×(10+34)×12 = 264.","½×(10+34)×12 = 264."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21069,"question_number":21070,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 35 cm makes 12 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","35 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 12 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["2642","2642"],["2640","2640"],["2639","2639"],["2641","2641"]],"answer":1,"explanation":["12×2×22/7×35 = 2640.","12×2×22/7×35 = 2640."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21070,"question_number":21071,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 12 circular mats, each of radius 35 cm. Find their total area in cm², using π=22/7.","தலா 35 செமீ ஆரமுள்ள 12 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["46200","46200"],["46202","46202"],["46199","46199"],["46201","46201"]],"answer":0,"explanation":["12×22/7×35² = 46200.","12×22/7×35² = 46200."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21071,"question_number":21072,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 30° and 54°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 30°, 54°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["98","98"],["97","97"],["95","95"],["96","96"]],"answer":3,"explanation":["180−30−54 = 96°.","180−30−54 = 96°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21072,"question_number":21073,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 55°. One remote interior angle is 32°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 55°. அதற்கான ஓர் எதிர் உட்கோணம் 32°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["22","22"],["24","24"],["25","25"],["23","23"]],"answer":3,"explanation":["55 − 32 = 23°.","55 − 32 = 23°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21073,"question_number":21074,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 5, 17, 29, 41, 53.","5, 17, 29, 41, 53 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["31","31"],["29","29"],["28","28"],["30","30"]],"answer":1,"explanation":["Sum/5 = 145/5 = 29.","கூடுதல்/5 = 145/5 = 29."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21074,"question_number":21075,"practice_set":843},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 65, 5, 29, 89, 17.","வரிசைப்படுத்தி இடைநிலை காண்க: 65, 5, 29, 89, 17."],"options":[["31","31"],["28","28"],["30","30"],["29","29"]],"answer":3,"explanation":["Sorted: 5, 17, 29, 65, 89; middle value = 29.","வரிசை: 5, 17, 29, 65, 89; நடு மதிப்பு = 29."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21075,"question_number":21076,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 5, 17, 5, 29, 41, 5?","5, 17, 5, 29, 41, 5 தரவுகளின் முகடு எது?"],"options":[["6","6"],["4","4"],["7","7"],["5","5"]],"answer":3,"explanation":["5 occurs 3 times; each other value occurs once.","5 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21076,"question_number":21077,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 5 hours and another in 12 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 5 மணியிலும் மற்றொன்று 12 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["77/17","77/17"],["94/17","94/17"],["43/17","43/17"],["60/17","60/17"]],"answer":3,"explanation":["Combined hourly rate = 1/5+1/12; time = 60/17 = 60/17 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/5+1/12; காலம் = 60/17 = 60/17 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21077,"question_number":21078,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −5/12. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −5/12. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["29/12","29/12"],["-7/12","-7/12"],["5/12","5/12"],["17/12","17/12"]],"answer":2,"explanation":["−5/12 + 5/12 = 0. Simplified additive inverse: 5/12.","−5/12 + 5/12 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 5/12."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21078,"question_number":21079,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 5 and 12?","5 மற்றும் 12 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["17/2","17/2"],["15/2","15/2"],["21/2","21/2"],["19/2","19/2"]],"answer":0,"explanation":["(5+12)/2 = 17/2.","(5+12)/2 = 17/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21079,"question_number":21080,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 6/12 + 1/13.","கூட்டிச் சுருக்குக: 6/12 + 1/13."],"options":[["41/26","41/26"],["-11/26","-11/26"],["67/26","67/26"],["15/26","15/26"]],"answer":3,"explanation":["[6×13 + 12]/[12×13] = 15/26.","[6×13 + 12]/[12×13] = 15/26."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21080,"question_number":21081,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 6/12 − 1/13.","கழித்துச் சுருக்குக: 6/12 − 1/13."],"options":[["-15/26","-15/26"],["63/26","63/26"],["37/26","37/26"],["11/26","11/26"]],"answer":3,"explanation":["[6×13 − 12]/[12×13] = 11/26.","[6×13 − 12]/[12×13] = 11/26."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21081,"question_number":21082,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−6/12) × (13/7).","(−6/12) × (13/7) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-27/14","-27/14"],["15/14","15/14"],["1/14","1/14"],["-13/14","-13/14"]],"answer":3,"explanation":["−78/84 = -13/14.","−78/84 = -13/14."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21082,"question_number":21083,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (6/12) ÷ (7/13) in simplest form.","(6/12) ÷ (7/13) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["13/14","13/14"],["41/14","41/14"],["27/14","27/14"],["-1/14","-1/14"]],"answer":0,"explanation":["(6/12) × (13/7) = 13/14.","(6/12) × (13/7) = 13/14."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21083,"question_number":21084,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 7.2 and 0.12.","7.2 மற்றும் 0.12 தசம எண்களைக் கூட்டுக."],"options":[["7.33","7.33"],["7.42","7.42"],["7.32","7.32"],["7.31","7.31"]],"answer":2,"explanation":["7.2 + 0.12 = 7.32.","7.2 + 0.12 = 7.32."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21084,"question_number":21085,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 12x + 6 = 222.","12x + 6 = 222 சமன்பாட்டைத் தீர்க்க."],"options":[["17","17"],["18","18"],["20","20"],["19","19"]],"answer":1,"explanation":["x = (222 − 6)/12 = 18.","x = (222 − 6)/12 = 18."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21085,"question_number":21086,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 6 and y = 12, find (x+y)² − x² − y², then divide by 2.","x = 6, y = 12 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["73","73"],["74","74"],["72","72"],["71","71"]],"answer":2,"explanation":["[(x+y)²−x²−y²]/2 = xy = 6×12 = 72.","[(x+y)²−x²−y²]/2 = xy = 6×12 = 72."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21086,"question_number":21087,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 6, y = 12.","x = 6, y = 12 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["323","323"],["324","324"],["325","325"],["326","326"]],"answer":1,"explanation":["(x+y)² = (6+12)² = 324.","(x+y)² = (6+12)² = 324."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21087,"question_number":21088,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^6 × 7^12 = 7^m, what is m?","7^6 × 7^12 = 7^m எனில் m என்ன?"],"options":[["17","17"],["19","19"],["20","20"],["18","18"]],"answer":3,"explanation":["m = 6 + 12 = 18.","m = 6 + 12 = 18."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21088,"question_number":21089,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^6)^12 = 2^m, find m.","(2^6)^12 = 2^m எனில் m காண்க."],"options":[["74","74"],["72","72"],["71","71"],["73","73"]],"answer":1,"explanation":["m = 6 × 12 = 72.","m = 6 × 12 = 72."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21089,"question_number":21090,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 60% of ₹120.","₹120 இன் 60% காண்க."],"options":[["72","72"],["71","71"],["73","73"],["74","74"]],"answer":0,"explanation":["120×60/100 = 72.","120×60/100 = 72."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21090,"question_number":21091,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹600 has a 60% discount. What is the sale price in rupees?","₹600 குறித்த விலையுள்ள பைக்கு 60% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["242","242"],["240","240"],["241","241"],["239","239"]],"answer":1,"explanation":["600 × (100−60)/100 = 240.","600 × (100−60)/100 = 240."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21091,"question_number":21092,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹600 sells for ₹960. Find the profit percentage.","₹600 க்கு வாங்கிய பொருள் ₹960 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["59","59"],["61","61"],["62","62"],["60","60"]],"answer":3,"explanation":["(960−600)/600×100 = 60%.","(960−600)/600×100 = 60%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21092,"question_number":21093,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹6000 at 12% per year for 3 years.","₹6000 க்கு ஆண்டுக்கு 12% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2160","2160"],["2159","2159"],["2162","2162"],["2161","2161"]],"answer":0,"explanation":["6000×12×3/100 = 2160.","6000×12×3/100 = 2160."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21093,"question_number":21094,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹60000 at 12% a year for 2 years, compounded annually.","₹60000 க்கு ஆண்டுக்கு 12% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["15265","15265"],["15263","15263"],["15264","15264"],["15266","15266"]],"answer":2,"explanation":["60000×[(1+12/100)²−1] = 15264.","60000×[(1+12/100)²−1] = 15264."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21094,"question_number":21095,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["12 metres of cloth cost ₹60. At the same rate, what is the cost of 15 metres in rupees?","12 மீ துணியின் விலை ₹60. அதே வீதத்தில் 15 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["77","77"],["75","75"],["74","74"],["76","76"]],"answer":1,"explanation":["60/12×15 = 75.","60/12×15 = 75."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21095,"question_number":21096,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["12 equally efficient machines complete a job in 6 hours. How many hours do 14 such machines require at the same rate?","சமத் திறனுடைய 12 இயந்திரங்கள் வேலையை 6 மணியில் முடிக்கின்றன. அதே வீதத்தில் 14 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["36/7","36/7"],["29/7","29/7"],["50/7","50/7"],["43/7","43/7"]],"answer":0,"explanation":["12×6/(12+2) = 36/7 hours.","12×6/(12+2) = 36/7 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21096,"question_number":21097,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 12 cm and perpendicular height 12 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 12 செமீ; செங்குத்து உயரம் 12 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["146","146"],["144","144"],["143","143"],["145","145"]],"answer":1,"explanation":["12×12 = 144.","12×12 = 144."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21097,"question_number":21098,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 12 cm and 24 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 12 செமீ, 24 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["146","146"],["145","145"],["143","143"],["144","144"]],"answer":3,"explanation":["½×12×24 = 144 cm².","½×12×24 = 144 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21098,"question_number":21099,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 12 m and 36 m, and height 12 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 12 மீ, 36 மீ; உயரம் 12 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["288","288"],["289","289"],["287","287"],["290","290"]],"answer":0,"explanation":["½×(12+36)×12 = 288.","½×(12+36)×12 = 288."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21099,"question_number":21100,"practice_set":844},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 42 cm makes 12 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","42 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 12 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["3168","3168"],["3170","3170"],["3169","3169"],["3167","3167"]],"answer":0,"explanation":["12×2×22/7×42 = 3168.","12×2×22/7×42 = 3168."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21100,"question_number":21101,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 12 circular mats, each of radius 42 cm. Find their total area in cm², using π=22/7.","தலா 42 செமீ ஆரமுள்ள 12 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["66530","66530"],["66529","66529"],["66527","66527"],["66528","66528"]],"answer":3,"explanation":["12×22/7×42² = 66528.","12×22/7×42² = 66528."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21101,"question_number":21102,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 32° and 54°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 32°, 54°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["94","94"],["96","96"],["93","93"],["95","95"]],"answer":0,"explanation":["180−32−54 = 94°.","180−32−54 = 94°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21102,"question_number":21103,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 56°. One remote interior angle is 32°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 56°. அதற்கான ஓர் எதிர் உட்கோணம் 32°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["24","24"],["26","26"],["23","23"],["25","25"]],"answer":0,"explanation":["56 − 32 = 24°.","56 − 32 = 24°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21103,"question_number":21104,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 6, 18, 30, 42, 54.","6, 18, 30, 42, 54 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["29","29"],["30","30"],["32","32"],["31","31"]],"answer":1,"explanation":["Sum/5 = 150/5 = 30.","கூடுதல்/5 = 150/5 = 30."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21104,"question_number":21105,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 66, 6, 30, 90, 18.","வரிசைப்படுத்தி இடைநிலை காண்க: 66, 6, 30, 90, 18."],"options":[["30","30"],["32","32"],["29","29"],["31","31"]],"answer":0,"explanation":["Sorted: 6, 18, 30, 66, 90; middle value = 30.","வரிசை: 6, 18, 30, 66, 90; நடு மதிப்பு = 30."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21105,"question_number":21106,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 6, 18, 6, 30, 42, 6?","6, 18, 6, 30, 42, 6 தரவுகளின் முகடு எது?"],"options":[["6","6"],["7","7"],["5","5"],["8","8"]],"answer":0,"explanation":["6 occurs 3 times; each other value occurs once.","6 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21106,"question_number":21107,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 6 hours and another in 12 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 6 மணியிலும் மற்றொன்று 12 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["5","5"],["3","3"],["6","6"],["4","4"]],"answer":3,"explanation":["Combined hourly rate = 1/6+1/12; time = 72/18 = 4 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/6+1/12; காலம் = 72/18 = 4 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21107,"question_number":21108,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −6/12. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −6/12. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["-1/2","-1/2"],["5/2","5/2"],["3/2","3/2"],["1/2","1/2"]],"answer":3,"explanation":["−6/12 + 6/12 = 0. Simplified additive inverse: 1/2.","−6/12 + 6/12 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 1/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21108,"question_number":21109,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 6 and 12?","6 மற்றும் 12 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["11","11"],["8","8"],["10","10"],["9","9"]],"answer":3,"explanation":["(6+12)/2 = 9.","(6+12)/2 = 9."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21109,"question_number":21110,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 7/12 + 1/13.","கூட்டிச் சுருக்குக: 7/12 + 1/13."],"options":[["-53/156","-53/156"],["415/156","415/156"],["259/156","259/156"],["103/156","103/156"]],"answer":3,"explanation":["[7×13 + 12]/[12×13] = 103/156.","[7×13 + 12]/[12×13] = 103/156."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21110,"question_number":21111,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 7/12 − 1/13.","கழித்துச் சுருக்குக: 7/12 − 1/13."],"options":[["235/156","235/156"],["79/156","79/156"],["-77/156","-77/156"],["391/156","391/156"]],"answer":1,"explanation":["[7×13 − 12]/[12×13] = 79/156.","[7×13 − 12]/[12×13] = 79/156."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21111,"question_number":21112,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−7/12) × (13/8).","(−7/12) × (13/8) பெருக்கற்பலனைச் சுருக்குக."],"options":[["5/96","5/96"],["-91/96","-91/96"],["-187/96","-187/96"],["101/96","101/96"]],"answer":1,"explanation":["−91/96 = -91/96.","−91/96 = -91/96."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21112,"question_number":21113,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (7/12) ÷ (8/13) in simplest form.","(7/12) ÷ (8/13) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["-5/96","-5/96"],["283/96","283/96"],["187/96","187/96"],["91/96","91/96"]],"answer":3,"explanation":["(7/12) × (13/8) = 91/96.","(7/12) × (13/8) = 91/96."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21113,"question_number":21114,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 8.2 and 0.12.","8.2 மற்றும் 0.12 தசம எண்களைக் கூட்டுக."],"options":[["8.42","8.42"],["8.33","8.33"],["8.32","8.32"],["8.31","8.31"]],"answer":2,"explanation":["8.2 + 0.12 = 8.32.","8.2 + 0.12 = 8.32."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21114,"question_number":21115,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 12x + 7 = 235.","12x + 7 = 235 சமன்பாட்டைத் தீர்க்க."],"options":[["21","21"],["18","18"],["19","19"],["20","20"]],"answer":2,"explanation":["x = (235 − 7)/12 = 19.","x = (235 − 7)/12 = 19."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21115,"question_number":21116,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 7 and y = 12, find (x+y)² − x² − y², then divide by 2.","x = 7, y = 12 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["85","85"],["86","86"],["84","84"],["83","83"]],"answer":2,"explanation":["[(x+y)²−x²−y²]/2 = xy = 7×12 = 84.","[(x+y)²−x²−y²]/2 = xy = 7×12 = 84."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21116,"question_number":21117,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 7, y = 12.","x = 7, y = 12 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["361","361"],["360","360"],["363","363"],["362","362"]],"answer":0,"explanation":["(x+y)² = (7+12)² = 361.","(x+y)² = (7+12)² = 361."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21117,"question_number":21118,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^7 × 7^12 = 7^m, what is m?","7^7 × 7^12 = 7^m எனில் m என்ன?"],"options":[["19","19"],["20","20"],["18","18"],["21","21"]],"answer":0,"explanation":["m = 7 + 12 = 19.","m = 7 + 12 = 19."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21118,"question_number":21119,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^7)^12 = 2^m, find m.","(2^7)^12 = 2^m எனில் m காண்க."],"options":[["83","83"],["84","84"],["86","86"],["85","85"]],"answer":1,"explanation":["m = 7 × 12 = 84.","m = 7 × 12 = 84."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21119,"question_number":21120,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 60% of ₹140.","₹140 இன் 60% காண்க."],"options":[["83","83"],["85","85"],["84","84"],["86","86"]],"answer":2,"explanation":["140×60/100 = 84.","140×60/100 = 84."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21120,"question_number":21121,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹700 has a 60% discount. What is the sale price in rupees?","₹700 குறித்த விலையுள்ள பைக்கு 60% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["282","282"],["279","279"],["280","280"],["281","281"]],"answer":2,"explanation":["700 × (100−60)/100 = 280.","700 × (100−60)/100 = 280."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21121,"question_number":21122,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹700 sells for ₹1120. Find the profit percentage.","₹700 க்கு வாங்கிய பொருள் ₹1120 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["59","59"],["60","60"],["62","62"],["61","61"]],"answer":1,"explanation":["(1120−700)/700×100 = 60%.","(1120−700)/700×100 = 60%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21122,"question_number":21123,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹7000 at 12% per year for 3 years.","₹7000 க்கு ஆண்டுக்கு 12% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2521","2521"],["2519","2519"],["2522","2522"],["2520","2520"]],"answer":3,"explanation":["7000×12×3/100 = 2520.","7000×12×3/100 = 2520."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21123,"question_number":21124,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹70000 at 12% a year for 2 years, compounded annually.","₹70000 க்கு ஆண்டுக்கு 12% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["17807","17807"],["17810","17810"],["17809","17809"],["17808","17808"]],"answer":3,"explanation":["70000×[(1+12/100)²−1] = 17808.","70000×[(1+12/100)²−1] = 17808."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21124,"question_number":21125,"practice_set":845},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["12 metres of cloth cost ₹70. At the same rate, what is the cost of 15 metres in rupees?","12 மீ துணியின் விலை ₹70. அதே வீதத்தில் 15 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["177/2","177/2"],["179/2","179/2"],["173/2","173/2"],["175/2","175/2"]],"answer":3,"explanation":["70/12×15 = 175/2.","70/12×15 = 175/2."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21125,"question_number":21126,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["12 equally efficient machines complete a job in 7 hours. How many hours do 14 such machines require at the same rate?","சமத் திறனுடைய 12 இயந்திரங்கள் வேலையை 7 மணியில் முடிக்கின்றன. அதே வீதத்தில் 14 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["6","6"],["7","7"],["8","8"],["5","5"]],"answer":0,"explanation":["12×7/(12+2) = 6 hours.","12×7/(12+2) = 6 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21126,"question_number":21127,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 14 cm and perpendicular height 12 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 14 செமீ; செங்குத்து உயரம் 12 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["168","168"],["167","167"],["170","170"],["169","169"]],"answer":0,"explanation":["14×12 = 168.","14×12 = 168."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21127,"question_number":21128,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 14 cm and 24 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 14 செமீ, 24 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["168","168"],["169","169"],["167","167"],["170","170"]],"answer":0,"explanation":["½×14×24 = 168 cm².","½×14×24 = 168 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21128,"question_number":21129,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 14 m and 38 m, and height 12 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 14 மீ, 38 மீ; உயரம் 12 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["312","312"],["311","311"],["314","314"],["313","313"]],"answer":0,"explanation":["½×(14+38)×12 = 312.","½×(14+38)×12 = 312."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21129,"question_number":21130,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 49 cm makes 12 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","49 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 12 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["3697","3697"],["3695","3695"],["3696","3696"],["3698","3698"]],"answer":2,"explanation":["12×2×22/7×49 = 3696.","12×2×22/7×49 = 3696."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21130,"question_number":21131,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 12 circular mats, each of radius 49 cm. Find their total area in cm², using π=22/7.","தலா 49 செமீ ஆரமுள்ள 12 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["90553","90553"],["90552","90552"],["90551","90551"],["90554","90554"]],"answer":1,"explanation":["12×22/7×49² = 90552.","12×22/7×49² = 90552."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21131,"question_number":21132,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 34° and 54°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 34°, 54°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["94","94"],["91","91"],["92","92"],["93","93"]],"answer":2,"explanation":["180−34−54 = 92°.","180−34−54 = 92°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21132,"question_number":21133,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 57°. One remote interior angle is 32°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 57°. அதற்கான ஓர் எதிர் உட்கோணம் 32°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["24","24"],["25","25"],["26","26"],["27","27"]],"answer":1,"explanation":["57 − 32 = 25°.","57 − 32 = 25°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21133,"question_number":21134,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 7, 19, 31, 43, 55.","7, 19, 31, 43, 55 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["30","30"],["33","33"],["32","32"],["31","31"]],"answer":3,"explanation":["Sum/5 = 155/5 = 31.","கூடுதல்/5 = 155/5 = 31."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21134,"question_number":21135,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 67, 7, 31, 91, 19.","வரிசைப்படுத்தி இடைநிலை காண்க: 67, 7, 31, 91, 19."],"options":[["30","30"],["31","31"],["32","32"],["33","33"]],"answer":1,"explanation":["Sorted: 7, 19, 31, 67, 91; middle value = 31.","வரிசை: 7, 19, 31, 67, 91; நடு மதிப்பு = 31."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21135,"question_number":21136,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 7, 19, 7, 31, 43, 7?","7, 19, 7, 31, 43, 7 தரவுகளின் முகடு எது?"],"options":[["9","9"],["8","8"],["6","6"],["7","7"]],"answer":3,"explanation":["7 occurs 3 times; each other value occurs once.","7 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21136,"question_number":21137,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 7 hours and another in 12 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 7 மணியிலும் மற்றொன்று 12 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["103/19","103/19"],["122/19","122/19"],["65/19","65/19"],["84/19","84/19"]],"answer":3,"explanation":["Combined hourly rate = 1/7+1/12; time = 84/19 = 84/19 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/7+1/12; காலம் = 84/19 = 84/19 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21137,"question_number":21138,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −7/12. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −7/12. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["-5/12","-5/12"],["19/12","19/12"],["7/12","7/12"],["31/12","31/12"]],"answer":2,"explanation":["−7/12 + 7/12 = 0. Simplified additive inverse: 7/12.","−7/12 + 7/12 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 7/12."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21138,"question_number":21139,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 7 and 12?","7 மற்றும் 12 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["21/2","21/2"],["23/2","23/2"],["17/2","17/2"],["19/2","19/2"]],"answer":3,"explanation":["(7+12)/2 = 19/2.","(7+12)/2 = 19/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21139,"question_number":21140,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 8/12 + 1/13.","கூட்டிச் சுருக்குக: 8/12 + 1/13."],"options":[["-10/39","-10/39"],["107/39","107/39"],["29/39","29/39"],["68/39","68/39"]],"answer":2,"explanation":["[8×13 + 12]/[12×13] = 29/39.","[8×13 + 12]/[12×13] = 29/39."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21140,"question_number":21141,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 8/12 − 1/13.","கழித்துச் சுருக்குக: 8/12 − 1/13."],"options":[["101/39","101/39"],["62/39","62/39"],["-16/39","-16/39"],["23/39","23/39"]],"answer":3,"explanation":["[8×13 − 12]/[12×13] = 23/39.","[8×13 − 12]/[12×13] = 23/39."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21141,"question_number":21142,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−8/12) × (13/9).","(−8/12) × (13/9) பெருக்கற்பலனைச் சுருக்குக."],"options":[["28/27","28/27"],["1/27","1/27"],["-26/27","-26/27"],["-53/27","-53/27"]],"answer":2,"explanation":["−104/108 = -26/27.","−104/108 = -26/27."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21142,"question_number":21143,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (8/12) ÷ (9/13) in simplest form.","(8/12) ÷ (9/13) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["53/27","53/27"],["80/27","80/27"],["26/27","26/27"],["-1/27","-1/27"]],"answer":2,"explanation":["(8/12) × (13/9) = 26/27.","(8/12) × (13/9) = 26/27."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21143,"question_number":21144,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 9.2 and 0.12.","9.2 மற்றும் 0.12 தசம எண்களைக் கூட்டுக."],"options":[["9.31","9.31"],["9.42","9.42"],["9.32","9.32"],["9.33","9.33"]],"answer":2,"explanation":["9.2 + 0.12 = 9.32.","9.2 + 0.12 = 9.32."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21144,"question_number":21145,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 12x + 8 = 248.","12x + 8 = 248 சமன்பாட்டைத் தீர்க்க."],"options":[["20","20"],["22","22"],["21","21"],["19","19"]],"answer":0,"explanation":["x = (248 − 8)/12 = 20.","x = (248 − 8)/12 = 20."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21145,"question_number":21146,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 8 and y = 12, find (x+y)² − x² − y², then divide by 2.","x = 8, y = 12 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["97","97"],["98","98"],["96","96"],["95","95"]],"answer":2,"explanation":["[(x+y)²−x²−y²]/2 = xy = 8×12 = 96.","[(x+y)²−x²−y²]/2 = xy = 8×12 = 96."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21146,"question_number":21147,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 8, y = 12.","x = 8, y = 12 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["402","402"],["399","399"],["401","401"],["400","400"]],"answer":3,"explanation":["(x+y)² = (8+12)² = 400.","(x+y)² = (8+12)² = 400."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21147,"question_number":21148,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^8 × 7^12 = 7^m, what is m?","7^8 × 7^12 = 7^m எனில் m என்ன?"],"options":[["19","19"],["21","21"],["22","22"],["20","20"]],"answer":3,"explanation":["m = 8 + 12 = 20.","m = 8 + 12 = 20."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21148,"question_number":21149,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^8)^12 = 2^m, find m.","(2^8)^12 = 2^m எனில் m காண்க."],"options":[["98","98"],["97","97"],["95","95"],["96","96"]],"answer":3,"explanation":["m = 8 × 12 = 96.","m = 8 × 12 = 96."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21149,"question_number":21150,"practice_set":846},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 60% of ₹160.","₹160 இன் 60% காண்க."],"options":[["95","95"],["98","98"],["96","96"],["97","97"]],"answer":2,"explanation":["160×60/100 = 96.","160×60/100 = 96."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21150,"question_number":21151,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹800 has a 60% discount. What is the sale price in rupees?","₹800 குறித்த விலையுள்ள பைக்கு 60% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["322","322"],["321","321"],["320","320"],["319","319"]],"answer":2,"explanation":["800 × (100−60)/100 = 320.","800 × (100−60)/100 = 320."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21151,"question_number":21152,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹800 sells for ₹1280. Find the profit percentage.","₹800 க்கு வாங்கிய பொருள் ₹1280 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["59","59"],["60","60"],["61","61"],["62","62"]],"answer":1,"explanation":["(1280−800)/800×100 = 60%.","(1280−800)/800×100 = 60%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21152,"question_number":21153,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹8000 at 12% per year for 3 years.","₹8000 க்கு ஆண்டுக்கு 12% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2882","2882"],["2880","2880"],["2879","2879"],["2881","2881"]],"answer":1,"explanation":["8000×12×3/100 = 2880.","8000×12×3/100 = 2880."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21153,"question_number":21154,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹80000 at 12% a year for 2 years, compounded annually.","₹80000 க்கு ஆண்டுக்கு 12% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["20354","20354"],["20351","20351"],["20352","20352"],["20353","20353"]],"answer":2,"explanation":["80000×[(1+12/100)²−1] = 20352.","80000×[(1+12/100)²−1] = 20352."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21154,"question_number":21155,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["12 metres of cloth cost ₹80. At the same rate, what is the cost of 15 metres in rupees?","12 மீ துணியின் விலை ₹80. அதே வீதத்தில் 15 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["102","102"],["101","101"],["99","99"],["100","100"]],"answer":3,"explanation":["80/12×15 = 100.","80/12×15 = 100."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21155,"question_number":21156,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["12 equally efficient machines complete a job in 8 hours. How many hours do 14 such machines require at the same rate?","சமத் திறனுடைய 12 இயந்திரங்கள் வேலையை 8 மணியில் முடிக்கின்றன. அதே வீதத்தில் 14 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["48/7","48/7"],["55/7","55/7"],["41/7","41/7"],["62/7","62/7"]],"answer":0,"explanation":["12×8/(12+2) = 48/7 hours.","12×8/(12+2) = 48/7 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21156,"question_number":21157,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 16 cm and perpendicular height 12 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 16 செமீ; செங்குத்து உயரம் 12 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["193","193"],["192","192"],["194","194"],["191","191"]],"answer":1,"explanation":["16×12 = 192.","16×12 = 192."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21157,"question_number":21158,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 16 cm and 24 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 16 செமீ, 24 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["193","193"],["191","191"],["194","194"],["192","192"]],"answer":3,"explanation":["½×16×24 = 192 cm².","½×16×24 = 192 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21158,"question_number":21159,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 16 m and 40 m, and height 12 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 16 மீ, 40 மீ; உயரம் 12 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["336","336"],["337","337"],["338","338"],["335","335"]],"answer":0,"explanation":["½×(16+40)×12 = 336.","½×(16+40)×12 = 336."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21159,"question_number":21160,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 56 cm makes 12 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","56 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 12 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["4224","4224"],["4223","4223"],["4225","4225"],["4226","4226"]],"answer":0,"explanation":["12×2×22/7×56 = 4224.","12×2×22/7×56 = 4224."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21160,"question_number":21161,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 12 circular mats, each of radius 56 cm. Find their total area in cm², using π=22/7.","தலா 56 செமீ ஆரமுள்ள 12 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["118274","118274"],["118273","118273"],["118271","118271"],["118272","118272"]],"answer":3,"explanation":["12×22/7×56² = 118272.","12×22/7×56² = 118272."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21161,"question_number":21162,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 36° and 54°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 36°, 54°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["89","89"],["91","91"],["92","92"],["90","90"]],"answer":3,"explanation":["180−36−54 = 90°.","180−36−54 = 90°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21162,"question_number":21163,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 58°. One remote interior angle is 32°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 58°. அதற்கான ஓர் எதிர் உட்கோணம் 32°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["25","25"],["27","27"],["28","28"],["26","26"]],"answer":3,"explanation":["58 − 32 = 26°.","58 − 32 = 26°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21163,"question_number":21164,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 8, 20, 32, 44, 56.","8, 20, 32, 44, 56 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["31","31"],["32","32"],["33","33"],["34","34"]],"answer":1,"explanation":["Sum/5 = 160/5 = 32.","கூடுதல்/5 = 160/5 = 32."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21164,"question_number":21165,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 68, 8, 32, 92, 20.","வரிசைப்படுத்தி இடைநிலை காண்க: 68, 8, 32, 92, 20."],"options":[["33","33"],["31","31"],["32","32"],["34","34"]],"answer":2,"explanation":["Sorted: 8, 20, 32, 68, 92; middle value = 32.","வரிசை: 8, 20, 32, 68, 92; நடு மதிப்பு = 32."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21165,"question_number":21166,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 8, 20, 8, 32, 44, 8?","8, 20, 8, 32, 44, 8 தரவுகளின் முகடு எது?"],"options":[["7","7"],["8","8"],["10","10"],["9","9"]],"answer":1,"explanation":["8 occurs 3 times; each other value occurs once.","8 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21166,"question_number":21167,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 8 hours and another in 12 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 8 மணியிலும் மற்றொன்று 12 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["29/5","29/5"],["24/5","24/5"],["34/5","34/5"],["19/5","19/5"]],"answer":1,"explanation":["Combined hourly rate = 1/8+1/12; time = 96/20 = 24/5 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/8+1/12; காலம் = 96/20 = 24/5 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21167,"question_number":21168,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −8/12. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −8/12. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["2/3","2/3"],["8/3","8/3"],["-1/3","-1/3"],["5/3","5/3"]],"answer":0,"explanation":["−8/12 + 8/12 = 0. Simplified additive inverse: 2/3.","−8/12 + 8/12 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 2/3."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21168,"question_number":21169,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 8 and 12?","8 மற்றும் 12 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["12","12"],["9","9"],["10","10"],["11","11"]],"answer":2,"explanation":["(8+12)/2 = 10.","(8+12)/2 = 10."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21169,"question_number":21170,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 9/12 + 1/13.","கூட்டிச் சுருக்குக: 9/12 + 1/13."],"options":[["147/52","147/52"],["-9/52","-9/52"],["95/52","95/52"],["43/52","43/52"]],"answer":3,"explanation":["[9×13 + 12]/[12×13] = 43/52.","[9×13 + 12]/[12×13] = 43/52."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21170,"question_number":21171,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 9/12 − 1/13.","கழித்துச் சுருக்குக: 9/12 − 1/13."],"options":[["87/52","87/52"],["139/52","139/52"],["35/52","35/52"],["-17/52","-17/52"]],"answer":2,"explanation":["[9×13 − 12]/[12×13] = 35/52.","[9×13 − 12]/[12×13] = 35/52."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21171,"question_number":21172,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−9/12) × (13/10).","(−9/12) × (13/10) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-79/40","-79/40"],["-39/40","-39/40"],["41/40","41/40"],["1/40","1/40"]],"answer":1,"explanation":["−117/120 = -39/40.","−117/120 = -39/40."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21172,"question_number":21173,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (9/12) ÷ (10/13) in simplest form.","(9/12) ÷ (10/13) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["119/40","119/40"],["79/40","79/40"],["-1/40","-1/40"],["39/40","39/40"]],"answer":3,"explanation":["(9/12) × (13/10) = 39/40.","(9/12) × (13/10) = 39/40."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21173,"question_number":21174,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 10.2 and 0.12.","10.2 மற்றும் 0.12 தசம எண்களைக் கூட்டுக."],"options":[["10.32","10.32"],["10.31","10.31"],["10.33","10.33"],["10.42","10.42"]],"answer":0,"explanation":["10.2 + 0.12 = 10.32.","10.2 + 0.12 = 10.32."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21174,"question_number":21175,"practice_set":847},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 12x + 9 = 261.","12x + 9 = 261 சமன்பாட்டைத் தீர்க்க."],"options":[["23","23"],["20","20"],["21","21"],["22","22"]],"answer":2,"explanation":["x = (261 − 9)/12 = 21.","x = (261 − 9)/12 = 21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21175,"question_number":21176,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 9 and y = 12, find (x+y)² − x² − y², then divide by 2.","x = 9, y = 12 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["110","110"],["109","109"],["108","108"],["107","107"]],"answer":2,"explanation":["[(x+y)²−x²−y²]/2 = xy = 9×12 = 108.","[(x+y)²−x²−y²]/2 = xy = 9×12 = 108."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21176,"question_number":21177,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 9, y = 12.","x = 9, y = 12 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["440","440"],["443","443"],["441","441"],["442","442"]],"answer":2,"explanation":["(x+y)² = (9+12)² = 441.","(x+y)² = (9+12)² = 441."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21177,"question_number":21178,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^9 × 7^12 = 7^m, what is m?","7^9 × 7^12 = 7^m எனில் m என்ன?"],"options":[["21","21"],["20","20"],["22","22"],["23","23"]],"answer":0,"explanation":["m = 9 + 12 = 21.","m = 9 + 12 = 21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21178,"question_number":21179,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^9)^12 = 2^m, find m.","(2^9)^12 = 2^m எனில் m காண்க."],"options":[["108","108"],["107","107"],["109","109"],["110","110"]],"answer":0,"explanation":["m = 9 × 12 = 108.","m = 9 × 12 = 108."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21179,"question_number":21180,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 60% of ₹180.","₹180 இன் 60% காண்க."],"options":[["107","107"],["110","110"],["109","109"],["108","108"]],"answer":3,"explanation":["180×60/100 = 108.","180×60/100 = 108."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21180,"question_number":21181,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹900 has a 60% discount. What is the sale price in rupees?","₹900 குறித்த விலையுள்ள பைக்கு 60% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["360","360"],["359","359"],["361","361"],["362","362"]],"answer":0,"explanation":["900 × (100−60)/100 = 360.","900 × (100−60)/100 = 360."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21181,"question_number":21182,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹900 sells for ₹1440. Find the profit percentage.","₹900 க்கு வாங்கிய பொருள் ₹1440 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["60","60"],["59","59"],["62","62"],["61","61"]],"answer":0,"explanation":["(1440−900)/900×100 = 60%.","(1440−900)/900×100 = 60%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21182,"question_number":21183,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹9000 at 12% per year for 3 years.","₹9000 க்கு ஆண்டுக்கு 12% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["3239","3239"],["3240","3240"],["3241","3241"],["3242","3242"]],"answer":1,"explanation":["9000×12×3/100 = 3240.","9000×12×3/100 = 3240."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21183,"question_number":21184,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹90000 at 12% a year for 2 years, compounded annually.","₹90000 க்கு ஆண்டுக்கு 12% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["22897","22897"],["22895","22895"],["22898","22898"],["22896","22896"]],"answer":3,"explanation":["90000×[(1+12/100)²−1] = 22896.","90000×[(1+12/100)²−1] = 22896."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21184,"question_number":21185,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["12 metres of cloth cost ₹90. At the same rate, what is the cost of 15 metres in rupees?","12 மீ துணியின் விலை ₹90. அதே வீதத்தில் 15 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["223/2","223/2"],["225/2","225/2"],["227/2","227/2"],["229/2","229/2"]],"answer":1,"explanation":["90/12×15 = 225/2.","90/12×15 = 225/2."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21185,"question_number":21186,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["12 equally efficient machines complete a job in 9 hours. How many hours do 14 such machines require at the same rate?","சமத் திறனுடைய 12 இயந்திரங்கள் வேலையை 9 மணியில் முடிக்கின்றன. அதே வீதத்தில் 14 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["47/7","47/7"],["68/7","68/7"],["54/7","54/7"],["61/7","61/7"]],"answer":2,"explanation":["12×9/(12+2) = 54/7 hours.","12×9/(12+2) = 54/7 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21186,"question_number":21187,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 18 cm and perpendicular height 12 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 18 செமீ; செங்குத்து உயரம் 12 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["218","218"],["215","215"],["217","217"],["216","216"]],"answer":3,"explanation":["18×12 = 216.","18×12 = 216."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21187,"question_number":21188,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 18 cm and 24 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 18 செமீ, 24 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["218","218"],["217","217"],["215","215"],["216","216"]],"answer":3,"explanation":["½×18×24 = 216 cm².","½×18×24 = 216 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21188,"question_number":21189,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 18 m and 42 m, and height 12 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 18 மீ, 42 மீ; உயரம் 12 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["359","359"],["361","361"],["362","362"],["360","360"]],"answer":3,"explanation":["½×(18+42)×12 = 360.","½×(18+42)×12 = 360."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21189,"question_number":21190,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 63 cm makes 12 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","63 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 12 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["4754","4754"],["4752","4752"],["4753","4753"],["4751","4751"]],"answer":1,"explanation":["12×2×22/7×63 = 4752.","12×2×22/7×63 = 4752."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21190,"question_number":21191,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 12 circular mats, each of radius 63 cm. Find their total area in cm², using π=22/7.","தலா 63 செமீ ஆரமுள்ள 12 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["149688","149688"],["149690","149690"],["149687","149687"],["149689","149689"]],"answer":0,"explanation":["12×22/7×63² = 149688.","12×22/7×63² = 149688."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21191,"question_number":21192,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 38° and 54°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 38°, 54°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["89","89"],["87","87"],["88","88"],["90","90"]],"answer":2,"explanation":["180−38−54 = 88°.","180−38−54 = 88°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21192,"question_number":21193,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 59°. One remote interior angle is 32°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 59°. அதற்கான ஓர் எதிர் உட்கோணம் 32°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["26","26"],["29","29"],["27","27"],["28","28"]],"answer":2,"explanation":["59 − 32 = 27°.","59 − 32 = 27°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21193,"question_number":21194,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 9, 21, 33, 45, 57.","9, 21, 33, 45, 57 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["33","33"],["34","34"],["35","35"],["32","32"]],"answer":0,"explanation":["Sum/5 = 165/5 = 33.","கூடுதல்/5 = 165/5 = 33."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21194,"question_number":21195,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 69, 9, 33, 93, 21.","வரிசைப்படுத்தி இடைநிலை காண்க: 69, 9, 33, 93, 21."],"options":[["33","33"],["35","35"],["32","32"],["34","34"]],"answer":0,"explanation":["Sorted: 9, 21, 33, 69, 93; middle value = 33.","வரிசை: 9, 21, 33, 69, 93; நடு மதிப்பு = 33."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21195,"question_number":21196,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 9, 21, 9, 33, 45, 9?","9, 21, 9, 33, 45, 9 தரவுகளின் முகடு எது?"],"options":[["8","8"],["11","11"],["10","10"],["9","9"]],"answer":3,"explanation":["9 occurs 3 times; each other value occurs once.","9 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21196,"question_number":21197,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 9 hours and another in 12 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 9 மணியிலும் மற்றொன்று 12 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["50/7","50/7"],["43/7","43/7"],["29/7","29/7"],["36/7","36/7"]],"answer":3,"explanation":["Combined hourly rate = 1/9+1/12; time = 108/21 = 36/7 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/9+1/12; காலம் = 108/21 = 36/7 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21197,"question_number":21198,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −9/12. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −9/12. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["7/4","7/4"],["3/4","3/4"],["-1/4","-1/4"],["11/4","11/4"]],"answer":1,"explanation":["−9/12 + 9/12 = 0. Simplified additive inverse: 3/4.","−9/12 + 9/12 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 3/4."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21198,"question_number":21199,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 9 and 12?","9 மற்றும் 12 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["23/2","23/2"],["25/2","25/2"],["21/2","21/2"],["19/2","19/2"]],"answer":2,"explanation":["(9+12)/2 = 21/2.","(9+12)/2 = 21/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21199,"question_number":21200,"practice_set":848},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 10/12 + 1/13.","கூட்டிச் சுருக்குக: 10/12 + 1/13."],"options":[["227/78","227/78"],["71/78","71/78"],["-7/78","-7/78"],["149/78","149/78"]],"answer":1,"explanation":["[10×13 + 12]/[12×13] = 71/78.","[10×13 + 12]/[12×13] = 71/78."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21200,"question_number":21201,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 10/12 − 1/13.","கழித்துச் சுருக்குக: 10/12 − 1/13."],"options":[["-19/78","-19/78"],["137/78","137/78"],["215/78","215/78"],["59/78","59/78"]],"answer":3,"explanation":["[10×13 − 12]/[12×13] = 59/78.","[10×13 − 12]/[12×13] = 59/78."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21201,"question_number":21202,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−10/12) × (13/11).","(−10/12) × (13/11) பெருக்கற்பலனைச் சுருக்குக."],"options":[["1/66","1/66"],["-131/66","-131/66"],["67/66","67/66"],["-65/66","-65/66"]],"answer":3,"explanation":["−130/132 = -65/66.","−130/132 = -65/66."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21202,"question_number":21203,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (10/12) ÷ (11/13) in simplest form.","(10/12) ÷ (11/13) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["65/66","65/66"],["131/66","131/66"],["-1/66","-1/66"],["197/66","197/66"]],"answer":0,"explanation":["(10/12) × (13/11) = 65/66.","(10/12) × (13/11) = 65/66."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21203,"question_number":21204,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 11.2 and 0.12.","11.2 மற்றும் 0.12 தசம எண்களைக் கூட்டுக."],"options":[["11.42","11.42"],["11.31","11.31"],["11.33","11.33"],["11.32","11.32"]],"answer":3,"explanation":["11.2 + 0.12 = 11.32.","11.2 + 0.12 = 11.32."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21204,"question_number":21205,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 12x + 10 = 274.","12x + 10 = 274 சமன்பாட்டைத் தீர்க்க."],"options":[["21","21"],["23","23"],["22","22"],["24","24"]],"answer":2,"explanation":["x = (274 − 10)/12 = 22.","x = (274 − 10)/12 = 22."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21205,"question_number":21206,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 10 and y = 12, find (x+y)² − x² − y², then divide by 2.","x = 10, y = 12 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["119","119"],["121","121"],["122","122"],["120","120"]],"answer":3,"explanation":["[(x+y)²−x²−y²]/2 = xy = 10×12 = 120.","[(x+y)²−x²−y²]/2 = xy = 10×12 = 120."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21206,"question_number":21207,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 10, y = 12.","x = 10, y = 12 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["486","486"],["483","483"],["485","485"],["484","484"]],"answer":3,"explanation":["(x+y)² = (10+12)² = 484.","(x+y)² = (10+12)² = 484."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21207,"question_number":21208,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^10 × 7^12 = 7^m, what is m?","7^10 × 7^12 = 7^m எனில் m என்ன?"],"options":[["21","21"],["22","22"],["23","23"],["24","24"]],"answer":1,"explanation":["m = 10 + 12 = 22.","m = 10 + 12 = 22."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21208,"question_number":21209,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^10)^12 = 2^m, find m.","(2^10)^12 = 2^m எனில் m காண்க."],"options":[["121","121"],["120","120"],["119","119"],["122","122"]],"answer":1,"explanation":["m = 10 × 12 = 120.","m = 10 × 12 = 120."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21209,"question_number":21210,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 60% of ₹200.","₹200 இன் 60% காண்க."],"options":[["122","122"],["120","120"],["121","121"],["119","119"]],"answer":1,"explanation":["200×60/100 = 120.","200×60/100 = 120."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21210,"question_number":21211,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹1000 has a 60% discount. What is the sale price in rupees?","₹1000 குறித்த விலையுள்ள பைக்கு 60% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["402","402"],["400","400"],["399","399"],["401","401"]],"answer":1,"explanation":["1000 × (100−60)/100 = 400.","1000 × (100−60)/100 = 400."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21211,"question_number":21212,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹1000 sells for ₹1600. Find the profit percentage.","₹1000 க்கு வாங்கிய பொருள் ₹1600 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["62","62"],["61","61"],["60","60"],["59","59"]],"answer":2,"explanation":["(1600−1000)/1000×100 = 60%.","(1600−1000)/1000×100 = 60%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21212,"question_number":21213,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹10000 at 12% per year for 3 years.","₹10000 க்கு ஆண்டுக்கு 12% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["3601","3601"],["3600","3600"],["3599","3599"],["3602","3602"]],"answer":1,"explanation":["10000×12×3/100 = 3600.","10000×12×3/100 = 3600."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21213,"question_number":21214,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹100000 at 12% a year for 2 years, compounded annually.","₹100000 க்கு ஆண்டுக்கு 12% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["25442","25442"],["25439","25439"],["25441","25441"],["25440","25440"]],"answer":3,"explanation":["100000×[(1+12/100)²−1] = 25440.","100000×[(1+12/100)²−1] = 25440."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21214,"question_number":21215,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["12 metres of cloth cost ₹100. At the same rate, what is the cost of 15 metres in rupees?","12 மீ துணியின் விலை ₹100. அதே வீதத்தில் 15 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["127","127"],["126","126"],["124","124"],["125","125"]],"answer":3,"explanation":["100/12×15 = 125.","100/12×15 = 125."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21215,"question_number":21216,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["12 equally efficient machines complete a job in 10 hours. How many hours do 14 such machines require at the same rate?","சமத் திறனுடைய 12 இயந்திரங்கள் வேலையை 10 மணியில் முடிக்கின்றன. அதே வீதத்தில் 14 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["67/7","67/7"],["53/7","53/7"],["74/7","74/7"],["60/7","60/7"]],"answer":3,"explanation":["12×10/(12+2) = 60/7 hours.","12×10/(12+2) = 60/7 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21216,"question_number":21217,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 20 cm and perpendicular height 12 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 20 செமீ; செங்குத்து உயரம் 12 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["240","240"],["241","241"],["239","239"],["242","242"]],"answer":0,"explanation":["20×12 = 240.","20×12 = 240."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21217,"question_number":21218,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 20 cm and 24 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 20 செமீ, 24 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["241","241"],["239","239"],["240","240"],["242","242"]],"answer":2,"explanation":["½×20×24 = 240 cm².","½×20×24 = 240 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21218,"question_number":21219,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 20 m and 44 m, and height 12 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 20 மீ, 44 மீ; உயரம் 12 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["386","386"],["383","383"],["385","385"],["384","384"]],"answer":3,"explanation":["½×(20+44)×12 = 384.","½×(20+44)×12 = 384."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21219,"question_number":21220,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 70 cm makes 12 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","70 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 12 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["5281","5281"],["5282","5282"],["5280","5280"],["5279","5279"]],"answer":2,"explanation":["12×2×22/7×70 = 5280.","12×2×22/7×70 = 5280."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21220,"question_number":21221,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 12 circular mats, each of radius 70 cm. Find their total area in cm², using π=22/7.","தலா 70 செமீ ஆரமுள்ள 12 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["184802","184802"],["184799","184799"],["184800","184800"],["184801","184801"]],"answer":2,"explanation":["12×22/7×70² = 184800.","12×22/7×70² = 184800."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21221,"question_number":21222,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 40° and 54°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 40°, 54°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["85","85"],["86","86"],["87","87"],["88","88"]],"answer":1,"explanation":["180−40−54 = 86°.","180−40−54 = 86°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21222,"question_number":21223,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 60°. One remote interior angle is 32°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 60°. அதற்கான ஓர் எதிர் உட்கோணம் 32°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["29","29"],["28","28"],["30","30"],["27","27"]],"answer":1,"explanation":["60 − 32 = 28°.","60 − 32 = 28°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21223,"question_number":21224,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 10, 22, 34, 46, 58.","10, 22, 34, 46, 58 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["35","35"],["34","34"],["36","36"],["33","33"]],"answer":1,"explanation":["Sum/5 = 170/5 = 34.","கூடுதல்/5 = 170/5 = 34."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21224,"question_number":21225,"practice_set":849},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 70, 10, 34, 94, 22.","வரிசைப்படுத்தி இடைநிலை காண்க: 70, 10, 34, 94, 22."],"options":[["33","33"],["36","36"],["34","34"],["35","35"]],"answer":2,"explanation":["Sorted: 10, 22, 34, 70, 94; middle value = 34.","வரிசை: 10, 22, 34, 70, 94; நடு மதிப்பு = 34."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21225,"question_number":21226,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 10, 22, 10, 34, 46, 10?","10, 22, 10, 34, 46, 10 தரவுகளின் முகடு எது?"],"options":[["10","10"],["9","9"],["11","11"],["12","12"]],"answer":0,"explanation":["10 occurs 3 times; each other value occurs once.","10 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21226,"question_number":21227,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 10 hours and another in 12 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 10 மணியிலும் மற்றொன்று 12 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["49/11","49/11"],["71/11","71/11"],["60/11","60/11"],["82/11","82/11"]],"answer":2,"explanation":["Combined hourly rate = 1/10+1/12; time = 120/22 = 60/11 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/10+1/12; காலம் = 120/22 = 60/11 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21227,"question_number":21228,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −10/12. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −10/12. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["17/6","17/6"],["5/6","5/6"],["-1/6","-1/6"],["11/6","11/6"]],"answer":1,"explanation":["−10/12 + 10/12 = 0. Simplified additive inverse: 5/6.","−10/12 + 10/12 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 5/6."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21228,"question_number":21229,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 10 and 12?","10 மற்றும் 12 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["11","11"],["13","13"],["12","12"],["10","10"]],"answer":0,"explanation":["(10+12)/2 = 11.","(10+12)/2 = 11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21229,"question_number":21230,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 11/12 + 1/13.","கூட்டிச் சுருக்குக: 11/12 + 1/13."],"options":[["311/156","311/156"],["155/156","155/156"],["-1/156","-1/156"],["467/156","467/156"]],"answer":1,"explanation":["[11×13 + 12]/[12×13] = 155/156.","[11×13 + 12]/[12×13] = 155/156."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21230,"question_number":21231,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 11/12 − 1/13.","கழித்துச் சுருக்குக: 11/12 − 1/13."],"options":[["-25/156","-25/156"],["131/156","131/156"],["287/156","287/156"],["443/156","443/156"]],"answer":1,"explanation":["[11×13 − 12]/[12×13] = 131/156.","[11×13 − 12]/[12×13] = 131/156."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21231,"question_number":21232,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−11/12) × (13/12).","(−11/12) × (13/12) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-287/144","-287/144"],["1/144","1/144"],["145/144","145/144"],["-143/144","-143/144"]],"answer":3,"explanation":["−143/144 = -143/144.","−143/144 = -143/144."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21232,"question_number":21233,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (11/12) ÷ (12/13) in simplest form.","(11/12) ÷ (12/13) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["143/144","143/144"],["431/144","431/144"],["-1/144","-1/144"],["287/144","287/144"]],"answer":0,"explanation":["(11/12) × (13/12) = 143/144.","(11/12) × (13/12) = 143/144."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21233,"question_number":21234,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 12.2 and 0.12.","12.2 மற்றும் 0.12 தசம எண்களைக் கூட்டுக."],"options":[["12.42","12.42"],["12.31","12.31"],["12.32","12.32"],["12.33","12.33"]],"answer":2,"explanation":["12.2 + 0.12 = 12.32.","12.2 + 0.12 = 12.32."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21234,"question_number":21235,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 12x + 11 = 287.","12x + 11 = 287 சமன்பாட்டைத் தீர்க்க."],"options":[["25","25"],["23","23"],["22","22"],["24","24"]],"answer":1,"explanation":["x = (287 − 11)/12 = 23.","x = (287 − 11)/12 = 23."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21235,"question_number":21236,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 11 and y = 12, find (x+y)² − x² − y², then divide by 2.","x = 11, y = 12 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["133","133"],["132","132"],["134","134"],["131","131"]],"answer":1,"explanation":["[(x+y)²−x²−y²]/2 = xy = 11×12 = 132.","[(x+y)²−x²−y²]/2 = xy = 11×12 = 132."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21236,"question_number":21237,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 11, y = 12.","x = 11, y = 12 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["528","528"],["530","530"],["529","529"],["531","531"]],"answer":2,"explanation":["(x+y)² = (11+12)² = 529.","(x+y)² = (11+12)² = 529."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21237,"question_number":21238,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^11 × 7^12 = 7^m, what is m?","7^11 × 7^12 = 7^m எனில் m என்ன?"],"options":[["25","25"],["23","23"],["24","24"],["22","22"]],"answer":1,"explanation":["m = 11 + 12 = 23.","m = 11 + 12 = 23."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21238,"question_number":21239,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^11)^12 = 2^m, find m.","(2^11)^12 = 2^m எனில் m காண்க."],"options":[["134","134"],["131","131"],["133","133"],["132","132"]],"answer":3,"explanation":["m = 11 × 12 = 132.","m = 11 × 12 = 132."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21239,"question_number":21240,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 14884.","14884 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["124","124"],["121","121"],["123","123"],["122","122"]],"answer":3,"explanation":["122 × 122 = 14884; √14884 = 122.","122 × 122 = 14884; √14884 = 122."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":21240,"question_number":21241,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 1815848.","1815848 இன் கனமூலத்தைக் காண்க."],"options":[["121","121"],["124","124"],["123","123"],["122","122"]],"answer":3,"explanation":["122 × 122 × 122 = 1815848; cube root = 122.","122 × 122 × 122 = 1815848; கனமூலம் = 122."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":21241,"question_number":21242,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 60% of ₹220.","₹220 இன் 60% காண்க."],"options":[["132","132"],["131","131"],["134","134"],["133","133"]],"answer":0,"explanation":["220×60/100 = 132.","220×60/100 = 132."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21242,"question_number":21243,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹1100 has a 60% discount. What is the sale price in rupees?","₹1100 குறித்த விலையுள்ள பைக்கு 60% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["441","441"],["440","440"],["439","439"],["442","442"]],"answer":1,"explanation":["1100 × (100−60)/100 = 440.","1100 × (100−60)/100 = 440."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21243,"question_number":21244,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹1100 sells for ₹1760. Find the profit percentage.","₹1100 க்கு வாங்கிய பொருள் ₹1760 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["62","62"],["59","59"],["61","61"],["60","60"]],"answer":3,"explanation":["(1760−1100)/1100×100 = 60%.","(1760−1100)/1100×100 = 60%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21244,"question_number":21245,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹11000 at 12% per year for 3 years.","₹11000 க்கு ஆண்டுக்கு 12% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["3962","3962"],["3961","3961"],["3960","3960"],["3959","3959"]],"answer":2,"explanation":["11000×12×3/100 = 3960.","11000×12×3/100 = 3960."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21245,"question_number":21246,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹110000 at 12% a year for 2 years, compounded annually.","₹110000 க்கு ஆண்டுக்கு 12% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["27986","27986"],["27984","27984"],["27983","27983"],["27985","27985"]],"answer":1,"explanation":["110000×[(1+12/100)²−1] = 27984.","110000×[(1+12/100)²−1] = 27984."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21246,"question_number":21247,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["12 metres of cloth cost ₹110. At the same rate, what is the cost of 15 metres in rupees?","12 மீ துணியின் விலை ₹110. அதே வீதத்தில் 15 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["275/2","275/2"],["279/2","279/2"],["273/2","273/2"],["277/2","277/2"]],"answer":0,"explanation":["110/12×15 = 275/2.","110/12×15 = 275/2."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21247,"question_number":21248,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["12 equally efficient machines complete a job in 11 hours. How many hours do 14 such machines require at the same rate?","சமத் திறனுடைய 12 இயந்திரங்கள் வேலையை 11 மணியில் முடிக்கின்றன. அதே வீதத்தில் 14 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["73/7","73/7"],["80/7","80/7"],["66/7","66/7"],["59/7","59/7"]],"answer":2,"explanation":["12×11/(12+2) = 66/7 hours.","12×11/(12+2) = 66/7 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21248,"question_number":21249,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 22 cm and perpendicular height 12 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 22 செமீ; செங்குத்து உயரம் 12 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["264","264"],["266","266"],["265","265"],["263","263"]],"answer":0,"explanation":["22×12 = 264.","22×12 = 264."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21249,"question_number":21250,"practice_set":850},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 22 cm and 24 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 22 செமீ, 24 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["266","266"],["265","265"],["263","263"],["264","264"]],"answer":3,"explanation":["½×22×24 = 264 cm².","½×22×24 = 264 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21250,"question_number":21251,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 22 m and 46 m, and height 12 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 22 மீ, 46 மீ; உயரம் 12 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["407","407"],["409","409"],["410","410"],["408","408"]],"answer":3,"explanation":["½×(22+46)×12 = 408.","½×(22+46)×12 = 408."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21251,"question_number":21252,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 77 cm makes 12 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","77 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 12 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["5810","5810"],["5809","5809"],["5808","5808"],["5807","5807"]],"answer":2,"explanation":["12×2×22/7×77 = 5808.","12×2×22/7×77 = 5808."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21252,"question_number":21253,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 12 circular mats, each of radius 77 cm. Find their total area in cm², using π=22/7.","தலா 77 செமீ ஆரமுள்ள 12 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["223607","223607"],["223609","223609"],["223610","223610"],["223608","223608"]],"answer":3,"explanation":["12×22/7×77² = 223608.","12×22/7×77² = 223608."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21253,"question_number":21254,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 42° and 54°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 42°, 54°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["83","83"],["86","86"],["85","85"],["84","84"]],"answer":3,"explanation":["180−42−54 = 84°.","180−42−54 = 84°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21254,"question_number":21255,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 61°. One remote interior angle is 32°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 61°. அதற்கான ஓர் எதிர் உட்கோணம் 32°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["30","30"],["29","29"],["31","31"],["28","28"]],"answer":1,"explanation":["61 − 32 = 29°.","61 − 32 = 29°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21255,"question_number":21256,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 11, 23, 35, 47, 59.","11, 23, 35, 47, 59 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["35","35"],["34","34"],["36","36"],["37","37"]],"answer":0,"explanation":["Sum/5 = 175/5 = 35.","கூடுதல்/5 = 175/5 = 35."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21256,"question_number":21257,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 71, 11, 35, 95, 23.","வரிசைப்படுத்தி இடைநிலை காண்க: 71, 11, 35, 95, 23."],"options":[["34","34"],["36","36"],["35","35"],["37","37"]],"answer":2,"explanation":["Sorted: 11, 23, 35, 71, 95; middle value = 35.","வரிசை: 11, 23, 35, 71, 95; நடு மதிப்பு = 35."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21257,"question_number":21258,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 11, 23, 11, 35, 47, 11?","11, 23, 11, 35, 47, 11 தரவுகளின் முகடு எது?"],"options":[["12","12"],["10","10"],["13","13"],["11","11"]],"answer":3,"explanation":["11 occurs 3 times; each other value occurs once.","11 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21258,"question_number":21259,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 11 hours and another in 12 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 11 மணியிலும் மற்றொன்று 12 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["178/23","178/23"],["155/23","155/23"],["109/23","109/23"],["132/23","132/23"]],"answer":3,"explanation":["Combined hourly rate = 1/11+1/12; time = 132/23 = 132/23 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/11+1/12; காலம் = 132/23 = 132/23 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21259,"question_number":21260,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −11/12. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −11/12. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["23/12","23/12"],["35/12","35/12"],["11/12","11/12"],["-1/12","-1/12"]],"answer":2,"explanation":["−11/12 + 11/12 = 0. Simplified additive inverse: 11/12.","−11/12 + 11/12 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 11/12."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21260,"question_number":21261,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 11 and 12?","11 மற்றும் 12 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["25/2","25/2"],["21/2","21/2"],["23/2","23/2"],["27/2","27/2"]],"answer":2,"explanation":["(11+12)/2 = 23/2.","(11+12)/2 = 23/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21261,"question_number":21262,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 2/13 + 1/14.","கூட்டிச் சுருக்குக: 2/13 + 1/14."],"options":[["223/182","223/182"],["405/182","405/182"],["41/182","41/182"],["-141/182","-141/182"]],"answer":2,"explanation":["[2×14 + 13]/[13×14] = 41/182.","[2×14 + 13]/[13×14] = 41/182."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21262,"question_number":21263,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 2/13 − 1/14.","கழித்துச் சுருக்குக: 2/13 − 1/14."],"options":[["379/182","379/182"],["-167/182","-167/182"],["197/182","197/182"],["15/182","15/182"]],"answer":3,"explanation":["[2×14 − 13]/[13×14] = 15/182.","[2×14 − 13]/[13×14] = 15/182."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21263,"question_number":21264,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−2/13) × (14/3).","(−2/13) × (14/3) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-67/39","-67/39"],["-28/39","-28/39"],["11/39","11/39"],["50/39","50/39"]],"answer":1,"explanation":["−28/39 = -28/39.","−28/39 = -28/39."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21264,"question_number":21265,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (2/13) ÷ (3/14) in simplest form.","(2/13) ÷ (3/14) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["67/39","67/39"],["-11/39","-11/39"],["28/39","28/39"],["106/39","106/39"]],"answer":2,"explanation":["(2/13) × (14/3) = 28/39.","(2/13) × (14/3) = 28/39."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21265,"question_number":21266,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 3.3 and 0.13.","3.3 மற்றும் 0.13 தசம எண்களைக் கூட்டுக."],"options":[["3.43","3.43"],["3.42","3.42"],["3.44","3.44"],["3.53","3.53"]],"answer":0,"explanation":["3.3 + 0.13 = 3.43.","3.3 + 0.13 = 3.43."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21266,"question_number":21267,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 13x + 2 = 197.","13x + 2 = 197 சமன்பாட்டைத் தீர்க்க."],"options":[["16","16"],["17","17"],["14","14"],["15","15"]],"answer":3,"explanation":["x = (197 − 2)/13 = 15.","x = (197 − 2)/13 = 15."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21267,"question_number":21268,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 2 and y = 13, find (x+y)² − x² − y², then divide by 2.","x = 2, y = 13 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["26","26"],["28","28"],["27","27"],["25","25"]],"answer":0,"explanation":["[(x+y)²−x²−y²]/2 = xy = 2×13 = 26.","[(x+y)²−x²−y²]/2 = xy = 2×13 = 26."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21268,"question_number":21269,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 2, y = 13.","x = 2, y = 13 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["224","224"],["226","226"],["225","225"],["227","227"]],"answer":2,"explanation":["(x+y)² = (2+13)² = 225.","(x+y)² = (2+13)² = 225."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21269,"question_number":21270,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^2 × 7^13 = 7^m, what is m?","7^2 × 7^13 = 7^m எனில் m என்ன?"],"options":[["17","17"],["15","15"],["14","14"],["16","16"]],"answer":1,"explanation":["m = 2 + 13 = 15.","m = 2 + 13 = 15."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21270,"question_number":21271,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^2)^13 = 2^m, find m.","(2^2)^13 = 2^m எனில் m காண்க."],"options":[["25","25"],["26","26"],["28","28"],["27","27"]],"answer":1,"explanation":["m = 2 × 13 = 26.","m = 2 × 13 = 26."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21271,"question_number":21272,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 65% of ₹40.","₹40 இன் 65% காண்க."],"options":[["27","27"],["28","28"],["25","25"],["26","26"]],"answer":3,"explanation":["40×65/100 = 26.","40×65/100 = 26."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21272,"question_number":21273,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹200 has a 65% discount. What is the sale price in rupees?","₹200 குறித்த விலையுள்ள பைக்கு 65% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["71","71"],["69","69"],["70","70"],["72","72"]],"answer":2,"explanation":["200 × (100−65)/100 = 70.","200 × (100−65)/100 = 70."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21273,"question_number":21274,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹200 sells for ₹330. Find the profit percentage.","₹200 க்கு வாங்கிய பொருள் ₹330 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["66","66"],["64","64"],["65","65"],["67","67"]],"answer":2,"explanation":["(330−200)/200×100 = 65%.","(330−200)/200×100 = 65%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21274,"question_number":21275,"practice_set":851},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹2000 at 13% per year for 3 years.","₹2000 க்கு ஆண்டுக்கு 13% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["781","781"],["779","779"],["782","782"],["780","780"]],"answer":3,"explanation":["2000×13×3/100 = 780.","2000×13×3/100 = 780."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21275,"question_number":21276,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹20000 at 13% a year for 2 years, compounded annually.","₹20000 க்கு ஆண்டுக்கு 13% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["5540","5540"],["5537","5537"],["5538","5538"],["5539","5539"]],"answer":2,"explanation":["20000×[(1+13/100)²−1] = 5538.","20000×[(1+13/100)²−1] = 5538."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21276,"question_number":21277,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["13 metres of cloth cost ₹20. At the same rate, what is the cost of 16 metres in rupees?","13 மீ துணியின் விலை ₹20. அதே வீதத்தில் 16 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["333/13","333/13"],["307/13","307/13"],["346/13","346/13"],["320/13","320/13"]],"answer":3,"explanation":["20/13×16 = 320/13.","20/13×16 = 320/13."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21277,"question_number":21278,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["13 equally efficient machines complete a job in 2 hours. How many hours do 15 such machines require at the same rate?","சமத் திறனுடைய 13 இயந்திரங்கள் வேலையை 2 மணியில் முடிக்கின்றன. அதே வீதத்தில் 15 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["11/15","11/15"],["41/15","41/15"],["56/15","56/15"],["26/15","26/15"]],"answer":3,"explanation":["13×2/(13+2) = 26/15 hours.","13×2/(13+2) = 26/15 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21278,"question_number":21279,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 4 cm and perpendicular height 13 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 4 செமீ; செங்குத்து உயரம் 13 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["53","53"],["51","51"],["54","54"],["52","52"]],"answer":3,"explanation":["4×13 = 52.","4×13 = 52."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21279,"question_number":21280,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 4 cm and 26 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 4 செமீ, 26 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["53","53"],["52","52"],["54","54"],["51","51"]],"answer":1,"explanation":["½×4×26 = 52 cm².","½×4×26 = 52 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21280,"question_number":21281,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 4 m and 30 m, and height 13 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 4 மீ, 30 மீ; உயரம் 13 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["223","223"],["221","221"],["220","220"],["222","222"]],"answer":1,"explanation":["½×(4+30)×13 = 221.","½×(4+30)×13 = 221."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21281,"question_number":21282,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 14 cm makes 13 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","14 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 13 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["1144","1144"],["1145","1145"],["1146","1146"],["1143","1143"]],"answer":0,"explanation":["13×2×22/7×14 = 1144.","13×2×22/7×14 = 1144."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21282,"question_number":21283,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 13 circular mats, each of radius 14 cm. Find their total area in cm², using π=22/7.","தலா 14 செமீ ஆரமுள்ள 13 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["8009","8009"],["8007","8007"],["8010","8010"],["8008","8008"]],"answer":3,"explanation":["13×22/7×14² = 8008.","13×22/7×14² = 8008."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21283,"question_number":21284,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 24° and 56°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 24°, 56°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["101","101"],["99","99"],["100","100"],["102","102"]],"answer":2,"explanation":["180−24−56 = 100°.","180−24−56 = 100°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21284,"question_number":21285,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 52°. One remote interior angle is 33°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 52°. அதற்கான ஓர் எதிர் உட்கோணம் 33°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["19","19"],["20","20"],["18","18"],["21","21"]],"answer":0,"explanation":["52 − 33 = 19°.","52 − 33 = 19°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21285,"question_number":21286,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 2, 15, 28, 41, 54.","2, 15, 28, 41, 54 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["28","28"],["29","29"],["30","30"],["27","27"]],"answer":0,"explanation":["Sum/5 = 140/5 = 28.","கூடுதல்/5 = 140/5 = 28."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21286,"question_number":21287,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 67, 2, 28, 93, 15.","வரிசைப்படுத்தி இடைநிலை காண்க: 67, 2, 28, 93, 15."],"options":[["28","28"],["27","27"],["30","30"],["29","29"]],"answer":0,"explanation":["Sorted: 2, 15, 28, 67, 93; middle value = 28.","வரிசை: 2, 15, 28, 67, 93; நடு மதிப்பு = 28."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21287,"question_number":21288,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 2, 15, 2, 28, 41, 2?","2, 15, 2, 28, 41, 2 தரவுகளின் முகடு எது?"],"options":[["4","4"],["1","1"],["3","3"],["2","2"]],"answer":3,"explanation":["2 occurs 3 times; each other value occurs once.","2 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21288,"question_number":21289,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 2 hours and another in 13 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 2 மணியிலும் மற்றொன்று 13 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["26/15","26/15"],["11/15","11/15"],["41/15","41/15"],["56/15","56/15"]],"answer":0,"explanation":["Combined hourly rate = 1/2+1/13; time = 26/15 = 26/15 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/2+1/13; காலம் = 26/15 = 26/15 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21289,"question_number":21290,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −2/13. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −2/13. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["-11/13","-11/13"],["15/13","15/13"],["2/13","2/13"],["28/13","28/13"]],"answer":2,"explanation":["−2/13 + 2/13 = 0. Simplified additive inverse: 2/13.","−2/13 + 2/13 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 2/13."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21290,"question_number":21291,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 2 and 13?","2 மற்றும் 13 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["17/2","17/2"],["19/2","19/2"],["13/2","13/2"],["15/2","15/2"]],"answer":3,"explanation":["(2+13)/2 = 15/2.","(2+13)/2 = 15/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21291,"question_number":21292,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 3/13 + 1/14.","கூட்டிச் சுருக்குக: 3/13 + 1/14."],"options":[["419/182","419/182"],["237/182","237/182"],["55/182","55/182"],["-127/182","-127/182"]],"answer":2,"explanation":["[3×14 + 13]/[13×14] = 55/182.","[3×14 + 13]/[13×14] = 55/182."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21292,"question_number":21293,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 3/13 − 1/14.","கழித்துச் சுருக்குக: 3/13 − 1/14."],"options":[["393/182","393/182"],["211/182","211/182"],["29/182","29/182"],["-153/182","-153/182"]],"answer":2,"explanation":["[3×14 − 13]/[13×14] = 29/182.","[3×14 − 13]/[13×14] = 29/182."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21293,"question_number":21294,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−3/13) × (14/4).","(−3/13) × (14/4) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-21/26","-21/26"],["31/26","31/26"],["5/26","5/26"],["-47/26","-47/26"]],"answer":0,"explanation":["−42/52 = -21/26.","−42/52 = -21/26."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21294,"question_number":21295,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (3/13) ÷ (4/14) in simplest form.","(3/13) ÷ (4/14) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["47/26","47/26"],["21/26","21/26"],["-5/26","-5/26"],["73/26","73/26"]],"answer":1,"explanation":["(3/13) × (14/4) = 21/26.","(3/13) × (14/4) = 21/26."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21295,"question_number":21296,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 4.3 and 0.13.","4.3 மற்றும் 0.13 தசம எண்களைக் கூட்டுக."],"options":[["4.42","4.42"],["4.53","4.53"],["4.44","4.44"],["4.43","4.43"]],"answer":3,"explanation":["4.3 + 0.13 = 4.43.","4.3 + 0.13 = 4.43."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21296,"question_number":21297,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 13x + 3 = 211.","13x + 3 = 211 சமன்பாட்டைத் தீர்க்க."],"options":[["17","17"],["18","18"],["16","16"],["15","15"]],"answer":2,"explanation":["x = (211 − 3)/13 = 16.","x = (211 − 3)/13 = 16."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21297,"question_number":21298,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 3 and y = 13, find (x+y)² − x² − y², then divide by 2.","x = 3, y = 13 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["41","41"],["39","39"],["40","40"],["38","38"]],"answer":1,"explanation":["[(x+y)²−x²−y²]/2 = xy = 3×13 = 39.","[(x+y)²−x²−y²]/2 = xy = 3×13 = 39."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21298,"question_number":21299,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 3, y = 13.","x = 3, y = 13 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["256","256"],["257","257"],["258","258"],["255","255"]],"answer":0,"explanation":["(x+y)² = (3+13)² = 256.","(x+y)² = (3+13)² = 256."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21299,"question_number":21300,"practice_set":852},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^3 × 7^13 = 7^m, what is m?","7^3 × 7^13 = 7^m எனில் m என்ன?"],"options":[["16","16"],["18","18"],["15","15"],["17","17"]],"answer":0,"explanation":["m = 3 + 13 = 16.","m = 3 + 13 = 16."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21300,"question_number":21301,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^3)^13 = 2^m, find m.","(2^3)^13 = 2^m எனில் m காண்க."],"options":[["41","41"],["39","39"],["40","40"],["38","38"]],"answer":1,"explanation":["m = 3 × 13 = 39.","m = 3 × 13 = 39."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21301,"question_number":21302,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 65% of ₹60.","₹60 இன் 65% காண்க."],"options":[["41","41"],["38","38"],["39","39"],["40","40"]],"answer":2,"explanation":["60×65/100 = 39.","60×65/100 = 39."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21302,"question_number":21303,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹300 has a 65% discount. What is the sale price in rupees?","₹300 குறித்த விலையுள்ள பைக்கு 65% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["106","106"],["104","104"],["107","107"],["105","105"]],"answer":3,"explanation":["300 × (100−65)/100 = 105.","300 × (100−65)/100 = 105."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21303,"question_number":21304,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹300 sells for ₹495. Find the profit percentage.","₹300 க்கு வாங்கிய பொருள் ₹495 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["64","64"],["65","65"],["67","67"],["66","66"]],"answer":1,"explanation":["(495−300)/300×100 = 65%.","(495−300)/300×100 = 65%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21304,"question_number":21305,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹3000 at 13% per year for 3 years.","₹3000 க்கு ஆண்டுக்கு 13% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1172","1172"],["1169","1169"],["1171","1171"],["1170","1170"]],"answer":3,"explanation":["3000×13×3/100 = 1170.","3000×13×3/100 = 1170."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21305,"question_number":21306,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹30000 at 13% a year for 2 years, compounded annually.","₹30000 க்கு ஆண்டுக்கு 13% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["8308","8308"],["8307","8307"],["8306","8306"],["8309","8309"]],"answer":1,"explanation":["30000×[(1+13/100)²−1] = 8307.","30000×[(1+13/100)²−1] = 8307."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21306,"question_number":21307,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["13 metres of cloth cost ₹30. At the same rate, what is the cost of 16 metres in rupees?","13 மீ துணியின் விலை ₹30. அதே வீதத்தில் 16 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["467/13","467/13"],["506/13","506/13"],["493/13","493/13"],["480/13","480/13"]],"answer":3,"explanation":["30/13×16 = 480/13.","30/13×16 = 480/13."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21307,"question_number":21308,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["13 equally efficient machines complete a job in 3 hours. How many hours do 15 such machines require at the same rate?","சமத் திறனுடைய 13 இயந்திரங்கள் வேலையை 3 மணியில் முடிக்கின்றன. அதே வீதத்தில் 15 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["13/5","13/5"],["23/5","23/5"],["8/5","8/5"],["18/5","18/5"]],"answer":0,"explanation":["13×3/(13+2) = 13/5 hours.","13×3/(13+2) = 13/5 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21308,"question_number":21309,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 6 cm and perpendicular height 13 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 6 செமீ; செங்குத்து உயரம் 13 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["79","79"],["78","78"],["77","77"],["80","80"]],"answer":1,"explanation":["6×13 = 78.","6×13 = 78."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21309,"question_number":21310,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 6 cm and 26 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 6 செமீ, 26 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["78","78"],["79","79"],["80","80"],["77","77"]],"answer":0,"explanation":["½×6×26 = 78 cm².","½×6×26 = 78 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21310,"question_number":21311,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 6 m and 32 m, and height 13 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 6 மீ, 32 மீ; உயரம் 13 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["247","247"],["248","248"],["246","246"],["249","249"]],"answer":0,"explanation":["½×(6+32)×13 = 247.","½×(6+32)×13 = 247."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21311,"question_number":21312,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 21 cm makes 13 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","21 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 13 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["1715","1715"],["1717","1717"],["1716","1716"],["1718","1718"]],"answer":2,"explanation":["13×2×22/7×21 = 1716.","13×2×22/7×21 = 1716."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21312,"question_number":21313,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 13 circular mats, each of radius 21 cm. Find their total area in cm², using π=22/7.","தலா 21 செமீ ஆரமுள்ள 13 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["18018","18018"],["18020","18020"],["18017","18017"],["18019","18019"]],"answer":0,"explanation":["13×22/7×21² = 18018.","13×22/7×21² = 18018."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21313,"question_number":21314,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 26° and 56°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 26°, 56°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["100","100"],["99","99"],["98","98"],["97","97"]],"answer":2,"explanation":["180−26−56 = 98°.","180−26−56 = 98°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21314,"question_number":21315,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 53°. One remote interior angle is 33°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 53°. அதற்கான ஓர் எதிர் உட்கோணம் 33°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["19","19"],["21","21"],["22","22"],["20","20"]],"answer":3,"explanation":["53 − 33 = 20°.","53 − 33 = 20°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21315,"question_number":21316,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 3, 16, 29, 42, 55.","3, 16, 29, 42, 55 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["28","28"],["30","30"],["31","31"],["29","29"]],"answer":3,"explanation":["Sum/5 = 145/5 = 29.","கூடுதல்/5 = 145/5 = 29."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21316,"question_number":21317,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 68, 3, 29, 94, 16.","வரிசைப்படுத்தி இடைநிலை காண்க: 68, 3, 29, 94, 16."],"options":[["30","30"],["29","29"],["31","31"],["28","28"]],"answer":1,"explanation":["Sorted: 3, 16, 29, 68, 94; middle value = 29.","வரிசை: 3, 16, 29, 68, 94; நடு மதிப்பு = 29."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21317,"question_number":21318,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 3, 16, 3, 29, 42, 3?","3, 16, 3, 29, 42, 3 தரவுகளின் முகடு எது?"],"options":[["2","2"],["5","5"],["4","4"],["3","3"]],"answer":3,"explanation":["3 occurs 3 times; each other value occurs once.","3 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21318,"question_number":21319,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 3 hours and another in 13 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 3 மணியிலும் மற்றொன்று 13 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["71/16","71/16"],["55/16","55/16"],["39/16","39/16"],["23/16","23/16"]],"answer":2,"explanation":["Combined hourly rate = 1/3+1/13; time = 39/16 = 39/16 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/3+1/13; காலம் = 39/16 = 39/16 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21319,"question_number":21320,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −3/13. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −3/13. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["-10/13","-10/13"],["16/13","16/13"],["29/13","29/13"],["3/13","3/13"]],"answer":3,"explanation":["−3/13 + 3/13 = 0. Simplified additive inverse: 3/13.","−3/13 + 3/13 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 3/13."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21320,"question_number":21321,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 3 and 13?","3 மற்றும் 13 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["9","9"],["10","10"],["7","7"],["8","8"]],"answer":3,"explanation":["(3+13)/2 = 8.","(3+13)/2 = 8."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21321,"question_number":21322,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 4/13 + 1/14.","கூட்டிச் சுருக்குக: 4/13 + 1/14."],"options":[["-113/182","-113/182"],["251/182","251/182"],["433/182","433/182"],["69/182","69/182"]],"answer":3,"explanation":["[4×14 + 13]/[13×14] = 69/182.","[4×14 + 13]/[13×14] = 69/182."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21322,"question_number":21323,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 4/13 − 1/14.","கழித்துச் சுருக்குக: 4/13 − 1/14."],"options":[["225/182","225/182"],["407/182","407/182"],["-139/182","-139/182"],["43/182","43/182"]],"answer":3,"explanation":["[4×14 − 13]/[13×14] = 43/182.","[4×14 − 13]/[13×14] = 43/182."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21323,"question_number":21324,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−4/13) × (14/5).","(−4/13) × (14/5) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-121/65","-121/65"],["9/65","9/65"],["-56/65","-56/65"],["74/65","74/65"]],"answer":2,"explanation":["−56/65 = -56/65.","−56/65 = -56/65."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21324,"question_number":21325,"practice_set":853},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (4/13) ÷ (5/14) in simplest form.","(4/13) ÷ (5/14) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["121/65","121/65"],["56/65","56/65"],["-9/65","-9/65"],["186/65","186/65"]],"answer":1,"explanation":["(4/13) × (14/5) = 56/65.","(4/13) × (14/5) = 56/65."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21325,"question_number":21326,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 5.3 and 0.13.","5.3 மற்றும் 0.13 தசம எண்களைக் கூட்டுக."],"options":[["5.43","5.43"],["5.42","5.42"],["5.44","5.44"],["5.53","5.53"]],"answer":0,"explanation":["5.3 + 0.13 = 5.43.","5.3 + 0.13 = 5.43."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21326,"question_number":21327,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 13x + 4 = 225.","13x + 4 = 225 சமன்பாட்டைத் தீர்க்க."],"options":[["16","16"],["19","19"],["18","18"],["17","17"]],"answer":3,"explanation":["x = (225 − 4)/13 = 17.","x = (225 − 4)/13 = 17."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21327,"question_number":21328,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 4 and y = 13, find (x+y)² − x² − y², then divide by 2.","x = 4, y = 13 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["53","53"],["54","54"],["51","51"],["52","52"]],"answer":3,"explanation":["[(x+y)²−x²−y²]/2 = xy = 4×13 = 52.","[(x+y)²−x²−y²]/2 = xy = 4×13 = 52."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21328,"question_number":21329,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 4, y = 13.","x = 4, y = 13 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["288","288"],["289","289"],["291","291"],["290","290"]],"answer":1,"explanation":["(x+y)² = (4+13)² = 289.","(x+y)² = (4+13)² = 289."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21329,"question_number":21330,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^4 × 7^13 = 7^m, what is m?","7^4 × 7^13 = 7^m எனில் m என்ன?"],"options":[["17","17"],["19","19"],["18","18"],["16","16"]],"answer":0,"explanation":["m = 4 + 13 = 17.","m = 4 + 13 = 17."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21330,"question_number":21331,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^4)^13 = 2^m, find m.","(2^4)^13 = 2^m எனில் m காண்க."],"options":[["52","52"],["53","53"],["51","51"],["54","54"]],"answer":0,"explanation":["m = 4 × 13 = 52.","m = 4 × 13 = 52."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21331,"question_number":21332,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 65% of ₹80.","₹80 இன் 65% காண்க."],"options":[["51","51"],["53","53"],["54","54"],["52","52"]],"answer":3,"explanation":["80×65/100 = 52.","80×65/100 = 52."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21332,"question_number":21333,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹400 has a 65% discount. What is the sale price in rupees?","₹400 குறித்த விலையுள்ள பைக்கு 65% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["141","141"],["139","139"],["142","142"],["140","140"]],"answer":3,"explanation":["400 × (100−65)/100 = 140.","400 × (100−65)/100 = 140."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21333,"question_number":21334,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹400 sells for ₹660. Find the profit percentage.","₹400 க்கு வாங்கிய பொருள் ₹660 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["65","65"],["66","66"],["67","67"],["64","64"]],"answer":0,"explanation":["(660−400)/400×100 = 65%.","(660−400)/400×100 = 65%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21334,"question_number":21335,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹4000 at 13% per year for 3 years.","₹4000 க்கு ஆண்டுக்கு 13% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1559","1559"],["1562","1562"],["1560","1560"],["1561","1561"]],"answer":2,"explanation":["4000×13×3/100 = 1560.","4000×13×3/100 = 1560."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21335,"question_number":21336,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹40000 at 13% a year for 2 years, compounded annually.","₹40000 க்கு ஆண்டுக்கு 13% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["11076","11076"],["11077","11077"],["11078","11078"],["11075","11075"]],"answer":0,"explanation":["40000×[(1+13/100)²−1] = 11076.","40000×[(1+13/100)²−1] = 11076."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21336,"question_number":21337,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["13 metres of cloth cost ₹40. At the same rate, what is the cost of 16 metres in rupees?","13 மீ துணியின் விலை ₹40. அதே வீதத்தில் 16 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["666/13","666/13"],["640/13","640/13"],["627/13","627/13"],["653/13","653/13"]],"answer":1,"explanation":["40/13×16 = 640/13.","40/13×16 = 640/13."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21337,"question_number":21338,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["13 equally efficient machines complete a job in 4 hours. How many hours do 15 such machines require at the same rate?","சமத் திறனுடைய 13 இயந்திரங்கள் வேலையை 4 மணியில் முடிக்கின்றன. அதே வீதத்தில் 15 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["52/15","52/15"],["82/15","82/15"],["67/15","67/15"],["37/15","37/15"]],"answer":0,"explanation":["13×4/(13+2) = 52/15 hours.","13×4/(13+2) = 52/15 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21338,"question_number":21339,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 8 cm and perpendicular height 13 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 8 செமீ; செங்குத்து உயரம் 13 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["105","105"],["104","104"],["103","103"],["106","106"]],"answer":1,"explanation":["8×13 = 104.","8×13 = 104."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21339,"question_number":21340,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 8 cm and 26 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 8 செமீ, 26 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["103","103"],["105","105"],["104","104"],["106","106"]],"answer":2,"explanation":["½×8×26 = 104 cm².","½×8×26 = 104 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21340,"question_number":21341,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 8 m and 34 m, and height 13 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 8 மீ, 34 மீ; உயரம் 13 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["272","272"],["275","275"],["274","274"],["273","273"]],"answer":3,"explanation":["½×(8+34)×13 = 273.","½×(8+34)×13 = 273."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21341,"question_number":21342,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 28 cm makes 13 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","28 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 13 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["2288","2288"],["2287","2287"],["2289","2289"],["2290","2290"]],"answer":0,"explanation":["13×2×22/7×28 = 2288.","13×2×22/7×28 = 2288."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21342,"question_number":21343,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 13 circular mats, each of radius 28 cm. Find their total area in cm², using π=22/7.","தலா 28 செமீ ஆரமுள்ள 13 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["32032","32032"],["32031","32031"],["32033","32033"],["32034","32034"]],"answer":0,"explanation":["13×22/7×28² = 32032.","13×22/7×28² = 32032."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21343,"question_number":21344,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 28° and 56°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 28°, 56°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["96","96"],["98","98"],["97","97"],["95","95"]],"answer":0,"explanation":["180−28−56 = 96°.","180−28−56 = 96°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21344,"question_number":21345,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 54°. One remote interior angle is 33°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 54°. அதற்கான ஓர் எதிர் உட்கோணம் 33°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["22","22"],["21","21"],["20","20"],["23","23"]],"answer":1,"explanation":["54 − 33 = 21°.","54 − 33 = 21°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21345,"question_number":21346,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 4, 17, 30, 43, 56.","4, 17, 30, 43, 56 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["29","29"],["30","30"],["32","32"],["31","31"]],"answer":1,"explanation":["Sum/5 = 150/5 = 30.","கூடுதல்/5 = 150/5 = 30."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21346,"question_number":21347,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 69, 4, 30, 95, 17.","வரிசைப்படுத்தி இடைநிலை காண்க: 69, 4, 30, 95, 17."],"options":[["30","30"],["32","32"],["29","29"],["31","31"]],"answer":0,"explanation":["Sorted: 4, 17, 30, 69, 95; middle value = 30.","வரிசை: 4, 17, 30, 69, 95; நடு மதிப்பு = 30."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21347,"question_number":21348,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 4, 17, 4, 30, 43, 4?","4, 17, 4, 30, 43, 4 தரவுகளின் முகடு எது?"],"options":[["4","4"],["6","6"],["3","3"],["5","5"]],"answer":0,"explanation":["4 occurs 3 times; each other value occurs once.","4 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21348,"question_number":21349,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 4 hours and another in 13 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 4 மணியிலும் மற்றொன்று 13 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["69/17","69/17"],["86/17","86/17"],["52/17","52/17"],["35/17","35/17"]],"answer":2,"explanation":["Combined hourly rate = 1/4+1/13; time = 52/17 = 52/17 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/4+1/13; காலம் = 52/17 = 52/17 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21349,"question_number":21350,"practice_set":854},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −4/13. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −4/13. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["4/13","4/13"],["30/13","30/13"],["-9/13","-9/13"],["17/13","17/13"]],"answer":0,"explanation":["−4/13 + 4/13 = 0. Simplified additive inverse: 4/13.","−4/13 + 4/13 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 4/13."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21350,"question_number":21351,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 4 and 13?","4 மற்றும் 13 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["21/2","21/2"],["19/2","19/2"],["15/2","15/2"],["17/2","17/2"]],"answer":3,"explanation":["(4+13)/2 = 17/2.","(4+13)/2 = 17/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21351,"question_number":21352,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 5/13 + 1/14.","கூட்டிச் சுருக்குக: 5/13 + 1/14."],"options":[["-99/182","-99/182"],["447/182","447/182"],["265/182","265/182"],["83/182","83/182"]],"answer":3,"explanation":["[5×14 + 13]/[13×14] = 83/182.","[5×14 + 13]/[13×14] = 83/182."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21352,"question_number":21353,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 5/13 − 1/14.","கழித்துச் சுருக்குக: 5/13 − 1/14."],"options":[["421/182","421/182"],["-125/182","-125/182"],["239/182","239/182"],["57/182","57/182"]],"answer":3,"explanation":["[5×14 − 13]/[13×14] = 57/182.","[5×14 − 13]/[13×14] = 57/182."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21353,"question_number":21354,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−5/13) × (14/6).","(−5/13) × (14/6) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-35/39","-35/39"],["43/39","43/39"],["-74/39","-74/39"],["4/39","4/39"]],"answer":0,"explanation":["−70/78 = -35/39.","−70/78 = -35/39."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21354,"question_number":21355,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (5/13) ÷ (6/14) in simplest form.","(5/13) ÷ (6/14) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["113/39","113/39"],["-4/39","-4/39"],["35/39","35/39"],["74/39","74/39"]],"answer":2,"explanation":["(5/13) × (14/6) = 35/39.","(5/13) × (14/6) = 35/39."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21355,"question_number":21356,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 6.3 and 0.13.","6.3 மற்றும் 0.13 தசம எண்களைக் கூட்டுக."],"options":[["6.44","6.44"],["6.43","6.43"],["6.53","6.53"],["6.42","6.42"]],"answer":1,"explanation":["6.3 + 0.13 = 6.43.","6.3 + 0.13 = 6.43."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21356,"question_number":21357,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 13x + 5 = 239.","13x + 5 = 239 சமன்பாட்டைத் தீர்க்க."],"options":[["18","18"],["17","17"],["19","19"],["20","20"]],"answer":0,"explanation":["x = (239 − 5)/13 = 18.","x = (239 − 5)/13 = 18."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21357,"question_number":21358,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 5 and y = 13, find (x+y)² − x² − y², then divide by 2.","x = 5, y = 13 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["65","65"],["64","64"],["66","66"],["67","67"]],"answer":0,"explanation":["[(x+y)²−x²−y²]/2 = xy = 5×13 = 65.","[(x+y)²−x²−y²]/2 = xy = 5×13 = 65."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21358,"question_number":21359,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 5, y = 13.","x = 5, y = 13 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["326","326"],["323","323"],["324","324"],["325","325"]],"answer":2,"explanation":["(x+y)² = (5+13)² = 324.","(x+y)² = (5+13)² = 324."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21359,"question_number":21360,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^5 × 7^13 = 7^m, what is m?","7^5 × 7^13 = 7^m எனில் m என்ன?"],"options":[["18","18"],["17","17"],["20","20"],["19","19"]],"answer":0,"explanation":["m = 5 + 13 = 18.","m = 5 + 13 = 18."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21360,"question_number":21361,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^5)^13 = 2^m, find m.","(2^5)^13 = 2^m எனில் m காண்க."],"options":[["66","66"],["64","64"],["65","65"],["67","67"]],"answer":2,"explanation":["m = 5 × 13 = 65.","m = 5 × 13 = 65."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21361,"question_number":21362,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 65% of ₹100.","₹100 இன் 65% காண்க."],"options":[["66","66"],["64","64"],["67","67"],["65","65"]],"answer":3,"explanation":["100×65/100 = 65.","100×65/100 = 65."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21362,"question_number":21363,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹500 has a 65% discount. What is the sale price in rupees?","₹500 குறித்த விலையுள்ள பைக்கு 65% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["176","176"],["177","177"],["174","174"],["175","175"]],"answer":3,"explanation":["500 × (100−65)/100 = 175.","500 × (100−65)/100 = 175."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21363,"question_number":21364,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹500 sells for ₹825. Find the profit percentage.","₹500 க்கு வாங்கிய பொருள் ₹825 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["65","65"],["66","66"],["67","67"],["64","64"]],"answer":0,"explanation":["(825−500)/500×100 = 65%.","(825−500)/500×100 = 65%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21364,"question_number":21365,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹5000 at 13% per year for 3 years.","₹5000 க்கு ஆண்டுக்கு 13% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1952","1952"],["1950","1950"],["1951","1951"],["1949","1949"]],"answer":1,"explanation":["5000×13×3/100 = 1950.","5000×13×3/100 = 1950."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21365,"question_number":21366,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹50000 at 13% a year for 2 years, compounded annually.","₹50000 க்கு ஆண்டுக்கு 13% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["13847","13847"],["13846","13846"],["13845","13845"],["13844","13844"]],"answer":2,"explanation":["50000×[(1+13/100)²−1] = 13845.","50000×[(1+13/100)²−1] = 13845."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21366,"question_number":21367,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["13 metres of cloth cost ₹50. At the same rate, what is the cost of 16 metres in rupees?","13 மீ துணியின் விலை ₹50. அதே வீதத்தில் 16 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["787/13","787/13"],["813/13","813/13"],["800/13","800/13"],["826/13","826/13"]],"answer":2,"explanation":["50/13×16 = 800/13.","50/13×16 = 800/13."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21367,"question_number":21368,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["13 equally efficient machines complete a job in 5 hours. How many hours do 15 such machines require at the same rate?","சமத் திறனுடைய 13 இயந்திரங்கள் வேலையை 5 மணியில் முடிக்கின்றன. அதே வீதத்தில் 15 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["19/3","19/3"],["10/3","10/3"],["13/3","13/3"],["16/3","16/3"]],"answer":2,"explanation":["13×5/(13+2) = 13/3 hours.","13×5/(13+2) = 13/3 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21368,"question_number":21369,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 10 cm and perpendicular height 13 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 10 செமீ; செங்குத்து உயரம் 13 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["132","132"],["130","130"],["129","129"],["131","131"]],"answer":1,"explanation":["10×13 = 130.","10×13 = 130."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21369,"question_number":21370,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 10 cm and 26 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 10 செமீ, 26 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["129","129"],["130","130"],["131","131"],["132","132"]],"answer":1,"explanation":["½×10×26 = 130 cm².","½×10×26 = 130 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21370,"question_number":21371,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 10 m and 36 m, and height 13 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 10 மீ, 36 மீ; உயரம் 13 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["300","300"],["301","301"],["299","299"],["298","298"]],"answer":2,"explanation":["½×(10+36)×13 = 299.","½×(10+36)×13 = 299."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21371,"question_number":21372,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 35 cm makes 13 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","35 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 13 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["2862","2862"],["2860","2860"],["2861","2861"],["2859","2859"]],"answer":1,"explanation":["13×2×22/7×35 = 2860.","13×2×22/7×35 = 2860."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21372,"question_number":21373,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 13 circular mats, each of radius 35 cm. Find their total area in cm², using π=22/7.","தலா 35 செமீ ஆரமுள்ள 13 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["50049","50049"],["50052","50052"],["50050","50050"],["50051","50051"]],"answer":2,"explanation":["13×22/7×35² = 50050.","13×22/7×35² = 50050."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21373,"question_number":21374,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 30° and 56°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 30°, 56°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["96","96"],["93","93"],["94","94"],["95","95"]],"answer":2,"explanation":["180−30−56 = 94°.","180−30−56 = 94°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21374,"question_number":21375,"practice_set":855},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 55°. One remote interior angle is 33°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 55°. அதற்கான ஓர் எதிர் உட்கோணம் 33°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["21","21"],["24","24"],["22","22"],["23","23"]],"answer":2,"explanation":["55 − 33 = 22°.","55 − 33 = 22°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21375,"question_number":21376,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 5, 18, 31, 44, 57.","5, 18, 31, 44, 57 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["30","30"],["31","31"],["32","32"],["33","33"]],"answer":1,"explanation":["Sum/5 = 155/5 = 31.","கூடுதல்/5 = 155/5 = 31."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21376,"question_number":21377,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 70, 5, 31, 96, 18.","வரிசைப்படுத்தி இடைநிலை காண்க: 70, 5, 31, 96, 18."],"options":[["32","32"],["33","33"],["30","30"],["31","31"]],"answer":3,"explanation":["Sorted: 5, 18, 31, 70, 96; middle value = 31.","வரிசை: 5, 18, 31, 70, 96; நடு மதிப்பு = 31."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21377,"question_number":21378,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 5, 18, 5, 31, 44, 5?","5, 18, 5, 31, 44, 5 தரவுகளின் முகடு எது?"],"options":[["5","5"],["7","7"],["4","4"],["6","6"]],"answer":0,"explanation":["5 occurs 3 times; each other value occurs once.","5 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21378,"question_number":21379,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 5 hours and another in 13 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 5 மணியிலும் மற்றொன்று 13 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["65/18","65/18"],["83/18","83/18"],["47/18","47/18"],["101/18","101/18"]],"answer":0,"explanation":["Combined hourly rate = 1/5+1/13; time = 65/18 = 65/18 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/5+1/13; காலம் = 65/18 = 65/18 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21379,"question_number":21380,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −5/13. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −5/13. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["5/13","5/13"],["-8/13","-8/13"],["31/13","31/13"],["18/13","18/13"]],"answer":0,"explanation":["−5/13 + 5/13 = 0. Simplified additive inverse: 5/13.","−5/13 + 5/13 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 5/13."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21380,"question_number":21381,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 5 and 13?","5 மற்றும் 13 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["11","11"],["8","8"],["9","9"],["10","10"]],"answer":2,"explanation":["(5+13)/2 = 9.","(5+13)/2 = 9."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21381,"question_number":21382,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 6/13 + 1/14.","கூட்டிச் சுருக்குக: 6/13 + 1/14."],"options":[["279/182","279/182"],["461/182","461/182"],["-85/182","-85/182"],["97/182","97/182"]],"answer":3,"explanation":["[6×14 + 13]/[13×14] = 97/182.","[6×14 + 13]/[13×14] = 97/182."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21382,"question_number":21383,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 6/13 − 1/14.","கழித்துச் சுருக்குக: 6/13 − 1/14."],"options":[["-111/182","-111/182"],["71/182","71/182"],["253/182","253/182"],["435/182","435/182"]],"answer":1,"explanation":["[6×14 − 13]/[13×14] = 71/182.","[6×14 − 13]/[13×14] = 71/182."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21383,"question_number":21384,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−6/13) × (14/7).","(−6/13) × (14/7) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-25/13","-25/13"],["-12/13","-12/13"],["1/13","1/13"],["14/13","14/13"]],"answer":1,"explanation":["−84/91 = -12/13.","−84/91 = -12/13."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21384,"question_number":21385,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (6/13) ÷ (7/14) in simplest form.","(6/13) ÷ (7/14) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["38/13","38/13"],["12/13","12/13"],["25/13","25/13"],["-1/13","-1/13"]],"answer":1,"explanation":["(6/13) × (14/7) = 12/13.","(6/13) × (14/7) = 12/13."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21385,"question_number":21386,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 7.3 and 0.13.","7.3 மற்றும் 0.13 தசம எண்களைக் கூட்டுக."],"options":[["7.53","7.53"],["7.44","7.44"],["7.42","7.42"],["7.43","7.43"]],"answer":3,"explanation":["7.3 + 0.13 = 7.43.","7.3 + 0.13 = 7.43."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21386,"question_number":21387,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 13x + 6 = 253.","13x + 6 = 253 சமன்பாட்டைத் தீர்க்க."],"options":[["18","18"],["19","19"],["21","21"],["20","20"]],"answer":1,"explanation":["x = (253 − 6)/13 = 19.","x = (253 − 6)/13 = 19."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21387,"question_number":21388,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 6 and y = 13, find (x+y)² − x² − y², then divide by 2.","x = 6, y = 13 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["80","80"],["78","78"],["79","79"],["77","77"]],"answer":1,"explanation":["[(x+y)²−x²−y²]/2 = xy = 6×13 = 78.","[(x+y)²−x²−y²]/2 = xy = 6×13 = 78."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21388,"question_number":21389,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 6, y = 13.","x = 6, y = 13 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["361","361"],["360","360"],["362","362"],["363","363"]],"answer":0,"explanation":["(x+y)² = (6+13)² = 361.","(x+y)² = (6+13)² = 361."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21389,"question_number":21390,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^6 × 7^13 = 7^m, what is m?","7^6 × 7^13 = 7^m எனில் m என்ன?"],"options":[["21","21"],["20","20"],["19","19"],["18","18"]],"answer":2,"explanation":["m = 6 + 13 = 19.","m = 6 + 13 = 19."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21390,"question_number":21391,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^6)^13 = 2^m, find m.","(2^6)^13 = 2^m எனில் m காண்க."],"options":[["78","78"],["79","79"],["80","80"],["77","77"]],"answer":0,"explanation":["m = 6 × 13 = 78.","m = 6 × 13 = 78."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21391,"question_number":21392,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 65% of ₹120.","₹120 இன் 65% காண்க."],"options":[["80","80"],["77","77"],["79","79"],["78","78"]],"answer":3,"explanation":["120×65/100 = 78.","120×65/100 = 78."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21392,"question_number":21393,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹600 has a 65% discount. What is the sale price in rupees?","₹600 குறித்த விலையுள்ள பைக்கு 65% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["209","209"],["210","210"],["211","211"],["212","212"]],"answer":1,"explanation":["600 × (100−65)/100 = 210.","600 × (100−65)/100 = 210."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21393,"question_number":21394,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹600 sells for ₹990. Find the profit percentage.","₹600 க்கு வாங்கிய பொருள் ₹990 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["65","65"],["67","67"],["66","66"],["64","64"]],"answer":0,"explanation":["(990−600)/600×100 = 65%.","(990−600)/600×100 = 65%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21394,"question_number":21395,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹6000 at 13% per year for 3 years.","₹6000 க்கு ஆண்டுக்கு 13% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2340","2340"],["2339","2339"],["2341","2341"],["2342","2342"]],"answer":0,"explanation":["6000×13×3/100 = 2340.","6000×13×3/100 = 2340."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21395,"question_number":21396,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹60000 at 13% a year for 2 years, compounded annually.","₹60000 க்கு ஆண்டுக்கு 13% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["16613","16613"],["16614","16614"],["16615","16615"],["16616","16616"]],"answer":1,"explanation":["60000×[(1+13/100)²−1] = 16614.","60000×[(1+13/100)²−1] = 16614."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21396,"question_number":21397,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["13 metres of cloth cost ₹60. At the same rate, what is the cost of 16 metres in rupees?","13 மீ துணியின் விலை ₹60. அதே வீதத்தில் 16 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["947/13","947/13"],["986/13","986/13"],["960/13","960/13"],["973/13","973/13"]],"answer":2,"explanation":["60/13×16 = 960/13.","60/13×16 = 960/13."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21397,"question_number":21398,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["13 equally efficient machines complete a job in 6 hours. How many hours do 15 such machines require at the same rate?","சமத் திறனுடைய 13 இயந்திரங்கள் வேலையை 6 மணியில் முடிக்கின்றன. அதே வீதத்தில் 15 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["21/5","21/5"],["26/5","26/5"],["31/5","31/5"],["36/5","36/5"]],"answer":1,"explanation":["13×6/(13+2) = 26/5 hours.","13×6/(13+2) = 26/5 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21398,"question_number":21399,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 12 cm and perpendicular height 13 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 12 செமீ; செங்குத்து உயரம் 13 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["155","155"],["158","158"],["157","157"],["156","156"]],"answer":3,"explanation":["12×13 = 156.","12×13 = 156."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21399,"question_number":21400,"practice_set":856},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 12 cm and 26 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 12 செமீ, 26 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["158","158"],["157","157"],["155","155"],["156","156"]],"answer":3,"explanation":["½×12×26 = 156 cm².","½×12×26 = 156 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21400,"question_number":21401,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 12 m and 38 m, and height 13 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 12 மீ, 38 மீ; உயரம் 13 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["326","326"],["324","324"],["325","325"],["327","327"]],"answer":2,"explanation":["½×(12+38)×13 = 325.","½×(12+38)×13 = 325."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21401,"question_number":21402,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 42 cm makes 13 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","42 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 13 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["3434","3434"],["3433","3433"],["3432","3432"],["3431","3431"]],"answer":2,"explanation":["13×2×22/7×42 = 3432.","13×2×22/7×42 = 3432."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21402,"question_number":21403,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 13 circular mats, each of radius 42 cm. Find their total area in cm², using π=22/7.","தலா 42 செமீ ஆரமுள்ள 13 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["72073","72073"],["72071","72071"],["72072","72072"],["72074","72074"]],"answer":2,"explanation":["13×22/7×42² = 72072.","13×22/7×42² = 72072."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21403,"question_number":21404,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 32° and 56°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 32°, 56°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["91","91"],["94","94"],["93","93"],["92","92"]],"answer":3,"explanation":["180−32−56 = 92°.","180−32−56 = 92°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21404,"question_number":21405,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 56°. One remote interior angle is 33°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 56°. அதற்கான ஓர் எதிர் உட்கோணம் 33°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["24","24"],["22","22"],["25","25"],["23","23"]],"answer":3,"explanation":["56 − 33 = 23°.","56 − 33 = 23°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21405,"question_number":21406,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 6, 19, 32, 45, 58.","6, 19, 32, 45, 58 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["32","32"],["31","31"],["33","33"],["34","34"]],"answer":0,"explanation":["Sum/5 = 160/5 = 32.","கூடுதல்/5 = 160/5 = 32."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21406,"question_number":21407,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 71, 6, 32, 97, 19.","வரிசைப்படுத்தி இடைநிலை காண்க: 71, 6, 32, 97, 19."],"options":[["32","32"],["31","31"],["34","34"],["33","33"]],"answer":0,"explanation":["Sorted: 6, 19, 32, 71, 97; middle value = 32.","வரிசை: 6, 19, 32, 71, 97; நடு மதிப்பு = 32."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21407,"question_number":21408,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 6, 19, 6, 32, 45, 6?","6, 19, 6, 32, 45, 6 தரவுகளின் முகடு எது?"],"options":[["7","7"],["8","8"],["5","5"],["6","6"]],"answer":3,"explanation":["6 occurs 3 times; each other value occurs once.","6 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21408,"question_number":21409,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 6 hours and another in 13 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 6 மணியிலும் மற்றொன்று 13 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["97/19","97/19"],["59/19","59/19"],["78/19","78/19"],["116/19","116/19"]],"answer":2,"explanation":["Combined hourly rate = 1/6+1/13; time = 78/19 = 78/19 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/6+1/13; காலம் = 78/19 = 78/19 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21409,"question_number":21410,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −6/13. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −6/13. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["6/13","6/13"],["-7/13","-7/13"],["19/13","19/13"],["32/13","32/13"]],"answer":0,"explanation":["−6/13 + 6/13 = 0. Simplified additive inverse: 6/13.","−6/13 + 6/13 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 6/13."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21410,"question_number":21411,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 6 and 13?","6 மற்றும் 13 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["23/2","23/2"],["17/2","17/2"],["19/2","19/2"],["21/2","21/2"]],"answer":2,"explanation":["(6+13)/2 = 19/2.","(6+13)/2 = 19/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21411,"question_number":21412,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 7/13 + 1/14.","கூட்டிச் சுருக்குக: 7/13 + 1/14."],"options":[["293/182","293/182"],["111/182","111/182"],["475/182","475/182"],["-71/182","-71/182"]],"answer":1,"explanation":["[7×14 + 13]/[13×14] = 111/182.","[7×14 + 13]/[13×14] = 111/182."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21412,"question_number":21413,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 7/13 − 1/14.","கழித்துச் சுருக்குக: 7/13 − 1/14."],"options":[["267/182","267/182"],["85/182","85/182"],["-97/182","-97/182"],["449/182","449/182"]],"answer":1,"explanation":["[7×14 − 13]/[13×14] = 85/182.","[7×14 − 13]/[13×14] = 85/182."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21413,"question_number":21414,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−7/13) × (14/8).","(−7/13) × (14/8) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-49/52","-49/52"],["3/52","3/52"],["-101/52","-101/52"],["55/52","55/52"]],"answer":0,"explanation":["−98/104 = -49/52.","−98/104 = -49/52."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21414,"question_number":21415,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (7/13) ÷ (8/14) in simplest form.","(7/13) ÷ (8/14) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["153/52","153/52"],["-3/52","-3/52"],["101/52","101/52"],["49/52","49/52"]],"answer":3,"explanation":["(7/13) × (14/8) = 49/52.","(7/13) × (14/8) = 49/52."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21415,"question_number":21416,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 8.3 and 0.13.","8.3 மற்றும் 0.13 தசம எண்களைக் கூட்டுக."],"options":[["8.53","8.53"],["8.44","8.44"],["8.43","8.43"],["8.42","8.42"]],"answer":2,"explanation":["8.3 + 0.13 = 8.43.","8.3 + 0.13 = 8.43."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21416,"question_number":21417,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 13x + 7 = 267.","13x + 7 = 267 சமன்பாட்டைத் தீர்க்க."],"options":[["21","21"],["20","20"],["22","22"],["19","19"]],"answer":1,"explanation":["x = (267 − 7)/13 = 20.","x = (267 − 7)/13 = 20."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21417,"question_number":21418,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 7 and y = 13, find (x+y)² − x² − y², then divide by 2.","x = 7, y = 13 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["91","91"],["92","92"],["90","90"],["93","93"]],"answer":0,"explanation":["[(x+y)²−x²−y²]/2 = xy = 7×13 = 91.","[(x+y)²−x²−y²]/2 = xy = 7×13 = 91."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21418,"question_number":21419,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 7, y = 13.","x = 7, y = 13 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["400","400"],["399","399"],["402","402"],["401","401"]],"answer":0,"explanation":["(x+y)² = (7+13)² = 400.","(x+y)² = (7+13)² = 400."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21419,"question_number":21420,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^7 × 7^13 = 7^m, what is m?","7^7 × 7^13 = 7^m எனில் m என்ன?"],"options":[["21","21"],["22","22"],["20","20"],["19","19"]],"answer":2,"explanation":["m = 7 + 13 = 20.","m = 7 + 13 = 20."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21420,"question_number":21421,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^7)^13 = 2^m, find m.","(2^7)^13 = 2^m எனில் m காண்க."],"options":[["91","91"],["92","92"],["93","93"],["90","90"]],"answer":0,"explanation":["m = 7 × 13 = 91.","m = 7 × 13 = 91."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21421,"question_number":21422,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 65% of ₹140.","₹140 இன் 65% காண்க."],"options":[["90","90"],["93","93"],["92","92"],["91","91"]],"answer":3,"explanation":["140×65/100 = 91.","140×65/100 = 91."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21422,"question_number":21423,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹700 has a 65% discount. What is the sale price in rupees?","₹700 குறித்த விலையுள்ள பைக்கு 65% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["244","244"],["247","247"],["245","245"],["246","246"]],"answer":2,"explanation":["700 × (100−65)/100 = 245.","700 × (100−65)/100 = 245."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21423,"question_number":21424,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹700 sells for ₹1155. Find the profit percentage.","₹700 க்கு வாங்கிய பொருள் ₹1155 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["64","64"],["65","65"],["67","67"],["66","66"]],"answer":1,"explanation":["(1155−700)/700×100 = 65%.","(1155−700)/700×100 = 65%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21424,"question_number":21425,"practice_set":857},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹7000 at 13% per year for 3 years.","₹7000 க்கு ஆண்டுக்கு 13% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2730","2730"],["2732","2732"],["2731","2731"],["2729","2729"]],"answer":0,"explanation":["7000×13×3/100 = 2730.","7000×13×3/100 = 2730."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21425,"question_number":21426,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹70000 at 13% a year for 2 years, compounded annually.","₹70000 க்கு ஆண்டுக்கு 13% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["19383","19383"],["19384","19384"],["19382","19382"],["19385","19385"]],"answer":0,"explanation":["70000×[(1+13/100)²−1] = 19383.","70000×[(1+13/100)²−1] = 19383."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21426,"question_number":21427,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["13 metres of cloth cost ₹70. At the same rate, what is the cost of 16 metres in rupees?","13 மீ துணியின் விலை ₹70. அதே வீதத்தில் 16 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["1146/13","1146/13"],["1107/13","1107/13"],["1133/13","1133/13"],["1120/13","1120/13"]],"answer":3,"explanation":["70/13×16 = 1120/13.","70/13×16 = 1120/13."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21427,"question_number":21428,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["13 equally efficient machines complete a job in 7 hours. How many hours do 15 such machines require at the same rate?","சமத் திறனுடைய 13 இயந்திரங்கள் வேலையை 7 மணியில் முடிக்கின்றன. அதே வீதத்தில் 15 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["121/15","121/15"],["106/15","106/15"],["76/15","76/15"],["91/15","91/15"]],"answer":3,"explanation":["13×7/(13+2) = 91/15 hours.","13×7/(13+2) = 91/15 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21428,"question_number":21429,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 14 cm and perpendicular height 13 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 14 செமீ; செங்குத்து உயரம் 13 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["182","182"],["183","183"],["181","181"],["184","184"]],"answer":0,"explanation":["14×13 = 182.","14×13 = 182."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21429,"question_number":21430,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 14 cm and 26 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 14 செமீ, 26 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["182","182"],["184","184"],["181","181"],["183","183"]],"answer":0,"explanation":["½×14×26 = 182 cm².","½×14×26 = 182 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21430,"question_number":21431,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 14 m and 40 m, and height 13 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 14 மீ, 40 மீ; உயரம் 13 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["351","351"],["350","350"],["352","352"],["353","353"]],"answer":0,"explanation":["½×(14+40)×13 = 351.","½×(14+40)×13 = 351."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21431,"question_number":21432,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 49 cm makes 13 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","49 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 13 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["4006","4006"],["4004","4004"],["4003","4003"],["4005","4005"]],"answer":1,"explanation":["13×2×22/7×49 = 4004.","13×2×22/7×49 = 4004."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21432,"question_number":21433,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 13 circular mats, each of radius 49 cm. Find their total area in cm², using π=22/7.","தலா 49 செமீ ஆரமுள்ள 13 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["98100","98100"],["98099","98099"],["98098","98098"],["98097","98097"]],"answer":2,"explanation":["13×22/7×49² = 98098.","13×22/7×49² = 98098."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21433,"question_number":21434,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 34° and 56°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 34°, 56°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["92","92"],["90","90"],["89","89"],["91","91"]],"answer":1,"explanation":["180−34−56 = 90°.","180−34−56 = 90°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21434,"question_number":21435,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 57°. One remote interior angle is 33°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 57°. அதற்கான ஓர் எதிர் உட்கோணம் 33°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["23","23"],["24","24"],["25","25"],["26","26"]],"answer":1,"explanation":["57 − 33 = 24°.","57 − 33 = 24°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21435,"question_number":21436,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 7, 20, 33, 46, 59.","7, 20, 33, 46, 59 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["33","33"],["34","34"],["32","32"],["35","35"]],"answer":0,"explanation":["Sum/5 = 165/5 = 33.","கூடுதல்/5 = 165/5 = 33."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21436,"question_number":21437,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 72, 7, 33, 98, 20.","வரிசைப்படுத்தி இடைநிலை காண்க: 72, 7, 33, 98, 20."],"options":[["34","34"],["32","32"],["33","33"],["35","35"]],"answer":2,"explanation":["Sorted: 7, 20, 33, 72, 98; middle value = 33.","வரிசை: 7, 20, 33, 72, 98; நடு மதிப்பு = 33."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21437,"question_number":21438,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 7, 20, 7, 33, 46, 7?","7, 20, 7, 33, 46, 7 தரவுகளின் முகடு எது?"],"options":[["8","8"],["7","7"],["9","9"],["6","6"]],"answer":1,"explanation":["7 occurs 3 times; each other value occurs once.","7 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21438,"question_number":21439,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 7 hours and another in 13 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 7 மணியிலும் மற்றொன்று 13 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["71/20","71/20"],["131/20","131/20"],["111/20","111/20"],["91/20","91/20"]],"answer":3,"explanation":["Combined hourly rate = 1/7+1/13; time = 91/20 = 91/20 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/7+1/13; காலம் = 91/20 = 91/20 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21439,"question_number":21440,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −7/13. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −7/13. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["7/13","7/13"],["20/13","20/13"],["33/13","33/13"],["-6/13","-6/13"]],"answer":0,"explanation":["−7/13 + 7/13 = 0. Simplified additive inverse: 7/13.","−7/13 + 7/13 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 7/13."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21440,"question_number":21441,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 7 and 13?","7 மற்றும் 13 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["11","11"],["12","12"],["9","9"],["10","10"]],"answer":3,"explanation":["(7+13)/2 = 10.","(7+13)/2 = 10."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21441,"question_number":21442,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 8/13 + 1/14.","கூட்டிச் சுருக்குக: 8/13 + 1/14."],"options":[["307/182","307/182"],["489/182","489/182"],["125/182","125/182"],["-57/182","-57/182"]],"answer":2,"explanation":["[8×14 + 13]/[13×14] = 125/182.","[8×14 + 13]/[13×14] = 125/182."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21442,"question_number":21443,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 8/13 − 1/14.","கழித்துச் சுருக்குக: 8/13 − 1/14."],"options":[["99/182","99/182"],["281/182","281/182"],["463/182","463/182"],["-83/182","-83/182"]],"answer":0,"explanation":["[8×14 − 13]/[13×14] = 99/182.","[8×14 − 13]/[13×14] = 99/182."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21443,"question_number":21444,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−8/13) × (14/9).","(−8/13) × (14/9) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-112/117","-112/117"],["122/117","122/117"],["5/117","5/117"],["-229/117","-229/117"]],"answer":0,"explanation":["−112/117 = -112/117.","−112/117 = -112/117."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21444,"question_number":21445,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (8/13) ÷ (9/14) in simplest form.","(8/13) ÷ (9/14) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["346/117","346/117"],["112/117","112/117"],["229/117","229/117"],["-5/117","-5/117"]],"answer":1,"explanation":["(8/13) × (14/9) = 112/117.","(8/13) × (14/9) = 112/117."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21445,"question_number":21446,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 9.3 and 0.13.","9.3 மற்றும் 0.13 தசம எண்களைக் கூட்டுக."],"options":[["9.44","9.44"],["9.53","9.53"],["9.42","9.42"],["9.43","9.43"]],"answer":3,"explanation":["9.3 + 0.13 = 9.43.","9.3 + 0.13 = 9.43."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21446,"question_number":21447,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 13x + 8 = 281.","13x + 8 = 281 சமன்பாட்டைத் தீர்க்க."],"options":[["22","22"],["21","21"],["23","23"],["20","20"]],"answer":1,"explanation":["x = (281 − 8)/13 = 21.","x = (281 − 8)/13 = 21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21447,"question_number":21448,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 8 and y = 13, find (x+y)² − x² − y², then divide by 2.","x = 8, y = 13 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["103","103"],["106","106"],["104","104"],["105","105"]],"answer":2,"explanation":["[(x+y)²−x²−y²]/2 = xy = 8×13 = 104.","[(x+y)²−x²−y²]/2 = xy = 8×13 = 104."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21448,"question_number":21449,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 8, y = 13.","x = 8, y = 13 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["442","442"],["441","441"],["443","443"],["440","440"]],"answer":1,"explanation":["(x+y)² = (8+13)² = 441.","(x+y)² = (8+13)² = 441."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21449,"question_number":21450,"practice_set":858},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^8 × 7^13 = 7^m, what is m?","7^8 × 7^13 = 7^m எனில் m என்ன?"],"options":[["22","22"],["23","23"],["21","21"],["20","20"]],"answer":2,"explanation":["m = 8 + 13 = 21.","m = 8 + 13 = 21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21450,"question_number":21451,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^8)^13 = 2^m, find m.","(2^8)^13 = 2^m எனில் m காண்க."],"options":[["106","106"],["103","103"],["104","104"],["105","105"]],"answer":2,"explanation":["m = 8 × 13 = 104.","m = 8 × 13 = 104."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21451,"question_number":21452,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 65% of ₹160.","₹160 இன் 65% காண்க."],"options":[["103","103"],["105","105"],["106","106"],["104","104"]],"answer":3,"explanation":["160×65/100 = 104.","160×65/100 = 104."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21452,"question_number":21453,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹800 has a 65% discount. What is the sale price in rupees?","₹800 குறித்த விலையுள்ள பைக்கு 65% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["280","280"],["282","282"],["281","281"],["279","279"]],"answer":0,"explanation":["800 × (100−65)/100 = 280.","800 × (100−65)/100 = 280."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21453,"question_number":21454,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹800 sells for ₹1320. Find the profit percentage.","₹800 க்கு வாங்கிய பொருள் ₹1320 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["66","66"],["67","67"],["65","65"],["64","64"]],"answer":2,"explanation":["(1320−800)/800×100 = 65%.","(1320−800)/800×100 = 65%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21454,"question_number":21455,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹8000 at 13% per year for 3 years.","₹8000 க்கு ஆண்டுக்கு 13% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["3120","3120"],["3121","3121"],["3119","3119"],["3122","3122"]],"answer":0,"explanation":["8000×13×3/100 = 3120.","8000×13×3/100 = 3120."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21455,"question_number":21456,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹80000 at 13% a year for 2 years, compounded annually.","₹80000 க்கு ஆண்டுக்கு 13% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["22151","22151"],["22154","22154"],["22153","22153"],["22152","22152"]],"answer":3,"explanation":["80000×[(1+13/100)²−1] = 22152.","80000×[(1+13/100)²−1] = 22152."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21456,"question_number":21457,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["13 metres of cloth cost ₹80. At the same rate, what is the cost of 16 metres in rupees?","13 மீ துணியின் விலை ₹80. அதே வீதத்தில் 16 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["1280/13","1280/13"],["1293/13","1293/13"],["1267/13","1267/13"],["1306/13","1306/13"]],"answer":0,"explanation":["80/13×16 = 1280/13.","80/13×16 = 1280/13."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21457,"question_number":21458,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["13 equally efficient machines complete a job in 8 hours. How many hours do 15 such machines require at the same rate?","சமத் திறனுடைய 13 இயந்திரங்கள் வேலையை 8 மணியில் முடிக்கின்றன. அதே வீதத்தில் 15 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["119/15","119/15"],["89/15","89/15"],["104/15","104/15"],["134/15","134/15"]],"answer":2,"explanation":["13×8/(13+2) = 104/15 hours.","13×8/(13+2) = 104/15 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21458,"question_number":21459,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 16 cm and perpendicular height 13 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 16 செமீ; செங்குத்து உயரம் 13 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["209","209"],["208","208"],["210","210"],["207","207"]],"answer":1,"explanation":["16×13 = 208.","16×13 = 208."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21459,"question_number":21460,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 16 cm and 26 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 16 செமீ, 26 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["207","207"],["210","210"],["209","209"],["208","208"]],"answer":3,"explanation":["½×16×26 = 208 cm².","½×16×26 = 208 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21460,"question_number":21461,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 16 m and 42 m, and height 13 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 16 மீ, 42 மீ; உயரம் 13 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["377","377"],["376","376"],["378","378"],["379","379"]],"answer":0,"explanation":["½×(16+42)×13 = 377.","½×(16+42)×13 = 377."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21461,"question_number":21462,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 56 cm makes 13 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","56 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 13 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["4578","4578"],["4577","4577"],["4576","4576"],["4575","4575"]],"answer":2,"explanation":["13×2×22/7×56 = 4576.","13×2×22/7×56 = 4576."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21462,"question_number":21463,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 13 circular mats, each of radius 56 cm. Find their total area in cm², using π=22/7.","தலா 56 செமீ ஆரமுள்ள 13 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["128129","128129"],["128130","128130"],["128127","128127"],["128128","128128"]],"answer":3,"explanation":["13×22/7×56² = 128128.","13×22/7×56² = 128128."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21463,"question_number":21464,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 36° and 56°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 36°, 56°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["88","88"],["90","90"],["89","89"],["87","87"]],"answer":0,"explanation":["180−36−56 = 88°.","180−36−56 = 88°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21464,"question_number":21465,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 58°. One remote interior angle is 33°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 58°. அதற்கான ஓர் எதிர் உட்கோணம் 33°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["25","25"],["24","24"],["27","27"],["26","26"]],"answer":0,"explanation":["58 − 33 = 25°.","58 − 33 = 25°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21465,"question_number":21466,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 8, 21, 34, 47, 60.","8, 21, 34, 47, 60 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["35","35"],["36","36"],["34","34"],["33","33"]],"answer":2,"explanation":["Sum/5 = 170/5 = 34.","கூடுதல்/5 = 170/5 = 34."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21466,"question_number":21467,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 73, 8, 34, 99, 21.","வரிசைப்படுத்தி இடைநிலை காண்க: 73, 8, 34, 99, 21."],"options":[["34","34"],["33","33"],["36","36"],["35","35"]],"answer":0,"explanation":["Sorted: 8, 21, 34, 73, 99; middle value = 34.","வரிசை: 8, 21, 34, 73, 99; நடு மதிப்பு = 34."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21467,"question_number":21468,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 8, 21, 8, 34, 47, 8?","8, 21, 8, 34, 47, 8 தரவுகளின் முகடு எது?"],"options":[["9","9"],["8","8"],["10","10"],["7","7"]],"answer":1,"explanation":["8 occurs 3 times; each other value occurs once.","8 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21468,"question_number":21469,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 8 hours and another in 13 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 8 மணியிலும் மற்றொன்று 13 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["83/21","83/21"],["104/21","104/21"],["146/21","146/21"],["125/21","125/21"]],"answer":1,"explanation":["Combined hourly rate = 1/8+1/13; time = 104/21 = 104/21 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/8+1/13; காலம் = 104/21 = 104/21 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21469,"question_number":21470,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −8/13. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −8/13. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["34/13","34/13"],["-5/13","-5/13"],["21/13","21/13"],["8/13","8/13"]],"answer":3,"explanation":["−8/13 + 8/13 = 0. Simplified additive inverse: 8/13.","−8/13 + 8/13 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 8/13."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21470,"question_number":21471,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 8 and 13?","8 மற்றும் 13 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["19/2","19/2"],["25/2","25/2"],["21/2","21/2"],["23/2","23/2"]],"answer":2,"explanation":["(8+13)/2 = 21/2.","(8+13)/2 = 21/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21471,"question_number":21472,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 9/13 + 1/14.","கூட்டிச் சுருக்குக: 9/13 + 1/14."],"options":[["321/182","321/182"],["503/182","503/182"],["139/182","139/182"],["-43/182","-43/182"]],"answer":2,"explanation":["[9×14 + 13]/[13×14] = 139/182.","[9×14 + 13]/[13×14] = 139/182."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21472,"question_number":21473,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 9/13 − 1/14.","கழித்துச் சுருக்குக: 9/13 − 1/14."],"options":[["295/182","295/182"],["-69/182","-69/182"],["113/182","113/182"],["477/182","477/182"]],"answer":2,"explanation":["[9×14 − 13]/[13×14] = 113/182.","[9×14 − 13]/[13×14] = 113/182."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21473,"question_number":21474,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−9/13) × (14/10).","(−9/13) × (14/10) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-128/65","-128/65"],["2/65","2/65"],["67/65","67/65"],["-63/65","-63/65"]],"answer":3,"explanation":["−126/130 = -63/65.","−126/130 = -63/65."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21474,"question_number":21475,"practice_set":859},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (9/13) ÷ (10/14) in simplest form.","(9/13) ÷ (10/14) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["193/65","193/65"],["128/65","128/65"],["-2/65","-2/65"],["63/65","63/65"]],"answer":3,"explanation":["(9/13) × (14/10) = 63/65.","(9/13) × (14/10) = 63/65."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21475,"question_number":21476,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 10.3 and 0.13.","10.3 மற்றும் 0.13 தசம எண்களைக் கூட்டுக."],"options":[["10.42","10.42"],["10.43","10.43"],["10.44","10.44"],["10.53","10.53"]],"answer":1,"explanation":["10.3 + 0.13 = 10.43.","10.3 + 0.13 = 10.43."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21476,"question_number":21477,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 13x + 9 = 295.","13x + 9 = 295 சமன்பாட்டைத் தீர்க்க."],"options":[["21","21"],["22","22"],["24","24"],["23","23"]],"answer":1,"explanation":["x = (295 − 9)/13 = 22.","x = (295 − 9)/13 = 22."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21477,"question_number":21478,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 9 and y = 13, find (x+y)² − x² − y², then divide by 2.","x = 9, y = 13 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["119","119"],["116","116"],["118","118"],["117","117"]],"answer":3,"explanation":["[(x+y)²−x²−y²]/2 = xy = 9×13 = 117.","[(x+y)²−x²−y²]/2 = xy = 9×13 = 117."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21478,"question_number":21479,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 9, y = 13.","x = 9, y = 13 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["486","486"],["483","483"],["484","484"],["485","485"]],"answer":2,"explanation":["(x+y)² = (9+13)² = 484.","(x+y)² = (9+13)² = 484."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21479,"question_number":21480,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^9 × 7^13 = 7^m, what is m?","7^9 × 7^13 = 7^m எனில் m என்ன?"],"options":[["24","24"],["22","22"],["21","21"],["23","23"]],"answer":1,"explanation":["m = 9 + 13 = 22.","m = 9 + 13 = 22."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21480,"question_number":21481,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^9)^13 = 2^m, find m.","(2^9)^13 = 2^m எனில் m காண்க."],"options":[["119","119"],["117","117"],["116","116"],["118","118"]],"answer":1,"explanation":["m = 9 × 13 = 117.","m = 9 × 13 = 117."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21481,"question_number":21482,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 65% of ₹180.","₹180 இன் 65% காண்க."],"options":[["116","116"],["117","117"],["119","119"],["118","118"]],"answer":1,"explanation":["180×65/100 = 117.","180×65/100 = 117."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21482,"question_number":21483,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹900 has a 65% discount. What is the sale price in rupees?","₹900 குறித்த விலையுள்ள பைக்கு 65% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["317","317"],["314","314"],["316","316"],["315","315"]],"answer":3,"explanation":["900 × (100−65)/100 = 315.","900 × (100−65)/100 = 315."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21483,"question_number":21484,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹900 sells for ₹1485. Find the profit percentage.","₹900 க்கு வாங்கிய பொருள் ₹1485 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["67","67"],["66","66"],["65","65"],["64","64"]],"answer":2,"explanation":["(1485−900)/900×100 = 65%.","(1485−900)/900×100 = 65%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21484,"question_number":21485,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹9000 at 13% per year for 3 years.","₹9000 க்கு ஆண்டுக்கு 13% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["3512","3512"],["3510","3510"],["3509","3509"],["3511","3511"]],"answer":1,"explanation":["9000×13×3/100 = 3510.","9000×13×3/100 = 3510."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21485,"question_number":21486,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹90000 at 13% a year for 2 years, compounded annually.","₹90000 க்கு ஆண்டுக்கு 13% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["24922","24922"],["24923","24923"],["24921","24921"],["24920","24920"]],"answer":2,"explanation":["90000×[(1+13/100)²−1] = 24921.","90000×[(1+13/100)²−1] = 24921."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21486,"question_number":21487,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["13 metres of cloth cost ₹90. At the same rate, what is the cost of 16 metres in rupees?","13 மீ துணியின் விலை ₹90. அதே வீதத்தில் 16 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["1440/13","1440/13"],["1453/13","1453/13"],["1427/13","1427/13"],["1466/13","1466/13"]],"answer":0,"explanation":["90/13×16 = 1440/13.","90/13×16 = 1440/13."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21487,"question_number":21488,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["13 equally efficient machines complete a job in 9 hours. How many hours do 15 such machines require at the same rate?","சமத் திறனுடைய 13 இயந்திரங்கள் வேலையை 9 மணியில் முடிக்கின்றன. அதே வீதத்தில் 15 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["44/5","44/5"],["34/5","34/5"],["49/5","49/5"],["39/5","39/5"]],"answer":3,"explanation":["13×9/(13+2) = 39/5 hours.","13×9/(13+2) = 39/5 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21488,"question_number":21489,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 18 cm and perpendicular height 13 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 18 செமீ; செங்குத்து உயரம் 13 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["235","235"],["234","234"],["236","236"],["233","233"]],"answer":1,"explanation":["18×13 = 234.","18×13 = 234."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21489,"question_number":21490,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 18 cm and 26 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 18 செமீ, 26 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["236","236"],["234","234"],["235","235"],["233","233"]],"answer":1,"explanation":["½×18×26 = 234 cm².","½×18×26 = 234 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21490,"question_number":21491,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 18 m and 44 m, and height 13 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 18 மீ, 44 மீ; உயரம் 13 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["403","403"],["402","402"],["405","405"],["404","404"]],"answer":0,"explanation":["½×(18+44)×13 = 403.","½×(18+44)×13 = 403."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21491,"question_number":21492,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 63 cm makes 13 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","63 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 13 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["5149","5149"],["5148","5148"],["5147","5147"],["5150","5150"]],"answer":1,"explanation":["13×2×22/7×63 = 5148.","13×2×22/7×63 = 5148."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21492,"question_number":21493,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 13 circular mats, each of radius 63 cm. Find their total area in cm², using π=22/7.","தலா 63 செமீ ஆரமுள்ள 13 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["162162","162162"],["162161","162161"],["162164","162164"],["162163","162163"]],"answer":0,"explanation":["13×22/7×63² = 162162.","13×22/7×63² = 162162."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21493,"question_number":21494,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 38° and 56°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 38°, 56°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["86","86"],["88","88"],["85","85"],["87","87"]],"answer":0,"explanation":["180−38−56 = 86°.","180−38−56 = 86°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21494,"question_number":21495,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 59°. One remote interior angle is 33°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 59°. அதற்கான ஓர் எதிர் உட்கோணம் 33°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["27","27"],["26","26"],["25","25"],["28","28"]],"answer":1,"explanation":["59 − 33 = 26°.","59 − 33 = 26°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21495,"question_number":21496,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 9, 22, 35, 48, 61.","9, 22, 35, 48, 61 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["36","36"],["37","37"],["35","35"],["34","34"]],"answer":2,"explanation":["Sum/5 = 175/5 = 35.","கூடுதல்/5 = 175/5 = 35."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21496,"question_number":21497,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 74, 9, 35, 100, 22.","வரிசைப்படுத்தி இடைநிலை காண்க: 74, 9, 35, 100, 22."],"options":[["37","37"],["36","36"],["35","35"],["34","34"]],"answer":2,"explanation":["Sorted: 9, 22, 35, 74, 100; middle value = 35.","வரிசை: 9, 22, 35, 74, 100; நடு மதிப்பு = 35."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21497,"question_number":21498,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 9, 22, 9, 35, 48, 9?","9, 22, 9, 35, 48, 9 தரவுகளின் முகடு எது?"],"options":[["11","11"],["8","8"],["9","9"],["10","10"]],"answer":2,"explanation":["9 occurs 3 times; each other value occurs once.","9 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21498,"question_number":21499,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 9 hours and another in 13 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 9 மணியிலும் மற்றொன்று 13 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["161/22","161/22"],["117/22","117/22"],["139/22","139/22"],["95/22","95/22"]],"answer":1,"explanation":["Combined hourly rate = 1/9+1/13; time = 117/22 = 117/22 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/9+1/13; காலம் = 117/22 = 117/22 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21499,"question_number":21500,"practice_set":860},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −9/13. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −9/13. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["-4/13","-4/13"],["35/13","35/13"],["22/13","22/13"],["9/13","9/13"]],"answer":3,"explanation":["−9/13 + 9/13 = 0. Simplified additive inverse: 9/13.","−9/13 + 9/13 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 9/13."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21500,"question_number":21501,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 9 and 13?","9 மற்றும் 13 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["12","12"],["13","13"],["11","11"],["10","10"]],"answer":2,"explanation":["(9+13)/2 = 11.","(9+13)/2 = 11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21501,"question_number":21502,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 10/13 + 1/14.","கூட்டிச் சுருக்குக: 10/13 + 1/14."],"options":[["153/182","153/182"],["335/182","335/182"],["-29/182","-29/182"],["517/182","517/182"]],"answer":0,"explanation":["[10×14 + 13]/[13×14] = 153/182.","[10×14 + 13]/[13×14] = 153/182."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21502,"question_number":21503,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 10/13 − 1/14.","கழித்துச் சுருக்குக: 10/13 − 1/14."],"options":[["309/182","309/182"],["491/182","491/182"],["-55/182","-55/182"],["127/182","127/182"]],"answer":3,"explanation":["[10×14 − 13]/[13×14] = 127/182.","[10×14 − 13]/[13×14] = 127/182."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21503,"question_number":21504,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−10/13) × (14/11).","(−10/13) × (14/11) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-140/143","-140/143"],["-283/143","-283/143"],["3/143","3/143"],["146/143","146/143"]],"answer":0,"explanation":["−140/143 = -140/143.","−140/143 = -140/143."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21504,"question_number":21505,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (10/13) ÷ (11/14) in simplest form.","(10/13) ÷ (11/14) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["140/143","140/143"],["426/143","426/143"],["-3/143","-3/143"],["283/143","283/143"]],"answer":0,"explanation":["(10/13) × (14/11) = 140/143.","(10/13) × (14/11) = 140/143."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21505,"question_number":21506,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 11.3 and 0.13.","11.3 மற்றும் 0.13 தசம எண்களைக் கூட்டுக."],"options":[["11.43","11.43"],["11.44","11.44"],["11.42","11.42"],["11.53","11.53"]],"answer":0,"explanation":["11.3 + 0.13 = 11.43.","11.3 + 0.13 = 11.43."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21506,"question_number":21507,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 13x + 10 = 309.","13x + 10 = 309 சமன்பாட்டைத் தீர்க்க."],"options":[["22","22"],["25","25"],["23","23"],["24","24"]],"answer":2,"explanation":["x = (309 − 10)/13 = 23.","x = (309 − 10)/13 = 23."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21507,"question_number":21508,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 10 and y = 13, find (x+y)² − x² − y², then divide by 2.","x = 10, y = 13 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["131","131"],["130","130"],["132","132"],["129","129"]],"answer":1,"explanation":["[(x+y)²−x²−y²]/2 = xy = 10×13 = 130.","[(x+y)²−x²−y²]/2 = xy = 10×13 = 130."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21508,"question_number":21509,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 10, y = 13.","x = 10, y = 13 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["529","529"],["528","528"],["530","530"],["531","531"]],"answer":0,"explanation":["(x+y)² = (10+13)² = 529.","(x+y)² = (10+13)² = 529."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21509,"question_number":21510,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^10 × 7^13 = 7^m, what is m?","7^10 × 7^13 = 7^m எனில் m என்ன?"],"options":[["25","25"],["23","23"],["24","24"],["22","22"]],"answer":1,"explanation":["m = 10 + 13 = 23.","m = 10 + 13 = 23."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21510,"question_number":21511,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^10)^13 = 2^m, find m.","(2^10)^13 = 2^m எனில் m காண்க."],"options":[["131","131"],["129","129"],["130","130"],["132","132"]],"answer":2,"explanation":["m = 10 × 13 = 130.","m = 10 × 13 = 130."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21511,"question_number":21512,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 65% of ₹200.","₹200 இன் 65% காண்க."],"options":[["130","130"],["129","129"],["132","132"],["131","131"]],"answer":0,"explanation":["200×65/100 = 130.","200×65/100 = 130."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21512,"question_number":21513,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹1000 has a 65% discount. What is the sale price in rupees?","₹1000 குறித்த விலையுள்ள பைக்கு 65% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["350","350"],["352","352"],["349","349"],["351","351"]],"answer":0,"explanation":["1000 × (100−65)/100 = 350.","1000 × (100−65)/100 = 350."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21513,"question_number":21514,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹1000 sells for ₹1650. Find the profit percentage.","₹1000 க்கு வாங்கிய பொருள் ₹1650 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["67","67"],["64","64"],["65","65"],["66","66"]],"answer":2,"explanation":["(1650−1000)/1000×100 = 65%.","(1650−1000)/1000×100 = 65%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21514,"question_number":21515,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹10000 at 13% per year for 3 years.","₹10000 க்கு ஆண்டுக்கு 13% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["3900","3900"],["3899","3899"],["3901","3901"],["3902","3902"]],"answer":0,"explanation":["10000×13×3/100 = 3900.","10000×13×3/100 = 3900."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21515,"question_number":21516,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹100000 at 13% a year for 2 years, compounded annually.","₹100000 க்கு ஆண்டுக்கு 13% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["27690","27690"],["27689","27689"],["27691","27691"],["27692","27692"]],"answer":0,"explanation":["100000×[(1+13/100)²−1] = 27690.","100000×[(1+13/100)²−1] = 27690."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21516,"question_number":21517,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["13 metres of cloth cost ₹100. At the same rate, what is the cost of 16 metres in rupees?","13 மீ துணியின் விலை ₹100. அதே வீதத்தில் 16 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["1626/13","1626/13"],["1587/13","1587/13"],["1600/13","1600/13"],["1613/13","1613/13"]],"answer":2,"explanation":["100/13×16 = 1600/13.","100/13×16 = 1600/13."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21517,"question_number":21518,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["13 equally efficient machines complete a job in 10 hours. How many hours do 15 such machines require at the same rate?","சமத் திறனுடைய 13 இயந்திரங்கள் வேலையை 10 மணியில் முடிக்கின்றன. அதே வீதத்தில் 15 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["32/3","32/3"],["26/3","26/3"],["29/3","29/3"],["23/3","23/3"]],"answer":1,"explanation":["13×10/(13+2) = 26/3 hours.","13×10/(13+2) = 26/3 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21518,"question_number":21519,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 20 cm and perpendicular height 13 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 20 செமீ; செங்குத்து உயரம் 13 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["260","260"],["262","262"],["261","261"],["259","259"]],"answer":0,"explanation":["20×13 = 260.","20×13 = 260."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21519,"question_number":21520,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 20 cm and 26 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 20 செமீ, 26 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["259","259"],["262","262"],["261","261"],["260","260"]],"answer":3,"explanation":["½×20×26 = 260 cm².","½×20×26 = 260 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21520,"question_number":21521,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 20 m and 46 m, and height 13 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 20 மீ, 46 மீ; உயரம் 13 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["430","430"],["428","428"],["429","429"],["431","431"]],"answer":2,"explanation":["½×(20+46)×13 = 429.","½×(20+46)×13 = 429."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21521,"question_number":21522,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 70 cm makes 13 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","70 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 13 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["5720","5720"],["5721","5721"],["5719","5719"],["5722","5722"]],"answer":0,"explanation":["13×2×22/7×70 = 5720.","13×2×22/7×70 = 5720."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21522,"question_number":21523,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 13 circular mats, each of radius 70 cm. Find their total area in cm², using π=22/7.","தலா 70 செமீ ஆரமுள்ள 13 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["200201","200201"],["200200","200200"],["200202","200202"],["200199","200199"]],"answer":1,"explanation":["13×22/7×70² = 200200.","13×22/7×70² = 200200."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21523,"question_number":21524,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 40° and 56°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 40°, 56°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["84","84"],["85","85"],["83","83"],["86","86"]],"answer":0,"explanation":["180−40−56 = 84°.","180−40−56 = 84°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21524,"question_number":21525,"practice_set":861},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 60°. One remote interior angle is 33°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 60°. அதற்கான ஓர் எதிர் உட்கோணம் 33°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["27","27"],["28","28"],["26","26"],["29","29"]],"answer":0,"explanation":["60 − 33 = 27°.","60 − 33 = 27°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21525,"question_number":21526,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 10, 23, 36, 49, 62.","10, 23, 36, 49, 62 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["36","36"],["35","35"],["37","37"],["38","38"]],"answer":0,"explanation":["Sum/5 = 180/5 = 36.","கூடுதல்/5 = 180/5 = 36."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21526,"question_number":21527,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 75, 10, 36, 101, 23.","வரிசைப்படுத்தி இடைநிலை காண்க: 75, 10, 36, 101, 23."],"options":[["37","37"],["38","38"],["36","36"],["35","35"]],"answer":2,"explanation":["Sorted: 10, 23, 36, 75, 101; middle value = 36.","வரிசை: 10, 23, 36, 75, 101; நடு மதிப்பு = 36."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21527,"question_number":21528,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 10, 23, 10, 36, 49, 10?","10, 23, 10, 36, 49, 10 தரவுகளின் முகடு எது?"],"options":[["12","12"],["10","10"],["9","9"],["11","11"]],"answer":1,"explanation":["10 occurs 3 times; each other value occurs once.","10 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21528,"question_number":21529,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 10 hours and another in 13 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 10 மணியிலும் மற்றொன்று 13 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["153/23","153/23"],["130/23","130/23"],["107/23","107/23"],["176/23","176/23"]],"answer":1,"explanation":["Combined hourly rate = 1/10+1/13; time = 130/23 = 130/23 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/10+1/13; காலம் = 130/23 = 130/23 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21529,"question_number":21530,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −10/13. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −10/13. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["10/13","10/13"],["-3/13","-3/13"],["23/13","23/13"],["36/13","36/13"]],"answer":0,"explanation":["−10/13 + 10/13 = 0. Simplified additive inverse: 10/13.","−10/13 + 10/13 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 10/13."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21530,"question_number":21531,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 10 and 13?","10 மற்றும் 13 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["25/2","25/2"],["27/2","27/2"],["21/2","21/2"],["23/2","23/2"]],"answer":3,"explanation":["(10+13)/2 = 23/2.","(10+13)/2 = 23/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21531,"question_number":21532,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 11/13 + 1/14.","கூட்டிச் சுருக்குக: 11/13 + 1/14."],"options":[["167/182","167/182"],["349/182","349/182"],["531/182","531/182"],["-15/182","-15/182"]],"answer":0,"explanation":["[11×14 + 13]/[13×14] = 167/182.","[11×14 + 13]/[13×14] = 167/182."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21532,"question_number":21533,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 11/13 − 1/14.","கழித்துச் சுருக்குக: 11/13 − 1/14."],"options":[["323/182","323/182"],["141/182","141/182"],["505/182","505/182"],["-41/182","-41/182"]],"answer":1,"explanation":["[11×14 − 13]/[13×14] = 141/182.","[11×14 − 13]/[13×14] = 141/182."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21533,"question_number":21534,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−11/13) × (14/12).","(−11/13) × (14/12) பெருக்கற்பலனைச் சுருக்குக."],"options":[["79/78","79/78"],["-155/78","-155/78"],["1/78","1/78"],["-77/78","-77/78"]],"answer":3,"explanation":["−154/156 = -77/78.","−154/156 = -77/78."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21534,"question_number":21535,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (11/13) ÷ (12/14) in simplest form.","(11/13) ÷ (12/14) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["-1/78","-1/78"],["155/78","155/78"],["77/78","77/78"],["233/78","233/78"]],"answer":2,"explanation":["(11/13) × (14/12) = 77/78.","(11/13) × (14/12) = 77/78."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21535,"question_number":21536,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 12.3 and 0.13.","12.3 மற்றும் 0.13 தசம எண்களைக் கூட்டுக."],"options":[["12.43","12.43"],["12.44","12.44"],["12.53","12.53"],["12.42","12.42"]],"answer":0,"explanation":["12.3 + 0.13 = 12.43.","12.3 + 0.13 = 12.43."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21536,"question_number":21537,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 13x + 11 = 323.","13x + 11 = 323 சமன்பாட்டைத் தீர்க்க."],"options":[["24","24"],["23","23"],["26","26"],["25","25"]],"answer":0,"explanation":["x = (323 − 11)/13 = 24.","x = (323 − 11)/13 = 24."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21537,"question_number":21538,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 11 and y = 13, find (x+y)² − x² − y², then divide by 2.","x = 11, y = 13 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["143","143"],["142","142"],["145","145"],["144","144"]],"answer":0,"explanation":["[(x+y)²−x²−y²]/2 = xy = 11×13 = 143.","[(x+y)²−x²−y²]/2 = xy = 11×13 = 143."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21538,"question_number":21539,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 11, y = 13.","x = 11, y = 13 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["577","577"],["576","576"],["575","575"],["578","578"]],"answer":1,"explanation":["(x+y)² = (11+13)² = 576.","(x+y)² = (11+13)² = 576."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21539,"question_number":21540,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^11 × 7^13 = 7^m, what is m?","7^11 × 7^13 = 7^m எனில் m என்ன?"],"options":[["26","26"],["25","25"],["23","23"],["24","24"]],"answer":3,"explanation":["m = 11 + 13 = 24.","m = 11 + 13 = 24."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21540,"question_number":21541,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^11)^13 = 2^m, find m.","(2^11)^13 = 2^m எனில் m காண்க."],"options":[["143","143"],["142","142"],["144","144"],["145","145"]],"answer":0,"explanation":["m = 11 × 13 = 143.","m = 11 × 13 = 143."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21541,"question_number":21542,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 15129.","15129 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["124","124"],["123","123"],["125","125"],["122","122"]],"answer":1,"explanation":["123 × 123 = 15129; √15129 = 123.","123 × 123 = 15129; √15129 = 123."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":21542,"question_number":21543,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 1860867.","1860867 இன் கனமூலத்தைக் காண்க."],"options":[["123","123"],["125","125"],["124","124"],["122","122"]],"answer":0,"explanation":["123 × 123 × 123 = 1860867; cube root = 123.","123 × 123 × 123 = 1860867; கனமூலம் = 123."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":21543,"question_number":21544,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 65% of ₹220.","₹220 இன் 65% காண்க."],"options":[["143","143"],["144","144"],["145","145"],["142","142"]],"answer":0,"explanation":["220×65/100 = 143.","220×65/100 = 143."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21544,"question_number":21545,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹1100 has a 65% discount. What is the sale price in rupees?","₹1100 குறித்த விலையுள்ள பைக்கு 65% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["385","385"],["384","384"],["387","387"],["386","386"]],"answer":0,"explanation":["1100 × (100−65)/100 = 385.","1100 × (100−65)/100 = 385."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21545,"question_number":21546,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹1100 sells for ₹1815. Find the profit percentage.","₹1100 க்கு வாங்கிய பொருள் ₹1815 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["66","66"],["65","65"],["64","64"],["67","67"]],"answer":1,"explanation":["(1815−1100)/1100×100 = 65%.","(1815−1100)/1100×100 = 65%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21546,"question_number":21547,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹11000 at 13% per year for 3 years.","₹11000 க்கு ஆண்டுக்கு 13% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["4289","4289"],["4292","4292"],["4290","4290"],["4291","4291"]],"answer":2,"explanation":["11000×13×3/100 = 4290.","11000×13×3/100 = 4290."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21547,"question_number":21548,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹110000 at 13% a year for 2 years, compounded annually.","₹110000 க்கு ஆண்டுக்கு 13% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["30460","30460"],["30458","30458"],["30459","30459"],["30461","30461"]],"answer":2,"explanation":["110000×[(1+13/100)²−1] = 30459.","110000×[(1+13/100)²−1] = 30459."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21548,"question_number":21549,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["13 metres of cloth cost ₹110. At the same rate, what is the cost of 16 metres in rupees?","13 மீ துணியின் விலை ₹110. அதே வீதத்தில் 16 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["1747/13","1747/13"],["1760/13","1760/13"],["1786/13","1786/13"],["1773/13","1773/13"]],"answer":1,"explanation":["110/13×16 = 1760/13.","110/13×16 = 1760/13."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21549,"question_number":21550,"practice_set":862},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["13 equally efficient machines complete a job in 11 hours. How many hours do 15 such machines require at the same rate?","சமத் திறனுடைய 13 இயந்திரங்கள் வேலையை 11 மணியில் முடிக்கின்றன. அதே வீதத்தில் 15 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["128/15","128/15"],["143/15","143/15"],["173/15","173/15"],["158/15","158/15"]],"answer":1,"explanation":["13×11/(13+2) = 143/15 hours.","13×11/(13+2) = 143/15 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21550,"question_number":21551,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 22 cm and perpendicular height 13 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 22 செமீ; செங்குத்து உயரம் 13 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["287","287"],["285","285"],["288","288"],["286","286"]],"answer":3,"explanation":["22×13 = 286.","22×13 = 286."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21551,"question_number":21552,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 22 cm and 26 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 22 செமீ, 26 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["285","285"],["286","286"],["288","288"],["287","287"]],"answer":1,"explanation":["½×22×26 = 286 cm².","½×22×26 = 286 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21552,"question_number":21553,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 22 m and 48 m, and height 13 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 22 மீ, 48 மீ; உயரம் 13 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["455","455"],["457","457"],["456","456"],["454","454"]],"answer":0,"explanation":["½×(22+48)×13 = 455.","½×(22+48)×13 = 455."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21553,"question_number":21554,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 77 cm makes 13 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","77 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 13 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["6294","6294"],["6292","6292"],["6293","6293"],["6291","6291"]],"answer":1,"explanation":["13×2×22/7×77 = 6292.","13×2×22/7×77 = 6292."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21554,"question_number":21555,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 13 circular mats, each of radius 77 cm. Find their total area in cm², using π=22/7.","தலா 77 செமீ ஆரமுள்ள 13 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["242242","242242"],["242243","242243"],["242241","242241"],["242244","242244"]],"answer":0,"explanation":["13×22/7×77² = 242242.","13×22/7×77² = 242242."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21555,"question_number":21556,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 42° and 56°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 42°, 56°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["82","82"],["81","81"],["84","84"],["83","83"]],"answer":0,"explanation":["180−42−56 = 82°.","180−42−56 = 82°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21556,"question_number":21557,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 61°. One remote interior angle is 33°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 61°. அதற்கான ஓர் எதிர் உட்கோணம் 33°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["28","28"],["30","30"],["27","27"],["29","29"]],"answer":0,"explanation":["61 − 33 = 28°.","61 − 33 = 28°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21557,"question_number":21558,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 11, 24, 37, 50, 63.","11, 24, 37, 50, 63 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["37","37"],["39","39"],["36","36"],["38","38"]],"answer":0,"explanation":["Sum/5 = 185/5 = 37.","கூடுதல்/5 = 185/5 = 37."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21558,"question_number":21559,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 76, 11, 37, 102, 24.","வரிசைப்படுத்தி இடைநிலை காண்க: 76, 11, 37, 102, 24."],"options":[["36","36"],["39","39"],["38","38"],["37","37"]],"answer":3,"explanation":["Sorted: 11, 24, 37, 76, 102; middle value = 37.","வரிசை: 11, 24, 37, 76, 102; நடு மதிப்பு = 37."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21559,"question_number":21560,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 11, 24, 11, 37, 50, 11?","11, 24, 11, 37, 50, 11 தரவுகளின் முகடு எது?"],"options":[["12","12"],["10","10"],["13","13"],["11","11"]],"answer":3,"explanation":["11 occurs 3 times; each other value occurs once.","11 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21560,"question_number":21561,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 11 hours and another in 13 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 11 மணியிலும் மற்றொன்று 13 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["143/24","143/24"],["191/24","191/24"],["167/24","167/24"],["119/24","119/24"]],"answer":0,"explanation":["Combined hourly rate = 1/11+1/13; time = 143/24 = 143/24 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/11+1/13; காலம் = 143/24 = 143/24 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21561,"question_number":21562,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −11/13. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −11/13. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["-2/13","-2/13"],["11/13","11/13"],["37/13","37/13"],["24/13","24/13"]],"answer":1,"explanation":["−11/13 + 11/13 = 0. Simplified additive inverse: 11/13.","−11/13 + 11/13 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 11/13."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21562,"question_number":21563,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 11 and 13?","11 மற்றும் 13 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["11","11"],["14","14"],["12","12"],["13","13"]],"answer":2,"explanation":["(11+13)/2 = 12.","(11+13)/2 = 12."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21563,"question_number":21564,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 2/14 + 1/15.","கூட்டிச் சுருக்குக: 2/14 + 1/15."],"options":[["127/105","127/105"],["-83/105","-83/105"],["232/105","232/105"],["22/105","22/105"]],"answer":3,"explanation":["[2×15 + 14]/[14×15] = 22/105.","[2×15 + 14]/[14×15] = 22/105."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21564,"question_number":21565,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 2/14 − 1/15.","கழித்துச் சுருக்குக: 2/14 − 1/15."],"options":[["113/105","113/105"],["8/105","8/105"],["218/105","218/105"],["-97/105","-97/105"]],"answer":1,"explanation":["[2×15 − 14]/[14×15] = 8/105.","[2×15 − 14]/[14×15] = 8/105."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21565,"question_number":21566,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−2/14) × (15/3).","(−2/14) × (15/3) பெருக்கற்பலனைச் சுருக்குக."],"options":[["9/7","9/7"],["-12/7","-12/7"],["-5/7","-5/7"],["2/7","2/7"]],"answer":2,"explanation":["−30/42 = -5/7.","−30/42 = -5/7."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21566,"question_number":21567,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (2/14) ÷ (3/15) in simplest form.","(2/14) ÷ (3/15) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["12/7","12/7"],["19/7","19/7"],["-2/7","-2/7"],["5/7","5/7"]],"answer":3,"explanation":["(2/14) × (15/3) = 5/7.","(2/14) × (15/3) = 5/7."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21567,"question_number":21568,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 3.4 and 0.14.","3.4 மற்றும் 0.14 தசம எண்களைக் கூட்டுக."],"options":[["3.53","3.53"],["3.54","3.54"],["3.55","3.55"],["3.64","3.64"]],"answer":1,"explanation":["3.4 + 0.14 = 3.54.","3.4 + 0.14 = 3.54."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21568,"question_number":21569,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 14x + 2 = 226.","14x + 2 = 226 சமன்பாட்டைத் தீர்க்க."],"options":[["18","18"],["15","15"],["16","16"],["17","17"]],"answer":2,"explanation":["x = (226 − 2)/14 = 16.","x = (226 − 2)/14 = 16."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21569,"question_number":21570,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 2 and y = 14, find (x+y)² − x² − y², then divide by 2.","x = 2, y = 14 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["30","30"],["27","27"],["28","28"],["29","29"]],"answer":2,"explanation":["[(x+y)²−x²−y²]/2 = xy = 2×14 = 28.","[(x+y)²−x²−y²]/2 = xy = 2×14 = 28."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21570,"question_number":21571,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 2, y = 14.","x = 2, y = 14 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["258","258"],["257","257"],["255","255"],["256","256"]],"answer":3,"explanation":["(x+y)² = (2+14)² = 256.","(x+y)² = (2+14)² = 256."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21571,"question_number":21572,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^2 × 7^14 = 7^m, what is m?","7^2 × 7^14 = 7^m எனில் m என்ன?"],"options":[["16","16"],["17","17"],["15","15"],["18","18"]],"answer":0,"explanation":["m = 2 + 14 = 16.","m = 2 + 14 = 16."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21572,"question_number":21573,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^2)^14 = 2^m, find m.","(2^2)^14 = 2^m எனில் m காண்க."],"options":[["30","30"],["27","27"],["28","28"],["29","29"]],"answer":2,"explanation":["m = 2 × 14 = 28.","m = 2 × 14 = 28."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21573,"question_number":21574,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 70% of ₹40.","₹40 இன் 70% காண்க."],"options":[["27","27"],["30","30"],["29","29"],["28","28"]],"answer":3,"explanation":["40×70/100 = 28.","40×70/100 = 28."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21574,"question_number":21575,"practice_set":863},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹200 has a 70% discount. What is the sale price in rupees?","₹200 குறித்த விலையுள்ள பைக்கு 70% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["62","62"],["59","59"],["60","60"],["61","61"]],"answer":2,"explanation":["200 × (100−70)/100 = 60.","200 × (100−70)/100 = 60."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21575,"question_number":21576,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹200 sells for ₹340. Find the profit percentage.","₹200 க்கு வாங்கிய பொருள் ₹340 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["71","71"],["69","69"],["70","70"],["72","72"]],"answer":2,"explanation":["(340−200)/200×100 = 70%.","(340−200)/200×100 = 70%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21576,"question_number":21577,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹2000 at 14% per year for 3 years.","₹2000 க்கு ஆண்டுக்கு 14% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["840","840"],["841","841"],["839","839"],["842","842"]],"answer":0,"explanation":["2000×14×3/100 = 840.","2000×14×3/100 = 840."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21577,"question_number":21578,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹20000 at 14% a year for 2 years, compounded annually.","₹20000 க்கு ஆண்டுக்கு 14% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["5993","5993"],["5994","5994"],["5992","5992"],["5991","5991"]],"answer":2,"explanation":["20000×[(1+14/100)²−1] = 5992.","20000×[(1+14/100)²−1] = 5992."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21578,"question_number":21579,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["14 metres of cloth cost ₹20. At the same rate, what is the cost of 17 metres in rupees?","14 மீ துணியின் விலை ₹20. அதே வீதத்தில் 17 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["170/7","170/7"],["177/7","177/7"],["163/7","163/7"],["184/7","184/7"]],"answer":0,"explanation":["20/14×17 = 170/7.","20/14×17 = 170/7."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21579,"question_number":21580,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["14 equally efficient machines complete a job in 2 hours. How many hours do 16 such machines require at the same rate?","சமத் திறனுடைய 14 இயந்திரங்கள் வேலையை 2 மணியில் முடிக்கின்றன. அதே வீதத்தில் 16 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["7/4","7/4"],["15/4","15/4"],["11/4","11/4"],["3/4","3/4"]],"answer":0,"explanation":["14×2/(14+2) = 7/4 hours.","14×2/(14+2) = 7/4 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21580,"question_number":21581,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 4 cm and perpendicular height 14 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 4 செமீ; செங்குத்து உயரம் 14 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["55","55"],["57","57"],["58","58"],["56","56"]],"answer":3,"explanation":["4×14 = 56.","4×14 = 56."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21581,"question_number":21582,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 4 cm and 28 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 4 செமீ, 28 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["55","55"],["56","56"],["57","57"],["58","58"]],"answer":1,"explanation":["½×4×28 = 56 cm².","½×4×28 = 56 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21582,"question_number":21583,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 4 m and 32 m, and height 14 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 4 மீ, 32 மீ; உயரம் 14 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["251","251"],["252","252"],["254","254"],["253","253"]],"answer":1,"explanation":["½×(4+32)×14 = 252.","½×(4+32)×14 = 252."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21583,"question_number":21584,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 14 cm makes 14 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","14 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 14 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["1231","1231"],["1232","1232"],["1234","1234"],["1233","1233"]],"answer":1,"explanation":["14×2×22/7×14 = 1232.","14×2×22/7×14 = 1232."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21584,"question_number":21585,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 14 circular mats, each of radius 14 cm. Find their total area in cm², using π=22/7.","தலா 14 செமீ ஆரமுள்ள 14 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["8626","8626"],["8625","8625"],["8624","8624"],["8623","8623"]],"answer":2,"explanation":["14×22/7×14² = 8624.","14×22/7×14² = 8624."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21585,"question_number":21586,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 24° and 58°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 24°, 58°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["98","98"],["99","99"],["100","100"],["97","97"]],"answer":0,"explanation":["180−24−58 = 98°.","180−24−58 = 98°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21586,"question_number":21587,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 52°. One remote interior angle is 34°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 52°. அதற்கான ஓர் எதிர் உட்கோணம் 34°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["20","20"],["17","17"],["19","19"],["18","18"]],"answer":3,"explanation":["52 − 34 = 18°.","52 − 34 = 18°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21587,"question_number":21588,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 2, 16, 30, 44, 58.","2, 16, 30, 44, 58 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["31","31"],["29","29"],["30","30"],["32","32"]],"answer":2,"explanation":["Sum/5 = 150/5 = 30.","கூடுதல்/5 = 150/5 = 30."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21588,"question_number":21589,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 72, 2, 30, 100, 16.","வரிசைப்படுத்தி இடைநிலை காண்க: 72, 2, 30, 100, 16."],"options":[["31","31"],["32","32"],["29","29"],["30","30"]],"answer":3,"explanation":["Sorted: 2, 16, 30, 72, 100; middle value = 30.","வரிசை: 2, 16, 30, 72, 100; நடு மதிப்பு = 30."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21589,"question_number":21590,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 2, 16, 2, 30, 44, 2?","2, 16, 2, 30, 44, 2 தரவுகளின் முகடு எது?"],"options":[["4","4"],["1","1"],["3","3"],["2","2"]],"answer":3,"explanation":["2 occurs 3 times; each other value occurs once.","2 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21590,"question_number":21591,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 2 hours and another in 14 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 2 மணியிலும் மற்றொன்று 14 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["3/4","3/4"],["11/4","11/4"],["15/4","15/4"],["7/4","7/4"]],"answer":3,"explanation":["Combined hourly rate = 1/2+1/14; time = 28/16 = 7/4 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/2+1/14; காலம் = 28/16 = 7/4 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21591,"question_number":21592,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −2/14. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −2/14. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["15/7","15/7"],["-6/7","-6/7"],["1/7","1/7"],["8/7","8/7"]],"answer":2,"explanation":["−2/14 + 2/14 = 0. Simplified additive inverse: 1/7.","−2/14 + 2/14 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 1/7."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21592,"question_number":21593,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 2 and 14?","2 மற்றும் 14 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["7","7"],["10","10"],["8","8"],["9","9"]],"answer":2,"explanation":["(2+14)/2 = 8.","(2+14)/2 = 8."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21593,"question_number":21594,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 3/14 + 1/15.","கூட்டிச் சுருக்குக: 3/14 + 1/15."],"options":[["479/210","479/210"],["269/210","269/210"],["59/210","59/210"],["-151/210","-151/210"]],"answer":2,"explanation":["[3×15 + 14]/[14×15] = 59/210.","[3×15 + 14]/[14×15] = 59/210."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21594,"question_number":21595,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 3/14 − 1/15.","கழித்துச் சுருக்குக: 3/14 − 1/15."],"options":[["-179/210","-179/210"],["31/210","31/210"],["241/210","241/210"],["451/210","451/210"]],"answer":1,"explanation":["[3×15 − 14]/[14×15] = 31/210.","[3×15 − 14]/[14×15] = 31/210."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21595,"question_number":21596,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−3/14) × (15/4).","(−3/14) × (15/4) பெருக்கற்பலனைச் சுருக்குக."],"options":[["67/56","67/56"],["11/56","11/56"],["-45/56","-45/56"],["-101/56","-101/56"]],"answer":2,"explanation":["−45/56 = -45/56.","−45/56 = -45/56."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21596,"question_number":21597,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (3/14) ÷ (4/15) in simplest form.","(3/14) ÷ (4/15) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["157/56","157/56"],["101/56","101/56"],["-11/56","-11/56"],["45/56","45/56"]],"answer":3,"explanation":["(3/14) × (15/4) = 45/56.","(3/14) × (15/4) = 45/56."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21597,"question_number":21598,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 4.4 and 0.14.","4.4 மற்றும் 0.14 தசம எண்களைக் கூட்டுக."],"options":[["4.53","4.53"],["4.54","4.54"],["4.64","4.64"],["4.55","4.55"]],"answer":1,"explanation":["4.4 + 0.14 = 4.54.","4.4 + 0.14 = 4.54."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21598,"question_number":21599,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 14x + 3 = 241.","14x + 3 = 241 சமன்பாட்டைத் தீர்க்க."],"options":[["18","18"],["16","16"],["17","17"],["19","19"]],"answer":2,"explanation":["x = (241 − 3)/14 = 17.","x = (241 − 3)/14 = 17."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21599,"question_number":21600,"practice_set":864},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 3 and y = 14, find (x+y)² − x² − y², then divide by 2.","x = 3, y = 14 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["42","42"],["43","43"],["44","44"],["41","41"]],"answer":0,"explanation":["[(x+y)²−x²−y²]/2 = xy = 3×14 = 42.","[(x+y)²−x²−y²]/2 = xy = 3×14 = 42."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21600,"question_number":21601,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 3, y = 14.","x = 3, y = 14 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["291","291"],["290","290"],["288","288"],["289","289"]],"answer":3,"explanation":["(x+y)² = (3+14)² = 289.","(x+y)² = (3+14)² = 289."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21601,"question_number":21602,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^3 × 7^14 = 7^m, what is m?","7^3 × 7^14 = 7^m எனில் m என்ன?"],"options":[["16","16"],["19","19"],["18","18"],["17","17"]],"answer":3,"explanation":["m = 3 + 14 = 17.","m = 3 + 14 = 17."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21602,"question_number":21603,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^3)^14 = 2^m, find m.","(2^3)^14 = 2^m எனில் m காண்க."],"options":[["44","44"],["41","41"],["42","42"],["43","43"]],"answer":2,"explanation":["m = 3 × 14 = 42.","m = 3 × 14 = 42."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21603,"question_number":21604,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 70% of ₹60.","₹60 இன் 70% காண்க."],"options":[["44","44"],["42","42"],["43","43"],["41","41"]],"answer":1,"explanation":["60×70/100 = 42.","60×70/100 = 42."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21604,"question_number":21605,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹300 has a 70% discount. What is the sale price in rupees?","₹300 குறித்த விலையுள்ள பைக்கு 70% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["91","91"],["89","89"],["92","92"],["90","90"]],"answer":3,"explanation":["300 × (100−70)/100 = 90.","300 × (100−70)/100 = 90."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21605,"question_number":21606,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹300 sells for ₹510. Find the profit percentage.","₹300 க்கு வாங்கிய பொருள் ₹510 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["69","69"],["72","72"],["70","70"],["71","71"]],"answer":2,"explanation":["(510−300)/300×100 = 70%.","(510−300)/300×100 = 70%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21606,"question_number":21607,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹3000 at 14% per year for 3 years.","₹3000 க்கு ஆண்டுக்கு 14% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1261","1261"],["1262","1262"],["1260","1260"],["1259","1259"]],"answer":2,"explanation":["3000×14×3/100 = 1260.","3000×14×3/100 = 1260."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21607,"question_number":21608,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹30000 at 14% a year for 2 years, compounded annually.","₹30000 க்கு ஆண்டுக்கு 14% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["8989","8989"],["8988","8988"],["8987","8987"],["8990","8990"]],"answer":1,"explanation":["30000×[(1+14/100)²−1] = 8988.","30000×[(1+14/100)²−1] = 8988."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21608,"question_number":21609,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["14 metres of cloth cost ₹30. At the same rate, what is the cost of 17 metres in rupees?","14 மீ துணியின் விலை ₹30. அதே வீதத்தில் 17 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["255/7","255/7"],["269/7","269/7"],["262/7","262/7"],["248/7","248/7"]],"answer":0,"explanation":["30/14×17 = 255/7.","30/14×17 = 255/7."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21609,"question_number":21610,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["14 equally efficient machines complete a job in 3 hours. How many hours do 16 such machines require at the same rate?","சமத் திறனுடைய 14 இயந்திரங்கள் வேலையை 3 மணியில் முடிக்கின்றன. அதே வீதத்தில் 16 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["13/8","13/8"],["29/8","29/8"],["37/8","37/8"],["21/8","21/8"]],"answer":3,"explanation":["14×3/(14+2) = 21/8 hours.","14×3/(14+2) = 21/8 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21610,"question_number":21611,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 6 cm and perpendicular height 14 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 6 செமீ; செங்குத்து உயரம் 14 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["86","86"],["83","83"],["84","84"],["85","85"]],"answer":2,"explanation":["6×14 = 84.","6×14 = 84."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21611,"question_number":21612,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 6 cm and 28 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 6 செமீ, 28 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["85","85"],["84","84"],["83","83"],["86","86"]],"answer":1,"explanation":["½×6×28 = 84 cm².","½×6×28 = 84 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21612,"question_number":21613,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 6 m and 34 m, and height 14 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 6 மீ, 34 மீ; உயரம் 14 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["281","281"],["280","280"],["279","279"],["282","282"]],"answer":1,"explanation":["½×(6+34)×14 = 280.","½×(6+34)×14 = 280."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21613,"question_number":21614,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 21 cm makes 14 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","21 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 14 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["1847","1847"],["1849","1849"],["1848","1848"],["1850","1850"]],"answer":2,"explanation":["14×2×22/7×21 = 1848.","14×2×22/7×21 = 1848."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21614,"question_number":21615,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 14 circular mats, each of radius 21 cm. Find their total area in cm², using π=22/7.","தலா 21 செமீ ஆரமுள்ள 14 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["19404","19404"],["19406","19406"],["19403","19403"],["19405","19405"]],"answer":0,"explanation":["14×22/7×21² = 19404.","14×22/7×21² = 19404."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21615,"question_number":21616,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 26° and 58°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 26°, 58°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["95","95"],["96","96"],["98","98"],["97","97"]],"answer":1,"explanation":["180−26−58 = 96°.","180−26−58 = 96°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21616,"question_number":21617,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 53°. One remote interior angle is 34°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 53°. அதற்கான ஓர் எதிர் உட்கோணம் 34°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["19","19"],["20","20"],["21","21"],["18","18"]],"answer":0,"explanation":["53 − 34 = 19°.","53 − 34 = 19°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21617,"question_number":21618,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 3, 17, 31, 45, 59.","3, 17, 31, 45, 59 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["31","31"],["33","33"],["32","32"],["30","30"]],"answer":0,"explanation":["Sum/5 = 155/5 = 31.","கூடுதல்/5 = 155/5 = 31."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21618,"question_number":21619,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 73, 3, 31, 101, 17.","வரிசைப்படுத்தி இடைநிலை காண்க: 73, 3, 31, 101, 17."],"options":[["33","33"],["32","32"],["30","30"],["31","31"]],"answer":3,"explanation":["Sorted: 3, 17, 31, 73, 101; middle value = 31.","வரிசை: 3, 17, 31, 73, 101; நடு மதிப்பு = 31."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21619,"question_number":21620,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 3, 17, 3, 31, 45, 3?","3, 17, 3, 31, 45, 3 தரவுகளின் முகடு எது?"],"options":[["4","4"],["2","2"],["3","3"],["5","5"]],"answer":2,"explanation":["3 occurs 3 times; each other value occurs once.","3 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21620,"question_number":21621,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 3 hours and another in 14 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 3 மணியிலும் மற்றொன்று 14 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["42/17","42/17"],["59/17","59/17"],["25/17","25/17"],["76/17","76/17"]],"answer":0,"explanation":["Combined hourly rate = 1/3+1/14; time = 42/17 = 42/17 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/3+1/14; காலம் = 42/17 = 42/17 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21621,"question_number":21622,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −3/14. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −3/14. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["31/14","31/14"],["3/14","3/14"],["-11/14","-11/14"],["17/14","17/14"]],"answer":1,"explanation":["−3/14 + 3/14 = 0. Simplified additive inverse: 3/14.","−3/14 + 3/14 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 3/14."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21622,"question_number":21623,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 3 and 14?","3 மற்றும் 14 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["21/2","21/2"],["17/2","17/2"],["15/2","15/2"],["19/2","19/2"]],"answer":1,"explanation":["(3+14)/2 = 17/2.","(3+14)/2 = 17/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21623,"question_number":21624,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 4/14 + 1/15.","கூட்டிச் சுருக்குக: 4/14 + 1/15."],"options":[["142/105","142/105"],["247/105","247/105"],["-68/105","-68/105"],["37/105","37/105"]],"answer":3,"explanation":["[4×15 + 14]/[14×15] = 37/105.","[4×15 + 14]/[14×15] = 37/105."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21624,"question_number":21625,"practice_set":865},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 4/14 − 1/15.","கழித்துச் சுருக்குக: 4/14 − 1/15."],"options":[["-82/105","-82/105"],["233/105","233/105"],["128/105","128/105"],["23/105","23/105"]],"answer":3,"explanation":["[4×15 − 14]/[14×15] = 23/105.","[4×15 − 14]/[14×15] = 23/105."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21625,"question_number":21626,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−4/14) × (15/5).","(−4/14) × (15/5) பெருக்கற்பலனைச் சுருக்குக."],"options":[["8/7","8/7"],["1/7","1/7"],["-6/7","-6/7"],["-13/7","-13/7"]],"answer":2,"explanation":["−60/70 = -6/7.","−60/70 = -6/7."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21626,"question_number":21627,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (4/14) ÷ (5/15) in simplest form.","(4/14) ÷ (5/15) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["13/7","13/7"],["6/7","6/7"],["20/7","20/7"],["-1/7","-1/7"]],"answer":1,"explanation":["(4/14) × (15/5) = 6/7.","(4/14) × (15/5) = 6/7."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21627,"question_number":21628,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 5.4 and 0.14.","5.4 மற்றும் 0.14 தசம எண்களைக் கூட்டுக."],"options":[["5.53","5.53"],["5.54","5.54"],["5.64","5.64"],["5.55","5.55"]],"answer":1,"explanation":["5.4 + 0.14 = 5.54.","5.4 + 0.14 = 5.54."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21628,"question_number":21629,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 14x + 4 = 256.","14x + 4 = 256 சமன்பாட்டைத் தீர்க்க."],"options":[["19","19"],["20","20"],["17","17"],["18","18"]],"answer":3,"explanation":["x = (256 − 4)/14 = 18.","x = (256 − 4)/14 = 18."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21629,"question_number":21630,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 4 and y = 14, find (x+y)² − x² − y², then divide by 2.","x = 4, y = 14 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["55","55"],["56","56"],["58","58"],["57","57"]],"answer":1,"explanation":["[(x+y)²−x²−y²]/2 = xy = 4×14 = 56.","[(x+y)²−x²−y²]/2 = xy = 4×14 = 56."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21630,"question_number":21631,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 4, y = 14.","x = 4, y = 14 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["325","325"],["324","324"],["326","326"],["323","323"]],"answer":1,"explanation":["(x+y)² = (4+14)² = 324.","(x+y)² = (4+14)² = 324."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21631,"question_number":21632,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^4 × 7^14 = 7^m, what is m?","7^4 × 7^14 = 7^m எனில் m என்ன?"],"options":[["20","20"],["17","17"],["19","19"],["18","18"]],"answer":3,"explanation":["m = 4 + 14 = 18.","m = 4 + 14 = 18."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21632,"question_number":21633,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^4)^14 = 2^m, find m.","(2^4)^14 = 2^m எனில் m காண்க."],"options":[["55","55"],["57","57"],["58","58"],["56","56"]],"answer":3,"explanation":["m = 4 × 14 = 56.","m = 4 × 14 = 56."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21633,"question_number":21634,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 70% of ₹80.","₹80 இன் 70% காண்க."],"options":[["56","56"],["55","55"],["58","58"],["57","57"]],"answer":0,"explanation":["80×70/100 = 56.","80×70/100 = 56."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21634,"question_number":21635,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹400 has a 70% discount. What is the sale price in rupees?","₹400 குறித்த விலையுள்ள பைக்கு 70% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["119","119"],["120","120"],["121","121"],["122","122"]],"answer":1,"explanation":["400 × (100−70)/100 = 120.","400 × (100−70)/100 = 120."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21635,"question_number":21636,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹400 sells for ₹680. Find the profit percentage.","₹400 க்கு வாங்கிய பொருள் ₹680 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["70","70"],["72","72"],["71","71"],["69","69"]],"answer":0,"explanation":["(680−400)/400×100 = 70%.","(680−400)/400×100 = 70%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21636,"question_number":21637,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹4000 at 14% per year for 3 years.","₹4000 க்கு ஆண்டுக்கு 14% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1681","1681"],["1679","1679"],["1680","1680"],["1682","1682"]],"answer":2,"explanation":["4000×14×3/100 = 1680.","4000×14×3/100 = 1680."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21637,"question_number":21638,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹40000 at 14% a year for 2 years, compounded annually.","₹40000 க்கு ஆண்டுக்கு 14% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["11986","11986"],["11983","11983"],["11985","11985"],["11984","11984"]],"answer":3,"explanation":["40000×[(1+14/100)²−1] = 11984.","40000×[(1+14/100)²−1] = 11984."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21638,"question_number":21639,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["14 metres of cloth cost ₹40. At the same rate, what is the cost of 17 metres in rupees?","14 மீ துணியின் விலை ₹40. அதே வீதத்தில் 17 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["347/7","347/7"],["333/7","333/7"],["354/7","354/7"],["340/7","340/7"]],"answer":3,"explanation":["40/14×17 = 340/7.","40/14×17 = 340/7."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21639,"question_number":21640,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["14 equally efficient machines complete a job in 4 hours. How many hours do 16 such machines require at the same rate?","சமத் திறனுடைய 14 இயந்திரங்கள் வேலையை 4 மணியில் முடிக்கின்றன. அதே வீதத்தில் 16 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["9/2","9/2"],["5/2","5/2"],["11/2","11/2"],["7/2","7/2"]],"answer":3,"explanation":["14×4/(14+2) = 7/2 hours.","14×4/(14+2) = 7/2 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21640,"question_number":21641,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 8 cm and perpendicular height 14 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 8 செமீ; செங்குத்து உயரம் 14 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["113","113"],["112","112"],["114","114"],["111","111"]],"answer":1,"explanation":["8×14 = 112.","8×14 = 112."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21641,"question_number":21642,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 8 cm and 28 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 8 செமீ, 28 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["112","112"],["111","111"],["114","114"],["113","113"]],"answer":0,"explanation":["½×8×28 = 112 cm².","½×8×28 = 112 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21642,"question_number":21643,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 8 m and 36 m, and height 14 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 8 மீ, 36 மீ; உயரம் 14 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["309","309"],["310","310"],["307","307"],["308","308"]],"answer":3,"explanation":["½×(8+36)×14 = 308.","½×(8+36)×14 = 308."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21643,"question_number":21644,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 28 cm makes 14 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","28 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 14 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["2463","2463"],["2464","2464"],["2465","2465"],["2466","2466"]],"answer":1,"explanation":["14×2×22/7×28 = 2464.","14×2×22/7×28 = 2464."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21644,"question_number":21645,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 14 circular mats, each of radius 28 cm. Find their total area in cm², using π=22/7.","தலா 28 செமீ ஆரமுள்ள 14 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["34496","34496"],["34498","34498"],["34497","34497"],["34495","34495"]],"answer":0,"explanation":["14×22/7×28² = 34496.","14×22/7×28² = 34496."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21645,"question_number":21646,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 28° and 58°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 28°, 58°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["93","93"],["94","94"],["95","95"],["96","96"]],"answer":1,"explanation":["180−28−58 = 94°.","180−28−58 = 94°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21646,"question_number":21647,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 54°. One remote interior angle is 34°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 54°. அதற்கான ஓர் எதிர் உட்கோணம் 34°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["22","22"],["21","21"],["19","19"],["20","20"]],"answer":3,"explanation":["54 − 34 = 20°.","54 − 34 = 20°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21647,"question_number":21648,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 4, 18, 32, 46, 60.","4, 18, 32, 46, 60 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["34","34"],["31","31"],["33","33"],["32","32"]],"answer":3,"explanation":["Sum/5 = 160/5 = 32.","கூடுதல்/5 = 160/5 = 32."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21648,"question_number":21649,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 74, 4, 32, 102, 18.","வரிசைப்படுத்தி இடைநிலை காண்க: 74, 4, 32, 102, 18."],"options":[["33","33"],["34","34"],["32","32"],["31","31"]],"answer":2,"explanation":["Sorted: 4, 18, 32, 74, 102; middle value = 32.","வரிசை: 4, 18, 32, 74, 102; நடு மதிப்பு = 32."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21649,"question_number":21650,"practice_set":866},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 4, 18, 4, 32, 46, 4?","4, 18, 4, 32, 46, 4 தரவுகளின் முகடு எது?"],"options":[["4","4"],["6","6"],["3","3"],["5","5"]],"answer":0,"explanation":["4 occurs 3 times; each other value occurs once.","4 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21650,"question_number":21651,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 4 hours and another in 14 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 4 மணியிலும் மற்றொன்று 14 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["28/9","28/9"],["46/9","46/9"],["19/9","19/9"],["37/9","37/9"]],"answer":0,"explanation":["Combined hourly rate = 1/4+1/14; time = 56/18 = 28/9 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/4+1/14; காலம் = 56/18 = 28/9 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21651,"question_number":21652,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −4/14. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −4/14. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["9/7","9/7"],["2/7","2/7"],["16/7","16/7"],["-5/7","-5/7"]],"answer":1,"explanation":["−4/14 + 4/14 = 0. Simplified additive inverse: 2/7.","−4/14 + 4/14 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 2/7."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21652,"question_number":21653,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 4 and 14?","4 மற்றும் 14 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["10","10"],["9","9"],["8","8"],["11","11"]],"answer":1,"explanation":["(4+14)/2 = 9.","(4+14)/2 = 9."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21653,"question_number":21654,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 5/14 + 1/15.","கூட்டிச் சுருக்குக: 5/14 + 1/15."],"options":[["509/210","509/210"],["89/210","89/210"],["-121/210","-121/210"],["299/210","299/210"]],"answer":1,"explanation":["[5×15 + 14]/[14×15] = 89/210.","[5×15 + 14]/[14×15] = 89/210."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21654,"question_number":21655,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 5/14 − 1/15.","கழித்துச் சுருக்குக: 5/14 − 1/15."],"options":[["481/210","481/210"],["-149/210","-149/210"],["271/210","271/210"],["61/210","61/210"]],"answer":3,"explanation":["[5×15 − 14]/[14×15] = 61/210.","[5×15 − 14]/[14×15] = 61/210."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21655,"question_number":21656,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−5/14) × (15/6).","(−5/14) × (15/6) பெருக்கற்பலனைச் சுருக்குக."],"options":[["3/28","3/28"],["-25/28","-25/28"],["31/28","31/28"],["-53/28","-53/28"]],"answer":1,"explanation":["−75/84 = -25/28.","−75/84 = -25/28."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21656,"question_number":21657,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (5/14) ÷ (6/15) in simplest form.","(5/14) ÷ (6/15) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["25/28","25/28"],["53/28","53/28"],["-3/28","-3/28"],["81/28","81/28"]],"answer":0,"explanation":["(5/14) × (15/6) = 25/28.","(5/14) × (15/6) = 25/28."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21657,"question_number":21658,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 6.4 and 0.14.","6.4 மற்றும் 0.14 தசம எண்களைக் கூட்டுக."],"options":[["6.64","6.64"],["6.55","6.55"],["6.54","6.54"],["6.53","6.53"]],"answer":2,"explanation":["6.4 + 0.14 = 6.54.","6.4 + 0.14 = 6.54."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21658,"question_number":21659,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 14x + 5 = 271.","14x + 5 = 271 சமன்பாட்டைத் தீர்க்க."],"options":[["19","19"],["20","20"],["18","18"],["21","21"]],"answer":0,"explanation":["x = (271 − 5)/14 = 19.","x = (271 − 5)/14 = 19."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21659,"question_number":21660,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 5 and y = 14, find (x+y)² − x² − y², then divide by 2.","x = 5, y = 14 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["69","69"],["70","70"],["71","71"],["72","72"]],"answer":1,"explanation":["[(x+y)²−x²−y²]/2 = xy = 5×14 = 70.","[(x+y)²−x²−y²]/2 = xy = 5×14 = 70."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21660,"question_number":21661,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 5, y = 14.","x = 5, y = 14 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["363","363"],["362","362"],["361","361"],["360","360"]],"answer":2,"explanation":["(x+y)² = (5+14)² = 361.","(x+y)² = (5+14)² = 361."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21661,"question_number":21662,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^5 × 7^14 = 7^m, what is m?","7^5 × 7^14 = 7^m எனில் m என்ன?"],"options":[["19","19"],["21","21"],["18","18"],["20","20"]],"answer":0,"explanation":["m = 5 + 14 = 19.","m = 5 + 14 = 19."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21662,"question_number":21663,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^5)^14 = 2^m, find m.","(2^5)^14 = 2^m எனில் m காண்க."],"options":[["71","71"],["70","70"],["69","69"],["72","72"]],"answer":1,"explanation":["m = 5 × 14 = 70.","m = 5 × 14 = 70."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21663,"question_number":21664,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 70% of ₹100.","₹100 இன் 70% காண்க."],"options":[["70","70"],["72","72"],["71","71"],["69","69"]],"answer":0,"explanation":["100×70/100 = 70.","100×70/100 = 70."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21664,"question_number":21665,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹500 has a 70% discount. What is the sale price in rupees?","₹500 குறித்த விலையுள்ள பைக்கு 70% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["149","149"],["151","151"],["152","152"],["150","150"]],"answer":3,"explanation":["500 × (100−70)/100 = 150.","500 × (100−70)/100 = 150."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21665,"question_number":21666,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹500 sells for ₹850. Find the profit percentage.","₹500 க்கு வாங்கிய பொருள் ₹850 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["72","72"],["69","69"],["70","70"],["71","71"]],"answer":2,"explanation":["(850−500)/500×100 = 70%.","(850−500)/500×100 = 70%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21666,"question_number":21667,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹5000 at 14% per year for 3 years.","₹5000 க்கு ஆண்டுக்கு 14% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2102","2102"],["2099","2099"],["2101","2101"],["2100","2100"]],"answer":3,"explanation":["5000×14×3/100 = 2100.","5000×14×3/100 = 2100."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21667,"question_number":21668,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹50000 at 14% a year for 2 years, compounded annually.","₹50000 க்கு ஆண்டுக்கு 14% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["14981","14981"],["14982","14982"],["14980","14980"],["14979","14979"]],"answer":2,"explanation":["50000×[(1+14/100)²−1] = 14980.","50000×[(1+14/100)²−1] = 14980."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21668,"question_number":21669,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["14 metres of cloth cost ₹50. At the same rate, what is the cost of 17 metres in rupees?","14 மீ துணியின் விலை ₹50. அதே வீதத்தில் 17 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["439/7","439/7"],["418/7","418/7"],["432/7","432/7"],["425/7","425/7"]],"answer":3,"explanation":["50/14×17 = 425/7.","50/14×17 = 425/7."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21669,"question_number":21670,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["14 equally efficient machines complete a job in 5 hours. How many hours do 16 such machines require at the same rate?","சமத் திறனுடைய 14 இயந்திரங்கள் வேலையை 5 மணியில் முடிக்கின்றன. அதே வீதத்தில் 16 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["35/8","35/8"],["51/8","51/8"],["43/8","43/8"],["27/8","27/8"]],"answer":0,"explanation":["14×5/(14+2) = 35/8 hours.","14×5/(14+2) = 35/8 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21670,"question_number":21671,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 10 cm and perpendicular height 14 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 10 செமீ; செங்குத்து உயரம் 14 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["140","140"],["141","141"],["139","139"],["142","142"]],"answer":0,"explanation":["10×14 = 140.","10×14 = 140."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21671,"question_number":21672,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 10 cm and 28 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 10 செமீ, 28 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["139","139"],["141","141"],["142","142"],["140","140"]],"answer":3,"explanation":["½×10×28 = 140 cm².","½×10×28 = 140 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21672,"question_number":21673,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 10 m and 38 m, and height 14 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 10 மீ, 38 மீ; உயரம் 14 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["336","336"],["335","335"],["337","337"],["338","338"]],"answer":0,"explanation":["½×(10+38)×14 = 336.","½×(10+38)×14 = 336."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21673,"question_number":21674,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 35 cm makes 14 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","35 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 14 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["3082","3082"],["3081","3081"],["3079","3079"],["3080","3080"]],"answer":3,"explanation":["14×2×22/7×35 = 3080.","14×2×22/7×35 = 3080."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21674,"question_number":21675,"practice_set":867},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 14 circular mats, each of radius 35 cm. Find their total area in cm², using π=22/7.","தலா 35 செமீ ஆரமுள்ள 14 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["53899","53899"],["53902","53902"],["53901","53901"],["53900","53900"]],"answer":3,"explanation":["14×22/7×35² = 53900.","14×22/7×35² = 53900."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21675,"question_number":21676,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 30° and 58°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 30°, 58°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["91","91"],["93","93"],["94","94"],["92","92"]],"answer":3,"explanation":["180−30−58 = 92°.","180−30−58 = 92°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21676,"question_number":21677,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 55°. One remote interior angle is 34°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 55°. அதற்கான ஓர் எதிர் உட்கோணம் 34°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["21","21"],["20","20"],["23","23"],["22","22"]],"answer":0,"explanation":["55 − 34 = 21°.","55 − 34 = 21°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21677,"question_number":21678,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 5, 19, 33, 47, 61.","5, 19, 33, 47, 61 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["34","34"],["33","33"],["32","32"],["35","35"]],"answer":1,"explanation":["Sum/5 = 165/5 = 33.","கூடுதல்/5 = 165/5 = 33."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21678,"question_number":21679,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 75, 5, 33, 103, 19.","வரிசைப்படுத்தி இடைநிலை காண்க: 75, 5, 33, 103, 19."],"options":[["32","32"],["33","33"],["34","34"],["35","35"]],"answer":1,"explanation":["Sorted: 5, 19, 33, 75, 103; middle value = 33.","வரிசை: 5, 19, 33, 75, 103; நடு மதிப்பு = 33."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21679,"question_number":21680,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 5, 19, 5, 33, 47, 5?","5, 19, 5, 33, 47, 5 தரவுகளின் முகடு எது?"],"options":[["5","5"],["6","6"],["4","4"],["7","7"]],"answer":0,"explanation":["5 occurs 3 times; each other value occurs once.","5 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21680,"question_number":21681,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 5 hours and another in 14 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 5 மணியிலும் மற்றொன்று 14 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["89/19","89/19"],["51/19","51/19"],["108/19","108/19"],["70/19","70/19"]],"answer":3,"explanation":["Combined hourly rate = 1/5+1/14; time = 70/19 = 70/19 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/5+1/14; காலம் = 70/19 = 70/19 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21681,"question_number":21682,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −5/14. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −5/14. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["19/14","19/14"],["5/14","5/14"],["33/14","33/14"],["-9/14","-9/14"]],"answer":1,"explanation":["−5/14 + 5/14 = 0. Simplified additive inverse: 5/14.","−5/14 + 5/14 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 5/14."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21682,"question_number":21683,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 5 and 14?","5 மற்றும் 14 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["17/2","17/2"],["19/2","19/2"],["23/2","23/2"],["21/2","21/2"]],"answer":1,"explanation":["(5+14)/2 = 19/2.","(5+14)/2 = 19/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21683,"question_number":21684,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 6/14 + 1/15.","கூட்டிச் சுருக்குக: 6/14 + 1/15."],"options":[["262/105","262/105"],["-53/105","-53/105"],["157/105","157/105"],["52/105","52/105"]],"answer":3,"explanation":["[6×15 + 14]/[14×15] = 52/105.","[6×15 + 14]/[14×15] = 52/105."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21684,"question_number":21685,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 6/14 − 1/15.","கழித்துச் சுருக்குக: 6/14 − 1/15."],"options":[["248/105","248/105"],["143/105","143/105"],["-67/105","-67/105"],["38/105","38/105"]],"answer":3,"explanation":["[6×15 − 14]/[14×15] = 38/105.","[6×15 − 14]/[14×15] = 38/105."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21685,"question_number":21686,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−6/14) × (15/7).","(−6/14) × (15/7) பெருக்கற்பலனைச் சுருக்குக."],"options":[["4/49","4/49"],["-45/49","-45/49"],["-94/49","-94/49"],["53/49","53/49"]],"answer":1,"explanation":["−90/98 = -45/49.","−90/98 = -45/49."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21686,"question_number":21687,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (6/14) ÷ (7/15) in simplest form.","(6/14) ÷ (7/15) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["45/49","45/49"],["-4/49","-4/49"],["94/49","94/49"],["143/49","143/49"]],"answer":0,"explanation":["(6/14) × (15/7) = 45/49.","(6/14) × (15/7) = 45/49."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21687,"question_number":21688,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 7.4 and 0.14.","7.4 மற்றும் 0.14 தசம எண்களைக் கூட்டுக."],"options":[["7.55","7.55"],["7.54","7.54"],["7.53","7.53"],["7.64","7.64"]],"answer":1,"explanation":["7.4 + 0.14 = 7.54.","7.4 + 0.14 = 7.54."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21688,"question_number":21689,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 14x + 6 = 286.","14x + 6 = 286 சமன்பாட்டைத் தீர்க்க."],"options":[["20","20"],["21","21"],["22","22"],["19","19"]],"answer":0,"explanation":["x = (286 − 6)/14 = 20.","x = (286 − 6)/14 = 20."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21689,"question_number":21690,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 6 and y = 14, find (x+y)² − x² − y², then divide by 2.","x = 6, y = 14 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["84","84"],["83","83"],["85","85"],["86","86"]],"answer":0,"explanation":["[(x+y)²−x²−y²]/2 = xy = 6×14 = 84.","[(x+y)²−x²−y²]/2 = xy = 6×14 = 84."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21690,"question_number":21691,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 6, y = 14.","x = 6, y = 14 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["399","399"],["402","402"],["400","400"],["401","401"]],"answer":2,"explanation":["(x+y)² = (6+14)² = 400.","(x+y)² = (6+14)² = 400."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21691,"question_number":21692,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^6 × 7^14 = 7^m, what is m?","7^6 × 7^14 = 7^m எனில் m என்ன?"],"options":[["19","19"],["20","20"],["21","21"],["22","22"]],"answer":1,"explanation":["m = 6 + 14 = 20.","m = 6 + 14 = 20."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21692,"question_number":21693,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^6)^14 = 2^m, find m.","(2^6)^14 = 2^m எனில் m காண்க."],"options":[["86","86"],["85","85"],["83","83"],["84","84"]],"answer":3,"explanation":["m = 6 × 14 = 84.","m = 6 × 14 = 84."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21693,"question_number":21694,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 70% of ₹120.","₹120 இன் 70% காண்க."],"options":[["84","84"],["86","86"],["83","83"],["85","85"]],"answer":0,"explanation":["120×70/100 = 84.","120×70/100 = 84."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21694,"question_number":21695,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹600 has a 70% discount. What is the sale price in rupees?","₹600 குறித்த விலையுள்ள பைக்கு 70% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["181","181"],["182","182"],["179","179"],["180","180"]],"answer":3,"explanation":["600 × (100−70)/100 = 180.","600 × (100−70)/100 = 180."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21695,"question_number":21696,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹600 sells for ₹1020. Find the profit percentage.","₹600 க்கு வாங்கிய பொருள் ₹1020 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["71","71"],["69","69"],["70","70"],["72","72"]],"answer":2,"explanation":["(1020−600)/600×100 = 70%.","(1020−600)/600×100 = 70%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21696,"question_number":21697,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹6000 at 14% per year for 3 years.","₹6000 க்கு ஆண்டுக்கு 14% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2519","2519"],["2521","2521"],["2520","2520"],["2522","2522"]],"answer":2,"explanation":["6000×14×3/100 = 2520.","6000×14×3/100 = 2520."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21697,"question_number":21698,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹60000 at 14% a year for 2 years, compounded annually.","₹60000 க்கு ஆண்டுக்கு 14% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["17977","17977"],["17976","17976"],["17975","17975"],["17978","17978"]],"answer":1,"explanation":["60000×[(1+14/100)²−1] = 17976.","60000×[(1+14/100)²−1] = 17976."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21698,"question_number":21699,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["14 metres of cloth cost ₹60. At the same rate, what is the cost of 17 metres in rupees?","14 மீ துணியின் விலை ₹60. அதே வீதத்தில் 17 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["517/7","517/7"],["510/7","510/7"],["503/7","503/7"],["524/7","524/7"]],"answer":1,"explanation":["60/14×17 = 510/7.","60/14×17 = 510/7."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21699,"question_number":21700,"practice_set":868},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["14 equally efficient machines complete a job in 6 hours. How many hours do 16 such machines require at the same rate?","சமத் திறனுடைய 14 இயந்திரங்கள் வேலையை 6 மணியில் முடிக்கின்றன. அதே வீதத்தில் 16 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["17/4","17/4"],["25/4","25/4"],["21/4","21/4"],["29/4","29/4"]],"answer":2,"explanation":["14×6/(14+2) = 21/4 hours.","14×6/(14+2) = 21/4 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21700,"question_number":21701,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 12 cm and perpendicular height 14 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 12 செமீ; செங்குத்து உயரம் 14 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["167","167"],["170","170"],["168","168"],["169","169"]],"answer":2,"explanation":["12×14 = 168.","12×14 = 168."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21701,"question_number":21702,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 12 cm and 28 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 12 செமீ, 28 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["167","167"],["170","170"],["169","169"],["168","168"]],"answer":3,"explanation":["½×12×28 = 168 cm².","½×12×28 = 168 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21702,"question_number":21703,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 12 m and 40 m, and height 14 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 12 மீ, 40 மீ; உயரம் 14 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["366","366"],["363","363"],["364","364"],["365","365"]],"answer":2,"explanation":["½×(12+40)×14 = 364.","½×(12+40)×14 = 364."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21703,"question_number":21704,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 42 cm makes 14 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","42 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 14 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["3697","3697"],["3696","3696"],["3695","3695"],["3698","3698"]],"answer":1,"explanation":["14×2×22/7×42 = 3696.","14×2×22/7×42 = 3696."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21704,"question_number":21705,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 14 circular mats, each of radius 42 cm. Find their total area in cm², using π=22/7.","தலா 42 செமீ ஆரமுள்ள 14 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["77618","77618"],["77615","77615"],["77617","77617"],["77616","77616"]],"answer":3,"explanation":["14×22/7×42² = 77616.","14×22/7×42² = 77616."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21705,"question_number":21706,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 32° and 58°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 32°, 58°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["91","91"],["89","89"],["90","90"],["92","92"]],"answer":2,"explanation":["180−32−58 = 90°.","180−32−58 = 90°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21706,"question_number":21707,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 56°. One remote interior angle is 34°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 56°. அதற்கான ஓர் எதிர் உட்கோணம் 34°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["23","23"],["22","22"],["24","24"],["21","21"]],"answer":1,"explanation":["56 − 34 = 22°.","56 − 34 = 22°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21707,"question_number":21708,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 6, 20, 34, 48, 62.","6, 20, 34, 48, 62 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["36","36"],["33","33"],["34","34"],["35","35"]],"answer":2,"explanation":["Sum/5 = 170/5 = 34.","கூடுதல்/5 = 170/5 = 34."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21708,"question_number":21709,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 76, 6, 34, 104, 20.","வரிசைப்படுத்தி இடைநிலை காண்க: 76, 6, 34, 104, 20."],"options":[["35","35"],["36","36"],["33","33"],["34","34"]],"answer":3,"explanation":["Sorted: 6, 20, 34, 76, 104; middle value = 34.","வரிசை: 6, 20, 34, 76, 104; நடு மதிப்பு = 34."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21709,"question_number":21710,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 6, 20, 6, 34, 48, 6?","6, 20, 6, 34, 48, 6 தரவுகளின் முகடு எது?"],"options":[["8","8"],["6","6"],["7","7"],["5","5"]],"answer":1,"explanation":["6 occurs 3 times; each other value occurs once.","6 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21710,"question_number":21711,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 6 hours and another in 14 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 6 மணியிலும் மற்றொன்று 14 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["21/5","21/5"],["16/5","16/5"],["26/5","26/5"],["31/5","31/5"]],"answer":0,"explanation":["Combined hourly rate = 1/6+1/14; time = 84/20 = 21/5 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/6+1/14; காலம் = 84/20 = 21/5 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21711,"question_number":21712,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −6/14. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −6/14. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["-4/7","-4/7"],["17/7","17/7"],["3/7","3/7"],["10/7","10/7"]],"answer":2,"explanation":["−6/14 + 6/14 = 0. Simplified additive inverse: 3/7.","−6/14 + 6/14 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 3/7."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21712,"question_number":21713,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 6 and 14?","6 மற்றும் 14 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["9","9"],["10","10"],["12","12"],["11","11"]],"answer":1,"explanation":["(6+14)/2 = 10.","(6+14)/2 = 10."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21713,"question_number":21714,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 7/14 + 1/15.","கூட்டிச் சுருக்குக: 7/14 + 1/15."],"options":[["-13/30","-13/30"],["47/30","47/30"],["77/30","77/30"],["17/30","17/30"]],"answer":3,"explanation":["[7×15 + 14]/[14×15] = 17/30.","[7×15 + 14]/[14×15] = 17/30."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21714,"question_number":21715,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 7/14 − 1/15.","கழித்துச் சுருக்குக: 7/14 − 1/15."],"options":[["43/30","43/30"],["13/30","13/30"],["73/30","73/30"],["-17/30","-17/30"]],"answer":1,"explanation":["[7×15 − 14]/[14×15] = 13/30.","[7×15 − 14]/[14×15] = 13/30."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21715,"question_number":21716,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−7/14) × (15/8).","(−7/14) × (15/8) பெருக்கற்பலனைச் சுருக்குக."],"options":[["17/16","17/16"],["1/16","1/16"],["-31/16","-31/16"],["-15/16","-15/16"]],"answer":3,"explanation":["−105/112 = -15/16.","−105/112 = -15/16."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21716,"question_number":21717,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (7/14) ÷ (8/15) in simplest form.","(7/14) ÷ (8/15) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["15/16","15/16"],["31/16","31/16"],["47/16","47/16"],["-1/16","-1/16"]],"answer":0,"explanation":["(7/14) × (15/8) = 15/16.","(7/14) × (15/8) = 15/16."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21717,"question_number":21718,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 8.4 and 0.14.","8.4 மற்றும் 0.14 தசம எண்களைக் கூட்டுக."],"options":[["8.55","8.55"],["8.53","8.53"],["8.54","8.54"],["8.64","8.64"]],"answer":2,"explanation":["8.4 + 0.14 = 8.54.","8.4 + 0.14 = 8.54."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21718,"question_number":21719,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 14x + 7 = 301.","14x + 7 = 301 சமன்பாட்டைத் தீர்க்க."],"options":[["23","23"],["21","21"],["20","20"],["22","22"]],"answer":1,"explanation":["x = (301 − 7)/14 = 21.","x = (301 − 7)/14 = 21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21719,"question_number":21720,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 7 and y = 14, find (x+y)² − x² − y², then divide by 2.","x = 7, y = 14 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["98","98"],["100","100"],["99","99"],["97","97"]],"answer":0,"explanation":["[(x+y)²−x²−y²]/2 = xy = 7×14 = 98.","[(x+y)²−x²−y²]/2 = xy = 7×14 = 98."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21720,"question_number":21721,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 7, y = 14.","x = 7, y = 14 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["442","442"],["443","443"],["441","441"],["440","440"]],"answer":2,"explanation":["(x+y)² = (7+14)² = 441.","(x+y)² = (7+14)² = 441."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21721,"question_number":21722,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^7 × 7^14 = 7^m, what is m?","7^7 × 7^14 = 7^m எனில் m என்ன?"],"options":[["21","21"],["20","20"],["23","23"],["22","22"]],"answer":0,"explanation":["m = 7 + 14 = 21.","m = 7 + 14 = 21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21722,"question_number":21723,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^7)^14 = 2^m, find m.","(2^7)^14 = 2^m எனில் m காண்க."],"options":[["97","97"],["100","100"],["99","99"],["98","98"]],"answer":3,"explanation":["m = 7 × 14 = 98.","m = 7 × 14 = 98."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21723,"question_number":21724,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 70% of ₹140.","₹140 இன் 70% காண்க."],"options":[["97","97"],["100","100"],["98","98"],["99","99"]],"answer":2,"explanation":["140×70/100 = 98.","140×70/100 = 98."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21724,"question_number":21725,"practice_set":869},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹700 has a 70% discount. What is the sale price in rupees?","₹700 குறித்த விலையுள்ள பைக்கு 70% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["210","210"],["211","211"],["209","209"],["212","212"]],"answer":0,"explanation":["700 × (100−70)/100 = 210.","700 × (100−70)/100 = 210."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21725,"question_number":21726,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹700 sells for ₹1190. Find the profit percentage.","₹700 க்கு வாங்கிய பொருள் ₹1190 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["71","71"],["72","72"],["69","69"],["70","70"]],"answer":3,"explanation":["(1190−700)/700×100 = 70%.","(1190−700)/700×100 = 70%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21726,"question_number":21727,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹7000 at 14% per year for 3 years.","₹7000 க்கு ஆண்டுக்கு 14% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2941","2941"],["2940","2940"],["2939","2939"],["2942","2942"]],"answer":1,"explanation":["7000×14×3/100 = 2940.","7000×14×3/100 = 2940."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21727,"question_number":21728,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹70000 at 14% a year for 2 years, compounded annually.","₹70000 க்கு ஆண்டுக்கு 14% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["20972","20972"],["20973","20973"],["20974","20974"],["20971","20971"]],"answer":0,"explanation":["70000×[(1+14/100)²−1] = 20972.","70000×[(1+14/100)²−1] = 20972."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21728,"question_number":21729,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["14 metres of cloth cost ₹70. At the same rate, what is the cost of 17 metres in rupees?","14 மீ துணியின் விலை ₹70. அதே வீதத்தில் 17 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["84","84"],["87","87"],["86","86"],["85","85"]],"answer":3,"explanation":["70/14×17 = 85.","70/14×17 = 85."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21729,"question_number":21730,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["14 equally efficient machines complete a job in 7 hours. How many hours do 16 such machines require at the same rate?","சமத் திறனுடைய 14 இயந்திரங்கள் வேலையை 7 மணியில் முடிக்கின்றன. அதே வீதத்தில் 16 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["65/8","65/8"],["49/8","49/8"],["57/8","57/8"],["41/8","41/8"]],"answer":1,"explanation":["14×7/(14+2) = 49/8 hours.","14×7/(14+2) = 49/8 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21730,"question_number":21731,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 14 cm and perpendicular height 14 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 14 செமீ; செங்குத்து உயரம் 14 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["196","196"],["197","197"],["195","195"],["198","198"]],"answer":0,"explanation":["14×14 = 196.","14×14 = 196."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21731,"question_number":21732,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 14 cm and 28 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 14 செமீ, 28 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["195","195"],["198","198"],["197","197"],["196","196"]],"answer":3,"explanation":["½×14×28 = 196 cm².","½×14×28 = 196 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21732,"question_number":21733,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 14 m and 42 m, and height 14 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 14 மீ, 42 மீ; உயரம் 14 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["393","393"],["391","391"],["394","394"],["392","392"]],"answer":3,"explanation":["½×(14+42)×14 = 392.","½×(14+42)×14 = 392."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21733,"question_number":21734,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 49 cm makes 14 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","49 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 14 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["4312","4312"],["4311","4311"],["4313","4313"],["4314","4314"]],"answer":0,"explanation":["14×2×22/7×49 = 4312.","14×2×22/7×49 = 4312."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21734,"question_number":21735,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 14 circular mats, each of radius 49 cm. Find their total area in cm², using π=22/7.","தலா 49 செமீ ஆரமுள்ள 14 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["105645","105645"],["105644","105644"],["105643","105643"],["105646","105646"]],"answer":1,"explanation":["14×22/7×49² = 105644.","14×22/7×49² = 105644."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21735,"question_number":21736,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 34° and 58°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 34°, 58°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["90","90"],["87","87"],["88","88"],["89","89"]],"answer":2,"explanation":["180−34−58 = 88°.","180−34−58 = 88°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21736,"question_number":21737,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 57°. One remote interior angle is 34°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 57°. அதற்கான ஓர் எதிர் உட்கோணம் 34°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["23","23"],["25","25"],["24","24"],["22","22"]],"answer":0,"explanation":["57 − 34 = 23°.","57 − 34 = 23°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21737,"question_number":21738,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 7, 21, 35, 49, 63.","7, 21, 35, 49, 63 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["37","37"],["36","36"],["34","34"],["35","35"]],"answer":3,"explanation":["Sum/5 = 175/5 = 35.","கூடுதல்/5 = 175/5 = 35."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21738,"question_number":21739,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 77, 7, 35, 105, 21.","வரிசைப்படுத்தி இடைநிலை காண்க: 77, 7, 35, 105, 21."],"options":[["34","34"],["37","37"],["36","36"],["35","35"]],"answer":3,"explanation":["Sorted: 7, 21, 35, 77, 105; middle value = 35.","வரிசை: 7, 21, 35, 77, 105; நடு மதிப்பு = 35."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21739,"question_number":21740,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 7, 21, 7, 35, 49, 7?","7, 21, 7, 35, 49, 7 தரவுகளின் முகடு எது?"],"options":[["9","9"],["6","6"],["7","7"],["8","8"]],"answer":2,"explanation":["7 occurs 3 times; each other value occurs once.","7 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21740,"question_number":21741,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 7 hours and another in 14 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 7 மணியிலும் மற்றொன்று 14 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["14/3","14/3"],["11/3","11/3"],["17/3","17/3"],["20/3","20/3"]],"answer":0,"explanation":["Combined hourly rate = 1/7+1/14; time = 98/21 = 14/3 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/7+1/14; காலம் = 98/21 = 14/3 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21741,"question_number":21742,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −7/14. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −7/14. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["5/2","5/2"],["-1/2","-1/2"],["3/2","3/2"],["1/2","1/2"]],"answer":3,"explanation":["−7/14 + 7/14 = 0. Simplified additive inverse: 1/2.","−7/14 + 7/14 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 1/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21742,"question_number":21743,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 7 and 14?","7 மற்றும் 14 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["23/2","23/2"],["25/2","25/2"],["21/2","21/2"],["19/2","19/2"]],"answer":2,"explanation":["(7+14)/2 = 21/2.","(7+14)/2 = 21/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21743,"question_number":21744,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 8/14 + 1/15.","கூட்டிச் சுருக்குக: 8/14 + 1/15."],"options":[["-38/105","-38/105"],["277/105","277/105"],["172/105","172/105"],["67/105","67/105"]],"answer":3,"explanation":["[8×15 + 14]/[14×15] = 67/105.","[8×15 + 14]/[14×15] = 67/105."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21744,"question_number":21745,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 8/14 − 1/15.","கழித்துச் சுருக்குக: 8/14 − 1/15."],"options":[["53/105","53/105"],["158/105","158/105"],["263/105","263/105"],["-52/105","-52/105"]],"answer":0,"explanation":["[8×15 − 14]/[14×15] = 53/105.","[8×15 − 14]/[14×15] = 53/105."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21745,"question_number":21746,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−8/14) × (15/9).","(−8/14) × (15/9) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-41/21","-41/21"],["1/21","1/21"],["-20/21","-20/21"],["22/21","22/21"]],"answer":2,"explanation":["−120/126 = -20/21.","−120/126 = -20/21."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21746,"question_number":21747,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (8/14) ÷ (9/15) in simplest form.","(8/14) ÷ (9/15) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["41/21","41/21"],["20/21","20/21"],["62/21","62/21"],["-1/21","-1/21"]],"answer":1,"explanation":["(8/14) × (15/9) = 20/21.","(8/14) × (15/9) = 20/21."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21747,"question_number":21748,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 9.4 and 0.14.","9.4 மற்றும் 0.14 தசம எண்களைக் கூட்டுக."],"options":[["9.53","9.53"],["9.64","9.64"],["9.54","9.54"],["9.55","9.55"]],"answer":2,"explanation":["9.4 + 0.14 = 9.54.","9.4 + 0.14 = 9.54."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21748,"question_number":21749,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 14x + 8 = 316.","14x + 8 = 316 சமன்பாட்டைத் தீர்க்க."],"options":[["23","23"],["21","21"],["24","24"],["22","22"]],"answer":3,"explanation":["x = (316 − 8)/14 = 22.","x = (316 − 8)/14 = 22."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21749,"question_number":21750,"practice_set":870},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 8 and y = 14, find (x+y)² − x² − y², then divide by 2.","x = 8, y = 14 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["114","114"],["113","113"],["111","111"],["112","112"]],"answer":3,"explanation":["[(x+y)²−x²−y²]/2 = xy = 8×14 = 112.","[(x+y)²−x²−y²]/2 = xy = 8×14 = 112."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21750,"question_number":21751,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 8, y = 14.","x = 8, y = 14 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["483","483"],["485","485"],["484","484"],["486","486"]],"answer":2,"explanation":["(x+y)² = (8+14)² = 484.","(x+y)² = (8+14)² = 484."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21751,"question_number":21752,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^8 × 7^14 = 7^m, what is m?","7^8 × 7^14 = 7^m எனில் m என்ன?"],"options":[["21","21"],["23","23"],["24","24"],["22","22"]],"answer":3,"explanation":["m = 8 + 14 = 22.","m = 8 + 14 = 22."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21752,"question_number":21753,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^8)^14 = 2^m, find m.","(2^8)^14 = 2^m எனில் m காண்க."],"options":[["111","111"],["114","114"],["113","113"],["112","112"]],"answer":3,"explanation":["m = 8 × 14 = 112.","m = 8 × 14 = 112."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21753,"question_number":21754,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 70% of ₹160.","₹160 இன் 70% காண்க."],"options":[["111","111"],["112","112"],["113","113"],["114","114"]],"answer":1,"explanation":["160×70/100 = 112.","160×70/100 = 112."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21754,"question_number":21755,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹800 has a 70% discount. What is the sale price in rupees?","₹800 குறித்த விலையுள்ள பைக்கு 70% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["239","239"],["241","241"],["242","242"],["240","240"]],"answer":3,"explanation":["800 × (100−70)/100 = 240.","800 × (100−70)/100 = 240."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21755,"question_number":21756,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹800 sells for ₹1360. Find the profit percentage.","₹800 க்கு வாங்கிய பொருள் ₹1360 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["71","71"],["69","69"],["72","72"],["70","70"]],"answer":3,"explanation":["(1360−800)/800×100 = 70%.","(1360−800)/800×100 = 70%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21756,"question_number":21757,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹8000 at 14% per year for 3 years.","₹8000 க்கு ஆண்டுக்கு 14% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["3361","3361"],["3362","3362"],["3359","3359"],["3360","3360"]],"answer":3,"explanation":["8000×14×3/100 = 3360.","8000×14×3/100 = 3360."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21757,"question_number":21758,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹80000 at 14% a year for 2 years, compounded annually.","₹80000 க்கு ஆண்டுக்கு 14% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["23970","23970"],["23967","23967"],["23968","23968"],["23969","23969"]],"answer":2,"explanation":["80000×[(1+14/100)²−1] = 23968.","80000×[(1+14/100)²−1] = 23968."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21758,"question_number":21759,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["14 metres of cloth cost ₹80. At the same rate, what is the cost of 17 metres in rupees?","14 மீ துணியின் விலை ₹80. அதே வீதத்தில் 17 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["680/7","680/7"],["694/7","694/7"],["673/7","673/7"],["687/7","687/7"]],"answer":0,"explanation":["80/14×17 = 680/7.","80/14×17 = 680/7."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21759,"question_number":21760,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["14 equally efficient machines complete a job in 8 hours. How many hours do 16 such machines require at the same rate?","சமத் திறனுடைய 14 இயந்திரங்கள் வேலையை 8 மணியில் முடிக்கின்றன. அதே வீதத்தில் 16 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["7","7"],["6","6"],["9","9"],["8","8"]],"answer":0,"explanation":["14×8/(14+2) = 7 hours.","14×8/(14+2) = 7 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21760,"question_number":21761,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 16 cm and perpendicular height 14 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 16 செமீ; செங்குத்து உயரம் 14 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["224","224"],["223","223"],["225","225"],["226","226"]],"answer":0,"explanation":["16×14 = 224.","16×14 = 224."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21761,"question_number":21762,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 16 cm and 28 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 16 செமீ, 28 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["224","224"],["225","225"],["226","226"],["223","223"]],"answer":0,"explanation":["½×16×28 = 224 cm².","½×16×28 = 224 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21762,"question_number":21763,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 16 m and 44 m, and height 14 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 16 மீ, 44 மீ; உயரம் 14 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["419","419"],["422","422"],["421","421"],["420","420"]],"answer":3,"explanation":["½×(16+44)×14 = 420.","½×(16+44)×14 = 420."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21763,"question_number":21764,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 56 cm makes 14 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","56 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 14 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["4927","4927"],["4930","4930"],["4928","4928"],["4929","4929"]],"answer":2,"explanation":["14×2×22/7×56 = 4928.","14×2×22/7×56 = 4928."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21764,"question_number":21765,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 14 circular mats, each of radius 56 cm. Find their total area in cm², using π=22/7.","தலா 56 செமீ ஆரமுள்ள 14 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["137983","137983"],["137986","137986"],["137984","137984"],["137985","137985"]],"answer":2,"explanation":["14×22/7×56² = 137984.","14×22/7×56² = 137984."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21765,"question_number":21766,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 36° and 58°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 36°, 58°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["85","85"],["87","87"],["88","88"],["86","86"]],"answer":3,"explanation":["180−36−58 = 86°.","180−36−58 = 86°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21766,"question_number":21767,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 58°. One remote interior angle is 34°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 58°. அதற்கான ஓர் எதிர் உட்கோணம் 34°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["25","25"],["23","23"],["26","26"],["24","24"]],"answer":3,"explanation":["58 − 34 = 24°.","58 − 34 = 24°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21767,"question_number":21768,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 8, 22, 36, 50, 64.","8, 22, 36, 50, 64 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["38","38"],["36","36"],["37","37"],["35","35"]],"answer":1,"explanation":["Sum/5 = 180/5 = 36.","கூடுதல்/5 = 180/5 = 36."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21768,"question_number":21769,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 78, 8, 36, 106, 22.","வரிசைப்படுத்தி இடைநிலை காண்க: 78, 8, 36, 106, 22."],"options":[["37","37"],["35","35"],["36","36"],["38","38"]],"answer":2,"explanation":["Sorted: 8, 22, 36, 78, 106; middle value = 36.","வரிசை: 8, 22, 36, 78, 106; நடு மதிப்பு = 36."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21769,"question_number":21770,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 8, 22, 8, 36, 50, 8?","8, 22, 8, 36, 50, 8 தரவுகளின் முகடு எது?"],"options":[["8","8"],["10","10"],["9","9"],["7","7"]],"answer":0,"explanation":["8 occurs 3 times; each other value occurs once.","8 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21770,"question_number":21771,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 8 hours and another in 14 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 8 மணியிலும் மற்றொன்று 14 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["78/11","78/11"],["67/11","67/11"],["45/11","45/11"],["56/11","56/11"]],"answer":3,"explanation":["Combined hourly rate = 1/8+1/14; time = 112/22 = 56/11 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/8+1/14; காலம் = 112/22 = 56/11 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21771,"question_number":21772,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −8/14. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −8/14. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["-3/7","-3/7"],["18/7","18/7"],["11/7","11/7"],["4/7","4/7"]],"answer":3,"explanation":["−8/14 + 8/14 = 0. Simplified additive inverse: 4/7.","−8/14 + 8/14 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 4/7."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21772,"question_number":21773,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 8 and 14?","8 மற்றும் 14 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["12","12"],["11","11"],["10","10"],["13","13"]],"answer":1,"explanation":["(8+14)/2 = 11.","(8+14)/2 = 11."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21773,"question_number":21774,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 9/14 + 1/15.","கூட்டிச் சுருக்குக: 9/14 + 1/15."],"options":[["-61/210","-61/210"],["149/210","149/210"],["359/210","359/210"],["569/210","569/210"]],"answer":1,"explanation":["[9×15 + 14]/[14×15] = 149/210.","[9×15 + 14]/[14×15] = 149/210."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21774,"question_number":21775,"practice_set":871},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 9/14 − 1/15.","கழித்துச் சுருக்குக: 9/14 − 1/15."],"options":[["331/210","331/210"],["121/210","121/210"],["541/210","541/210"],["-89/210","-89/210"]],"answer":1,"explanation":["[9×15 − 14]/[14×15] = 121/210.","[9×15 − 14]/[14×15] = 121/210."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21775,"question_number":21776,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−9/14) × (15/10).","(−9/14) × (15/10) பெருக்கற்பலனைச் சுருக்குக."],"options":[["29/28","29/28"],["-55/28","-55/28"],["1/28","1/28"],["-27/28","-27/28"]],"answer":3,"explanation":["−135/140 = -27/28.","−135/140 = -27/28."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21776,"question_number":21777,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (9/14) ÷ (10/15) in simplest form.","(9/14) ÷ (10/15) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["27/28","27/28"],["55/28","55/28"],["83/28","83/28"],["-1/28","-1/28"]],"answer":0,"explanation":["(9/14) × (15/10) = 27/28.","(9/14) × (15/10) = 27/28."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21777,"question_number":21778,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 10.4 and 0.14.","10.4 மற்றும் 0.14 தசம எண்களைக் கூட்டுக."],"options":[["10.54","10.54"],["10.64","10.64"],["10.55","10.55"],["10.53","10.53"]],"answer":0,"explanation":["10.4 + 0.14 = 10.54.","10.4 + 0.14 = 10.54."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21778,"question_number":21779,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 14x + 9 = 331.","14x + 9 = 331 சமன்பாட்டைத் தீர்க்க."],"options":[["25","25"],["22","22"],["24","24"],["23","23"]],"answer":3,"explanation":["x = (331 − 9)/14 = 23.","x = (331 − 9)/14 = 23."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21779,"question_number":21780,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 9 and y = 14, find (x+y)² − x² − y², then divide by 2.","x = 9, y = 14 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["125","125"],["126","126"],["127","127"],["128","128"]],"answer":1,"explanation":["[(x+y)²−x²−y²]/2 = xy = 9×14 = 126.","[(x+y)²−x²−y²]/2 = xy = 9×14 = 126."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21780,"question_number":21781,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 9, y = 14.","x = 9, y = 14 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["529","529"],["528","528"],["530","530"],["531","531"]],"answer":0,"explanation":["(x+y)² = (9+14)² = 529.","(x+y)² = (9+14)² = 529."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21781,"question_number":21782,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^9 × 7^14 = 7^m, what is m?","7^9 × 7^14 = 7^m எனில் m என்ன?"],"options":[["25","25"],["22","22"],["24","24"],["23","23"]],"answer":3,"explanation":["m = 9 + 14 = 23.","m = 9 + 14 = 23."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21782,"question_number":21783,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^9)^14 = 2^m, find m.","(2^9)^14 = 2^m எனில் m காண்க."],"options":[["125","125"],["126","126"],["128","128"],["127","127"]],"answer":1,"explanation":["m = 9 × 14 = 126.","m = 9 × 14 = 126."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21783,"question_number":21784,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 70% of ₹180.","₹180 இன் 70% காண்க."],"options":[["126","126"],["125","125"],["128","128"],["127","127"]],"answer":0,"explanation":["180×70/100 = 126.","180×70/100 = 126."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21784,"question_number":21785,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹900 has a 70% discount. What is the sale price in rupees?","₹900 குறித்த விலையுள்ள பைக்கு 70% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["272","272"],["270","270"],["271","271"],["269","269"]],"answer":1,"explanation":["900 × (100−70)/100 = 270.","900 × (100−70)/100 = 270."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21785,"question_number":21786,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹900 sells for ₹1530. Find the profit percentage.","₹900 க்கு வாங்கிய பொருள் ₹1530 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["72","72"],["71","71"],["70","70"],["69","69"]],"answer":2,"explanation":["(1530−900)/900×100 = 70%.","(1530−900)/900×100 = 70%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21786,"question_number":21787,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹9000 at 14% per year for 3 years.","₹9000 க்கு ஆண்டுக்கு 14% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["3781","3781"],["3780","3780"],["3779","3779"],["3782","3782"]],"answer":1,"explanation":["9000×14×3/100 = 3780.","9000×14×3/100 = 3780."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21787,"question_number":21788,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹90000 at 14% a year for 2 years, compounded annually.","₹90000 க்கு ஆண்டுக்கு 14% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["26963","26963"],["26966","26966"],["26964","26964"],["26965","26965"]],"answer":2,"explanation":["90000×[(1+14/100)²−1] = 26964.","90000×[(1+14/100)²−1] = 26964."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21788,"question_number":21789,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["14 metres of cloth cost ₹90. At the same rate, what is the cost of 17 metres in rupees?","14 மீ துணியின் விலை ₹90. அதே வீதத்தில் 17 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["772/7","772/7"],["779/7","779/7"],["765/7","765/7"],["758/7","758/7"]],"answer":2,"explanation":["90/14×17 = 765/7.","90/14×17 = 765/7."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21789,"question_number":21790,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["14 equally efficient machines complete a job in 9 hours. How many hours do 16 such machines require at the same rate?","சமத் திறனுடைய 14 இயந்திரங்கள் வேலையை 9 மணியில் முடிக்கின்றன. அதே வீதத்தில் 16 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["79/8","79/8"],["55/8","55/8"],["71/8","71/8"],["63/8","63/8"]],"answer":3,"explanation":["14×9/(14+2) = 63/8 hours.","14×9/(14+2) = 63/8 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21790,"question_number":21791,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 18 cm and perpendicular height 14 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 18 செமீ; செங்குத்து உயரம் 14 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["254","254"],["253","253"],["251","251"],["252","252"]],"answer":3,"explanation":["18×14 = 252.","18×14 = 252."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21791,"question_number":21792,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 18 cm and 28 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 18 செமீ, 28 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["253","253"],["254","254"],["251","251"],["252","252"]],"answer":3,"explanation":["½×18×28 = 252 cm².","½×18×28 = 252 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21792,"question_number":21793,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 18 m and 46 m, and height 14 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 18 மீ, 46 மீ; உயரம் 14 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["447","447"],["448","448"],["449","449"],["450","450"]],"answer":1,"explanation":["½×(18+46)×14 = 448.","½×(18+46)×14 = 448."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21793,"question_number":21794,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 63 cm makes 14 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","63 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 14 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["5545","5545"],["5546","5546"],["5543","5543"],["5544","5544"]],"answer":3,"explanation":["14×2×22/7×63 = 5544.","14×2×22/7×63 = 5544."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21794,"question_number":21795,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 14 circular mats, each of radius 63 cm. Find their total area in cm², using π=22/7.","தலா 63 செமீ ஆரமுள்ள 14 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["174636","174636"],["174635","174635"],["174638","174638"],["174637","174637"]],"answer":0,"explanation":["14×22/7×63² = 174636.","14×22/7×63² = 174636."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21795,"question_number":21796,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 38° and 58°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 38°, 58°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["85","85"],["83","83"],["84","84"],["86","86"]],"answer":2,"explanation":["180−38−58 = 84°.","180−38−58 = 84°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21796,"question_number":21797,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 59°. One remote interior angle is 34°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 59°. அதற்கான ஓர் எதிர் உட்கோணம் 34°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["26","26"],["24","24"],["27","27"],["25","25"]],"answer":3,"explanation":["59 − 34 = 25°.","59 − 34 = 25°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21797,"question_number":21798,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 9, 23, 37, 51, 65.","9, 23, 37, 51, 65 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["37","37"],["36","36"],["38","38"],["39","39"]],"answer":0,"explanation":["Sum/5 = 185/5 = 37.","கூடுதல்/5 = 185/5 = 37."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21798,"question_number":21799,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 79, 9, 37, 107, 23.","வரிசைப்படுத்தி இடைநிலை காண்க: 79, 9, 37, 107, 23."],"options":[["39","39"],["37","37"],["36","36"],["38","38"]],"answer":1,"explanation":["Sorted: 9, 23, 37, 79, 107; middle value = 37.","வரிசை: 9, 23, 37, 79, 107; நடு மதிப்பு = 37."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21799,"question_number":21800,"practice_set":872},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 9, 23, 9, 37, 51, 9?","9, 23, 9, 37, 51, 9 தரவுகளின் முகடு எது?"],"options":[["8","8"],["11","11"],["9","9"],["10","10"]],"answer":2,"explanation":["9 occurs 3 times; each other value occurs once.","9 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21800,"question_number":21801,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 9 hours and another in 14 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 9 மணியிலும் மற்றொன்று 14 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["126/23","126/23"],["149/23","149/23"],["103/23","103/23"],["172/23","172/23"]],"answer":0,"explanation":["Combined hourly rate = 1/9+1/14; time = 126/23 = 126/23 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/9+1/14; காலம் = 126/23 = 126/23 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21801,"question_number":21802,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −9/14. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −9/14. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["9/14","9/14"],["-5/14","-5/14"],["37/14","37/14"],["23/14","23/14"]],"answer":0,"explanation":["−9/14 + 9/14 = 0. Simplified additive inverse: 9/14.","−9/14 + 9/14 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 9/14."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21802,"question_number":21803,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 9 and 14?","9 மற்றும் 14 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["27/2","27/2"],["23/2","23/2"],["25/2","25/2"],["21/2","21/2"]],"answer":1,"explanation":["(9+14)/2 = 23/2.","(9+14)/2 = 23/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21803,"question_number":21804,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 10/14 + 1/15.","கூட்டிச் சுருக்குக: 10/14 + 1/15."],"options":[["82/105","82/105"],["292/105","292/105"],["-23/105","-23/105"],["187/105","187/105"]],"answer":0,"explanation":["[10×15 + 14]/[14×15] = 82/105.","[10×15 + 14]/[14×15] = 82/105."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21804,"question_number":21805,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 10/14 − 1/15.","கழித்துச் சுருக்குக: 10/14 − 1/15."],"options":[["173/105","173/105"],["68/105","68/105"],["278/105","278/105"],["-37/105","-37/105"]],"answer":1,"explanation":["[10×15 − 14]/[14×15] = 68/105.","[10×15 − 14]/[14×15] = 68/105."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21805,"question_number":21806,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−10/14) × (15/11).","(−10/14) × (15/11) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-152/77","-152/77"],["-75/77","-75/77"],["2/77","2/77"],["79/77","79/77"]],"answer":1,"explanation":["−150/154 = -75/77.","−150/154 = -75/77."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21806,"question_number":21807,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (10/14) ÷ (11/15) in simplest form.","(10/14) ÷ (11/15) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["-2/77","-2/77"],["229/77","229/77"],["152/77","152/77"],["75/77","75/77"]],"answer":3,"explanation":["(10/14) × (15/11) = 75/77.","(10/14) × (15/11) = 75/77."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21807,"question_number":21808,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 11.4 and 0.14.","11.4 மற்றும் 0.14 தசம எண்களைக் கூட்டுக."],"options":[["11.55","11.55"],["11.64","11.64"],["11.54","11.54"],["11.53","11.53"]],"answer":2,"explanation":["11.4 + 0.14 = 11.54.","11.4 + 0.14 = 11.54."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21808,"question_number":21809,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 14x + 10 = 346.","14x + 10 = 346 சமன்பாட்டைத் தீர்க்க."],"options":[["26","26"],["24","24"],["23","23"],["25","25"]],"answer":1,"explanation":["x = (346 − 10)/14 = 24.","x = (346 − 10)/14 = 24."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21809,"question_number":21810,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 10 and y = 14, find (x+y)² − x² − y², then divide by 2.","x = 10, y = 14 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["141","141"],["139","139"],["140","140"],["142","142"]],"answer":2,"explanation":["[(x+y)²−x²−y²]/2 = xy = 10×14 = 140.","[(x+y)²−x²−y²]/2 = xy = 10×14 = 140."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21810,"question_number":21811,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 10, y = 14.","x = 10, y = 14 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["575","575"],["576","576"],["577","577"],["578","578"]],"answer":1,"explanation":["(x+y)² = (10+14)² = 576.","(x+y)² = (10+14)² = 576."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21811,"question_number":21812,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^10 × 7^14 = 7^m, what is m?","7^10 × 7^14 = 7^m எனில் m என்ன?"],"options":[["25","25"],["26","26"],["24","24"],["23","23"]],"answer":2,"explanation":["m = 10 + 14 = 24.","m = 10 + 14 = 24."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21812,"question_number":21813,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^10)^14 = 2^m, find m.","(2^10)^14 = 2^m எனில் m காண்க."],"options":[["140","140"],["142","142"],["139","139"],["141","141"]],"answer":0,"explanation":["m = 10 × 14 = 140.","m = 10 × 14 = 140."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21813,"question_number":21814,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 70% of ₹200.","₹200 இன் 70% காண்க."],"options":[["139","139"],["140","140"],["142","142"],["141","141"]],"answer":1,"explanation":["200×70/100 = 140.","200×70/100 = 140."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21814,"question_number":21815,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹1000 has a 70% discount. What is the sale price in rupees?","₹1000 குறித்த விலையுள்ள பைக்கு 70% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["300","300"],["301","301"],["302","302"],["299","299"]],"answer":0,"explanation":["1000 × (100−70)/100 = 300.","1000 × (100−70)/100 = 300."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21815,"question_number":21816,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹1000 sells for ₹1700. Find the profit percentage.","₹1000 க்கு வாங்கிய பொருள் ₹1700 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["70","70"],["72","72"],["71","71"],["69","69"]],"answer":0,"explanation":["(1700−1000)/1000×100 = 70%.","(1700−1000)/1000×100 = 70%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21816,"question_number":21817,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹10000 at 14% per year for 3 years.","₹10000 க்கு ஆண்டுக்கு 14% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["4200","4200"],["4199","4199"],["4201","4201"],["4202","4202"]],"answer":0,"explanation":["10000×14×3/100 = 4200.","10000×14×3/100 = 4200."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21817,"question_number":21818,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹100000 at 14% a year for 2 years, compounded annually.","₹100000 க்கு ஆண்டுக்கு 14% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["29960","29960"],["29959","29959"],["29962","29962"],["29961","29961"]],"answer":0,"explanation":["100000×[(1+14/100)²−1] = 29960.","100000×[(1+14/100)²−1] = 29960."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21818,"question_number":21819,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["14 metres of cloth cost ₹100. At the same rate, what is the cost of 17 metres in rupees?","14 மீ துணியின் விலை ₹100. அதே வீதத்தில் 17 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["850/7","850/7"],["843/7","843/7"],["857/7","857/7"],["864/7","864/7"]],"answer":0,"explanation":["100/14×17 = 850/7.","100/14×17 = 850/7."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21819,"question_number":21820,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["14 equally efficient machines complete a job in 10 hours. How many hours do 16 such machines require at the same rate?","சமத் திறனுடைய 14 இயந்திரங்கள் வேலையை 10 மணியில் முடிக்கின்றன. அதே வீதத்தில் 16 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["43/4","43/4"],["39/4","39/4"],["31/4","31/4"],["35/4","35/4"]],"answer":3,"explanation":["14×10/(14+2) = 35/4 hours.","14×10/(14+2) = 35/4 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21820,"question_number":21821,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 20 cm and perpendicular height 14 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 20 செமீ; செங்குத்து உயரம் 14 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["279","279"],["280","280"],["282","282"],["281","281"]],"answer":1,"explanation":["20×14 = 280.","20×14 = 280."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21821,"question_number":21822,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 20 cm and 28 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 20 செமீ, 28 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["280","280"],["281","281"],["282","282"],["279","279"]],"answer":0,"explanation":["½×20×28 = 280 cm².","½×20×28 = 280 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21822,"question_number":21823,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 20 m and 48 m, and height 14 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 20 மீ, 48 மீ; உயரம் 14 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["478","478"],["475","475"],["477","477"],["476","476"]],"answer":3,"explanation":["½×(20+48)×14 = 476.","½×(20+48)×14 = 476."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21823,"question_number":21824,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 70 cm makes 14 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","70 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 14 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["6161","6161"],["6162","6162"],["6159","6159"],["6160","6160"]],"answer":3,"explanation":["14×2×22/7×70 = 6160.","14×2×22/7×70 = 6160."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21824,"question_number":21825,"practice_set":873},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 14 circular mats, each of radius 70 cm. Find their total area in cm², using π=22/7.","தலா 70 செமீ ஆரமுள்ள 14 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["215602","215602"],["215599","215599"],["215601","215601"],["215600","215600"]],"answer":3,"explanation":["14×22/7×70² = 215600.","14×22/7×70² = 215600."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21825,"question_number":21826,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 40° and 58°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 40°, 58°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["82","82"],["83","83"],["81","81"],["84","84"]],"answer":0,"explanation":["180−40−58 = 82°.","180−40−58 = 82°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21826,"question_number":21827,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 60°. One remote interior angle is 34°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 60°. அதற்கான ஓர் எதிர் உட்கோணம் 34°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["25","25"],["28","28"],["27","27"],["26","26"]],"answer":3,"explanation":["60 − 34 = 26°.","60 − 34 = 26°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21827,"question_number":21828,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 10, 24, 38, 52, 66.","10, 24, 38, 52, 66 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["40","40"],["38","38"],["37","37"],["39","39"]],"answer":1,"explanation":["Sum/5 = 190/5 = 38.","கூடுதல்/5 = 190/5 = 38."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21828,"question_number":21829,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 80, 10, 38, 108, 24.","வரிசைப்படுத்தி இடைநிலை காண்க: 80, 10, 38, 108, 24."],"options":[["37","37"],["38","38"],["40","40"],["39","39"]],"answer":1,"explanation":["Sorted: 10, 24, 38, 80, 108; middle value = 38.","வரிசை: 10, 24, 38, 80, 108; நடு மதிப்பு = 38."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21829,"question_number":21830,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 10, 24, 10, 38, 52, 10?","10, 24, 10, 38, 52, 10 தரவுகளின் முகடு எது?"],"options":[["11","11"],["12","12"],["10","10"],["9","9"]],"answer":2,"explanation":["10 occurs 3 times; each other value occurs once.","10 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21830,"question_number":21831,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 10 hours and another in 14 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 10 மணியிலும் மற்றொன்று 14 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["41/6","41/6"],["47/6","47/6"],["35/6","35/6"],["29/6","29/6"]],"answer":2,"explanation":["Combined hourly rate = 1/10+1/14; time = 140/24 = 35/6 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/10+1/14; காலம் = 140/24 = 35/6 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21831,"question_number":21832,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −10/14. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −10/14. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["-2/7","-2/7"],["5/7","5/7"],["12/7","12/7"],["19/7","19/7"]],"answer":1,"explanation":["−10/14 + 10/14 = 0. Simplified additive inverse: 5/7.","−10/14 + 10/14 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 5/7."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21832,"question_number":21833,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 10 and 14?","10 மற்றும் 14 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["14","14"],["11","11"],["12","12"],["13","13"]],"answer":2,"explanation":["(10+14)/2 = 12.","(10+14)/2 = 12."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21833,"question_number":21834,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 11/14 + 1/15.","கூட்டிச் சுருக்குக: 11/14 + 1/15."],"options":[["599/210","599/210"],["179/210","179/210"],["-31/210","-31/210"],["389/210","389/210"]],"answer":1,"explanation":["[11×15 + 14]/[14×15] = 179/210.","[11×15 + 14]/[14×15] = 179/210."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21834,"question_number":21835,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 11/14 − 1/15.","கழித்துச் சுருக்குக: 11/14 − 1/15."],"options":[["571/210","571/210"],["-59/210","-59/210"],["151/210","151/210"],["361/210","361/210"]],"answer":2,"explanation":["[11×15 − 14]/[14×15] = 151/210.","[11×15 − 14]/[14×15] = 151/210."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21835,"question_number":21836,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−11/14) × (15/12).","(−11/14) × (15/12) பெருக்கற்பலனைச் சுருக்குக."],"options":[["57/56","57/56"],["-55/56","-55/56"],["-111/56","-111/56"],["1/56","1/56"]],"answer":1,"explanation":["−165/168 = -55/56.","−165/168 = -55/56."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21836,"question_number":21837,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (11/14) ÷ (12/15) in simplest form.","(11/14) ÷ (12/15) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["55/56","55/56"],["167/56","167/56"],["-1/56","-1/56"],["111/56","111/56"]],"answer":0,"explanation":["(11/14) × (15/12) = 55/56.","(11/14) × (15/12) = 55/56."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21837,"question_number":21838,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 12.4 and 0.14.","12.4 மற்றும் 0.14 தசம எண்களைக் கூட்டுக."],"options":[["12.64","12.64"],["12.55","12.55"],["12.54","12.54"],["12.53","12.53"]],"answer":2,"explanation":["12.4 + 0.14 = 12.54.","12.4 + 0.14 = 12.54."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21838,"question_number":21839,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 14x + 11 = 361.","14x + 11 = 361 சமன்பாட்டைத் தீர்க்க."],"options":[["24","24"],["25","25"],["27","27"],["26","26"]],"answer":1,"explanation":["x = (361 − 11)/14 = 25.","x = (361 − 11)/14 = 25."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21839,"question_number":21840,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 11 and y = 14, find (x+y)² − x² − y², then divide by 2.","x = 11, y = 14 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["154","154"],["153","153"],["156","156"],["155","155"]],"answer":0,"explanation":["[(x+y)²−x²−y²]/2 = xy = 11×14 = 154.","[(x+y)²−x²−y²]/2 = xy = 11×14 = 154."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21840,"question_number":21841,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 11, y = 14.","x = 11, y = 14 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["627","627"],["625","625"],["624","624"],["626","626"]],"answer":1,"explanation":["(x+y)² = (11+14)² = 625.","(x+y)² = (11+14)² = 625."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21841,"question_number":21842,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^11 × 7^14 = 7^m, what is m?","7^11 × 7^14 = 7^m எனில் m என்ன?"],"options":[["24","24"],["25","25"],["27","27"],["26","26"]],"answer":1,"explanation":["m = 11 + 14 = 25.","m = 11 + 14 = 25."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21842,"question_number":21843,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^11)^14 = 2^m, find m.","(2^11)^14 = 2^m எனில் m காண்க."],"options":[["154","154"],["153","153"],["155","155"],["156","156"]],"answer":0,"explanation":["m = 11 × 14 = 154.","m = 11 × 14 = 154."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21843,"question_number":21844,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the positive square root of 15376.","15376 இன் மிகை வர்க்கமூலத்தைக் காண்க."],"options":[["125","125"],["124","124"],["126","126"],["123","123"]],"answer":1,"explanation":["124 × 124 = 15376; √15376 = 124.","124 × 124 = 15376; √15376 = 124."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-10","practice_kind":"numerical_variant","id":21844,"question_number":21845,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the cube root of 1906624.","1906624 இன் கனமூலத்தைக் காண்க."],"options":[["124","124"],["125","125"],["126","126"],["123","123"]],"answer":0,"explanation":["124 × 124 × 124 = 1906624; cube root = 124.","124 × 124 × 124 = 1906624; கனமூலம் = 124."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-11","practice_kind":"numerical_variant","id":21845,"question_number":21846,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 70% of ₹220.","₹220 இன் 70% காண்க."],"options":[["153","153"],["155","155"],["156","156"],["154","154"]],"answer":3,"explanation":["220×70/100 = 154.","220×70/100 = 154."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21846,"question_number":21847,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹1100 has a 70% discount. What is the sale price in rupees?","₹1100 குறித்த விலையுள்ள பைக்கு 70% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["331","331"],["332","332"],["329","329"],["330","330"]],"answer":3,"explanation":["1100 × (100−70)/100 = 330.","1100 × (100−70)/100 = 330."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21847,"question_number":21848,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹1100 sells for ₹1870. Find the profit percentage.","₹1100 க்கு வாங்கிய பொருள் ₹1870 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["72","72"],["71","71"],["69","69"],["70","70"]],"answer":3,"explanation":["(1870−1100)/1100×100 = 70%.","(1870−1100)/1100×100 = 70%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21848,"question_number":21849,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹11000 at 14% per year for 3 years.","₹11000 க்கு ஆண்டுக்கு 14% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["4620","4620"],["4621","4621"],["4622","4622"],["4619","4619"]],"answer":0,"explanation":["11000×14×3/100 = 4620.","11000×14×3/100 = 4620."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21849,"question_number":21850,"practice_set":874},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹110000 at 14% a year for 2 years, compounded annually.","₹110000 க்கு ஆண்டுக்கு 14% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["32957","32957"],["32955","32955"],["32958","32958"],["32956","32956"]],"answer":3,"explanation":["110000×[(1+14/100)²−1] = 32956.","110000×[(1+14/100)²−1] = 32956."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21850,"question_number":21851,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["14 metres of cloth cost ₹110. At the same rate, what is the cost of 17 metres in rupees?","14 மீ துணியின் விலை ₹110. அதே வீதத்தில் 17 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["935/7","935/7"],["942/7","942/7"],["928/7","928/7"],["949/7","949/7"]],"answer":0,"explanation":["110/14×17 = 935/7.","110/14×17 = 935/7."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21851,"question_number":21852,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["14 equally efficient machines complete a job in 11 hours. How many hours do 16 such machines require at the same rate?","சமத் திறனுடைய 14 இயந்திரங்கள் வேலையை 11 மணியில் முடிக்கின்றன. அதே வீதத்தில் 16 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["93/8","93/8"],["69/8","69/8"],["77/8","77/8"],["85/8","85/8"]],"answer":2,"explanation":["14×11/(14+2) = 77/8 hours.","14×11/(14+2) = 77/8 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21852,"question_number":21853,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 22 cm and perpendicular height 14 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 22 செமீ; செங்குத்து உயரம் 14 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["308","308"],["307","307"],["309","309"],["310","310"]],"answer":0,"explanation":["22×14 = 308.","22×14 = 308."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21853,"question_number":21854,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 22 cm and 28 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 22 செமீ, 28 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["307","307"],["309","309"],["308","308"],["310","310"]],"answer":2,"explanation":["½×22×28 = 308 cm².","½×22×28 = 308 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21854,"question_number":21855,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 22 m and 50 m, and height 14 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 22 மீ, 50 மீ; உயரம் 14 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["505","505"],["503","503"],["506","506"],["504","504"]],"answer":3,"explanation":["½×(22+50)×14 = 504.","½×(22+50)×14 = 504."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21855,"question_number":21856,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 77 cm makes 14 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","77 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 14 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["6776","6776"],["6778","6778"],["6777","6777"],["6775","6775"]],"answer":0,"explanation":["14×2×22/7×77 = 6776.","14×2×22/7×77 = 6776."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21856,"question_number":21857,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 14 circular mats, each of radius 77 cm. Find their total area in cm², using π=22/7.","தலா 77 செமீ ஆரமுள்ள 14 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["260875","260875"],["260877","260877"],["260878","260878"],["260876","260876"]],"answer":3,"explanation":["14×22/7×77² = 260876.","14×22/7×77² = 260876."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21857,"question_number":21858,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 42° and 58°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 42°, 58°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["79","79"],["80","80"],["82","82"],["81","81"]],"answer":1,"explanation":["180−42−58 = 80°.","180−42−58 = 80°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21858,"question_number":21859,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 61°. One remote interior angle is 34°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 61°. அதற்கான ஓர் எதிர் உட்கோணம் 34°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["27","27"],["28","28"],["26","26"],["29","29"]],"answer":0,"explanation":["61 − 34 = 27°.","61 − 34 = 27°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21859,"question_number":21860,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 11, 25, 39, 53, 67.","11, 25, 39, 53, 67 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["39","39"],["38","38"],["41","41"],["40","40"]],"answer":0,"explanation":["Sum/5 = 195/5 = 39.","கூடுதல்/5 = 195/5 = 39."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21860,"question_number":21861,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 81, 11, 39, 109, 25.","வரிசைப்படுத்தி இடைநிலை காண்க: 81, 11, 39, 109, 25."],"options":[["40","40"],["39","39"],["41","41"],["38","38"]],"answer":1,"explanation":["Sorted: 11, 25, 39, 81, 109; middle value = 39.","வரிசை: 11, 25, 39, 81, 109; நடு மதிப்பு = 39."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21861,"question_number":21862,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 11, 25, 11, 39, 53, 11?","11, 25, 11, 39, 53, 11 தரவுகளின் முகடு எது?"],"options":[["12","12"],["10","10"],["13","13"],["11","11"]],"answer":3,"explanation":["11 occurs 3 times; each other value occurs once.","11 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21862,"question_number":21863,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 11 hours and another in 14 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 11 மணியிலும் மற்றொன்று 14 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["204/25","204/25"],["129/25","129/25"],["154/25","154/25"],["179/25","179/25"]],"answer":2,"explanation":["Combined hourly rate = 1/11+1/14; time = 154/25 = 154/25 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/11+1/14; காலம் = 154/25 = 154/25 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21863,"question_number":21864,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −11/14. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −11/14. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["25/14","25/14"],["-3/14","-3/14"],["11/14","11/14"],["39/14","39/14"]],"answer":2,"explanation":["−11/14 + 11/14 = 0. Simplified additive inverse: 11/14.","−11/14 + 11/14 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 11/14."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21864,"question_number":21865,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 11 and 14?","11 மற்றும் 14 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["27/2","27/2"],["25/2","25/2"],["23/2","23/2"],["29/2","29/2"]],"answer":1,"explanation":["(11+14)/2 = 25/2.","(11+14)/2 = 25/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21865,"question_number":21866,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 2/15 + 1/16.","கூட்டிச் சுருக்குக: 2/15 + 1/16."],"options":[["-193/240","-193/240"],["287/240","287/240"],["47/240","47/240"],["527/240","527/240"]],"answer":2,"explanation":["[2×16 + 15]/[15×16] = 47/240.","[2×16 + 15]/[15×16] = 47/240."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21866,"question_number":21867,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 2/15 − 1/16.","கழித்துச் சுருக்குக: 2/15 − 1/16."],"options":[["17/240","17/240"],["-223/240","-223/240"],["497/240","497/240"],["257/240","257/240"]],"answer":0,"explanation":["[2×16 − 15]/[15×16] = 17/240.","[2×16 − 15]/[15×16] = 17/240."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21867,"question_number":21868,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−2/15) × (16/3).","(−2/15) × (16/3) பெருக்கற்பலனைச் சுருக்குக."],"options":[["13/45","13/45"],["58/45","58/45"],["-32/45","-32/45"],["-77/45","-77/45"]],"answer":2,"explanation":["−32/45 = -32/45.","−32/45 = -32/45."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21868,"question_number":21869,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (2/15) ÷ (3/16) in simplest form.","(2/15) ÷ (3/16) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["77/45","77/45"],["32/45","32/45"],["-13/45","-13/45"],["122/45","122/45"]],"answer":1,"explanation":["(2/15) × (16/3) = 32/45.","(2/15) × (16/3) = 32/45."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21869,"question_number":21870,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 3.5 and 0.15.","3.5 மற்றும் 0.15 தசம எண்களைக் கூட்டுக."],"options":[["3.66","3.66"],["3.65","3.65"],["3.64","3.64"],["3.75","3.75"]],"answer":1,"explanation":["3.5 + 0.15 = 3.65.","3.5 + 0.15 = 3.65."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21870,"question_number":21871,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 15x + 2 = 257.","15x + 2 = 257 சமன்பாட்டைத் தீர்க்க."],"options":[["17","17"],["19","19"],["18","18"],["16","16"]],"answer":0,"explanation":["x = (257 − 2)/15 = 17.","x = (257 − 2)/15 = 17."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21871,"question_number":21872,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 2 and y = 15, find (x+y)² − x² − y², then divide by 2.","x = 2, y = 15 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["30","30"],["29","29"],["32","32"],["31","31"]],"answer":0,"explanation":["[(x+y)²−x²−y²]/2 = xy = 2×15 = 30.","[(x+y)²−x²−y²]/2 = xy = 2×15 = 30."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21872,"question_number":21873,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 2, y = 15.","x = 2, y = 15 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["291","291"],["290","290"],["289","289"],["288","288"]],"answer":2,"explanation":["(x+y)² = (2+15)² = 289.","(x+y)² = (2+15)² = 289."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21873,"question_number":21874,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^2 × 7^15 = 7^m, what is m?","7^2 × 7^15 = 7^m எனில் m என்ன?"],"options":[["19","19"],["16","16"],["18","18"],["17","17"]],"answer":3,"explanation":["m = 2 + 15 = 17.","m = 2 + 15 = 17."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21874,"question_number":21875,"practice_set":875},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^2)^15 = 2^m, find m.","(2^2)^15 = 2^m எனில் m காண்க."],"options":[["31","31"],["29","29"],["30","30"],["32","32"]],"answer":2,"explanation":["m = 2 × 15 = 30.","m = 2 × 15 = 30."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21875,"question_number":21876,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 75% of ₹40.","₹40 இன் 75% காண்க."],"options":[["30","30"],["31","31"],["29","29"],["32","32"]],"answer":0,"explanation":["40×75/100 = 30.","40×75/100 = 30."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21876,"question_number":21877,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹200 has a 75% discount. What is the sale price in rupees?","₹200 குறித்த விலையுள்ள பைக்கு 75% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["49","49"],["51","51"],["50","50"],["52","52"]],"answer":2,"explanation":["200 × (100−75)/100 = 50.","200 × (100−75)/100 = 50."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21877,"question_number":21878,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹200 sells for ₹350. Find the profit percentage.","₹200 க்கு வாங்கிய பொருள் ₹350 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["76","76"],["74","74"],["77","77"],["75","75"]],"answer":3,"explanation":["(350−200)/200×100 = 75%.","(350−200)/200×100 = 75%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21878,"question_number":21879,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹2000 at 15% per year for 3 years.","₹2000 க்கு ஆண்டுக்கு 15% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["900","900"],["901","901"],["902","902"],["899","899"]],"answer":0,"explanation":["2000×15×3/100 = 900.","2000×15×3/100 = 900."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21879,"question_number":21880,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹20000 at 15% a year for 2 years, compounded annually.","₹20000 க்கு ஆண்டுக்கு 15% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["6449","6449"],["6451","6451"],["6450","6450"],["6452","6452"]],"answer":2,"explanation":["20000×[(1+15/100)²−1] = 6450.","20000×[(1+15/100)²−1] = 6450."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21880,"question_number":21881,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["15 metres of cloth cost ₹20. At the same rate, what is the cost of 18 metres in rupees?","15 மீ துணியின் விலை ₹20. அதே வீதத்தில் 18 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["23","23"],["26","26"],["24","24"],["25","25"]],"answer":2,"explanation":["20/15×18 = 24.","20/15×18 = 24."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21881,"question_number":21882,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["15 equally efficient machines complete a job in 2 hours. How many hours do 17 such machines require at the same rate?","சமத் திறனுடைய 15 இயந்திரங்கள் வேலையை 2 மணியில் முடிக்கின்றன. அதே வீதத்தில் 17 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["30/17","30/17"],["47/17","47/17"],["13/17","13/17"],["64/17","64/17"]],"answer":0,"explanation":["15×2/(15+2) = 30/17 hours.","15×2/(15+2) = 30/17 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21882,"question_number":21883,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 4 cm and perpendicular height 15 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 4 செமீ; செங்குத்து உயரம் 15 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["62","62"],["59","59"],["60","60"],["61","61"]],"answer":2,"explanation":["4×15 = 60.","4×15 = 60."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21883,"question_number":21884,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 4 cm and 30 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 4 செமீ, 30 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["62","62"],["59","59"],["60","60"],["61","61"]],"answer":2,"explanation":["½×4×30 = 60 cm².","½×4×30 = 60 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21884,"question_number":21885,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 4 m and 34 m, and height 15 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 4 மீ, 34 மீ; உயரம் 15 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["286","286"],["285","285"],["284","284"],["287","287"]],"answer":1,"explanation":["½×(4+34)×15 = 285.","½×(4+34)×15 = 285."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21885,"question_number":21886,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 14 cm makes 15 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","14 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 15 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["1319","1319"],["1321","1321"],["1322","1322"],["1320","1320"]],"answer":3,"explanation":["15×2×22/7×14 = 1320.","15×2×22/7×14 = 1320."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21886,"question_number":21887,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 15 circular mats, each of radius 14 cm. Find their total area in cm², using π=22/7.","தலா 14 செமீ ஆரமுள்ள 15 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["9242","9242"],["9240","9240"],["9239","9239"],["9241","9241"]],"answer":1,"explanation":["15×22/7×14² = 9240.","15×22/7×14² = 9240."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21887,"question_number":21888,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 24° and 60°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 24°, 60°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["97","97"],["98","98"],["96","96"],["95","95"]],"answer":2,"explanation":["180−24−60 = 96°.","180−24−60 = 96°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21888,"question_number":21889,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 52°. One remote interior angle is 35°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 52°. அதற்கான ஓர் எதிர் உட்கோணம் 35°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["16","16"],["17","17"],["18","18"],["19","19"]],"answer":1,"explanation":["52 − 35 = 17°.","52 − 35 = 17°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21889,"question_number":21890,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 2, 17, 32, 47, 62.","2, 17, 32, 47, 62 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["32","32"],["33","33"],["31","31"],["34","34"]],"answer":0,"explanation":["Sum/5 = 160/5 = 32.","கூடுதல்/5 = 160/5 = 32."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21890,"question_number":21891,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 77, 2, 32, 107, 17.","வரிசைப்படுத்தி இடைநிலை காண்க: 77, 2, 32, 107, 17."],"options":[["33","33"],["32","32"],["31","31"],["34","34"]],"answer":1,"explanation":["Sorted: 2, 17, 32, 77, 107; middle value = 32.","வரிசை: 2, 17, 32, 77, 107; நடு மதிப்பு = 32."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21891,"question_number":21892,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 2, 17, 2, 32, 47, 2?","2, 17, 2, 32, 47, 2 தரவுகளின் முகடு எது?"],"options":[["2","2"],["1","1"],["3","3"],["4","4"]],"answer":0,"explanation":["2 occurs 3 times; each other value occurs once.","2 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21892,"question_number":21893,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 2 hours and another in 15 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 2 மணியிலும் மற்றொன்று 15 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["13/17","13/17"],["64/17","64/17"],["47/17","47/17"],["30/17","30/17"]],"answer":3,"explanation":["Combined hourly rate = 1/2+1/15; time = 30/17 = 30/17 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/2+1/15; காலம் = 30/17 = 30/17 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21893,"question_number":21894,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −2/15. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −2/15. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["17/15","17/15"],["2/15","2/15"],["32/15","32/15"],["-13/15","-13/15"]],"answer":1,"explanation":["−2/15 + 2/15 = 0. Simplified additive inverse: 2/15.","−2/15 + 2/15 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 2/15."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21894,"question_number":21895,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 2 and 15?","2 மற்றும் 15 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["19/2","19/2"],["21/2","21/2"],["17/2","17/2"],["15/2","15/2"]],"answer":2,"explanation":["(2+15)/2 = 17/2.","(2+15)/2 = 17/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21895,"question_number":21896,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 3/15 + 1/16.","கூட்டிச் சுருக்குக: 3/15 + 1/16."],"options":[["21/80","21/80"],["-59/80","-59/80"],["181/80","181/80"],["101/80","101/80"]],"answer":0,"explanation":["[3×16 + 15]/[15×16] = 21/80.","[3×16 + 15]/[15×16] = 21/80."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21896,"question_number":21897,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 3/15 − 1/16.","கழித்துச் சுருக்குக: 3/15 − 1/16."],"options":[["91/80","91/80"],["11/80","11/80"],["171/80","171/80"],["-69/80","-69/80"]],"answer":1,"explanation":["[3×16 − 15]/[15×16] = 11/80.","[3×16 − 15]/[15×16] = 11/80."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21897,"question_number":21898,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−3/15) × (16/4).","(−3/15) × (16/4) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-9/5","-9/5"],["1/5","1/5"],["-4/5","-4/5"],["6/5","6/5"]],"answer":2,"explanation":["−48/60 = -4/5.","−48/60 = -4/5."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21898,"question_number":21899,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (3/15) ÷ (4/16) in simplest form.","(3/15) ÷ (4/16) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["9/5","9/5"],["14/5","14/5"],["-1/5","-1/5"],["4/5","4/5"]],"answer":3,"explanation":["(3/15) × (16/4) = 4/5.","(3/15) × (16/4) = 4/5."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21899,"question_number":21900,"practice_set":876},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 4.5 and 0.15.","4.5 மற்றும் 0.15 தசம எண்களைக் கூட்டுக."],"options":[["4.65","4.65"],["4.75","4.75"],["4.64","4.64"],["4.66","4.66"]],"answer":0,"explanation":["4.5 + 0.15 = 4.65.","4.5 + 0.15 = 4.65."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21900,"question_number":21901,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 15x + 3 = 273.","15x + 3 = 273 சமன்பாட்டைத் தீர்க்க."],"options":[["19","19"],["18","18"],["17","17"],["20","20"]],"answer":1,"explanation":["x = (273 − 3)/15 = 18.","x = (273 − 3)/15 = 18."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21901,"question_number":21902,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 3 and y = 15, find (x+y)² − x² − y², then divide by 2.","x = 3, y = 15 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["44","44"],["46","46"],["45","45"],["47","47"]],"answer":2,"explanation":["[(x+y)²−x²−y²]/2 = xy = 3×15 = 45.","[(x+y)²−x²−y²]/2 = xy = 3×15 = 45."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21902,"question_number":21903,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 3, y = 15.","x = 3, y = 15 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["324","324"],["325","325"],["326","326"],["323","323"]],"answer":0,"explanation":["(x+y)² = (3+15)² = 324.","(x+y)² = (3+15)² = 324."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21903,"question_number":21904,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^3 × 7^15 = 7^m, what is m?","7^3 × 7^15 = 7^m எனில் m என்ன?"],"options":[["17","17"],["18","18"],["19","19"],["20","20"]],"answer":1,"explanation":["m = 3 + 15 = 18.","m = 3 + 15 = 18."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21904,"question_number":21905,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^3)^15 = 2^m, find m.","(2^3)^15 = 2^m எனில் m காண்க."],"options":[["44","44"],["46","46"],["47","47"],["45","45"]],"answer":3,"explanation":["m = 3 × 15 = 45.","m = 3 × 15 = 45."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21905,"question_number":21906,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 75% of ₹60.","₹60 இன் 75% காண்க."],"options":[["45","45"],["47","47"],["44","44"],["46","46"]],"answer":0,"explanation":["60×75/100 = 45.","60×75/100 = 45."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21906,"question_number":21907,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹300 has a 75% discount. What is the sale price in rupees?","₹300 குறித்த விலையுள்ள பைக்கு 75% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["75","75"],["76","76"],["77","77"],["74","74"]],"answer":0,"explanation":["300 × (100−75)/100 = 75.","300 × (100−75)/100 = 75."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21907,"question_number":21908,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹300 sells for ₹525. Find the profit percentage.","₹300 க்கு வாங்கிய பொருள் ₹525 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["75","75"],["76","76"],["74","74"],["77","77"]],"answer":0,"explanation":["(525−300)/300×100 = 75%.","(525−300)/300×100 = 75%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21908,"question_number":21909,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹3000 at 15% per year for 3 years.","₹3000 க்கு ஆண்டுக்கு 15% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1350","1350"],["1349","1349"],["1352","1352"],["1351","1351"]],"answer":0,"explanation":["3000×15×3/100 = 1350.","3000×15×3/100 = 1350."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21909,"question_number":21910,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹30000 at 15% a year for 2 years, compounded annually.","₹30000 க்கு ஆண்டுக்கு 15% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["9675","9675"],["9674","9674"],["9676","9676"],["9677","9677"]],"answer":0,"explanation":["30000×[(1+15/100)²−1] = 9675.","30000×[(1+15/100)²−1] = 9675."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21910,"question_number":21911,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["15 metres of cloth cost ₹30. At the same rate, what is the cost of 18 metres in rupees?","15 மீ துணியின் விலை ₹30. அதே வீதத்தில் 18 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["35","35"],["38","38"],["37","37"],["36","36"]],"answer":3,"explanation":["30/15×18 = 36.","30/15×18 = 36."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21911,"question_number":21912,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["15 equally efficient machines complete a job in 3 hours. How many hours do 17 such machines require at the same rate?","சமத் திறனுடைய 15 இயந்திரங்கள் வேலையை 3 மணியில் முடிக்கின்றன. அதே வீதத்தில் 17 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["28/17","28/17"],["45/17","45/17"],["79/17","79/17"],["62/17","62/17"]],"answer":1,"explanation":["15×3/(15+2) = 45/17 hours.","15×3/(15+2) = 45/17 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21912,"question_number":21913,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 6 cm and perpendicular height 15 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 6 செமீ; செங்குத்து உயரம் 15 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["90","90"],["91","91"],["92","92"],["89","89"]],"answer":0,"explanation":["6×15 = 90.","6×15 = 90."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21913,"question_number":21914,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 6 cm and 30 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 6 செமீ, 30 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["90","90"],["89","89"],["91","91"],["92","92"]],"answer":0,"explanation":["½×6×30 = 90 cm².","½×6×30 = 90 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21914,"question_number":21915,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 6 m and 36 m, and height 15 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 6 மீ, 36 மீ; உயரம் 15 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["317","317"],["314","314"],["315","315"],["316","316"]],"answer":2,"explanation":["½×(6+36)×15 = 315.","½×(6+36)×15 = 315."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21915,"question_number":21916,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 21 cm makes 15 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","21 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 15 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["1979","1979"],["1981","1981"],["1982","1982"],["1980","1980"]],"answer":3,"explanation":["15×2×22/7×21 = 1980.","15×2×22/7×21 = 1980."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21916,"question_number":21917,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 15 circular mats, each of radius 21 cm. Find their total area in cm², using π=22/7.","தலா 21 செமீ ஆரமுள்ள 15 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["20791","20791"],["20792","20792"],["20789","20789"],["20790","20790"]],"answer":3,"explanation":["15×22/7×21² = 20790.","15×22/7×21² = 20790."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21917,"question_number":21918,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 26° and 60°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 26°, 60°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["94","94"],["96","96"],["95","95"],["93","93"]],"answer":0,"explanation":["180−26−60 = 94°.","180−26−60 = 94°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21918,"question_number":21919,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 53°. One remote interior angle is 35°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 53°. அதற்கான ஓர் எதிர் உட்கோணம் 35°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["20","20"],["19","19"],["17","17"],["18","18"]],"answer":3,"explanation":["53 − 35 = 18°.","53 − 35 = 18°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21919,"question_number":21920,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 3, 18, 33, 48, 63.","3, 18, 33, 48, 63 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["32","32"],["34","34"],["33","33"],["35","35"]],"answer":2,"explanation":["Sum/5 = 165/5 = 33.","கூடுதல்/5 = 165/5 = 33."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21920,"question_number":21921,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 78, 3, 33, 108, 18.","வரிசைப்படுத்தி இடைநிலை காண்க: 78, 3, 33, 108, 18."],"options":[["32","32"],["33","33"],["35","35"],["34","34"]],"answer":1,"explanation":["Sorted: 3, 18, 33, 78, 108; middle value = 33.","வரிசை: 3, 18, 33, 78, 108; நடு மதிப்பு = 33."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21921,"question_number":21922,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 3, 18, 3, 33, 48, 3?","3, 18, 3, 33, 48, 3 தரவுகளின் முகடு எது?"],"options":[["3","3"],["4","4"],["5","5"],["2","2"]],"answer":0,"explanation":["3 occurs 3 times; each other value occurs once.","3 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21922,"question_number":21923,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 3 hours and another in 15 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 3 மணியிலும் மற்றொன்று 15 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["9/2","9/2"],["3/2","3/2"],["5/2","5/2"],["7/2","7/2"]],"answer":2,"explanation":["Combined hourly rate = 1/3+1/15; time = 45/18 = 5/2 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/3+1/15; காலம் = 45/18 = 5/2 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21923,"question_number":21924,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −3/15. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −3/15. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["6/5","6/5"],["-4/5","-4/5"],["1/5","1/5"],["11/5","11/5"]],"answer":2,"explanation":["−3/15 + 3/15 = 0. Simplified additive inverse: 1/5.","−3/15 + 3/15 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 1/5."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21924,"question_number":21925,"practice_set":877},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 3 and 15?","3 மற்றும் 15 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["11","11"],["10","10"],["8","8"],["9","9"]],"answer":3,"explanation":["(3+15)/2 = 9.","(3+15)/2 = 9."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21925,"question_number":21926,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 4/15 + 1/16.","கூட்டிச் சுருக்குக: 4/15 + 1/16."],"options":[["79/240","79/240"],["-161/240","-161/240"],["559/240","559/240"],["319/240","319/240"]],"answer":0,"explanation":["[4×16 + 15]/[15×16] = 79/240.","[4×16 + 15]/[15×16] = 79/240."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21926,"question_number":21927,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 4/15 − 1/16.","கழித்துச் சுருக்குக: 4/15 − 1/16."],"options":[["49/240","49/240"],["529/240","529/240"],["-191/240","-191/240"],["289/240","289/240"]],"answer":0,"explanation":["[4×16 − 15]/[15×16] = 49/240.","[4×16 − 15]/[15×16] = 49/240."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21927,"question_number":21928,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−4/15) × (16/5).","(−4/15) × (16/5) பெருக்கற்பலனைச் சுருக்குக."],"options":[["11/75","11/75"],["-64/75","-64/75"],["-139/75","-139/75"],["86/75","86/75"]],"answer":1,"explanation":["−64/75 = -64/75.","−64/75 = -64/75."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21928,"question_number":21929,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (4/15) ÷ (5/16) in simplest form.","(4/15) ÷ (5/16) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["214/75","214/75"],["139/75","139/75"],["-11/75","-11/75"],["64/75","64/75"]],"answer":3,"explanation":["(4/15) × (16/5) = 64/75.","(4/15) × (16/5) = 64/75."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21929,"question_number":21930,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 5.5 and 0.15.","5.5 மற்றும் 0.15 தசம எண்களைக் கூட்டுக."],"options":[["5.64","5.64"],["5.65","5.65"],["5.75","5.75"],["5.66","5.66"]],"answer":1,"explanation":["5.5 + 0.15 = 5.65.","5.5 + 0.15 = 5.65."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21930,"question_number":21931,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 15x + 4 = 289.","15x + 4 = 289 சமன்பாட்டைத் தீர்க்க."],"options":[["18","18"],["19","19"],["21","21"],["20","20"]],"answer":1,"explanation":["x = (289 − 4)/15 = 19.","x = (289 − 4)/15 = 19."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21931,"question_number":21932,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 4 and y = 15, find (x+y)² − x² − y², then divide by 2.","x = 4, y = 15 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["62","62"],["60","60"],["59","59"],["61","61"]],"answer":1,"explanation":["[(x+y)²−x²−y²]/2 = xy = 4×15 = 60.","[(x+y)²−x²−y²]/2 = xy = 4×15 = 60."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21932,"question_number":21933,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 4, y = 15.","x = 4, y = 15 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["362","362"],["361","361"],["360","360"],["363","363"]],"answer":1,"explanation":["(x+y)² = (4+15)² = 361.","(x+y)² = (4+15)² = 361."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21933,"question_number":21934,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^4 × 7^15 = 7^m, what is m?","7^4 × 7^15 = 7^m எனில் m என்ன?"],"options":[["21","21"],["18","18"],["20","20"],["19","19"]],"answer":3,"explanation":["m = 4 + 15 = 19.","m = 4 + 15 = 19."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21934,"question_number":21935,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^4)^15 = 2^m, find m.","(2^4)^15 = 2^m எனில் m காண்க."],"options":[["60","60"],["59","59"],["62","62"],["61","61"]],"answer":0,"explanation":["m = 4 × 15 = 60.","m = 4 × 15 = 60."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21935,"question_number":21936,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 75% of ₹80.","₹80 இன் 75% காண்க."],"options":[["61","61"],["59","59"],["60","60"],["62","62"]],"answer":2,"explanation":["80×75/100 = 60.","80×75/100 = 60."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21936,"question_number":21937,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹400 has a 75% discount. What is the sale price in rupees?","₹400 குறித்த விலையுள்ள பைக்கு 75% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["100","100"],["99","99"],["102","102"],["101","101"]],"answer":0,"explanation":["400 × (100−75)/100 = 100.","400 × (100−75)/100 = 100."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21937,"question_number":21938,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹400 sells for ₹700. Find the profit percentage.","₹400 க்கு வாங்கிய பொருள் ₹700 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["77","77"],["76","76"],["75","75"],["74","74"]],"answer":2,"explanation":["(700−400)/400×100 = 75%.","(700−400)/400×100 = 75%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21938,"question_number":21939,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹4000 at 15% per year for 3 years.","₹4000 க்கு ஆண்டுக்கு 15% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1801","1801"],["1800","1800"],["1802","1802"],["1799","1799"]],"answer":1,"explanation":["4000×15×3/100 = 1800.","4000×15×3/100 = 1800."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21939,"question_number":21940,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹40000 at 15% a year for 2 years, compounded annually.","₹40000 க்கு ஆண்டுக்கு 15% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["12900","12900"],["12902","12902"],["12899","12899"],["12901","12901"]],"answer":0,"explanation":["40000×[(1+15/100)²−1] = 12900.","40000×[(1+15/100)²−1] = 12900."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21940,"question_number":21941,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["15 metres of cloth cost ₹40. At the same rate, what is the cost of 18 metres in rupees?","15 மீ துணியின் விலை ₹40. அதே வீதத்தில் 18 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["49","49"],["50","50"],["48","48"],["47","47"]],"answer":2,"explanation":["40/15×18 = 48.","40/15×18 = 48."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21941,"question_number":21942,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["15 equally efficient machines complete a job in 4 hours. How many hours do 17 such machines require at the same rate?","சமத் திறனுடைய 15 இயந்திரங்கள் வேலையை 4 மணியில் முடிக்கின்றன. அதே வீதத்தில் 17 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["43/17","43/17"],["60/17","60/17"],["94/17","94/17"],["77/17","77/17"]],"answer":1,"explanation":["15×4/(15+2) = 60/17 hours.","15×4/(15+2) = 60/17 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21942,"question_number":21943,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 8 cm and perpendicular height 15 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 8 செமீ; செங்குத்து உயரம் 15 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["122","122"],["120","120"],["121","121"],["119","119"]],"answer":1,"explanation":["8×15 = 120.","8×15 = 120."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21943,"question_number":21944,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 8 cm and 30 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 8 செமீ, 30 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["121","121"],["120","120"],["119","119"],["122","122"]],"answer":1,"explanation":["½×8×30 = 120 cm².","½×8×30 = 120 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21944,"question_number":21945,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 8 m and 38 m, and height 15 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 8 மீ, 38 மீ; உயரம் 15 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["344","344"],["346","346"],["347","347"],["345","345"]],"answer":3,"explanation":["½×(8+38)×15 = 345.","½×(8+38)×15 = 345."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21945,"question_number":21946,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 28 cm makes 15 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","28 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 15 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["2641","2641"],["2640","2640"],["2639","2639"],["2642","2642"]],"answer":1,"explanation":["15×2×22/7×28 = 2640.","15×2×22/7×28 = 2640."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21946,"question_number":21947,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 15 circular mats, each of radius 28 cm. Find their total area in cm², using π=22/7.","தலா 28 செமீ ஆரமுள்ள 15 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["36960","36960"],["36961","36961"],["36962","36962"],["36959","36959"]],"answer":0,"explanation":["15×22/7×28² = 36960.","15×22/7×28² = 36960."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21947,"question_number":21948,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 28° and 60°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 28°, 60°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["92","92"],["94","94"],["91","91"],["93","93"]],"answer":0,"explanation":["180−28−60 = 92°.","180−28−60 = 92°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21948,"question_number":21949,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 54°. One remote interior angle is 35°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 54°. அதற்கான ஓர் எதிர் உட்கோணம் 35°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["20","20"],["18","18"],["19","19"],["21","21"]],"answer":2,"explanation":["54 − 35 = 19°.","54 − 35 = 19°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21949,"question_number":21950,"practice_set":878},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 4, 19, 34, 49, 64.","4, 19, 34, 49, 64 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["33","33"],["36","36"],["34","34"],["35","35"]],"answer":2,"explanation":["Sum/5 = 170/5 = 34.","கூடுதல்/5 = 170/5 = 34."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21950,"question_number":21951,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 79, 4, 34, 109, 19.","வரிசைப்படுத்தி இடைநிலை காண்க: 79, 4, 34, 109, 19."],"options":[["34","34"],["35","35"],["36","36"],["33","33"]],"answer":0,"explanation":["Sorted: 4, 19, 34, 79, 109; middle value = 34.","வரிசை: 4, 19, 34, 79, 109; நடு மதிப்பு = 34."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21951,"question_number":21952,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 4, 19, 4, 34, 49, 4?","4, 19, 4, 34, 49, 4 தரவுகளின் முகடு எது?"],"options":[["5","5"],["6","6"],["3","3"],["4","4"]],"answer":3,"explanation":["4 occurs 3 times; each other value occurs once.","4 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21952,"question_number":21953,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 4 hours and another in 15 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 4 மணியிலும் மற்றொன்று 15 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["98/19","98/19"],["41/19","41/19"],["79/19","79/19"],["60/19","60/19"]],"answer":3,"explanation":["Combined hourly rate = 1/4+1/15; time = 60/19 = 60/19 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/4+1/15; காலம் = 60/19 = 60/19 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21953,"question_number":21954,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −4/15. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −4/15. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["4/15","4/15"],["34/15","34/15"],["-11/15","-11/15"],["19/15","19/15"]],"answer":0,"explanation":["−4/15 + 4/15 = 0. Simplified additive inverse: 4/15.","−4/15 + 4/15 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 4/15."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21954,"question_number":21955,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 4 and 15?","4 மற்றும் 15 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["21/2","21/2"],["17/2","17/2"],["19/2","19/2"],["23/2","23/2"]],"answer":2,"explanation":["(4+15)/2 = 19/2.","(4+15)/2 = 19/2."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21955,"question_number":21956,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 5/15 + 1/16.","கூட்டிச் சுருக்குக: 5/15 + 1/16."],"options":[["19/48","19/48"],["67/48","67/48"],["-29/48","-29/48"],["115/48","115/48"]],"answer":0,"explanation":["[5×16 + 15]/[15×16] = 19/48.","[5×16 + 15]/[15×16] = 19/48."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21956,"question_number":21957,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 5/15 − 1/16.","கழித்துச் சுருக்குக: 5/15 − 1/16."],"options":[["-35/48","-35/48"],["61/48","61/48"],["109/48","109/48"],["13/48","13/48"]],"answer":3,"explanation":["[5×16 − 15]/[15×16] = 13/48.","[5×16 − 15]/[15×16] = 13/48."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21957,"question_number":21958,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−5/15) × (16/6).","(−5/15) × (16/6) பெருக்கற்பலனைச் சுருக்குக."],"options":[["-17/9","-17/9"],["1/9","1/9"],["-8/9","-8/9"],["10/9","10/9"]],"answer":2,"explanation":["−80/90 = -8/9.","−80/90 = -8/9."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21958,"question_number":21959,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (5/15) ÷ (6/16) in simplest form.","(5/15) ÷ (6/16) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["17/9","17/9"],["-1/9","-1/9"],["8/9","8/9"],["26/9","26/9"]],"answer":2,"explanation":["(5/15) × (16/6) = 8/9.","(5/15) × (16/6) = 8/9."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21959,"question_number":21960,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 6.5 and 0.15.","6.5 மற்றும் 0.15 தசம எண்களைக் கூட்டுக."],"options":[["6.64","6.64"],["6.65","6.65"],["6.75","6.75"],["6.66","6.66"]],"answer":1,"explanation":["6.5 + 0.15 = 6.65.","6.5 + 0.15 = 6.65."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21960,"question_number":21961,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 15x + 5 = 305.","15x + 5 = 305 சமன்பாட்டைத் தீர்க்க."],"options":[["20","20"],["19","19"],["21","21"],["22","22"]],"answer":0,"explanation":["x = (305 − 5)/15 = 20.","x = (305 − 5)/15 = 20."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21961,"question_number":21962,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 5 and y = 15, find (x+y)² − x² − y², then divide by 2.","x = 5, y = 15 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["76","76"],["75","75"],["74","74"],["77","77"]],"answer":1,"explanation":["[(x+y)²−x²−y²]/2 = xy = 5×15 = 75.","[(x+y)²−x²−y²]/2 = xy = 5×15 = 75."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21962,"question_number":21963,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 5, y = 15.","x = 5, y = 15 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["399","399"],["400","400"],["402","402"],["401","401"]],"answer":1,"explanation":["(x+y)² = (5+15)² = 400.","(x+y)² = (5+15)² = 400."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21963,"question_number":21964,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^5 × 7^15 = 7^m, what is m?","7^5 × 7^15 = 7^m எனில் m என்ன?"],"options":[["21","21"],["22","22"],["20","20"],["19","19"]],"answer":2,"explanation":["m = 5 + 15 = 20.","m = 5 + 15 = 20."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21964,"question_number":21965,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^5)^15 = 2^m, find m.","(2^5)^15 = 2^m எனில் m காண்க."],"options":[["76","76"],["77","77"],["75","75"],["74","74"]],"answer":2,"explanation":["m = 5 × 15 = 75.","m = 5 × 15 = 75."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21965,"question_number":21966,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 75% of ₹100.","₹100 இன் 75% காண்க."],"options":[["76","76"],["77","77"],["75","75"],["74","74"]],"answer":2,"explanation":["100×75/100 = 75.","100×75/100 = 75."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21966,"question_number":21967,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹500 has a 75% discount. What is the sale price in rupees?","₹500 குறித்த விலையுள்ள பைக்கு 75% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["127","127"],["125","125"],["126","126"],["124","124"]],"answer":1,"explanation":["500 × (100−75)/100 = 125.","500 × (100−75)/100 = 125."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21967,"question_number":21968,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹500 sells for ₹875. Find the profit percentage.","₹500 க்கு வாங்கிய பொருள் ₹875 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["74","74"],["76","76"],["77","77"],["75","75"]],"answer":3,"explanation":["(875−500)/500×100 = 75%.","(875−500)/500×100 = 75%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21968,"question_number":21969,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹5000 at 15% per year for 3 years.","₹5000 க்கு ஆண்டுக்கு 15% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2252","2252"],["2249","2249"],["2250","2250"],["2251","2251"]],"answer":2,"explanation":["5000×15×3/100 = 2250.","5000×15×3/100 = 2250."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21969,"question_number":21970,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the compound interest in rupees on ₹50000 at 15% a year for 2 years, compounded annually.","₹50000 க்கு ஆண்டுக்கு 15% வீதம் ஆண்டுதோறும் கூட்டப்படும் 2 ஆண்டுக் கூட்டுவட்டி எத்தனை ரூபாய்?"],"options":[["16126","16126"],["16127","16127"],["16125","16125"],["16124","16124"]],"answer":2,"explanation":["50000×[(1+15/100)²−1] = 16125.","50000×[(1+15/100)²−1] = 16125."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — compound interest · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — கூட்டுவட்டி · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-16","practice_kind":"numerical_variant","id":21970,"question_number":21971,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["15 metres of cloth cost ₹50. At the same rate, what is the cost of 18 metres in rupees?","15 மீ துணியின் விலை ₹50. அதே வீதத்தில் 18 மீ துணியின் விலை எத்தனை ரூபாய்?"],"options":[["59","59"],["61","61"],["60","60"],["62","62"]],"answer":2,"explanation":["50/15×18 = 60.","50/15×18 = 60."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Direct proportion · printed pp. 72–77. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · நேர்விகிதம் · அச்சுப் பக்கங்கள் 72–77. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-17","practice_kind":"numerical_variant","id":21971,"question_number":21972,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["15 equally efficient machines complete a job in 5 hours. How many hours do 17 such machines require at the same rate?","சமத் திறனுடைய 15 இயந்திரங்கள் வேலையை 5 மணியில் முடிக்கின்றன. அதே வீதத்தில் 17 இயந்திரங்கள் எத்தனை மணியில் முடிக்கும்?"],"options":[["58/17","58/17"],["75/17","75/17"],["92/17","92/17"],["109/17","109/17"]],"answer":1,"explanation":["15×5/(15+2) = 75/17 hours.","15×5/(15+2) = 75/17 மணி."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Inverse proportion · printed pp. 78–82. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எதிர்விகிதம் · அச்சுப் பக்கங்கள் 78–82. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-18","practice_kind":"numerical_variant","id":21972,"question_number":21973,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A parallelogram has base 10 cm and perpendicular height 15 cm. How many 1 cm² tiles cover its area exactly?","இணைகரத்தின் அடிப்பக்கம் 10 செமீ; செங்குத்து உயரம் 15 செமீ. அதன் பரப்பளவுக்குச் சமமாக எத்தனை 1 செமீ² ஓடுகள் தேவை?"],"options":[["149","149"],["150","150"],["151","151"],["152","152"]],"answer":1,"explanation":["10×15 = 150.","10×15 = 150."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — parallelogram · printed pp. 34–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — இணைகரம் · அச்சுப் பக்கங்கள் 34–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-19","practice_kind":"numerical_variant","id":21973,"question_number":21974,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rhombus has diagonals 10 cm and 30 cm. Calculate half the product of its diagonals, in cm².","சாய்சதுரத்தின் மூலைவிட்டங்கள் 10 செமீ, 30 செமீ. அவற்றின் பெருக்கற்பலனின் பாதியை செமீ² இல் காண்க."],"options":[["150","150"],["149","149"],["151","151"],["152","152"]],"answer":0,"explanation":["½×10×30 = 150 cm².","½×10×30 = 150 cm²."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — rhombus · printed pp. 40–43. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சாய்சதுரம் · அச்சுப் பக்கங்கள் 40–43. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-20","practice_kind":"numerical_variant","id":21974,"question_number":21975,"practice_set":879},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A trapezium has parallel sides 10 m and 40 m, and height 15 m. Find its area in m².","சரிவகத்தின் இணைப்பக்கங்கள் 10 மீ, 40 மீ; உயரம் 15 மீ. பரப்பளவு எத்தனை மீ²?"],"options":[["377","377"],["376","376"],["375","375"],["374","374"]],"answer":2,"explanation":["½×(10+40)×15 = 375.","½×(10+40)×15 = 375."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Measurements — trapezium · printed pp. 44–50. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · அளவைகள் — சரிவகம் · அச்சுப் பக்கங்கள் 44–50. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-21","practice_kind":"numerical_variant","id":21975,"question_number":21976,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A wheel of radius 35 cm makes 15 complete revolutions without slipping. Find the distance in cm. Use π=22/7.","35 செமீ ஆரமுள்ள சக்கரம் வழுக்காமல் 15 முழுச் சுற்றுகள் சுற்றுகிறது. கடந்த தொலைவு எத்தனை செமீ? π=22/7."],"options":[["3299","3299"],["3301","3301"],["3302","3302"],["3300","3300"]],"answer":3,"explanation":["15×2×22/7×35 = 3300.","15×2×22/7×35 = 3300."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Circumference · printed pp. 23–27. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டச் சுற்றளவு · அச்சுப் பக்கங்கள் 23–27. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-22","practice_kind":"numerical_variant","id":21976,"question_number":21977,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["There are 15 circular mats, each of radius 35 cm. Find their total area in cm², using π=22/7.","தலா 35 செமீ ஆரமுள்ள 15 வட்ட விரிப்புகளின் மொத்தப் பரப்பளவு எத்தனை செமீ²? π=22/7."],"options":[["57749","57749"],["57751","57751"],["57750","57750"],["57752","57752"]],"answer":2,"explanation":["15×22/7×35² = 57750.","15×22/7×35² = 57750."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Area of a circle · printed pp. 28–33. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வட்டப் பரப்பளவு · அச்சுப் பக்கங்கள் 28–33. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-23","practice_kind":"numerical_variant","id":21977,"question_number":21978,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 30° and 60°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 30°, 60°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["89","89"],["92","92"],["90","90"],["91","91"]],"answer":2,"explanation":["180−30−60 = 90°.","180−30−60 = 90°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Triangle angle sum · printed pp. 67–70. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · முக்கோணக் கோணக் கூடுதல் · அச்சுப் பக்கங்கள் 67–70. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-24","practice_kind":"numerical_variant","id":21978,"question_number":21979,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A triangle has an exterior angle of 55°. One remote interior angle is 35°. Find the other remote interior angle in degrees.","முக்கோணத்தின் வெளிக்கோணம் 55°. அதற்கான ஓர் எதிர் உட்கோணம் 35°. மற்றோர் எதிர் உட்கோணம் எத்தனை பாகை?"],"options":[["21","21"],["22","22"],["19","19"],["20","20"]],"answer":3,"explanation":["55 − 35 = 20°.","55 − 35 = 20°."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Exterior angles · printed pp. 69–74. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · வெளிக்கோணங்கள் · அச்சுப் பக்கங்கள் 69–74. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-25","practice_kind":"numerical_variant","id":21979,"question_number":21980,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the arithmetic mean of 5, 20, 35, 50, 65.","5, 20, 35, 50, 65 ஆகியவற்றின் கூட்டுச் சராசரி காண்க."],"options":[["35","35"],["36","36"],["37","37"],["34","34"]],"answer":0,"explanation":["Sum/5 = 175/5 = 35.","கூடுதல்/5 = 175/5 = 35."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-26","practice_kind":"numerical_variant","id":21980,"question_number":21981,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Arrange and find the median: 80, 5, 35, 110, 20.","வரிசைப்படுத்தி இடைநிலை காண்க: 80, 5, 35, 110, 20."],"options":[["36","36"],["35","35"],["37","37"],["34","34"]],"answer":1,"explanation":["Sorted: 5, 20, 35, 80, 110; middle value = 35.","வரிசை: 5, 20, 35, 80, 110; நடு மதிப்பு = 35."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-27","practice_kind":"numerical_variant","id":21981,"question_number":21982,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Which value is the mode of 5, 20, 5, 35, 50, 5?","5, 20, 5, 35, 50, 5 தரவுகளின் முகடு எது?"],"options":[["6","6"],["5","5"],["4","4"],["7","7"]],"answer":1,"explanation":["5 occurs 3 times; each other value occurs once.","5 மூன்று முறை வருகிறது; மற்ற மதிப்புகள் தலா ஒருமுறை வருகின்றன."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Statistics · printed pp. 94–111. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · புள்ளியியல் · அச்சுப் பக்கங்கள் 94–111. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-28","practice_kind":"numerical_variant","id":21982,"question_number":21983,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["One tap fills a tank in 5 hours and another in 15 hours. With both open and no leakage, how many hours are needed?","ஒரு குழாய் தொட்டியை 5 மணியிலும் மற்றொன்று 15 மணியிலும் நிரப்பும். கசிவின்றி இரண்டும் திறந்தால் எத்தனை மணியில் நிரம்பும்?"],"options":[["19/4","19/4"],["23/4","23/4"],["15/4","15/4"],["11/4","11/4"]],"answer":2,"explanation":["Combined hourly rate = 1/5+1/15; time = 75/20 = 15/4 hours.","ஒரு மணி நேரக் கூட்டு வீதம் = 1/5+1/15; காலம் = 75/20 = 15/4 மணி."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics — time and work · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் — காலமும் வேலையும் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-29","practice_kind":"numerical_variant","id":21983,"question_number":21984,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A rational number is −5/15. What must be added to it to get zero?","ஒரு விகிதமுறு எண் −5/15. அதனுடன் எதைக் கூட்டினால் பூச்சியம் கிடைக்கும்?"],"options":[["7/3","7/3"],["-2/3","-2/3"],["1/3","1/3"],["4/3","4/3"]],"answer":2,"explanation":["−5/15 + 5/15 = 0. Simplified additive inverse: 1/3.","−5/15 + 5/15 = 0. சுருக்கிய கூட்டல் எதிர்மறை: 1/3."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-30","practice_kind":"numerical_variant","id":21984,"question_number":21985,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["What rational number is exactly halfway between 5 and 15?","5 மற்றும் 15 ஆகிய எண்களுக்குச் சரியாக நடுவிலுள்ள விகிதமுறு எண் எது?"],"options":[["11","11"],["12","12"],["9","9"],["10","10"]],"answer":3,"explanation":["(5+15)/2 = 10.","(5+15)/2 = 10."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-31","practice_kind":"numerical_variant","id":21985,"question_number":21986,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 6/15 + 1/16.","கூட்டிச் சுருக்குக: 6/15 + 1/16."],"options":[["117/80","117/80"],["-43/80","-43/80"],["197/80","197/80"],["37/80","37/80"]],"answer":3,"explanation":["[6×16 + 15]/[15×16] = 37/80.","[6×16 + 15]/[15×16] = 37/80."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-0","practice_kind":"numerical_variant","id":21986,"question_number":21987,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Subtract and simplify: 6/15 − 1/16.","கழித்துச் சுருக்குக: 6/15 − 1/16."],"options":[["27/80","27/80"],["187/80","187/80"],["107/80","107/80"],["-53/80","-53/80"]],"answer":0,"explanation":["[6×16 − 15]/[15×16] = 27/80.","[6×16 − 15]/[15×16] = 27/80."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-1","practice_kind":"numerical_variant","id":21987,"question_number":21988,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simplified product (−6/15) × (16/7).","(−6/15) × (16/7) பெருக்கற்பலனைச் சுருக்குக."],"options":[["38/35","38/35"],["3/35","3/35"],["-32/35","-32/35"],["-67/35","-67/35"]],"answer":2,"explanation":["−96/105 = -32/35.","−96/105 = -32/35."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-2","practice_kind":"numerical_variant","id":21988,"question_number":21989,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Compute (6/15) ÷ (7/16) in simplest form.","(6/15) ÷ (7/16) ஐச் சுருக்கிய வடிவில் காண்க."],"options":[["67/35","67/35"],["-3/35","-3/35"],["102/35","102/35"],["32/35","32/35"]],"answer":3,"explanation":["(6/15) × (16/7) = 32/35.","(6/15) × (16/7) = 32/35."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Numbers · printed pp. 1–49. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · எண்கள் · அச்சுப் பக்கங்கள் 1–49. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-3","practice_kind":"numerical_variant","id":21989,"question_number":21990,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Add the decimals 7.5 and 0.15.","7.5 மற்றும் 0.15 தசம எண்களைக் கூட்டுக."],"options":[["7.64","7.64"],["7.65","7.65"],["7.75","7.75"],["7.66","7.66"]],"answer":1,"explanation":["7.5 + 0.15 = 7.65.","7.5 + 0.15 = 7.65."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Decimal operations · printed pp. 4–26. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தசமச் செயல்கள் · அச்சுப் பக்கங்கள் 4–26. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-4","practice_kind":"numerical_variant","id":21990,"question_number":21991,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Solve 15x + 6 = 321.","15x + 6 = 321 சமன்பாட்டைத் தீர்க்க."],"options":[["22","22"],["21","21"],["23","23"],["20","20"]],"answer":1,"explanation":["x = (321 − 6)/15 = 21.","x = (321 − 6)/15 = 21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 1 (English edition) · Simple linear equations · printed pp. 64–71. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 1 (ஆங்கிலப் பதிப்பு) · எளிய நேரியல் சமன்பாடுகள் · அச்சுப் பக்கங்கள் 64–71. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-5","practice_kind":"numerical_variant","id":21991,"question_number":21992,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["For x = 6 and y = 15, find (x+y)² − x² − y², then divide by 2.","x = 6, y = 15 எனில் (x+y)² − x² − y² மதிப்பைக் கண்டு 2 ஆல் வகுக்க."],"options":[["91","91"],["92","92"],["90","90"],["89","89"]],"answer":2,"explanation":["[(x+y)²−x²−y²]/2 = xy = 6×15 = 90.","[(x+y)²−x²−y²]/2 = xy = 6×15 = 90."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-6","practice_kind":"numerical_variant","id":21992,"question_number":21993,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Evaluate x² + 2xy + y² when x = 6, y = 15.","x = 6, y = 15 எனில் x² + 2xy + y² மதிப்பு காண்க."],"options":[["440","440"],["441","441"],["443","443"],["442","442"]],"answer":1,"explanation":["(x+y)² = (6+15)² = 441.","(x+y)² = (6+15)² = 441."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Identities · printed pp. 52–58. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · முற்றொருமைகள் · அச்சுப் பக்கங்கள் 52–58. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-7","practice_kind":"numerical_variant","id":21993,"question_number":21994,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If 7^6 × 7^15 = 7^m, what is m?","7^6 × 7^15 = 7^m எனில் m என்ன?"],"options":[["20","20"],["23","23"],["22","22"],["21","21"]],"answer":3,"explanation":["m = 6 + 15 = 21.","m = 6 + 15 = 21."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-8","practice_kind":"numerical_variant","id":21994,"question_number":21995,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["If (2^6)^15 = 2^m, find m.","(2^6)^15 = 2^m எனில் m காண்க."],"options":[["90","90"],["91","91"],["89","89"],["92","92"]],"answer":0,"explanation":["m = 6 × 15 = 90.","m = 6 × 15 = 90."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 2 (English edition) · Laws of exponents · printed pp. 46–52. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 2 (ஆங்கிலப் பதிப்பு) · அடுக்கு விதிகள் · அச்சுப் பக்கங்கள் 46–52. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-9","practice_kind":"numerical_variant","id":21995,"question_number":21996,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find 75% of ₹120.","₹120 இன் 75% காண்க."],"options":[["91","91"],["90","90"],["89","89"],["92","92"]],"answer":1,"explanation":["120×75/100 = 90.","120×75/100 = 90."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Percentages · printed pp. 35–39. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · சதவீதம் · அச்சுப் பக்கங்கள் 35–39. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-12","practice_kind":"numerical_variant","id":21996,"question_number":21997,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["A bag marked ₹600 has a 75% discount. What is the sale price in rupees?","₹600 குறித்த விலையுள்ள பைக்கு 75% தள்ளுபடி. விற்பனை விலை எத்தனை ரூபாய்?"],"options":[["150","150"],["149","149"],["152","152"],["151","151"]],"answer":0,"explanation":["600 × (100−75)/100 = 150.","600 × (100−75)/100 = 150."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-13","practice_kind":"numerical_variant","id":21997,"question_number":21998,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹600 sells for ₹1050. Find the profit percentage.","₹600 க்கு வாங்கிய பொருள் ₹1050 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் காண்க."],"options":[["74","74"],["77","77"],["76","76"],["75","75"]],"answer":3,"explanation":["(1050−600)/600×100 = 75%.","(1050−600)/600×100 = 75%."],"source":["Samacheer Kalvi Class 8 Mathematics (English edition) · Life Mathematics · printed pp. 121–154. Adapted practice.","சமச்சீர் கல்வி 8ஆம் வகுப்பு கணிதம் (ஆங்கிலப் பதிப்பு) · வாழ்வியல் கணிதம் · அச்சுப் பக்கங்கள் 121–154. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-14","practice_kind":"numerical_variant","id":21998,"question_number":21999,"practice_set":880},{"section":"SAT","subject":"Mathematics","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹6000 at 15% per year for 3 years.","₹6000 க்கு ஆண்டுக்கு 15% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["2699","2699"],["2701","2701"],["2700","2700"],["2702","2702"]],"answer":2,"explanation":["6000×15×3/100 = 2700.","6000×15×3/100 = 2700."],"source":["Samacheer Kalvi Class 7 Mathematics · Term 3 (English edition) · Simple interest · printed pp. 40–47. Adapted practice.","சமச்சீர் கல்வி 7ஆம் வகுப்பு கணிதம் · பருவம் 3 (ஆங்கிலப் பதிப்பு) · தனிவட்டி · அச்சுப் பக்கங்கள் 40–47. கருத்தின் அடிப்படையிலான பயிற்சி."],"template":"MATH-FOCUS-15","practice_kind":"numerical_variant","id":21999,"question_number":22000,"practice_set":880}]);
